const sbHeaders=()=>({apikey:SUPABASE.key,Authorization:'Bearer '+SUPABASE.key,'Content-Type':'application/json'});
async function sbSchema(){const r=await fetch(SUPABASE.url+'/rest/v1/',{headers:sbHeaders()});if(!r.ok)throw new Error('Supabase '+r.status);const s=await r.json();return s.definitions?.[SUPABASE.table]?.properties||s.components?.schemas?.[SUPABASE.table]?.properties||{}}
function firstColumn(cols,names){
  const list=Array.isArray(names)?names:[...arguments].slice(1);
  const map={
    id:'id',identifiant:'id',uuid:'id',
    type:'type_donnee',type_donnee:'type_donnee',
    cle:'reference_locale',key:'reference_locale',
    reference:'reference_locale',
    reference_locale:'reference_locale',
    nom:'reference_locale',
    module:'reference_locale',
    agence:'agence_id',agence_id:'agence_id',
    donnees:'contenu',data:'contenu',
    valeur:'contenu',json_data:'contenu',
    contenu:'contenu',
    supprimer:'supprimer',
    cree_par:'cree_par',
    created_at:'created_at',
    cree_a:'created_at',
    updated_at:'updated_at',
    mis_a_jour_a:'updated_at'
  };

  for(const n of list){
    if(cols&&cols[n])return n;
    if(map[n]&&cols&&cols[map[n]])return map[n];
  }

  return null;
}

async function sbSchema(){
  return {
    id:{},
    type_donnee:{},
    reference_locale:{},
    agence_id:{},
    contenu:{},
    supprimer:{},
    cree_par:{},
    created_at:{},
    updated_at:{}
  };
}

function __lpItemKey(x,kind){
  if(!x||typeof x!=='object')return '';

  if(kind==='products'){
    const semantic=[
      x.agency??x.agence??'',
      x.name??x.nom??x.produit??'',
      x.lot??''
    ].join('|').trim().toLowerCase();

    if(semantic.replace(/\|/g,'')){
      return 'product:'+semantic;
    }
  }

  const raw=
    x.id??
    x.uuid??
    x.invoice??
    x.ref??
    x.reference??
    x.username??
    x.phone??
    '';

  return raw===''?'':kind+':'+String(raw).trim().toLowerCase();
}

function __lpMergeArray(remote,local,kind){
  const out=[];
  const pos=new Map();

  const add=(item,localWins)=>{
    const copy=
      (item&&typeof item==='object')
      ?JSON.parse(JSON.stringify(item))
      :item;

    const k=__lpItemKey(copy,kind);

    if(!k){
      out.push(copy);
      return;
    }

    if(!pos.has(k)){
      pos.set(k,out.length);
      out.push(copy);
      return;
    }

    if(localWins){
      out[pos.get(k)]=copy;
    }
  };

  (Array.isArray(remote)?remote:[])
    .forEach(x=>add(x,false));

  (Array.isArray(local)?local:[])
    .forEach(x=>add(x,true));

  return out;
}

function __lpMergeDb(remote,local){
  const r=
    (remote&&typeof remote==='object')
    ?JSON.parse(JSON.stringify(remote))
    :{};

  const l=
    (local&&typeof local==='object')
    ?JSON.parse(JSON.stringify(local))
    :{};

  const out={...r,...l};

  const keys=
    new Set([
      ...Object.keys(r),
      ...Object.keys(l)
    ]);

  for(const k of keys){
    if(Array.isArray(r[k])||Array.isArray(l[k])){
      if (
    k === 'users' &&
    window.lpV5PrepareRemoteUsers
  ) {
    out[k] =
      window.lpV5PrepareRemoteUsers(
        r[k],
        l[k]
      );
  } else {
    out[k] =
      __lpMergeArray(
        r[k],
        l[k],
        k
      );
  }
    }
  }

  out.version='1.3.8';

  return migrate(out);
}

async function __lpRemoteMeta(){
  const cols=await sbSchema();

  const dataCol=
    firstColumn(
      cols,
      ['donnees','contenu','valeur','data','json_data']
    );

  const keyCol=
    firstColumn(
      cols,
      ['cle','reference_locale','nom','module','type']
    );

  if(!dataCol){
    throw new Error('Colonne JSON absente');
  }

  let q=
    SUPABASE.url+
    '/rest/v1/'+
    SUPABASE.table+
    '?select=*';

  if(keyCol){
    q+=
      '&'+
      keyCol+
      '=eq.'+
      encodeURIComponent('lpmp_v13');
  }

  const r=
    await fetch(
      q,
      {headers:sbHeaders()}
    );

  if(!r.ok){
    throw new Error(
      'Lecture '+
      r.status+
      ' '+
      (await r.text()).slice(0,160)
    );
  }

  const rows=await r.json();

  return {
    cols,
    dataCol,
    keyCol,
    rows
  };
}

