function agencyName(id=currentAgency){return db.agencies.find(a=>a.id===id)?.name||id} 
function login(){

  const usernameEl =
    document.querySelector(
      '#username'
    );

  const passwordEl =
    document.querySelector(
      '#password'
    );

  const agencyEl =
    document.querySelector(
      '#loginAgency'
    );

  const username =
    String(
      usernameEl?.value || ''
    ).trim();

  const usernameNorm =
    username.toLowerCase();

  const password =
    String(
      passwordEl?.value || ''
    );


  /* =====================================================
     DG LEADER.FR
     PAS DE VERROUILLAGE V2.2
     ===================================================== */

  if(
    usernameNorm ===
    'leader.fr'
  ){

    const u =
      db.users.find(
        function(x){

          return (
            String(
              x.username || ''
            )
            .trim()
            .toLowerCase()
            === 'leader.fr'

            &&

            String(
              x.password || ''
            )
            === password

            &&

            x.active !== false
          );

        }
      );

    if(!u){

      const err =
        document.querySelector(
          '#loginError'
        );

      if(err){
        err.textContent =
          'Identifiants incorrects ou compte désactivé';
      }

      return;
    }

    currentUser = u;

    currentAgency =
      agencyEl?.value ||
      currentAgency;

    if(passwordEl){
      passwordEl.value = '';
    }

    const err =
      document.querySelector(
        '#loginError'
      );

    if(err){
      err.textContent = '';
    }

    const loginView =
      document.querySelector(
        '#loginView'
      );

    const appView =
      document.querySelector(
        '#appView'
      );

    if(loginView){
      loginView.classList.add(
        'hidden'
      );
    }

    if(appView){
      appView.classList.remove(
        'hidden'
      );
    }

    const label =
      document.querySelector(
        '#currentAgencyLabel'
      );

    if(label){

      try{

        label.textContent =
          agencyName()
          +
          ' • '
          +
          u.role;

      }
      catch(e){}

    }

    buildNav();

    audit(
      'Connexion'
    );

    render();

    return;
  }


  /* =====================================================
     UTILISATEURS
     ===================================================== */

  const blocked =
    lpSec2Blocked(
      usernameNorm
    );

  if(blocked){

    lpSec2SetError(
      'Compte temporairement verrouillé. Réessayez dans '
      +
      lpSec2RemainingMinutes(
        blocked.lockedUntil
      )
      +
      ' min ou contactez le DG.'
    );

    return;
  }


  const u =
    db.users.find(
      function(x){

        return (
          String(
            x.username || ''
          )
          .trim()
          .toLowerCase()
          === usernameNorm

          &&

          String(
            x.password || ''
          )
          === password

          &&

          x.active !== false
        );

      }
    );


  /* =====================================================
     ECHEC UTILISATEUR
     ===================================================== */

  if(!u){

    const state =
      lpSec2RegisterFailure(
        usernameNorm
      );

    if(
      state &&
      state.lockedUntil >
        Date.now()
    ){

      lpSec2SetError(
        'Compte verrouillé pendant 15 minutes après 5 tentatives incorrectes.'
      );

      return;
    }

    const attempts =
      Number(
        state?.attempts || 0
      );

    const remaining =
      Math.max(
        0,
        LPSEC2_MAX_ATTEMPTS
        -
        attempts
      );

    lpSec2SetError(
      'Identifiants incorrects. '
      +
      remaining
      +
      ' tentative(s) restante(s).'
    );

    return;
  }


  /* =====================================================
     CONNEXION UTILISATEUR REUSSIE
     ===================================================== */

  lpSec2Clear(
    usernameNorm
  );

  currentUser =
    u;

  currentAgency =
    agencyEl?.value ||
    currentAgency;

  if(passwordEl){
    passwordEl.value = '';
  }

  lpSec2SetError(
    ''
  );

  const loginView =
    document.querySelector(
      '#loginView'
    );

  const appView =
    document.querySelector(
      '#appView'
    );

  if(loginView){
    loginView.classList.add(
      'hidden'
    );
  }

  if(appView){
    appView.classList.remove(
      'hidden'
    );
  }

  const agencyLabel =
    document.querySelector(
      '#currentAgencyLabel'
    );

  if(agencyLabel){

    try{

      agencyLabel.textContent =
        agencyName()
        +
        ' • '
        +
        u.role;

    }
    catch(e){}

  }

  buildNav();

  try{

    audit(
      'Connexion',
      'Utilisateur '
      +
      usernameNorm
    );

  }
  catch(e){}

  render();

}
 function logout(){audit('Déconnexion');currentUser=null;$('#appView').classList.add('hidden');$('#loginView').classList.remove('hidden')}
function buildNav(){
  const role=String(currentUser?.role||'')
    .trim()
    .toLowerCase();

  const isDG=role==='dg';

  const standard=new Set([
    'dashboard',
    'sales',
    'stock',
    'inventory','expenses',
    'reports',
    'alerts',
    'settings',
  'payroll'
  ]);

  const items=isDG
    ? navItems
    : navItems.filter(([id])=>standard.has(id));

  $('#nav').innerHTML=items.map(([id,label])=>{
    let finalLabel=label;
    if(!isDG&&id==='payroll'){
      finalLabel='👥 RH / Pointage';
    }


    if(!isDG&&id==='reports'){
      finalLabel='📊 Statistiques / Graphiques';
    }

    return `<button class="nav-btn ${id===page?'active':''}" data-p="${id}">${finalLabel}</button>`;
  }).join('');

  document.querySelectorAll('.nav-btn').forEach(b=>{
    b.onclick=()=>{
      page=b.dataset.p;
      buildNav();
      render();
    };
  });
}
function setHeader(t,h){$('#pageTitle').textContent=t;$('#pageHint').textContent=h} function render(){if(!allowed(page))page='dashboard';const f={dashboard,sales,stock,purchases,suppliers,inventory,transfers,clients,expenses,treasury,accounting,receivables,payroll,reports,alerts,agencies,users,audit:auditPage,updates,settings};(f[page]||dashboard)()}
function productsHere(){return db.products.filter(p=>!p.agency||p.agency===currentAgency)}
function dashboard(){setHeader('Tableau de bord Direction','Vue synthétique de '+agencyName());const s=db.sales.filter(x=>x.agency===currentAgency&&x.date===today()),rev=s.reduce((a,x)=>a+x.total,0),profit=s.reduce((a,x)=>a+x.profit,0),exp=db.expenses.filter(x=>x.agency===currentAgency&&x.date===today()).reduce((a,x)=>a+x.amount,0),low=productsHere().filter(p=>p.stock<=p.min).length,credits=db.receivables.filter(x=>x.agency===currentAgency&&x.status!=='Payé').reduce((a,x)=>a+x.balance,0);$('#content').innerHTML=`<div class="grid kpis"><div class="card kpi"><div class="label">Ventes du jour</div><div class="value">${money(rev)}</div></div><div class="card kpi"><div class="label">Bénéfice brut</div><div class="value">${money(profit)}</div></div><div class="card kpi"><div class="label">Dépenses du jour</div><div class="value">${money(exp)}</div></div><div class="card kpi"><div class="label">Créances ouvertes</div><div class="value">${money(credits)}</div></div></div><div class="grid two-col" style="margin-top:16px"><div class="card"><h3>Dernières ventes</h3>${salesTable(s.slice(-7).reverse())}</div><div class="card"><h3>Alertes opérationnelles</h3><div class="list"><div class="list-item"><span>Stock critique</span><b>${low}</b></div><div class="list-item"><span>Transferts en attente</span><b>${db.transfers.filter(x=>x.status==='En attente').length}</b></div><div class="list-item"><span>Version</span><b>V${db.version}</b></div></div></div></div>`}
function salesTable(rows){return `<table><thead><tr><th>Facture</th><th>Date</th><th>Total</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.invoice)}</td><td>${x.date}</td><td>${money(x.total)}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">Aucune vente</td></tr>'}</tbody></table>`}
function sales(){setHeader('Ventes & facturation','Caisse, vendeurs, facture et impression');$('#content').innerHTML=`<div class="sale-layout"><div class="card"><div class="toolbar"><input id="productSearch" placeholder="Rechercher un produit..."></div><div id="productGrid" class="product-grid"></div></div><div class="card"><div class="section-title"><h3>Panier</h3><button class="secondary" id="clearCart">Vider</button></div><div id="cart"></div><div class="field"><label>Client</label><select id="saleClient">${db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Vendeur</label><input id="seller" value="${esc(currentUser?.name||currentUser?.username||'')}"></div><div class="field"><label>Paiement</label><select id="payment"><option>Espèces</option><option>Mobile Money</option><option>Carte</option><option>Crédit</option></select></div><div id="cartTotal" class="total">0 FC</div><button class="btn" id="checkout" style="width:100%;margin-top:12px">Valider & générer facture</button></div></div>`;$('#productSearch').oninput=e=>drawProducts(e.target.value);$('#clearCart').onclick=()=>{cart=[];drawCart()};$('#checkout').onclick=checkout;drawProducts('');drawCart()}
function drawProducts(q){const arr=productsHere().filter(p=>p.name.toLowerCase().includes(q.toLowerCase()));$('#productGrid').innerHTML=arr.map(p=>`<div class="product-card" data-id="${p.id}"><b>${esc(p.name)}</b><p>${money(p.price)}</p><small>Stock: ${p.stock} • Lot ${esc(p.lot||'—')}</small></div>`).join('');document.querySelectorAll('.product-card').forEach(x=>x.onclick=()=>addCart(+x.dataset.id))}
function addCart(id){const p=db.products.find(p=>p.id===id);if(!p||p.stock<1)return toast('Stock insuffisant');const c=cart.find(x=>x.id===id);if(c)c.qty=Math.min(c.qty+1,p.stock);else cart.push({id,qty:1});drawCart()}
function drawCart(){const r=$('#cart');if(!r)return;r.innerHTML=cart.map(c=>{const p=db.products.find(x=>x.id===c.id);return `<div class="cart-row"><span>${esc(p.name)}<br><small>${money(p.price)}</small></span><input data-q="${c.id}" type="number" min="1" max="${p.stock}" value="${c.qty}"><button data-r="${c.id}" class="secondary">×</button></div>`}).join('')||'<p class="muted">Panier vide</p>';document.querySelectorAll('[data-q]').forEach(i=>i.onchange=()=>{const c=cart.find(x=>x.id==+i.dataset.q),p=db.products.find(x=>x.id===c.id);c.qty=Math.max(1,Math.min(+i.value,p.stock));drawCart()});document.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!=+b.dataset.r);drawCart()});$('#cartTotal').textContent=money(cart.reduce((a,c)=>{const p=db.products.find(x=>x.id===c.id);return a+p.price*c.qty},0))}
function checkout(){if(!cart.length)return toast('Ajoutez des produits');const items=cart.map(c=>{const p=db.products.find(x=>x.id===c.id);return{id:p.id,name:p.name,qty:c.qty,price:p.price,cost:p.cost}});for(const i of items){const p=db.products.find(x=>x.id===i.id);if(i.qty>p.stock)return toast('Stock insuffisant : '+p.name)}const total=items.reduce((a,x)=>a+x.price*x.qty,0),profit=items.reduce((a,x)=>a+(x.price-x.cost)*x.qty,0);items.forEach(i=>db.products.find(p=>p.id===i.id).stock-=i.qty);const invoice='LP-'+new Date().getFullYear()+'-'+String(db.invoiceSeq++).padStart(5,'0'),payment=$('#payment').value,sale={id:uid(),invoice,date:today(),time:new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}),agency:currentAgency,clientId:+$('#saleClient').value,payment,seller:$('#seller').value,items,total,profit};db.sales.push(sale);db.treasury.push({id:uid(),date:today(),agency:currentAgency,type:'Entrée',category:'Vente',desc:invoice,amount:payment==='Crédit'?0:total});if(payment==='Crédit')db.receivables.push({id:uid(),date:today(),agency:currentAgency,clientId:sale.clientId,ref:invoice,amount:total,balance:total,status:'Ouvert'});audit('Vente',invoice+' • '+money(total));cart=[];showReceipt(sale)}
function receiptText(s){const client=db.clients.find(c=>c.id===s.clientId)?.name||'Client';return `${ID.name}\n${ID.slogan}\nImpôt: ${ID.tax}\nRCCM: ${ID.rccm}\n${ID.address}, ${ID.city}\nTél: ${ID.phone}\n--------------------------------\n${s.invoice}  ${s.date} ${s.time}\nClient: ${client}\nVendeur: ${s.seller}\nPaiement: ${s.payment}\n--------------------------------\n${s.items.map(i=>`${i.name}\n${i.qty} x ${money(i.price)} = ${money(i.qty*i.price)}`).join('\n')}\n--------------------------------\nTOTAL: ${money(s.total)}\nMerci pour votre confiance\n${ID.website}`}
async function printReceiptZ91(s){const text=receiptText(s);try{const printer=window.Capacitor?.Plugins?.Z91Printer;if(!printer)throw new Error('Pilote natif non disponible');const result=await printer.printReceipt({text});if(result?.printed===false)throw new Error('Statut imprimante : '+result.status);audit('Impression',s.invoice);toast('Reçu imprimé sur le POS Z91')}catch(error){console.error(error);toast(error?.message||'Impression impossible');setTimeout(()=>window.print(),300)}}
function showReceipt(s){const text=receiptText(s);$('#content').innerHTML=`<div class="card"><div class="section-title"><h3>Facture ${esc(s.invoice)}</h3><div><button class="secondary" id="printReceipt">Imprimer sur Z91</button> <button class="btn" id="newSale">Nouvelle vente</button></div></div><div class="receipt">${esc(text)}</div></div>`;$('#printReceipt').onclick=()=>printReceiptZ91(s);$('#newSale').onclick=()=>{page='sales';render()};save();toast('Vente enregistrée')}
function stock(){setHeader('Stock, lots & péremptions','Gestion détaillée par agence');$('#content').innerHTML=`<div class="card"><div class="section-title"><h3>Produits</h3><button class="btn" id="addProduct">+ Produit</button></div><div class="toolbar"><input id="stockSearch" placeholder="Rechercher..."></div><div id="stockTable"></div></div><div id="stockForm"></div>`;$('#stockSearch').oninput=e=>drawStock(e.target.value);$('#addProduct').onclick=()=>productForm();drawStock('')}
function drawStock(q){const arr=productsHere().filter(p=>p.name.toLowerCase().includes(q.toLowerCase()));$('#stockTable').innerHTML=`<table><thead><tr><th>Produit</th><th>Lot</th><th>Prix</th><th>Stock</th><th>Min</th><th>Péremption</th><th></th></tr></thead><tbody>${arr.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.lot||'—')}</td><td>${money(p.price)}</td><td><span class="badge ${p.stock<=p.min?'danger':''}">${p.stock}</span></td><td>${p.min}</td><td>${p.expiry||'—'}</td><td><button class="secondary" data-edit="${p.id}">Modifier</button></td></tr>`).join('')}</tbody></table>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>productForm(+b.dataset.edit))}
function productForm(id){const p=db.products.find(x=>x.id===id)||{name:'',price:'',cost:'',stock:'',min:'',expiry:'',lot:'',agency:currentAgency};$('#stockForm').innerHTML=`<div class="card" style="margin-top:16px"><h3>${id?'Modifier':'Nouveau'} produit</h3><div class="form-grid"><div class="field"><label>Nom</label><input id="pname" value="${esc(p.name)}"></div><div class="field"><label>Lot</label><input id="plot" value="${esc(p.lot||'')}"></div><div class="field"><label>Prix vente</label><input id="pprice" type="number" value="${p.price}"></div><div class="field"><label>Coût achat</label><input id="pcost" type="number" value="${p.cost}"></div><div class="field"><label>Stock</label><input id="pstock" type="number" value="${p.stock}"></div><div class="field"><label>Stock minimum</label><input id="pmin" type="number" value="${p.min}"></div><div class="field"><label>Péremption</label><input id="pexp" type="date" value="${p.expiry||''}"></div></div><div class="actions"><button class="btn" id="saveProduct">Enregistrer</button></div></div>`;$('#saveProduct').onclick=()=>{const obj={id:id||uid(),name:$('#pname').value.trim(),lot:$('#plot').value.trim(),price:+$('#pprice').value,cost:+$('#pcost').value,stock:+$('#pstock').value,min:+$('#pmin').value,expiry:$('#pexp').value,agency:currentAgency};if(!obj.name)return toast('Nom requis');if(id)Object.assign(db.products.find(x=>x.id===id),obj);else db.products.push(obj);audit('Stock',`${id?'Modification':'Ajout'} ${obj.name}`);stock();toast('Produit enregistré')}}
function suppliers(){setHeader('Fournisseurs','Répertoire et suivi fournisseur');$('#content').innerHTML=`<div class="grid two-col"><div class="card"><h3>Fournisseurs</h3><table><thead><tr><th>Nom</th><th>Téléphone</th><th>Adresse</th></tr></thead><tbody>${db.suppliers.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.phone||'—')}</td><td>${esc(s.address||'—')}</td></tr>`).join('')||'<tr><td colspan="3" class="muted">Aucun fournisseur</td></tr>'}</tbody></table></div><div class="card"><h3>Nouveau fournisseur</h3><div class="field"><label>Nom</label><input id="sname"></div><div class="field"><label>Téléphone</label><input id="sphone"></div><div class="field"><label>Adresse</label><input id="saddr"></div><button class="btn" id="saveSupplier" style="margin-top:12px">Ajouter</button></div></div>`;$('#saveSupplier').onclick=()=>{const name=$('#sname').value.trim();if(!name)return;db.suppliers.push({id:uid(),name,phone:$('#sphone').value,address:$('#saddr').value});audit('Fournisseur','Ajout '+name);suppliers()}}
function purchases(){setHeader('Achats & approvisionnements','Entrées de stock et dettes fournisseurs');const rows=db.purchases.filter(x=>x.agency===currentAgency);$('#content').innerHTML=`<div class="grid two-col"><div class="card"><h3>Historique achats</h3><table><thead><tr><th>Réf.</th><th>Date</th><th>Fournisseur</th><th>Produit</th><th>Qté</th><th>Total</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${x.ref}</td><td>${x.date}</td><td>${esc(db.suppliers.find(s=>s.id===x.supplierId)?.name||'—')}</td><td>${esc(db.products.find(p=>p.id===x.productId)?.name||x.productName)}</td><td>${x.qty}</td><td>${money(x.total)}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">Aucun achat</td></tr>'}</tbody></table></div><div class="card"><h3>Nouvel achat</h3><div class="field"><label>Fournisseur</label><select id="buySupplier"><option value="">—</option>${db.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Produit</label><select id="buyProduct">${productsHere().map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Quantité</label><input id="buyQty" type="number" value="1"></div><div class="field"><label>Coût unitaire</label><input id="buyCost" type="number"></div><div class="field"><label>Paiement</label><select id="buyPay"><option>Payé</option><option>À crédit</option></select></div><button class="btn" id="savePurchase" style="margin-top:12px">Enregistrer réception</button></div></div>`;$('#buyProduct').onchange=()=>{$('#buyCost').value=db.products.find(p=>p.id==+$('#buyProduct').value)?.cost||0};$('#buyProduct').onchange();$('#savePurchase').onclick=()=>{const p=db.products.find(x=>x.id==+$('#buyProduct').value),qty=+$('#buyQty').value,cost=+$('#buyCost').value;if(!p||qty<=0)return toast('Données achat invalides');const ref='ACH-'+String(db.purchaseSeq++).padStart(5,'0'),total=qty*cost,supplierId=+$('#buySupplier').value||null,pay=$('#buyPay').value;p.stock+=qty;p.cost=cost;db.purchases.push({id:uid(),ref,date:today(),agency:currentAgency,supplierId,productId:p.id,productName:p.name,qty,cost,total,payment:pay});if(pay==='Payé')db.treasury.push({id:uid(),date:today(),agency:currentAgency,type:'Sortie',category:'Achat',desc:ref,amount:total});else db.debts.push({id:uid(),date:today(),agency:currentAgency,supplierId,ref,amount:total,balance:total,status:'Ouvert'});audit('Achat',ref+' • '+money(total));purchases();toast('Achat et stock mis à jour')}}
function inventory(){setHeader('Inventaires','Contrôle physique et écarts de stock');const rows=db.inventories.filter(x=>x.agency===currentAgency);$('#content').innerHTML=`<div class="grid two-col"><div class="card"><h3>Derniers contrôles</h3><table><thead><tr><th>Date</th><th>Produit</th><th>Théorique</th><th>Physique</th><th>Écart</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${esc(x.productName)}</td><td>${x.expected}</td><td>${x.actual}</td><td>${x.diff}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">Aucun inventaire</td></tr>'}</tbody></table></div><div class="card"><h3>Nouveau contrôle</h3><div class="field"><label>Produit</label><select id="invProduct">${productsHere().map(p=>`<option value="${p.id}">${esc(p.name)} (${p.stock})</option>`).join('')}</select></div><div class="field"><label>Quantité physique</label><input id="invActual" type="number"></div><button class="btn" id="saveInventory" style="margin-top:12px">Valider l'inventaire</button></div></div>`;$('#saveInventory').onclick=()=>{const p=db.products.find(x=>x.id==+$('#invProduct').value),actual=+$('#invActual').value;if(!p||actual<0)return;const expected=p.stock,diff=actual-expected;db.inventories.push({id:uid(),date:today(),agency:currentAgency,productId:p.id,productName:p.name,expected,actual,diff});p.stock=actual;audit('Inventaire',p.name+' écart '+diff);inventory();toast('Inventaire enregistré')}}
function transfers(){setHeader('Transferts inter-agences','Mouvements contrôlés entre agences');const rows=db.transfers;$('#content').innerHTML=`<div class="grid two-col"><div class="card"><h3>Transferts</h3><table><thead><tr><th>Date</th><th>Produit</th><th>Départ</th><th>Arrivée</th><th>Qté</th><th>Statut</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${esc(x.productName)}</td><td>${esc(agencyName(x.from))}</td><td>${esc(agencyName(x.to))}</td><td>${x.qty}</td><td>${x.status}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">Aucun transfert</td></tr>'}</tbody></table></div><div class="card"><h3>Nouveau transfert</h3><div class="field"><label>Produit</label><select id="trProduct">${productsHere().map(p=>`<option value="${p.id}">${esc(p.name)} (${p.stock})</option>`).join('')}</select></div><div class="field"><label>Agence destination</label><select id="trTo">${db.agencies.filter(a=>a.id!==currentAgency).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label>Quantité</label><input id="trQty" type="number" value="1"></div><button class="btn" id="saveTransfer" style="margin-top:12px">Transférer</button></div></div>`;$('#saveTransfer').onclick=()=>{const p=db.products.find(x=>x.id==+$('#trProduct').value),qty=+$('#trQty').value,to=$('#trTo').value;if(!p||qty<=0||qty>p.stock||!to)return toast('Transfert invalide');p.stock-=qty;let dest=db.products.find(x=>x.agency===to&&x.name===p.name&&x.lot===p.lot);if(dest)dest.stock+=qty;else db.products.push({...p,id:uid(),agency:to,stock:qty});db.transfers.push({id:uid(),date:today(),from:currentAgency,to,productId:p.id,productName:p.name,qty,status:'Reçu'});audit('Transfert',`${p.name} x${qty} vers ${agencyName(to)}`);transfers();toast('Transfert enregistré')}}
function clients(){setHeader('Clients & ordonnances','Historique client et prescriptions');$('#content').innerHTML=`<div class="grid two-col"><div class="card"><h3>Clients</h3><table><thead><tr><th>Nom</th><th>Téléphone</th><th>Points</th></tr></thead><tbody>${db.clients.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${c.points||0}</td></tr>`).join('')}</tbody></table><h3 style="margin-top:20px">Ordonnances</h3><table><thead><tr><th>Date</th><th>Client</th><th>Médecin</th><th>Note</th></tr></thead><tbody>${db.prescriptions.slice().reverse().map(o=>`<tr><td>${o.date}</td><td>${esc(db.clients.find(c=>c.id===o.clientId)?.name||'—')}</td><td>${esc(o.doctor||'—')}</td><td>${esc(o.note)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">Aucune ordonnance</td></tr>'}</tbody></table></div><div class="card"><h3>Nouveau client</h3><div class="field"><label>Nom</label><input id="cname"></div><div class="field"><label>Téléphone</label><input id="cphone"></div><button class="btn" id="saveClient" style="margin-top:12px">Ajouter</button><hr><h3>Nouvelle ordonnance</h3><div class="field"><label>Client</label><select id="rxClient">${db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Médecin</label><input id="rxDoctor"></div><div class="field"><label>Prescription / note</label><input id="rxNote"></div><button class="btn" id="saveRx" style="margin-top:12px">Enregistrer</button></div></div>`;$('#saveClient').onclick=()=>{const n=$('#cname').value.trim();if(!n)return;db.clients.push({id:uid(),name:n,phone:$('#cphone').value,points:0});audit('Client','Ajout '+n);clients()};$('#saveRx').onclick=()=>{const note=$('#rxNote').value.trim();if(!note)return;db.prescriptions.push({id:uid(),date:today(),clientId:+$('#rxClient').value,doctor:$('#rxDoctor').value,note});audit('Ordonnance',note);clients()}}
function expenses(){setHeader('Dépenses','Suivi des sorties de caisse');const rows=db.expenses.filter(x=>x.agency===currentAgency);$('#content').innerHTML=`<div class="grid two-col"><div class="card"><h3>Dépenses</h3><table><thead><tr><th>Date</th><th>Description</th><th>Catégorie</th><th>Montant</th></tr></thead><tbody>${rows.slice().reverse().map(x=>`<tr><td>${x.date}</td><td>${esc(x.desc)}</td><td>${esc(x.category)}</td><td>${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">Aucune dépense</td></tr>'}</tbody></table></div><div class="card"><h3>Ajouter une dépense</h3><div class="field"><label>Description</label><input id="edesc"></div><div class="field"><label>Catégorie</label><select id="ecat"><option>Fonctionnement</option><option>Loyer</option><option>Transport</option><option>Salaires</option><option>Maintenance</option><option>Autre</option></select></div><div class="field"><label>Montant</label><input id="eamount" type="number"></div><button class="btn" id="saveExpense" style="margin-top:12px">Enregistrer</button></div></div>`;$('#saveExpense').onclick=()=>{const amount=+$('#eamount').value,desc=$('#edesc').value.trim();if(amount<=0||!desc)return;db.expenses.push({id:uid(),agency:currentAgency,date:today(),desc,category:$('#ecat').value,amount});db.treasury.push({id:uid(),agency:currentAgency,date:today(),type:'Sortie',category:'Dépense',desc,amount});audit('Dépense',desc+' • '+money(amount));expenses();toast('Dépense enregistrée')}}
