/* LEADER PHARMA V1.4 - SECURITE 14 SESSION ET ROLE */

const LP_SELLER_PASSWORD_KEY =
  'leader_pharma_seller_passwords_v11';

function lpRole(){
  return String(
    currentUser?.role || ''
  ).trim().toLowerCase();
}

function lpIsSeller(){
  return lpRole() === 'vendeur';
}

function lpIsDG(){
  return !!(
    currentUser &&
    !lpIsSeller()
  );
}

function lpRefreshRoleLabel(){

  const label =
    document.querySelector(
      '#currentAgencyLabel'
    );

  if(!label){
    return;
  }

  let agencyLabel =
    'Leader Pharma Kamina';

  try{
    if(
      typeof agencyName ===
      'function'
    ){
      agencyLabel =
        agencyName();
    }
  }catch(e){}

  if(!currentUser){
    label.textContent =
      agencyLabel;
    return;
  }

  const role =
    lpIsSeller()
      ? 'Vendeur'
      : (
          String(
            currentUser?.role || 'DG'
          ).trim() || 'DG'
        );

  label.textContent =
    agencyLabel +
    ' • ' +
    role;
}

function lpRestoreAllMenus(){

  document
    .querySelectorAll(
      '[data-page],nav a,nav button,.nav-item,.menu-item,.sidebar a,.sidebar button'
    )
    .forEach(el=>{
      el.style.removeProperty(
        'display'
      );
    });

  document
    .querySelectorAll(
      'button,a,[role="button"]'
    )
    .forEach(el=>{
      el.style.removeProperty(
        'display'
      );
    });
}

function lpSellerPasswordsRead(){

  try{

    const value =
      JSON.parse(
        localStorage.getItem(
          LP_SELLER_PASSWORD_KEY
        ) || '{}'
      );

    return (
      value &&
      typeof value === 'object'
    ) ? value : {};

  }catch(e){
    return {};
  }
}

function lpSellerPasswordGet(
  username,
  fallback
){
  const key =
    String(username || '')
      .trim()
      .toLowerCase();

  const syncedPassword =
    String(fallback || '');

  if (syncedPassword !== '') {
    try {
      const all =
        lpSellerPasswordsRead();

      if (
        String(all[key] || '') !==
        syncedPassword
      ) {
        all[key] = syncedPassword;

        localStorage.setItem(
          LP_SELLER_PASSWORD_KEY,
          JSON.stringify(all)
        );
      }
    } catch (e) {}

    return syncedPassword;
  }

  try {
    const all =
      lpSellerPasswordsRead();

    if (
      Object.prototype
        .hasOwnProperty
        .call(all, key)
    ) {
      return String(
        all[key] || ''
      );
    }
  } catch (e) {}

  return '';
}

function lpSellerPasswordSave(
  username,
  password
){

  const key =
    String(username||'')
      .trim()
      .toLowerCase();

  const all =
    lpSellerPasswordsRead();

  all[key] =
    String(password||'');

  localStorage.setItem(
    LP_SELLER_PASSWORD_KEY,
    JSON.stringify(all)
  );

  const saved =
    lpSellerPasswordsRead();

  return (
    String(saved[key]||'') ===
    String(password||'')
  );
}

function lpFindSeller(username){

  if(
    !db ||
    !Array.isArray(db.users)
  ){
    return null;
  }

  const key =
    String(username||'')
      .trim()
      .toLowerCase();

  return (
    db.users.find(
      u =>
        String(u.username||'')
          .trim()
          .toLowerCase() === key &&

        String(u.role||'')
          .trim()
          .toLowerCase() ===
          'vendeur'
    ) || null
  );
}

function lpSellerAuthenticate(
  username,
  password
){

  const user =
    lpFindSeller(username);

  if(
    !user ||
    user.active === false
  ){
    return null;
  }

  const expected =
    lpSellerPasswordGet(
      user.username,
      user.password
    );

  if(
    String(password||'') !==
    String(expected||'')
  ){
    return null;
  }

  user.password =
    expected;

  return user;
}

