function lpSellerSettings(){

  if(!lpIsSeller()){
    return;
  }

  lpRefreshRoleLabel();

  setHeader(
    'Mon compte',
    'Paramètres personnels du vendeur'
  );

  $('#content').innerHTML=`
    <div class="card">

      <h3>
        Mon compte vendeur
      </h3>

      <div class="form-grid">

        <label>
          Nom
          <input
            value="${esc(
              currentUser.name||''
            )}"
            disabled
          >
        </label>

        <label>
          Identifiant
          <input
            value="${esc(
              currentUser.username||''
            )}"
            disabled
          >
        </label>

        <label>
          Rôle
          <input
            value="Vendeur"
            disabled
          >
        </label>

        <label>
          Nouveau mot de passe
          <input
            id="sellerNewPassword"
            type="password"
            minlength="6"
            autocomplete="new-password"
            placeholder="Minimum 6 caractères"
          >
        </label>

      </div>

      <div style="margin-top:16px">

        <button
          class="primary"
          id="sellerPasswordSave"
        >
          Modifier mon mot de passe
        </button>

      </div>

      <p class="muted">
        Vous pouvez modifier uniquement
        votre propre mot de passe.
      </p>

    </div>
  `;

  $('#sellerPasswordSave')
    .onclick=()=>{

      const field =
        $('#sellerNewPassword');

      const password =
        String(
          field.value||''
        );

      if(
        password.length < 6
      ){

        alert(
          'Le mot de passe doit contenir au moins 6 caractères.'
        );

        return;
      }

      const username =
        String(
          currentUser.username||
          ''
        )
        .trim()
        .toLowerCase();

      const user =
        lpFindSeller(
          username
        );

      if(!user){

        alert(
          'Compte vendeur introuvable.'
        );

        return;
      }

      if(
        !lpSellerPasswordSave(
          username,
          password
        )
      ){

        alert(
          'Erreur : le mot de passe n’a pas été sauvegardé.'
        );

        return;
      }

      user.password =
        password;

      currentUser.password =
        password;

      try{
        save();
      }catch(ex){}

      if(
        lpSellerPasswordGet(
          username,
          ''
        ) !== password
      ){

        alert(
          'Erreur de vérification du nouveau mot de passe.'
        );

        return;
      }

      field.value='';

      alert(
        'Mot de passe modifié avec succès. Reconnexion obligatoire.'
      );

      setTimeout(
        lpForceLogin,
        400
      );
    };

  setTimeout(
    lpSellerApplyPermissions,
    0
  );
}

