function lp16PersonalSettings(){

  if(
    !currentUser ||
    lp16IsDG() ||
    lp16Role() ===
      'vendeur'
  ){
    return;
  }

  setHeader(
    'Mon compte',
    'Sécurité personnelle'
  );

  $('#content').innerHTML =
    `
      <div class="card">

        <h3>
          Mon compte
        </h3>

        <div class="form-grid">

          <label>
            Nom

            <input
              value="${esc(
                currentUser.name ||
                ''
              )}"
              disabled
            >
          </label>

          <label>
            Identifiant

            <input
              value="${esc(
                currentUser.username ||
                ''
              )}"
              disabled
            >
          </label>

          <label>
            Rôle

            <input
              value="${esc(
                currentUser.role ||
                ''
              )}"
              disabled
            >
          </label>

          <label>
            Nouveau mot de passe

            <input
              id="lp16MyPassword"
              type="password"
              minlength="6"
              autocomplete="new-password"
            >
          </label>

        </div>

        <div
          style="margin-top:16px"
        >

          <button
            class="primary"
            id="lp16MyPasswordSave"
          >
            Modifier mon mot de passe
          </button>

        </div>

      </div>
    `;

  $('#lp16MyPasswordSave')
    .onclick =
      ()=>{

        const password =
          String(
            $('#lp16MyPassword')
              .value ||
            ''
          );

        if(
          password.length <
          6
        ){

          alert(
            'Le mot de passe doit contenir au moins 6 caractères.'
          );

          return;
        }

        const user =
          lp16FindUser(
            currentUser
              .username
          );

        if(!user){

          alert(
            'Compte introuvable.'
          );

          return;
        }

        user.password =
          password;

        currentUser.password =
          password;

        lp16Save();

        alert(
          'Mot de passe modifié. Reconnexion obligatoire.'
        );

        setTimeout(
          ()=>{

            try{
              lpForceLogin();
            }catch(ex){}

          },
          400
        );
      };
}

