function lp161PersistUsers(){

  try{

    if(
      db &&
      Array.isArray(
        db.users
      )
    ){

      save();

      /*
       * Vérification immédiate
       * de la sauvegarde locale.
       */

      const stored =
        JSON.parse(
          localStorage.getItem(
            'lpmp_v13'
          ) || 'null'
        );

      if(
        !stored ||
        !Array.isArray(
          stored.users
        )
      ){

        console.error(
          'SECURITE 16.1 : vérification utilisateurs impossible'
        );
      }
    }

  }catch(e){

    console.error(
      'SECURITE 16.1 persistance',
      e
    );
  }
}

