/* ==================================================
   LEADER PHARMA V1.4
   SECURITE 16.1 - RETIRER RESTAURER VENDEUR
   ================================================== */

function lp161IsSeller(){

  return !!(
    currentUser &&
    String(
      currentUser.role ||
      ''
    )
    .trim()
    .toLowerCase() ===
    'vendeur'
  );
}

function lp161Normalize(v){

  return String(
    v || ''
  )
  .trim()
  .toLowerCase()
  .normalize('NFD')
  .replace(
    /[\u0300-\u036f]/g,
    ''
  );
}

function lp161HideRestore(){

  if(
    !lp161IsSeller()
  ){
    return;
  }

  document
    .querySelectorAll(
      'button,a,[role="button"],[data-page],div,span'
    )
    .forEach(
      el=>{

        const text =
          lp161Normalize(
            el.textContent
          );

        if(
          text ===
          'restaurer'
        ){

          el.style.display =
            'none';
        }
      }
    );
}

/*
 * Bloquer également l'action
 * même si un élément Restaurer
 * devenait visible.
 */

document.addEventListener(
  'click',
  function(e){

    if(
      !lp161IsSeller()
    ){
      return;
    }

    const target =
      e.target.closest(
        'button,a,[role="button"],[data-page],div,span'
      );

    if(!target){
      return;
    }

    const text =
      lp161Normalize(
        target.textContent
      );

    if(
      text ===
      'restaurer'
    ){

      e.preventDefault();
      e.stopImmediatePropagation();

      return false;
    }
  },
  true
);

/*
 * Réappliquer après chaque render.
 */

const lp161RenderBase =
  render;

render =
  function(){

    const result =
      lp161RenderBase.apply(
        this,
        arguments
      );

    setTimeout(
      lp161HideRestore,
      0
    );

    return result;
  };

/*
 * Sécurité supplémentaire pour
 * les changements dynamiques
 * de tableau de bord.
 */

const lp161Observer =
  new MutationObserver(
    ()=>{
      lp161HideRestore();
    }
  );

if(
  document.body
){

  lp161Observer.observe(
    document.body,
    {
      childList:true,
      subtree:true
    }
  );
}

setTimeout(
  lp161HideRestore,
  0
);



/* ==================================================
   LEADER PHARMA V1.4
   SECURITE 16.2 - TABLEAUX DE BORD PAR ROLE
   ================================================== */

function lp162Norm(v){

  return String(v||'')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp162Role(){

  return lp162Norm(
    currentUser?.role || ''
  );
}

function lp162IsDG(){

  if(!currentUser){
    return false;
  }

  return (
    lp162Norm(
      currentUser.username
    ) === 'leader.fr' ||

    lp162Role() === 'dg' ||

    lp162Role() ===
      'direction generale'
  );
}

function lp162RoleTitle(){

  const role =
    lp162Role();

  const titles = {
    pharmacien:'Pharmacien',
    caissier:'Caissier',
    magasinier:'Magasinier',
    comptable:'Comptable',
    gerant:'Gérant',
    vendeur:'Vendeur'
  };

  return (
    titles[role] ||
    String(
      currentUser?.role ||
      'Utilisateur'
    )
  );
}

function lp162AgencyLabel(){

  try{

    if(
      typeof agencyName ===
      'function'
    ){
      return agencyName();
    }

  }catch(e){}

  return 'Leader Pharma Kamina';
}

