function lp162Allowed(
  pageName,
  text
){

  if(
    !currentUser ||
    lp162IsDG()
  ){
    return true;
  }

  /*
   * Le Vendeur reste géré
   * par la sécurité vendeur existante.
   */

  if(
    lp162Role() ===
    'vendeur'
  ){
    return true;
  }

  const list =
    LP162_ALLOWED[
      lp162Role()
    ] || [];

  const value =
    lp162Norm(
      String(
        pageName || ''
      ) +
      ' ' +
      String(
        text || ''
      )
    );

  return list.some(
    item =>
      value.includes(
        lp162Norm(item)
      )
  );
}

function lp162ApplyMenus(){

  if(
    !currentUser ||
    lp162IsDG() ||
    lp162Role() ===
      'vendeur'
  ){
    return;
  }

  document
    .querySelectorAll(
      '[data-page],nav a,nav button,.nav-item,.menu-item,.sidebar a,.sidebar button'
    )
    .forEach(
      el=>{

        /*
         * Toujours repartir
         * d'un affichage propre.
         */

        el.style
          .removeProperty(
            'display'
          );

        if(
          !lp162Allowed(
            el.dataset?.page,
            el.textContent
          )
        ){
          el.style.display =
            'none';
        }
      }
    );

  /*
   * Fonctions Direction
   * toujours interdites.
   */

  document
    .querySelectorAll(
      'button,a,[role="button"]'
    )
    .forEach(
      el=>{

        const text =
          lp162Norm(
            el.textContent
          );

        if(
          text.includes(
            'utilisateur'
          ) ||
          text.includes(
            'surveillance'
          ) ||
          text.includes(
            'sauvegarde'
          ) ||
          text ===
            'restaurer' ||
          text.includes(
            'mise a jour'
          )
        ){
          el.style.display =
            'none';
        }
      }
    );
}

/*
 * ==================================================
 * DONNEES PERSONNELLES
 * ==================================================
 */

function lp162TodaySales(){

  if(
    !db ||
    !Array.isArray(
      db.sales
    )
  ){
    return [];
  }

  const username =
    lp162Norm(
      currentUser?.username
    );

  const name =
    lp162Norm(
      currentUser?.name
    );

  return db.sales.filter(
    x=>{

      if(
        x.agency !==
          currentAgency ||
        x.date !==
          today() ||
        x.status ===
          'Annulée'
      ){
        return false;
      }

      const seller =
        lp162Norm(
          x.seller
        );

      return (
        seller === username ||
        seller === name
      );
    }
  );
}

function lp162AllTodaySales(){

  if(
    !db ||
    !Array.isArray(
      db.sales
    )
  ){
    return [];
  }

  return db.sales.filter(
    x =>
      x.agency ===
        currentAgency &&
      x.date ===
        today() &&
      x.status !==
        'Annulée'
  );
}

function lp162StockCount(){

  try{

    if(
      Array.isArray(
        db.products
      )
    ){
      return db.products
        .filter(
          x =>
            !x.agency ||
            x.agency ===
              currentAgency
        )
        .length;
    }

  }catch(e){}

  return 0;
}

function lp162ClientsCount(){

  try{

    if(
      Array.isArray(
        db.clients
      )
    ){
      return db.clients
        .length;
    }

  }catch(e){}

  return 0;
}

function lp162MoneyTotal(
  sales
){

  return (
    sales || []
  ).reduce(
    (sum,x)=>
      sum +
      (
        Number(
          x.total
        ) || 0
      ),
    0
  );
}

