function lp162RoleDashboard(){

  if(
    !currentUser ||
    lp162IsDG() ||
    lp162Role() ===
      'vendeur'
  ){
    return false;
  }

  switch(
    lp162Role()
  ){

    case 'pharmacien':
      lp162DashboardPharmacien();
      return true;

    case 'caissier':
      lp162DashboardCaissier();
      return true;

    case 'magasinier':
      lp162DashboardMagasinier();
      return true;

    case 'comptable':
      lp162DashboardComptable();
      return true;

    case 'gerant':
      lp162DashboardGerant();
      return true;
  }

  return false;
}

