/* ==================================================
   LEADER PHARMA V1.4
   SECURITE 16.3 - GESTION COMPLETE UTILISATEURS
   ================================================== */

function lp163Norm(v){
  return String(v||'')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp163IsDG(){
  return !!(
    currentUser &&
    (
      lp163Norm(
        currentUser.username
      ) === 'leader.fr' ||
      lp163Norm(
        currentUser.role
      ) === 'dg'
    )
  );
}

function lp163FindUser(username){

  if(
    !db ||
    !Array.isArray(db.users)
  ){
    return null;
  }

  const key =
    lp163Norm(username);

  return (
    db.users.find(
      u =>
        lp163Norm(
          u.username
        ) === key
    ) || null
  );
}

function lp163Save(){

  try{
    save();
  }catch(e){}

  try{
    if(
      typeof lp161PersistUsers ===
      'function'
    ){
      lp161PersistUsers();
    }
  }catch(e){}
}

function lp163SellerPasswordsRead(){

  try{

    return JSON.parse(
      localStorage.getItem(
        'leader_pharma_seller_passwords_v11'
      ) || '{}'
    ) || {};

  }catch(e){
    return {};
  }
}

function lp163SellerPasswordDelete(
  username
){

  try{

    const all =
      lp163SellerPasswordsRead();

    delete all[
      lp163Norm(username)
    ];

    localStorage.setItem(
      'leader_pharma_seller_passwords_v11',
      JSON.stringify(all)
    );

  }catch(e){}
}

function lp163SellerPasswordRename(
  oldUsername,
  newUsername,
  password
){

  try{

    const all =
      lp163SellerPasswordsRead();

    delete all[
      lp163Norm(oldUsername)
    ];

    all[
      lp163Norm(newUsername)
    ] =
      String(password||'');

    localStorage.setItem(
      'leader_pharma_seller_passwords_v11',
      JSON.stringify(all)
    );

  }catch(e){}
}

/* ==========================================
   AJOUTER LES BOUTONS
   MODIFIER + SUPPRIMER
   ========================================== */

function lp163EnhanceUsersPage(){

  if(!lp163IsDG()){
    return;
  }

  document
    .querySelectorAll(
      '.lp16-toggle'
    )
    .forEach(
      toggle=>{

        const username =
          String(
            toggle.dataset.user ||
            ''
          );

        if(!username){
          return;
        }

        const zone =
          toggle.parentElement;

        if(!zone){
          return;
        }

        if(
          !zone.querySelector(
            '.lp163-edit'
          )
        ){

          const edit =
            document.createElement(
              'button'
            );

          edit.className =
            'secondary lp163-edit';

          edit.dataset.user =
            username;

          edit.textContent =
            'Modifier';

          zone.appendChild(
            edit
          );
        }

        if(
          !zone.querySelector(
            '.lp163-delete'
          )
        ){

          const del =
            document.createElement(
              'button'
            );

          del.className =
            'secondary lp163-delete';

          del.dataset.user =
            username;

          del.textContent =
            'Supprimer';

          zone.appendChild(
            del
          );
        }
      }
    );
}

/* ==========================================
   MODIFIER UTILISATEUR
   ========================================== */

function lp163EditUser(username){

  if(!lp163IsDG()){
    return;
  }

  const user =
    lp163FindUser(
      username
    );

  if(!user){
    alert(
      'Utilisateur introuvable.'
    );
    return;
  }

  if(
    lp163Norm(
      user.username
    ) === 'leader.fr'
  ){
    alert(
      'Le compte Direction ne peut pas être modifié ici.'
    );
    return;
  }

  const oldUsername =
    String(
      user.username ||
      ''
    );

  const newName =
    prompt(
      'Nom complet :',
      String(
        user.name ||
        ''
      )
    );

  if(newName === null){
    return;
  }

  const newUsername =
    prompt(
      'Identifiant :',
      String(
        user.username ||
        ''
      )
    );

  if(newUsername === null){
    return;
  }

  const cleanName =
    String(
      newName
    ).trim();

  const cleanUsername =
    String(
      newUsername
    ).trim();

  if(
    !cleanName ||
    !cleanUsername
  ){
    alert(
      'Nom et identifiant sont obligatoires.'
    );
    return;
  }

  if(
    lp163Norm(
      cleanUsername
    ) ===
    'leader.fr'
  ){
    alert(
      'Cet identifiant est réservé à la Direction.'
    );
    return;
  }

  const existing =
    db.users.find(
      u =>
        u !== user &&
        lp163Norm(
          u.username
        ) ===
        lp163Norm(
          cleanUsername
        )
    );

  if(existing){
    alert(
      'Cet identifiant existe déjà.'
    );
    return;
  }

  const roles = [
    'Vendeur',
    'Pharmacien',
    'Caissier',
    'Magasinier',
    'Comptable',
    'Gérant'
  ];

  const roleText =
    prompt(
      'Rôle : Vendeur, Pharmacien, Caissier, Magasinier, Comptable ou Gérant',
      String(
        user.role ||
        'Vendeur'
      )
    );

  if(roleText === null){
    return;
  }

  const wanted =
    lp163Norm(
      roleText
    );

  const role =
    roles.find(
      r =>
        lp163Norm(r) ===
        wanted
    );

  if(!role){
    alert(
      'Rôle non reconnu.'
    );
    return;
  }

  user.name =
    cleanName;

  user.username =
    cleanUsername;

  user.role =
    role;

  /*
   * Synchroniser le stockage
   * spécial du vendeur.
   */

  if(
    lp163Norm(role) ===
    'vendeur'
  ){

    lp163SellerPasswordRename(
      oldUsername,
      cleanUsername,
      user.password
    );

  }else{

    lp163SellerPasswordDelete(
      oldUsername
    );

    lp163SellerPasswordDelete(
      cleanUsername
    );
  }

  lp163Save();

  try{
    audit(
      'Utilisateur modifié',
      oldUsername +
      ' -> ' +
      cleanUsername +
      ' • ' +
      role
    );
  }catch(e){}

  alert(
    'Utilisateur modifié avec succès.'
  );

  if(
    typeof lp16UsersPage ===
    'function'
  ){
    lp16UsersPage();

    setTimeout(
      lp163EnhanceUsersPage,
      50
    );
  }
}

/* ==========================================
   SUPPRIMER UTILISATEUR
   ========================================== */

function lp163DeleteUser(username){

  if(!lp163IsDG()){
    return;
  }

  const user =
    lp163FindUser(
      username
    );

  if(!user){
    alert(
      'Utilisateur introuvable.'
    );
    return;
  }

  if(
    lp163Norm(
      user.username
    ) ===
    'leader.fr' ||
    lp163Norm(
      user.role
    ) === 'dg'
  ){
    alert(
      'Le compte Direction ne peut pas être supprimé.'
    );
    return;
  }

  const ok =
    confirm(
      'Supprimer définitivement le compte "' +
      String(
        user.username ||
        ''
      ) +
      '" ?'
    );

  if(!ok){
    return;
  }

  const usernameSaved =
    String(
      user.username ||
      ''
    );

  db.users =
    db.users.filter(
      u => u !== user
    );

  lp163SellerPasswordDelete(
    usernameSaved
  );

  lp163Save();

  try{
    audit(
      'Utilisateur supprimé',
      usernameSaved
    );
  }catch(e){}

  alert(
    'Utilisateur supprimé avec succès.'
  );

  if(
    typeof lp16UsersPage ===
    'function'
  ){
    lp16UsersPage();

    setTimeout(
      lp163EnhanceUsersPage,
      50
    );
  }
}

