function lp166Allowed(text, role){

  if(role === 'dg'){
    return true;
  }

  const allowed =
    LP166_ACCESS[role] || [];

  return allowed.some(
    key =>
      text.includes(key)
  );
}

function lp166MenuItems(){

  return Array.from(
    document.querySelectorAll(
      'nav a,nav button,.nav-item,.menu-item,.sidebar a,.sidebar button,[data-page]'
    )
  );
}

function lp166ApplyMenus(){

  const role = lp166Role();

  if(!role){
    return;
  }

  lp166MenuItems().forEach(
    el => {

      const text =
        lp166Norm(
          el.textContent
        );

      /*
       * Ne jamais modifier le bouton
       * de deconnexion.
       */

      if(
        text.includes('deconnexion') ||
        text.includes("changer d'utilisateur")
      ){
        return;
      }

      if(
        lp166Allowed(
          text,
          role
        )
      ){
        el.style.removeProperty(
          'display'
        );

        el.hidden = false;

        el.removeAttribute(
          'aria-hidden'
        );
      }
      else{
        el.style.setProperty(
          'display',
          'none',
          'important'
        );

        el.hidden = true;

        el.setAttribute(
          'aria-hidden',
          'true'
        );
      }
    }
  );
}

/*
 * Restaurer est exclusivement DG.
 */

function lp166ProtectRestore(){

  const role = lp166Role();

  document
    .querySelectorAll(
      'button,a,[role="button"]'
    )
    .forEach(
      el => {

        const text =
          lp166Norm(
            el.textContent
          );

        if(text === 'restaurer'){

          if(role === 'dg'){
            el.style.removeProperty(
              'display'
            );
            el.hidden = false;
          }
          else{
            el.style.setProperty(
              'display',
              'none',
              'important'
            );
            el.hidden = true;
          }
        }
      }
    );
}

/*
 * Sauvegarder est également reserve DG.
 */

function lp166ProtectBackup(){

  const role = lp166Role();

  document
    .querySelectorAll(
      'button,a,[role="button"]'
    )
    .forEach(
      el => {

        const text =
          lp166Norm(
            el.textContent
          );

        if(text === 'sauvegarder'){

          if(role === 'dg'){
            el.style.removeProperty(
              'display'
            );
            el.hidden = false;
          }
          else{
            el.style.setProperty(
              'display',
              'none',
              'important'
            );
            el.hidden = true;
          }
        }
      }
    );
}

/*
 * Protection au clic :
 * une rubrique interdite ne peut pas
 * etre ouverte meme si un ancien bloc
 * la rend momentanement visible.
 */

document.addEventListener(
  'click',
  function(e){

    const role =
      lp166Role();

    if(!role){
      return;
    }

    const target =
      e.target.closest(
        'nav a,nav button,.nav-item,.menu-item,.sidebar a,.sidebar button,[data-page],button,a'
      );

    if(!target){
      return;
    }

    const text =
      lp166Norm(
        target.textContent
      );

    if(
      text.includes('deconnexion') ||
      text.includes("changer d'utilisateur")
    ){
      return;
    }

    if(
      text === 'restaurer' ||
      text === 'sauvegarder'
    ){
      if(role !== 'dg'){
        e.preventDefault();
        e.stopImmediatePropagation();
        return false;
      }

      return;
    }

    /*
     * Ne filtrer ici que les vrais
     * elements de navigation.
     */

    if(
      target.matches(
        'nav a,nav button,.nav-item,.menu-item,.sidebar a,.sidebar button,[data-page]'
      )
    ){
      if(
        !lp166Allowed(
          text,
          role
        )
      ){
        e.preventDefault();
        e.stopImmediatePropagation();
        return false;
      }
    }
  },
  true
);

function lp166Apply(){

  lp166ApplyMenus();
  lp166ProtectRestore();
  lp166ProtectBackup();
}

/*
 * Appliquer apres chaque rendu.
 */

const lp166PreviousRender =
  render;

render =
  function(){

    const result =
      lp166PreviousRender.apply(
        this,
        arguments
      );

    setTimeout(
      lp166Apply,
      20
    );

    return result;
  };

/*
 * Les anciennes couches peuvent
 * encore modifier le DOM apres render.
 * On impose donc la politique finale.
 */

let lp166Timer = null;

const lp166Observer =
  new MutationObserver(
    function(){

      clearTimeout(
        lp166Timer
      );

      lp166Timer =
        setTimeout(
          lp166Apply,
          30
        );
    }
  );

if(document.body){

  lp166Observer.observe(
    document.body,
    {
      childList:true,
      subtree:true
    }
  );
}

setTimeout(
  lp166Apply,
  50
);

setTimeout(
  lp166Apply,
  300
);

setTimeout(
  lp166Apply,
  1000
);



