function lp169Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp169Role(){

  if(!currentUser){
    return '';
  }

  const username =
    lp169Norm(
      currentUser.username
    );

  const rawRole =
    lp169Norm(
      currentUser.role
    );

  if(
    username === 'leader.fr' ||
    rawRole === 'dg' ||
    rawRole.includes(
      'direction generale'
    ) ||
    rawRole.includes(
      'directeur general'
    )
  ){
    return 'dg';
  }

  if(
    rawRole.includes(
      'pharmac'
    )
  ){
    return 'pharmacien';
  }

  if(
    rawRole.includes(
      'vendeur'
    ) ||
    rawRole === 'vente'
  ){
    return 'vendeur';
  }

  if(
    rawRole.includes(
      'caiss'
    ) ||
    rawRole === 'caisse'
  ){
    return 'caissier';
  }

  if(
    rawRole.includes(
      'magasin'
    ) ||
    rawRole === 'stock'
  ){
    return 'magasinier';
  }

  if(
    rawRole.includes(
      'comptable'
    ) ||
    rawRole.includes(
      'comptabil'
    )
  ){
    return 'comptable';
  }

  if(
    rawRole.includes(
      'gerant'
    ) ||
    rawRole.includes(
      'gestionnaire'
    )
  ){
    return 'gerant';
  }

  return 'standard';
}

