function lp169MenuItems(){

  return Array.from(
    document.querySelectorAll(
      '[data-page],nav a,nav button,.nav-item,.menu-item,.sidebar a,.sidebar button'
    )
  );
}

function lp169Show(el){

  if(!el){
    return;
  }

  el.hidden = false;

  el.removeAttribute(
    'hidden'
  );

  el.removeAttribute(
    'aria-hidden'
  );

  el.style.removeProperty(
    'display'
  );

  el.style.removeProperty(
    'visibility'
  );

  el.style.removeProperty(
    'opacity'
  );
}


function lp169Hide(el){

  if(!el){
    return;
  }

  /*
   * Une rubrique déjà validée pour
   * l'utilisateur courant ne doit
   * plus disparaître.
   */

  if(
    el.getAttribute &&
    el.getAttribute(
      'data-lp178-protected'
    ) === '1'
  ){
    lp169Show(el);
    return;
  }

  el.hidden = true;

  el.setAttribute(
    'aria-hidden',
    'true'
  );

  el.style.setProperty(
    'display',
    'none',
    'important'
  );
}



