function lp169ApplySensitive(){

  const role =
    lp169Role();

  if(!role){
    return;
  }

  document
    .querySelectorAll(
      'button,a,[role="button"],input[type="button"],input[type="submit"]'
    )
    .forEach(
      el=>{

            if(
      target.id === 'lpV11SavePrescription' ||
      target.id === 'lpV13SaveNote'
    ){
      return;
    }

const text =
          lp169Norm(
            el.textContent ||
            el.value ||
            ''
          );

        const sensitive =
          text === 'restaurer' ||
          text === 'sauvegarder' ||
          text.includes(
            'gestion utilisateurs'
          ) ||
          text.includes(
            'gerer utilisateurs'
          ) ||
          text.includes(
            'surveillance dg'
          );

        if(!sensitive){
          return;
        }

        if(role === 'dg'){
          lp169Show(el);
        }
        else{
          lp169Hide(el);
        }
      }
    );
}

