function lp169RoleTitle(){

  const role =
    lp169Role();

  const names = {
    dg:'DG',
    vendeur:'Vendeur',
    pharmacien:'Pharmacien',
    caissier:'Caissier',
    magasinier:'Magasinier',
    comptable:'Comptable',
    gerant:'Gérant',
    standard:'Utilisateur'
  };

  return (
    names[role] ||
    String(
      currentUser?.role ||
      ''
    )
  );
}

function lp169RefreshRoleLabel(){

  if(!currentUser){
    return;
  }

  const label =
    document.querySelector(
      '#currentAgencyLabel'
    );

  if(!label){
    return;
  }

  let agency =
    'Leader Pharma Kamina';

  try{

    if(
      typeof agencyName ===
      'function'
    ){
      agency =
        agencyName();
    }

  }catch(e){}

  const finalLabel =
    agency +
    ' • ' +
    lp169RoleTitle();

  /*
   * Ne modifier le DOM que
   * si le texte a réellement changé.
   */
  if(
    label.textContent !==
    finalLabel
  ){
    label.textContent =
      finalLabel;
  }
}

