/* ==================================================
   LEADER PHARMA V1.4
   17.8 MENUS PROTEGES
   ================================================== */

let lp178RoleKey = '';

let lp178Nodes = [];

function lp178CurrentKey(){

  if(
    typeof currentUser ===
      'undefined' ||
    !currentUser
  ){
    return '';
  }

  return String(
    currentUser.username || ''
  ) +
  '|' +
  String(
    currentUser.role || ''
  );
}

function lp178Role(){

  try{
    return lp169Role();
  }catch(e){
    return '';
  }
}

function lp178Anchor(){

  const label =
    document.querySelector(
      '#currentAgencyLabel'
    );

  if(
    label &&
    label.parentNode
  ){
    return label;
  }

  const logout =
    Array.from(
      document.querySelectorAll(
        'button,a'
      )
    ).find(
      el => {

        const t =
          String(
            el.textContent || ''
          )
          .toLowerCase();

        return (
          t.includes(
            'deconnexion'
          ) ||
          t.includes(
            'changer d'
          )
        );
      }
    );

  return logout || null;
}

function lp178Capture(){

  if(
    typeof currentUser ===
      'undefined' ||
    !currentUser
  ){
    return;
  }

  /*
   * DG totalement exclu
   * de cette correction.
   */

  if(lp178Role() === 'dg'){
    lp178Nodes = [];
    lp178RoleKey = '';
    return;
  }

  const key =
    lp178CurrentKey();

  if(
    key !== lp178RoleKey
  ){
    lp178Nodes = [];
    lp178RoleKey = key;
  }

  const items =
    Array.from(
      document.querySelectorAll(
        '[data-lp178-protected="1"]'
      )
    );

  /*
   * Capturer seulement quand
   * plusieurs rubriques correctes
   * existent réellement.
   */

  if(items.length >= 2){

    lp178Nodes =
      items.slice();

  }
}

function lp178Restore(){

  if(
    typeof currentUser ===
      'undefined' ||
    !currentUser
  ){
    return;
  }

  if(lp178Role() === 'dg'){
    return;
  }

  if(!lp178Nodes.length){
    lp178Capture();
    return;
  }

  const anchor =
    lp178Anchor();

  if(
    !anchor ||
    !anchor.parentNode
  ){
    return;
  }

  lp178Nodes.forEach(
    node => {

      node.hidden = false;

      node.removeAttribute(
        'hidden'
      );

      node.removeAttribute(
        'aria-hidden'
      );

      node.style.removeProperty(
        'display'
      );

      node.style.removeProperty(
        'visibility'
      );

      node.style.removeProperty(
        'opacity'
      );

      /*
       * Si render a retiré le bouton,
       * remettre le VRAI noeud original.
       * Les événements restent attachés.
       */

      if(!node.isConnected){

        anchor.parentNode.insertBefore(
          node,
          anchor
        );

      }
    }
  );
}

/*
 * Capturer après connexion.
 */

document.addEventListener(
  'click',
  function(){
    var lpV14AuthorizedAction =
      event && event.target && event.target.closest
      ? event.target.closest('#lpV11SavePrescription,#lpV13SaveNote')
      : null;

    if(lpV14AuthorizedAction){
      return;
    }


    setTimeout(
      function(){

        try{
          lp169ApplyMenus();
        }catch(e){}

        lp178Capture();
        lp178Restore();

      },
      50
    );

    setTimeout(
      lp178Restore,
      250
    );

    setTimeout(
      lp178Restore,
      600
    );

  },
  false
);

/*
 * Protéger les boutons pendant
 * les render() suivants.
 */

try{

  const lp178RenderBase =
    render;

  render =
    function(){

      /*
       * Avant render :
       * mémoriser les vrais boutons.
       */

      if(
        lp178Role() !== 'dg'
      ){
        lp178Capture();
      }

      const result =
        lp178RenderBase.apply(
          this,
          arguments
        );

      /*
       * Après render :
       * remettre uniquement
       * les boutons mémorisés.
       */

      if(
        lp178Role() !== 'dg'
      ){

        setTimeout(
          lp178Restore,
          0
        );

        setTimeout(
          lp178Restore,
          100
        );

        setTimeout(
          lp178Restore,
          300
        );

      }

      return result;
    };

}catch(e){}

/*
 * Changement d'utilisateur :
 * ne jamais garder le menu
 * du précédent.
 */

setInterval(
  function(){

    const key =
      lp178CurrentKey();

    if(
      key &&
      key !== lp178RoleKey
    ){

      lp178Nodes = [];
      lp178RoleKey = key;

      setTimeout(
        function(){

          try{
            lp169ApplyMenus();
          }catch(e){}

          lp178Capture();

        },
        100
      );
    }

  },
  1000
);

console.log(
  'Leader Pharma 17.8 menus proteges actif'
);



/* LEADER PHARMA 17.8.7 - LECTURE SEULE FINALE */

function lp1787Norm(v){
  return String(v||'')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp1787IsDG(){
  return lp1787Norm(currentUser?.role)==='dg';
}

function lp1787ProtectedPage(){
  if(lp1787IsDG())return false;

  const p=lp1787Norm(
    typeof page!=='undefined'
      ? page
      : ''
  );

  return [
    'stock',
    'inventory',
    'reports'
  ].includes(p);
}

const LP1787_BLOCKED=[
  'ajouter',
  'nouveau',
  'nouvelle',
  'creer',
  'créer',
  'modifier',
  'editer',
  'éditer',
  'supprimer',
  'corriger',
  'ajuster',
  'valider',
  'enregistrer',
  'sauvegarder',
  'entree stock',
  'entrée stock',
  'sortie stock',
  'transfert',
  'transferer',
  'transférer',
  'reception',
  'réception',
  'recevoir',
  'importer'
];

function lp1787ReadOnly(){

  if(
    !currentUser ||
    lp1787IsDG() ||
    !lp1787ProtectedPage()
  ){
    return;
  }

  document
    .querySelectorAll(
      'button,a,[role="button"],input[type="button"],input[type="submit"]'
    )
    .forEach(el=>{

      if(
        el.classList?.contains(
          'nav-btn'
        )
      ){
        return;
      }

      const text=lp1787Norm(
        el.textContent ||
        el.value ||
        el.getAttribute?.(
          'aria-label'
        ) ||
        ''
      );

      if(
        !LP1787_BLOCKED.some(
          x=>
            text.includes(
              lp1787Norm(x)
            )
        )
      ){
        return;
      }

      el.disabled=true;

      el.setAttribute(
        'aria-disabled',
        'true'
      );

      el.style.setProperty(
        'pointer-events',
        'none',
        'important'
      );

      el.style.setProperty(
        'opacity',
        '0.45',
        'important'
      );

      el.title=
        'Consultation uniquement';
    });
}

document.addEventListener(
  'click',
  function(e){

    if(
      !currentUser ||
      lp1787IsDG() ||
      !lp1787ProtectedPage()
    ){
      return;
    }

    const el=
      e.target.closest(
        'button,a,[role="button"],input[type="button"],input[type="submit"]'
      );

    if(
      !el ||
      el.classList?.contains(
        'nav-btn'
      )
    ){
      return;
    }

        if(
      el.id === 'lpV11SavePrescription' ||
      el.id === 'lpV13SaveNote'
    ){
      return;
    }

const text=
      lp1787Norm(
        el.textContent ||
        el.value ||
        ''
      );

    if(
      !LP1787_BLOCKED.some(
        x=>
          text.includes(
            lp1787Norm(x)
          )
      )
    ){
      return;
    }

    e.preventDefault();
    e.stopImmediatePropagation();

    try{
      toast(
        'Consultation uniquement'
      );
    }
    catch(err){}
  },
  true
);

try{
  const lp1787Render=render;

  render=function(){

    const result=
      lp1787Render.apply(
        this,
        arguments
      );

    lp1787ReadOnly();

    return result;
  };
}
catch(e){}



/* ================================================
   LEADER PHARMA 17.8.8
   CONSULTATION AUTORISEE HORS DG
   ================================================ */

function lp1788Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp1788IsDG(){

  return (
    lp1788Norm(
      currentUser?.role
    ) === 'dg'
  );
}

function lp1788ProtectedPage(){

  if(lp1788IsDG()){
    return false;
  }

  const value =
    lp1788Norm(
      typeof page !==
      'undefined'
        ? page
        : ''
    );

  return [
    'stock',
    'inventory',
    'reports'
  ].includes(value);
}

const LP1788_BLOCKED = [

  'ajouter',
  'nouveau',
  'nouvelle',
  'creer',
  'créer',

  'modifier',
  'editer',
  'éditer',

  'supprimer',

  'corriger',
  'ajuster',

  'valider',

  'enregistrer',
  'sauvegarder',

  'entree stock',
  'entrée stock',
  'sortie stock',

  'transfert',
  'transferer',
  'transférer',

  'reception',
  'réception',
  'recevoir',

  'importer'
];

function lp1788Text(el){

  return lp1788Norm(

    el?.textContent ||

    el?.value ||

    el?.getAttribute?.(
      'aria-label'
    ) ||

    el?.getAttribute?.(
      'title'
    ) ||

    ''
  );
}

function lp1788ReadOnly(){

  if(
    !currentUser ||
    lp1788IsDG() ||
    !lp1788ProtectedPage()
  ){
    return;
  }

  document
    .querySelectorAll(
      'button,a,[role="button"],input[type="button"],input[type="submit"]'
    )
    .forEach(
      el => {

        /*
         * Menu toujours actif.
         */
        if(
          el.classList?.contains(
            'nav-btn'
          )
        ){
          return;
        }

        const text =
          lp1788Text(el);

        if(!text){
          return;
        }

        const deny =
          LP1788_BLOCKED.some(
            word =>
              text.includes(
                lp1788Norm(word)
              )
          );

        if(!deny){
          return;
        }

        try{

          el.disabled = true;

          el.setAttribute(
            'aria-disabled',
            'true'
          );

          el.style.setProperty(
            'pointer-events',
            'none',
            'important'
          );

          el.style.setProperty(
            'opacity',
            '0.45',
            'important'
          );

          el.title =
            'Consultation uniquement';

        }
        catch(e){}
      }
    );
}

