function lp17810IsSeller(){

  if(!currentUser){
    return false;
  }

  const role =
    lp17810Norm(
      currentUser.role
    );

  return (
    role.includes('vendeur') ||
    role === 'vente'
  );
}

/*
 * Identifier uniquement :
 * - Ventes / Factures
 * - Alertes
 *
 * ET UNIQUEMENT POUR VENDEUR.
 */

function lp17810Target(el){

  if(
    !el ||
    !lp17810IsSeller()
  ){
    return '';
  }

  const value =
    lp17810Norm(
      String(
        el.dataset?.page ||
        ''
      ) +
      ' ' +
      String(
        el.dataset?.p ||
        ''
      ) +
      ' ' +
      String(
        el.dataset?.action ||
        ''
      ) +
      ' ' +
      String(
        el.getAttribute?.(
          'href'
        ) ||
        ''
      ) +
      ' ' +
      String(
        el.textContent ||
        ''
      )
    );

  /*
   * VENTES / FACTURES
   */
  if(
    value.includes('sales') ||
    value.includes('sale') ||
    value.includes('vente') ||
    value.includes('ventes') ||
    value.includes('facture') ||
    value.includes('factures')
  ){
    return 'sales';
  }

  /*
   * ALERTES
   */
  if(
    value.includes('alerts') ||
    value.includes('alert') ||
    value.includes('alerte') ||
    value.includes('alertes')
  ){
    return 'alerts';
  }

  return '';
}

