/* ================================================
   LEADER PHARMA 17.8.11
   VENTE FACTURE STABLE
   ================================================

   IMPORTANT :

   On NE CHANGE PAS :
   - le menu
   - Stock / Lots
   - Inventaires
   - Statistiques
   - Alertes
   - Parametres
   - Synchronisation
   - DG
   - mots de passe
   - impression
   - donnees

   Correction unique :

   Les anciens detecteurs 17.8.9 / 17.8.10
   doivent reagir UNIQUEMENT aux vrais boutons
   de navigation.

   Le texte "Lot AMX-001" d'un produit
   ne doit jamais etre interprete comme
   le menu Stock / Lots.
   ================================================ */

function lp17811Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp17811IsRealNav(el){

  if(!el){
    return false;
  }

  try{

    if(
      el.classList?.contains(
        'nav-btn'
      )
    ){
      return true;
    }

    if(
      el.dataset?.page
    ){
      return true;
    }

    if(
      el.dataset?.p
    ){
      return true;
    }

  }
  catch(e){}

  return false;
}

function lp17811NavValue(el){

  if(!el){
    return '';
  }

  const pageValue =
    String(
      el.dataset?.page ||
      el.dataset?.p ||
      ''
    );

  /*
   * Le texte n'est utilise
   * qu'apres confirmation qu'il
   * s'agit d'un vrai menu.
   */

  const textValue =
    lp17811IsRealNav(el)
      ? String(
          el.textContent || ''
        )
      : '';

  return lp17811Norm(
    pageValue +
    ' ' +
    textValue
  );
}

/*
 * =================================================
 * CORRIGER LE DETECTEUR 17.8.9
 * =================================================
 *
 * Les listeners 17.8.9 deja installes
 * appellent lp1789Target() au moment du clic.
 *
 * On remplace donc uniquement cette fonction.
 */

try{

  lp1789Target =
    function(el){

      if(
        !lp17811IsRealNav(el)
      ){
        return '';
      }

      const value =
        lp17811NavValue(el);

      /*
       * STOCK / LOTS
       */
      if(
        value.includes('stock') ||
        value.includes('stocks') ||
        value.includes('lot') ||
        value.includes('lots')
      ){
        return 'stock';
      }

      /*
       * INVENTAIRES
       */
      if(
        value.includes('inventory') ||
        value.includes('inventaire')
      ){
        return 'inventory';
      }

      /*
       * STATISTIQUES /
       * GRAPHIQUES /
       * RAPPORTS
       */
      if(
        value.includes('reports') ||
        value.includes('report') ||
        value.includes('rapport') ||
        value.includes('statistique') ||
        value.includes('graphique') ||
        value.includes('analyse')
      ){
        return 'reports';
      }

      return '';
    };

}
catch(e){

  console.error(
    '17.8.11 correction lp1789Target impossible',
    e
  );
}

/*
 * =================================================
 * CORRIGER AUSSI LE DETECTEUR 17.8.10
 * =================================================
 *
 * Ventes / Factures et Alertes
 * doivent aussi etre declenchees
 * uniquement depuis le menu.
 */

try{

  lp17810Target =
    function(el){

      if(
        !el ||
        !lp17810IsSeller()
      ){
        return '';
      }

      if(
        !lp17811IsRealNav(el)
      ){
        return '';
      }

      const value =
        lp17811NavValue(el);

      /*
       * VENTES / FACTURES
       */
      if(
        value.includes('sales') ||
        value.includes('sale') ||
        value.includes('vente') ||
        value.includes('ventes') ||
        value.includes('facture') ||
        value.includes('factures')
      ){
        return 'sales';
      }

      /*
       * ALERTES
       */
      if(
        value.includes('alerts') ||
        value.includes('alert') ||
        value.includes('alerte') ||
        value.includes('alertes')
      ){
        return 'alerts';
      }

      return '';
    };

}
catch(e){

  console.error(
    '17.8.11 correction lp17810Target impossible',
    e
  );
}

/*
 * =================================================
 * SECURITE PAGE SALES
 * =================================================
 *
 * Si l'utilisateur est deja dans Sales,
 * aucun clic sur une fiche produit,
 * un lot, une quantite ou le panier
 * ne doit etre pris pour une navigation
 * Stock / Inventory / Reports.
 */

function lp17811SalesGuard(){

  if(!currentUser){
    return;
  }

  const current =
    lp17811Norm(
      typeof page !==
        'undefined'
        ? page
        : ''
    );

  if(
    current !== 'sales'
  ){
    return;
  }

  /*
   * Reappliquer la lecture seule 17.8.8
   * seulement si necessaire.
   *
   * Sur Sales, lp1788ProtectedPage()
   * renvoie false : aucune action de vente
   * n'est donc bloquee.
   */

  try{

    if(
      typeof lp1788ReadOnly ===
      'function'
    ){
      lp1788ReadOnly();
    }

  }
  catch(e){}
}

/*
 * Apres rendu de Sales :
 * conserver la page et ses commandes.
 */

setTimeout(
  lp17811SalesGuard,
  0
);

console.log(
  'Leader Pharma 17.8.11 vente facture stable actif'
);



/* ================================================
   LEADER PHARMA V1.4
   17.8.12 SAUVEGARDE + JOURNAL AUDIT
   ================================================

   AJOUTS UNIQUEMENT :
   - sauvegarde locale automatique
   - sauvegarde avant mise a jour
   - journal audit
   - consultation audit DG dans Parametres

   AUCUNE MODIFICATION :
   - menus 17.8.11
   - ventes / factures
   - stock / lots
   - inventaires
   - statistiques
   - alertes
   - synchronisation Supabase
   - impression
   ================================================ */

const LP17812_AUDIT_KEY =
  'leaderPharmaAudit17812';

const LP17812_BACKUP_KEY =
  'leaderPharmaBackups17812';

const LP17812_DAILY_KEY =
  'leaderPharmaDailyBackup17812';

function lp17812Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp17812Role(){

  try{

    return lp17812Norm(
      currentUser?.role
    );

  }
  catch(e){

    return '';

  }
}

function lp17812IsDG(){

  const username =
    lp17812Norm(
      currentUser?.username
    );

  const role =
    lp17812Role();

  return (
    username === 'leader.fr' ||
    role === 'dg' ||
    role.includes(
      'direction generale'
    ) ||
    role.includes(
      'directeur general'
    )
  );
}

function lp17812Page(){

  try{

    return String(
      typeof page !==
        'undefined'
        ? page
        : ''
    );

  }
  catch(e){

    return '';

  }
}

function lp17812ReadJSON(
  key,
  fallback
){

  try{

    const raw =
      localStorage.getItem(
        key
      );

    if(!raw){
      return fallback;
    }

    return JSON.parse(
      raw
    );

  }
  catch(e){

    return fallback;

  }
}

function lp17812WriteJSON(
  key,
  value
){

  try{

    localStorage.setItem(
      key,
      JSON.stringify(
        value
      )
    );

    return true;

  }
  catch(e){

    console.error(
      '17.8.12 stockage impossible',
      key,
      e
    );

    return false;

  }
}

/*
 * JOURNAL AUDIT
 */

function lp17812Audit(
  action,
  detail,
  result
){

  try{

    const list =
      lp17812ReadJSON(
        LP17812_AUDIT_KEY,
        []
      );

    list.unshift({
      date:
        new Date()
          .toISOString(),

      utilisateur:
        String(
          currentUser?.username ||
          'Non connecte'
        ),

      role:
        String(
          currentUser?.role ||
          ''
        ),

      page:
        lp17812Page(),

      action:
        String(
          action || ''
        ),

      resultat:
        String(
          result ||
          'OK'
        ),

      detail:
        String(
          detail || ''
        )
    });

    /*
     * Garder les 2000 dernieres actions.
     */

    if(list.length > 2000){

      list.length =
        2000;

    }

    lp17812WriteJSON(
      LP17812_AUDIT_KEY,
      list
    );

  }
  catch(e){}
}

/*
 * CREER UNE SAUVEGARDE
 * DES DONNEES LOCALES.
 *
 * On exclut les propres cles
 * audit / sauvegarde pour eviter
 * la duplication recursive.
 */

function lp17812Snapshot(
  reason
){

  const data = {};

  try{

    for(
      let i = 0;
      i < localStorage.length;
      i++
    ){

      const key =
        localStorage.key(i);

      if(!key){
        continue;
      }

      if(
        key === LP17812_AUDIT_KEY ||
        key === LP17812_BACKUP_KEY ||
        key === LP17812_DAILY_KEY
      ){
        continue;
      }

      data[key] =
        localStorage.getItem(
          key
        );
    }

    const backups =
      lp17812ReadJSON(
        LP17812_BACKUP_KEY,
        []
      );

    const item = {
      id:
        Date.now(),

      date:
        new Date()
          .toISOString(),

      reason:
        String(
          reason ||
          'Sauvegarde'
        ),

      utilisateur:
        String(
          currentUser?.username ||
          ''
        ),

      count:
        Object.keys(
          data
        ).length,

      data:
        data
    };

    backups.unshift(
      item
    );

    /*
     * Garder les 10 dernieres.
     */

    if(backups.length > 10){

      backups.length =
        10;

    }

    const ok =
      lp17812WriteJSON(
        LP17812_BACKUP_KEY,
        backups
      );

    if(!ok){
      return false;
    }

    /*
     * Verification simple :
     * la sauvegarde doit etre
     * relisible immediatement.
     */

    const check =
      lp17812ReadJSON(
        LP17812_BACKUP_KEY,
        []
      );

    const valid =
      Array.isArray(check) &&
      check.length > 0 &&
      check[0]?.id ===
        item.id;

    lp17812Audit(
      'SAUVEGARDE',
      item.reason +
        ' • ' +
        item.count +
        ' cles locales',
      valid
        ? 'OK'
        : 'ERREUR'
    );

    return valid;

  }
  catch(e){

    lp17812Audit(
      'SAUVEGARDE',
      String(e),
      'ERREUR'
    );

    return false;

  }
}

/*
 * SAUVEGARDE QUOTIDIENNE
 */

function lp17812DailyBackup(){

  try{

    const today =
      new Date()
        .toISOString()
        .slice(
          0,
          10
        );

    const last =
      localStorage.getItem(
        LP17812_DAILY_KEY
      );

    if(last === today){
      return;
    }

    if(
      lp17812Snapshot(
        'Sauvegarde quotidienne automatique'
      )
    ){

      localStorage.setItem(
        LP17812_DAILY_KEY,
        today
      );

    }

  }
  catch(e){}
}

/*
 * SAUVEGARDE AVANT
 * TOUTE MISE A JOUR.
 */

document.addEventListener(
  'click',
  function(e){

    const el =
      e.target.closest(
        'button,a,[role="button"],input[type="button"],input[type="submit"]'
      );

    if(!el){
      return;
    }

    const text =
      lp17812Norm(
        el.textContent ||
        el.value ||
        el.getAttribute?.(
          'aria-label'
        ) ||
        ''
      );

    const update =
      text.includes(
        'mise a jour'
      ) ||
      text.includes(
        'mettre a jour'
      ) ||
      text.includes(
        'installer mise'
      ) ||
      text.includes(
        'telecharger mise'
      );

    if(!update){
      return;
    }

    const ok =
      lp17812Snapshot(
        'Avant mise a jour'
      );

    if(!ok){

      e.preventDefault();

      e.stopImmediatePropagation();

      try{

        alert(
          'Mise à jour bloquée : la sauvegarde de sécurité a échoué.'
        );

      }
      catch(err){}

      return;
    }

    lp17812Audit(
      'MISE A JOUR',
      text,
      'SAUVEGARDE OK'
    );

  },
  true
);

/*
 * AUDIT DES ACTIONS UTILISATEURS
 */

document.addEventListener(
  'click',
  function(e){

    if(!currentUser){
      return;
    }

    const el =
      e.target.closest(
        'button,a,[role="button"],.nav-btn,[data-page],[data-p],input[type="button"],input[type="submit"]'
      );

    if(!el){
      return;
    }

    const action =
      String(
        el.textContent ||
        el.value ||
        el.dataset?.page ||
        el.dataset?.p ||
        ''
      )
      .trim();

    if(!action){
      return;
    }

    let result =
      'OK';

    if(
      el.disabled ||
      el.getAttribute?.(
        'aria-disabled'
      ) === 'true'
    ){

      result =
        'REFUSE';

    }

    lp17812Audit(
      action,
      'Interaction utilisateur',
      result
    );

  },
  false
);

/*
 * AUDIT CONNEXION / DECONNEXION
 * par detection de l'etat utilisateur.
 */

let lp17812LastUser =
  '';

setInterval(
  function(){

    const now =
      String(
        currentUser?.username ||
        ''
      );

    if(
      now !==
      lp17812LastUser
    ){

      if(
        lp17812LastUser &&
        !now
      ){

        lp17812Audit(
          'DECONNEXION',
          lp17812LastUser,
          'OK'
        );

      }

      if(
        now
      ){

        lp17812Audit(
          'CONNEXION',
          now,
          'OK'
        );

      }

      lp17812LastUser =
        now;
    }

  },
  1000
);

/*
 * INTERFACE DG DANS PARAMETRES.
 *
 * Elle apparait seulement
 * lorsque DG ouvre Parametres.
 */

function lp17812AuditPanel(){

  if(
    !currentUser ||
    !lp17812IsDG()
  ){
    return;
  }

  const current =
    lp17812Norm(
      lp17812Page()
    );

  if(
    current !== 'settings'
  ){
    return;
  }

  if(
    document.getElementById(
      'lp17812-audit-panel'
    )
  ){
    return;
  }

  const host =
    document.querySelector(
      'main,.content,.page,.container'
    ) ||
    document.body;

  if(!host){
    return;
  }

  const panel =
    document.createElement(
      'section'
    );

  panel.id =
    'lp17812-audit-panel';

  panel.style.cssText =
    'margin:20px 0;' +
    'padding:16px;' +
    'border:1px solid #ddd;' +
    'border-radius:12px;' +
    'background:#fff;';

  const title =
    document.createElement(
      'h3'
    );

  title.textContent =
    'Journal d’audit';

  panel.appendChild(
    title
  );

  const info =
    document.createElement(
      'p'
    );

  info.textContent =
    'Utilisateur • Rôle • Date/Heure • Rubrique • Action • Résultat • Détail';

  panel.appendChild(
    info
  );

  const controls =
    document.createElement(
      'div'
    );

  controls.style.cssText =
    'display:flex;' +
    'gap:8px;' +
    'flex-wrap:wrap;' +
    'margin-bottom:12px;';

  const refresh =
    document.createElement(
      'button'
    );

  refresh.type =
    'button';

  refresh.textContent =
    'Actualiser journal';

  const backup =
    document.createElement(
      'button'
    );

  backup.type =
    'button';

  backup.textContent =
    'Sauvegarder maintenant';

  const restore =
    document.createElement(
      'button'
    );

  restore.type =
    'button';

  restore.textContent =
    'Restaurer dernière sauvegarde';

  controls.appendChild(
    refresh
  );

  controls.appendChild(
    backup
  );

  controls.appendChild(
    restore
  );

  panel.appendChild(
    controls
  );

  const tableWrap =
    document.createElement(
      'div'
    );

  tableWrap.style.cssText =
    'overflow:auto;' +
    'max-height:380px;';

  panel.appendChild(
    tableWrap
  );

  function draw(){

    const list =
      lp17812ReadJSON(
        LP17812_AUDIT_KEY,
        []
      );

    const rows =
      list
        .slice(
          0,
          200
        )
        .map(
          item => {

            const date =
              String(
                item.date ||
                ''
              )
              .replace(
                'T',
                ' '
              )
              .slice(
                0,
                19
              );

            return (
              '<tr>' +
              '<td>' +
              date +
              '</td>' +
              '<td>' +
              String(
                item.utilisateur ||
                ''
              ) +
              '</td>' +
              '<td>' +
              String(
                item.role ||
                ''
              ) +
              '</td>' +
              '<td>' +
              String(
                item.page ||
                ''
              ) +
              '</td>' +
              '<td>' +
              String(
                item.action ||
                ''
              ) +
              '</td>' +
              '<td>' +
              String(
                item.resultat ||
                ''
              ) +
              '</td>' +
              '</tr>'
            );
          }
        )
        .join('');

    tableWrap.innerHTML =
      '<table style="width:100%;border-collapse:collapse;font-size:12px">' +
      '<thead><tr>' +
      '<th>Date/Heure</th>' +
      '<th>Utilisateur</th>' +
      '<th>Rôle</th>' +
      '<th>Rubrique</th>' +
      '<th>Action</th>' +
      '<th>Résultat</th>' +
      '</tr></thead>' +
      '<tbody>' +
      rows +
      '</tbody>' +
      '</table>';
  }

  refresh.addEventListener(
    'click',
    draw
  );

  backup.addEventListener(
    'click',
    function(){

      const ok =
        lp17812Snapshot(
          'Sauvegarde manuelle DG'
        );

      try{

        alert(
          ok
            ? 'Sauvegarde créée avec succès.'
            : 'Échec de la sauvegarde.'
        );

      }
      catch(e){}

      draw();
    }
  );

  restore.addEventListener(
    'click',
    function(){

      const backups =
        lp17812ReadJSON(
          LP17812_BACKUP_KEY,
          []
        );

      if(
        !backups.length
      ){

        alert(
          'Aucune sauvegarde disponible.'
        );

        return;
      }

      const latest =
        backups[0];

      const confirmRestore =
        confirm(
          'Restaurer la dernière sauvegarde du ' +
          String(
            latest.date ||
            ''
          ) +
          ' ?'
        );

      if(!confirmRestore){
        return;
      }

      try{

        Object.entries(
          latest.data || {}
        )
        .forEach(
          ([key,value]) => {

            localStorage.setItem(
              key,
              value
            );

          }
        );

        lp17812Audit(
          'RESTAURATION',
          latest.reason ||
          '',
          'OK'
        );

        alert(
          'Restauration terminée. Redémarrez l’application.'
        );

      }
      catch(e){

        lp17812Audit(
          'RESTAURATION',
          String(e),
          'ERREUR'
        );

        alert(
          'Échec de la restauration.'
        );

      }
    }
  );

  host.appendChild(
    panel
  );

  draw();
}

