function lp17813RenderAudit(){

  if(
    typeof page === 'undefined' ||
    page !== 'audit'
  ){
    return false;
  }

  if(!lp17813IsDG()){
    page = 'dashboard';
    return false;
  }

  const candidates = [
    document.querySelector('#content'),
    document.querySelector('#app-content'),
    document.querySelector('main'),
    document.querySelector('.content'),
    document.querySelector('#app')
  ];

  const container =
    candidates.find(Boolean);

  if(!container){
    return false;
  }

  container.innerHTML =
    lp17813AuditPage();

  const refresh =
    document.getElementById(
      'lp17813Refresh'
    );

  if(refresh){

    refresh.onclick =
      function(){

        lp17813Audit(
          'Journal audit',
          'Actualisation du journal'
        );

        lp17813RenderAudit();
      };
  }

  const exportBtn =
    document.getElementById(
      'lp17813Export'
    );

  if(exportBtn){

    exportBtn.onclick =
      function(){

        const data =
          JSON.stringify(
            lp17813GetAudit(),
            null,
            2
          );

        const blob =
          new Blob(
            [data],
            {
              type:
                'application/json'
            }
          );

        const url =
          URL.createObjectURL(
            blob
          );

        const a =
          document.createElement(
            'a'
          );

        a.href = url;

        a.download =
          'Leader-Pharma-Journal-Audit.json';

        document.body
          .appendChild(a);

        a.click();

        a.remove();

        setTimeout(
          () =>
            URL.revokeObjectURL(url),
          1000
        );

        lp17813Audit(
          'Journal audit',
          'Export du journal'
        );
      };
  }

  return true;
}

