function lp17813AddMenu(){

  if(!lp17813IsDG()){
    return;
  }

  if(
    document.getElementById(
      'lp17813AuditMenu'
    )
  ){
    return;
  }

  const navButtons =
    Array.from(
      document.querySelectorAll(
        '.nav-btn'
      )
    );

  if(!navButtons.length){
    return;
  }

  const settings =
    navButtons.find(
      el =>
        lp17813Norm(
          el.textContent
        ).includes(
          'parametre'
        )
    );

  const model =
    settings ||
    navButtons[
      navButtons.length - 1
    ];

  if(!model){
    return;
  }

  const btn =
    model.cloneNode(true);

  btn.id =
    'lp17813AuditMenu';

  btn.removeAttribute(
    'data-page'
  );

  btn.removeAttribute(
    'data-p'
  );

  btn.textContent =
    '📋 Journal d’audit';

  btn.dataset.page =
    'audit';

  btn.onclick =
    function(e){

      e.preventDefault();

      e.stopPropagation();

      page = 'audit';

      lp17813Audit(
        'Journal audit',
        'Ouverture du journal'
      );

      lp17813RenderAudit();
    };

  model.parentNode.insertBefore(
    btn,
    model
  );
}

