/* ================================================
   LEADER PHARMA 17.9.0
   CLOUD BACKUP SECURISE
   ================================================

   BASE : 17.8.13

   NE MODIFIE PAS :
   - Ventes / Factures
   - Stock / Lots
   - Inventaires
   - Statistiques
   - Alertes
   - Menus existants
   - Impression
   - Synchronisation actuelle
   - Journal audit
   - Utilisateurs
   - Donnees existantes

   AJOUTE :
   - snapshot local
   - copie cloud
   - verification
   - historique sauvegardes
   - test restauration
   ================================================ */

const LP1790_LOCAL_KEY =
  'leader_pharma_cloud_backups_1790';

const LP1790_LAST_KEY =
  'leader_pharma_last_cloud_backup_1790';

function lp1790Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp1790IsDG(){

  try{

    return (
      lp1790Norm(
        currentUser?.role
      ) === 'dg'
    );

  }
  catch(e){

    return false;

  }
}

function lp1790Audit(
  action,
  result
){

  try{

    if(
      typeof lp17813Audit ===
      'function'
    ){

      lp17813Audit(
        'Sauvegarde cloud',
        action,
        result || 'OK'
      );

    }

  }
  catch(e){}
}

function lp1790Snapshot(){

  const data = {};

  try{

    for(
      let i = 0;
      i < localStorage.length;
      i++
    ){

      const key =
        localStorage.key(i);

      if(!key){
        continue;
      }

      /*
       * Ne pas sauvegarder
       * les sauvegardes elles-memes.
       */

      if(
        key === LP1790_LOCAL_KEY ||
        key === LP1790_LAST_KEY
      ){
        continue;
      }

      data[key] =
        localStorage.getItem(
          key
        );
    }

    return {
      version:
        '17.9.0',

      created_at:
        new Date()
          .toISOString(),

      utilisateur:
        String(
          currentUser?.name ||
          currentUser?.username ||
          currentUser?.login ||
          ''
        ),

      role:
        String(
          currentUser?.role ||
          ''
        ),

      nombre_cles:
        Object.keys(data)
          .length,

      donnees:
        data
    };

  }
  catch(e){

    lp1790Audit(
      'Creation snapshot',
      'ERREUR'
    );

    return null;

  }
}

/*
 * Empreinte simple pour verifier
 * que le contenu relu correspond
 * au contenu sauvegarde.
 */

function lp1790Hash(text){

  let hash =
    2166136261;

  const value =
    String(text || '');

  for(
    let i = 0;
    i < value.length;
    i++
  ){

    hash ^=
      value.charCodeAt(i);

    hash +=
      (hash << 1) +
      (hash << 4) +
      (hash << 7) +
      (hash << 8) +
      (hash << 24);
  }

  return (
    hash >>> 0
  ).toString(16);
}

function lp1790SaveLocal(
  snapshot
){

  if(!snapshot){
    return false;
  }

  try{

    const raw =
      localStorage.getItem(
        LP1790_LOCAL_KEY
      );

    let list = [];

    try{

      list =
        JSON.parse(
          raw || '[]'
        );

    }
    catch(e){

      list = [];

    }

    if(
      !Array.isArray(list)
    ){
      list = [];
    }

    const serialized =
      JSON.stringify(
        snapshot
      );

    const item = {
      id:
        Date.now(),

      created_at:
        snapshot.created_at,

      hash:
        lp1790Hash(
          serialized
        ),

      snapshot:
        snapshot
    };

    list.unshift(
      item
    );

    /*
     * 7 copies locales
     * de securite.
     */

    list =
      list.slice(
        0,
        7
      );

    localStorage.setItem(
      LP1790_LOCAL_KEY,
      JSON.stringify(list)
    );

    const verify =
      JSON.parse(
        localStorage.getItem(
          LP1790_LOCAL_KEY
        ) || '[]'
      );

    if(
      !Array.isArray(verify) ||
      !verify.length
    ){
      return false;
    }

    const check =
      lp1790Hash(
        JSON.stringify(
          verify[0].snapshot
        )
      );

    return (
      check ===
      verify[0].hash
    );

  }
  catch(e){

    return false;

  }
}

/*
 * Trouver la configuration Supabase
 * deja utilisee par l'application.
 *
 * Aucune nouvelle cle n'est
 * ajoutee dans le workflow.
 */

function lp1790SupabaseConfig(){

  try{

    const candidates = [
      window.SUPABASE_URL,
      window.supabaseUrl,
      window.SUPABASE_URL_VALUE,
      typeof SUPABASE_URL !== 'undefined'
        ? SUPABASE_URL
        : null,
      typeof supabaseUrl !== 'undefined'
        ? supabaseUrl
        : null
    ];

    const keys = [
      window.SUPABASE_ANON_KEY,
      window.supabaseKey,
      window.SUPABASE_KEY,
      typeof SUPABASE_ANON_KEY !== 'undefined'
        ? SUPABASE_ANON_KEY
        : null,
      typeof SUPABASE_KEY !== 'undefined'
        ? SUPABASE_KEY
        : null,
      typeof supabaseKey !== 'undefined'
        ? supabaseKey
        : null
    ];

    const url =
      candidates.find(
        x =>
          typeof x === 'string' &&
          x.includes(
            'supabase.co'
          )
      );

    const key =
      keys.find(
        x =>
          typeof x === 'string' &&
          x.length > 20
      );

    if(
      !url ||
      !key
    ){
      return null;
    }

    return {
      url:
        url.replace(
          /\/+$/,
          ''
        ),

      key:
        key
    };

  }
  catch(e){

    return null;

  }
}

/*
 * La copie cloud utilise
 * une ligne separee dans
 * donnees_application.
 *
 * type_donnee =
 * sauvegarde_cloud
 *
 * Elle ne remplace donc
 * aucun produit / vente /
 * stock existant.
 */

async function lp1790CloudBackup(){

  if(
    !currentUser ||
    !lp1790IsDG()
  ){

    try{
      toast(
        'Sauvegarde cloud réservée au DG'
      );
    }
    catch(e){}

    return false;
  }

  const snapshot =
    lp1790Snapshot();

  if(!snapshot){

    lp1790Audit(
      'Snapshot impossible',
      'ERREUR'
    );

    return false;
  }

  /*
   * Toujours creer la copie locale
   * AVANT le cloud.
   */

  const localOK =
    lp1790SaveLocal(
      snapshot
    );

  if(!localOK){

    lp1790Audit(
      'Sauvegarde locale avant cloud',
      'ERREUR'
    );

    try{
      toast(
        'Sauvegarde cloud bloquée : copie locale invalide'
      );
    }
    catch(e){}

    return false;
  }

  const config =
    lp1790SupabaseConfig();

  if(!config){

    lp1790Audit(
      'Configuration Supabase introuvable',
      'ERREUR'
    );

    try{
      toast(
        'Configuration Supabase introuvable'
      );
    }
    catch(e){}

    return false;
  }

  const serialized =
    JSON.stringify(
      snapshot
    );

  const hash =
    lp1790Hash(
      serialized
    );

  const reference =
    'backup-' +
    Date.now();

  const payload = {
    type_donnee:
      'sauvegarde_cloud',

    reference_locale:
      reference,

    agence_id:
      String(
        currentUser?.agencyId ||
        currentUser?.agence_id ||
        currentUser?.agency ||
        'leader-pharma'
      ),

    contenu: {
      version:
        '17.9.0',

      hash:
        hash,

      snapshot:
        snapshot
    },

    supprimer:
      false,

    cree_par:
      String(
        currentUser?.name ||
        currentUser?.username ||
        currentUser?.login ||
        'DG'
      )
  };

  try{

    const response =
      await fetch(
        config.url +
        '/rest/v1/donnees_application',
        {
          method:
            'POST',

          headers: {
            'apikey':
              config.key,

            'Authorization':
              'Bearer ' +
              config.key,

            'Content-Type':
              'application/json',

            'Prefer':
              'return=representation'
          },

          body:
            JSON.stringify(
              payload
            )
        }
      );

    if(!response.ok){

      throw new Error(
        'HTTP ' +
        response.status
      );
    }

    const result =
      await response.json();

    const first =
      Array.isArray(result)
        ? result[0]
        : result;

    const cloudHash =
      first?.contenu?.hash;

    if(
      cloudHash !== hash
    ){

      throw new Error(
        'Verification cloud incorrecte'
      );
    }

    localStorage.setItem(
      LP1790_LAST_KEY,
      JSON.stringify({
        reference:
          reference,

        date:
          snapshot.created_at,

        hash:
          hash
      })
    );

    lp1790Audit(
      'Sauvegarde cloud ' +
      reference,
      'OK'
    );

    try{
      toast(
        'Sauvegarde cloud vérifiée'
      );
    }
    catch(e){}

    return true;

  }
  catch(e){

    console.error(
      '17.9.0 cloud backup',
      e
    );

    lp1790Audit(
      'Sauvegarde cloud',
      'ERREUR'
    );

    try{
      toast(
        'Cloud indisponible • copie locale conservée'
      );
    }
    catch(err){}

    return false;

  }
}

/*
 * TEST DE RESTAURATION.
 *
 * IMPORTANT :
 * ce test NE MODIFIE PAS
 * les donnees actives.
 *
 * Il verifie uniquement
 * la derniere copie locale.
 */

function lp1790TestRestore(){

  if(
    !currentUser ||
    !lp1790IsDG()
  ){
    return false;
  }

  try{

    const list =
      JSON.parse(
        localStorage.getItem(
          LP1790_LOCAL_KEY
        ) || '[]'
      );

    if(
      !Array.isArray(list) ||
      !list.length
    ){

      try{
        toast(
          'Aucune sauvegarde de test'
        );
      }
      catch(e){}

      return false;
    }

    const item =
      list[0];

    const snapshot =
      item.snapshot;

    const hash =
      lp1790Hash(
        JSON.stringify(
          snapshot
        )
      );

    const valid =
      hash === item.hash &&
      snapshot &&
      snapshot.donnees &&
      typeof snapshot.donnees ===
        'object';

    lp1790Audit(
      'Test restauration',
      valid
        ? 'OK'
        : 'ERREUR'
    );

    try{

      toast(
        valid
          ? 'Test restauration réussi • données intactes'
          : 'Test restauration échoué'
      );

    }
    catch(e){}

    return valid;

  }
  catch(e){

    lp1790Audit(
      'Test restauration',
      'ERREUR'
    );

    return false;

  }
}

