/* ================================================
   LEADER PHARMA 17.9.3
   OPTIMISATION SOUPLESSE

   NE MODIFIE PAS :
   - checkout()
   - stock
   - impression Z91
   - factures
   - roles
   - cloud
   ================================================ */

let lp1793LastAction = 0;

function lp1793Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

/*
 * Evite les doubles pressions rapides
 * uniquement sur les actions sensibles.
 * Aucun calcul métier n'est modifié.
 */
document.addEventListener(
  'click',
  function(e){

    const el = e.target.closest(
      'button,[role="button"]'
    );

    if(!el){
      return;
    }

    const text = lp1793Norm(
      el.textContent ||
      el.value ||
      el.getAttribute?.('aria-label') ||
      ''
    );

    const protectedActions = [
      'valider & generer facture',
      'valider et generer facture',
      'sauvegarder dans le cloud',
      'tester la restauration',
      'synchroniser maintenant'
    ];

    const protect =
      protectedActions.some(
        x => text.includes(
          lp1793Norm(x)
        )
      );

    if(!protect){
      return;
    }

    const now = Date.now();

    if(
      now - lp1793LastAction < 1200
    ){
      e.preventDefault();
      e.stopImmediatePropagation();

      try{
        toast(
          'Opération déjà prise en compte'
        );
      }
      catch(err){}

      return;
    }

    lp1793LastAction = now;

  },
  true
);

/*
 * Amélioration visuelle téléphone / Z91.
 * Empêche les grandes tables de déborder
 * sans modifier leurs données.
 */
function lp1793ImproveLayout(){

  try{

    document.documentElement.style
      .maxWidth = '100%';

    document.body.style
      .maxWidth = '100%';

    document.body.style
      .overflowX = 'hidden';

    document
      .querySelectorAll('table')
      .forEach(
        table => {

          const parent =
            table.parentElement;

          if(
            parent &&
            parent.dataset
              .lp1793Scroll !== '1'
          ){

            parent.style
              .overflowX = 'auto';

            parent.style
              .WebkitOverflowScrolling =
              'touch';

            parent.dataset
              .lp1793Scroll = '1';
          }

        }
      );

  }
  catch(e){}
}

/*
 * Les champs de recherche restent
 * confortables sur écran tactile.
 */
function lp1793ImproveInputs(){

  try{

    document
      .querySelectorAll(
        'input,select,textarea,button'
      )
      .forEach(
        el => {

          if(
            !el.style.minHeight
          ){
            el.style.minHeight =
              '42px';
          }

        }
      );

  }
  catch(e){}
}

/*
 * Optimisation légère :
 * une seule mise à jour par frame.
 */
let lp1793FramePending = false;

function lp1793RefreshUI(){

  if(lp1793FramePending){
    return;
  }

  lp1793FramePending = true;

  requestAnimationFrame(
    function(){

      lp1793FramePending = false;

      lp1793ImproveLayout();
      lp1793ImproveInputs();

    }
  );
}

const lp1793Observer =
  new MutationObserver(
    lp1793RefreshUI
  );

function lp1793Start(){

  lp1793ImproveLayout();
  lp1793ImproveInputs();

  try{

    lp1793Observer.observe(
      document.body,
      {
        childList:true,
        subtree:true
      }
    );

  }
  catch(e){}

}

if(
  document.readyState ===
  'loading'
){

  document.addEventListener(
    'DOMContentLoaded',
    lp1793Start,
    {
      once:true
    }
  );

}
else{

  setTimeout(
    lp1793Start,
    0
  );

}

