function lp1798Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );
}

function lp1798IsDG(){

  try{

    return (
      lp1798Norm(
        currentUser?.role
      ) === 'dg'
    );

  }
  catch(e){

    return false;

  }
}

function lp1798Escape(v){

  return String(v ?? '')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#039;');

}

function lp1798Array(v){

  return Array.isArray(v)
    ? v
    : [];

}

function lp1798Data(){

  let users = [];
  let agencies = [];
  let products = [];
  let sales = [];
  let logs = [];

  try{
    users =
      lp1798Array(
        db?.users
      );
  }
  catch(e){}

  try{
    agencies =
      lp1798Array(
        db?.agencies
      );
  }
  catch(e){}

  try{
    products =
      lp1798Array(
        db?.products
      );
  }
  catch(e){}

  try{
    sales =
      lp1798Array(
        db?.sales
      );
  }
  catch(e){}

  try{

    logs =
      lp1798Array(
        db?.audit
      );

    if(!logs.length){
      logs =
        lp1798Array(
          db?.audits
        );
    }

    if(!logs.length){
      logs =
        lp1798Array(
          db?.logs
        );
    }

  }
  catch(e){}

  const activeUsers =
    users.filter(
      u =>
        u &&
        u.active !== false
    ).length;

  const rupture =
    products.filter(
      x =>
        Number(
          x?.stock || 0
        ) <= 0
    ).length;

  const lowStock =
    products.filter(
      x => {

        const stock =
          Number(
            x?.stock || 0
          );

        const min =
          Number(
            x?.min || 0
          );

        return (
          stock > 0 &&
          min > 0 &&
          stock <= min
        );

      }
    ).length;

  return {
    users,
    agencies,
    products,
    sales,
    logs,
    activeUsers,
    rupture,
    lowStock
  };
}

function lp1798Agency(){

  try{

    if(
      typeof agencyName ===
      'function'
    ){
      return agencyName();
    }

  }
  catch(e){}

  try{
    return String(
      currentAgency || '-'
    );
  }
  catch(e){
    return '-';
  }
}

function lp1798Network(){

  try{

    return navigator.onLine
      ? 'En ligne'
      : 'Hors ligne';

  }
  catch(e){

    return 'Inconnu';

  }
}

