/* ================================================
   LEADER PHARMA 17.10.0
   TABLEAU CONTROLE DG

   DG UNIQUEMENT

   NE MODIFIE PAS :
   - checkout()
   - stock
   - ventes / factures
   - impression Z91
   - Santé du DG
   - Surveillance DG
   - Journal audit
   - utilisateurs / roles
   - Supabase
   ================================================ */

function lp17100Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function lp17100IsDG(){
  try{
    return (
      lp17100Norm(
        currentUser?.role
      ) === 'dg'
    );
  }
  catch(e){
    return false;
  }
}

function lp17100Arr(v){
  return Array.isArray(v)
    ? v
    : [];
}

function lp17100Money(v){
  try{
    return new Intl.NumberFormat(
      'fr-CD'
    ).format(
      Number(v || 0)
    ) + ' FC';
  }
  catch(e){
    return String(
      Number(v || 0)
    ) + ' FC';
  }
}

function lp17100Today(){
  return new Date()
    .toISOString()
    .slice(0,10);
}

function lp17100SaleDate(sale){
  const raw =
    sale?.date ||
    sale?.createdAt ||
    sale?.created_at ||
    sale?.datetime ||
    sale?.time ||
    '';

  if(!raw){
    return '';
  }

  try{
    return new Date(raw)
      .toISOString()
      .slice(0,10);
  }
  catch(e){
    return String(raw)
      .slice(0,10);
  }
}

function lp17100SaleTotal(sale){
  const direct =
    Number(
      sale?.total ??
      sale?.amount ??
      sale?.montant ??
      0
    );

  if(direct > 0){
    return direct;
  }

  return lp17100Arr(
    sale?.items
  ).reduce(
    (sum,item) =>
      sum +
      Number(
        item?.qty ||
        item?.quantity ||
        0
      ) *
      Number(
        item?.price ||
        item?.unitPrice ||
        0
      ),
    0
  );
}

function lp17100SaleMargin(
  sale,
  products
){
  return lp17100Arr(
    sale?.items
  ).reduce(
    (sum,item) => {

      const qty =
        Number(
          item?.qty ||
          item?.quantity ||
          0
        );

      const price =
        Number(
          item?.price ||
          item?.unitPrice ||
          0
        );

      const product =
        products.find(
          p =>
            String(p?.id) ===
            String(item?.id)
        );

      const cost =
        Number(
          item?.cost ??
          product?.cost ??
          0
        );

      return (
        sum +
        Math.max(
          0,
          price - cost
        ) * qty
      );

    },
    0
  );
}

function lp17100ExpiryDays(dateValue){

  if(!dateValue){
    return null;
  }

  const d =
    new Date(dateValue);

  if(
    Number.isNaN(
      d.getTime()
    )
  ){
    return null;
  }

  return Math.ceil(
    (
      d.getTime() -
      Date.now()
    ) /
    86400000
  );
}

function lp17100Data(){

  const users =
    lp17100Arr(
      db?.users
    );

  const agencies =
    lp17100Arr(
      db?.agencies
    );

  const products =
    lp17100Arr(
      db?.products
    );

  const sales =
    lp17100Arr(
      db?.sales
    );

  const today =
    lp17100Today();

  const salesToday =
    sales.filter(
      x =>
        lp17100SaleDate(x) ===
        today
    );

  const caToday =
    salesToday.reduce(
      (sum,x) =>
        sum +
        lp17100SaleTotal(x),
      0
    );

  const marginToday =
    salesToday.reduce(
      (sum,x) =>
        sum +
        lp17100SaleMargin(
          x,
          products
        ),
      0
    );

  const activeUsers =
    users.filter(
      u =>
        u &&
        u.active !== false
    ).length;

  const rupture =
    products.filter(
      p =>
        Number(
          p?.stock || 0
        ) <= 0
    );

  const low =
    products.filter(
      p => {

        const stock =
          Number(
            p?.stock || 0
          );

        const min =
          Number(
            p?.min || 0
          );

        return (
          stock > 0 &&
          min > 0 &&
          stock <= min
        );

      }
    );

  const expiring =
    products.filter(
      p => {

        const days =
          lp17100ExpiryDays(
            p?.expiry
          );

        return (
          days !== null &&
          days >= 0 &&
          days <= 90
        );

      }
    );

  return {
    users,
    agencies,
    products,
    sales,
    salesToday,
    caToday,
    marginToday,
    activeUsers,
    rupture,
    low,
    expiring
  };
}

function lp17100AgencyRows(
  data
){

  return data.agencies
    .map(
      agency => {

        const id =
          agency?.id;

        const sales =
          data.salesToday.filter(
            sale =>
              String(
                sale?.agency || ''
              ) ===
              String(id || '')
          );

        const ca =
          sales.reduce(
            (sum,sale) =>
              sum +
              lp17100SaleTotal(
                sale
              ),
            0
          );

        const products =
          data.products.filter(
            p =>
              String(
                p?.agency || ''
              ) ===
              String(id || '')
          );

        return `
          <tr>
            <td>
              ${String(
                agency?.name ||
                id ||
                '-'
              )}
            </td>

            <td>
              ${sales.length}
            </td>

            <td>
              ${lp17100Money(ca)}
            </td>

            <td>
              ${products.length}
            </td>
          </tr>
        `;
      }
    )
    .join('');
}

