function lp17100Render(){

  if(
    typeof page === 'undefined' ||
    page !== 'dgcontrol'
  ){
    return false;
  }

  if(!lp17100IsDG()){
    page = 'dashboard';
    return false;
  }

  const container =
    document.querySelector(
      '#content'
    ) ||
    document.querySelector(
      '#app-content'
    ) ||
    document.querySelector(
      'main'
    ) ||
    document.querySelector(
      '.content'
    ) ||
    document.querySelector(
      '#app'
    );

  if(!container){
    return false;
  }

  container.innerHTML =
    lp17100Page();

  const refresh =
    document.getElementById(
      'lp17100Refresh'
    );

  if(refresh){
    refresh.onclick =
      function(){

        lp17100Render();

        try{
          toast(
            'Tableau DG actualisé'
          );
        }
        catch(e){}

      };
  }

  return true;
}

function lp17100AddMenu(){

  if(!lp17100IsDG()){
    return;
  }

  if(
    document.getElementById(
      'lp17100ControlMenu'
    )
  ){
    return;
  }

  const buttons =
    Array.from(
      document.querySelectorAll(
        '.nav-btn'
      )
    );

  if(!buttons.length){
    return;
  }

  const dashboard =
    buttons.find(
      b =>
        lp17100Norm(
          b.textContent
        ).includes(
          'tableau de bord'
        )
    );

  const model =
    dashboard ||
    buttons[0];

  if(!model){
    return;
  }

  const btn =
    model.cloneNode(true);

  btn.id =
    'lp17100ControlMenu';

  btn.removeAttribute(
    'data-p'
  );

  btn.removeAttribute(
    'data-page'
  );

  btn.dataset.page =
    'dgcontrol';

  btn.textContent =
    '📊 Contrôle DG';

  btn.onclick =
    function(e){

      e.preventDefault();
      e.stopPropagation();

      page =
        'dgcontrol';

      lp17100Render();

    };

  model.parentNode.insertBefore(
    btn,
    model.nextSibling
  );
}

try{

  const originalRender17100 =
    render;

  render =
    function(){

      if(
        typeof page !==
          'undefined' &&
        page ===
          'dgcontrol'
      ){

        setTimeout(
          lp17100Render,
          0
        );

        return;
      }

      const result =
        originalRender17100.apply(
          this,
          arguments
        );

      setTimeout(
        lp17100AddMenu,
        0
      );

      return result;
    };

}
catch(e){}

setTimeout(
  lp17100AddMenu,
  0
);

try{

  const observer17100 =
    new MutationObserver(
      lp17100AddMenu
    );

  observer17100.observe(
    document.body,
    {
      childList:true,
      subtree:true
    }
  );

}
catch(e){}

