function lp17101Apply(){

  try{

    if(
      typeof page ===
        'undefined' ||
      page !==
        'dgcontrol'
    ){
      return;
    }

    const titles =
      Array.from(
        document.querySelectorAll(
          'h1'
        )
      );

    const title =
      titles.find(
        el =>
          String(
            el.textContent || ''
          )
          .toLowerCase()
          .includes(
            'tableau de contrôle dg'
          )
      );

    if(!title){
      return;
    }

    const section =
      title.closest(
        'section'
      );

    if(!section){
      return;
    }

    section.classList.add(
      'lp17101-control-page'
    );

    const children =
      Array.from(
        section.children
      );

    const grid =
      children.find(
        el => {

          if(
            el.tagName !==
            'DIV'
          ){
            return false;
          }

          const cards =
            el.querySelectorAll(
              ':scope > .card'
            );

          return (
            cards.length >= 6
          );

        }
      );

    if(grid){
      grid.classList.add(
        'lp17101-kpi-grid'
      );
    }

  }
  catch(e){}

}

