function lp17102FindPage(){

  const titles =
    Array.from(
      document.querySelectorAll(
        'h1'
      )
    );

  const title =
    titles.find(
      el =>
        String(
          el.textContent || ''
        )
        .trim()
        .toLowerCase()
        .includes(
          'tableau de contrôle dg'
        )
    );

  if(!title){
    return null;
  }

  return title.closest(
    'section'
  );
}

function lp17102Apply(){

  try{

    if(
      typeof page ===
        'undefined' ||
      page !==
        'dgcontrol'
    ){

      document.body
        ?.classList
        .remove(
          'lp17102-dgcontrol-mobile'
        );

      return;
    }

    lp17102InstallStyle();

    const section =
      lp17102FindPage();

    if(!section){
      return;
    }

    document.body
      ?.classList
      .add(
        'lp17102-dgcontrol-mobile'
      );

    section.classList.add(
      'lp17101-control-page'
    );

    section.style.width =
      '100%';

    section.style.maxWidth =
      '100%';

    section.style.minWidth =
      '0';

    section.style.boxSizing =
      'border-box';

    section.style.overflowX =
      'hidden';

    const directDivs =
      Array.from(
        section.children
      )
      .filter(
        el =>
          el.tagName ===
          'DIV'
      );

    const grid =
      directDivs.find(
        el =>
          el.querySelectorAll(
            ':scope > .card'
          ).length >= 6
      );

    if(grid){

      grid.classList.add(
        'lp17101-kpi-grid'
      );

      grid.style.width =
        '100%';

      grid.style.maxWidth =
        '100%';

      grid.style.minWidth =
        '0';

      grid.style.gridTemplateColumns =
        window.innerWidth < 600
          ? 'minmax(0, 1fr)'
          : '';

    }

    const tables =
      Array.from(
        section.querySelectorAll(
          'table'
        )
      );

    tables.forEach(
      table => {

        const wrapper =
          table.parentElement;

        if(wrapper){

          wrapper.classList.add(
            'lp17102-table-scroll'
          );

          wrapper.style.width =
            '100%';

          wrapper.style.maxWidth =
            '100%';

          wrapper.style.overflowX =
            'auto';

        }

      }
    );

  }
  catch(e){}
}

