/* ================================================
   LEADER PHARMA 17.10.5.1
   SYNTHESE DG CORRIGEE

   CORRECTION :
   - aucun MutationObserver
   - aucune boucle DOM
   - aucun outerHTML repetitif
   - navigation preservee
   - menus preservees

   BASE :
   - 17.10.4 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - Sante DG
   - Surveillance DG
   - Journal audit
   ================================================ */

function lp171051Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171051IsDG(){
  try{
    return (
      lp171051Norm(
        currentUser?.role
      ) === 'dg'
    );
  }
  catch(e){
    return false;
  }
}

function lp171051Money(v){
  try{
    return new Intl.NumberFormat(
      'fr-CD'
    ).format(
      Number(v || 0)
    ) + ' FC';
  }
  catch(e){
    return String(
      Number(v || 0)
    ) + ' FC';
  }
}

function lp171051Data(){

  let ca = 0;
  let ventes = 0;
  let marge = 0;
  let urgences = 0;
  let surveillance = 0;
  let ruptures = 0;
  let faible = 0;
  let peremptions = 0;

  try{
    if(
      typeof lp17100Data ===
      'function'
    ){
      const d =
        lp17100Data();

      ca =
        Number(
          d?.caToday || 0
        );

      ventes =
        Number(
          d?.salesToday?.length || 0
        );

      marge =
        Number(
          d?.marginToday || 0
        );

      ruptures =
        Number(
          d?.rupture?.length || 0
        );

      faible =
        Number(
          d?.low?.length || 0
        );

      peremptions =
        Number(
          d?.expiring?.length || 0
        );
    }
  }
  catch(e){}

  try{
    if(
      typeof lp17104PriorityData ===
      'function'
    ){
      const p =
        lp17104PriorityData();

      urgences =
        Number(
          p?.urgent?.length || 0
        );

      surveillance =
        Number(
          p?.watch?.length || 0
        );
    }
  }
  catch(e){}

  let network = false;

  try{
    network =
      navigator.onLine === true;
  }
  catch(e){}

  return {
    ca,
    ventes,
    marge,
    urgences,
    surveillance,
    ruptures,
    faible,
    peremptions,
    network
  };
}

function lp171051Status(d){

  if(
    d.urgences > 0 ||
    d.ruptures > 0
  ){
    return {
      icon:'🔴',
      title:'Urgence opérationnelle',
      text:
        'Des actions immédiates sont nécessaires sur le stock ou les produits prioritaires.'
    };
  }

  if(
    d.surveillance > 0 ||
    d.faible > 0 ||
    d.peremptions > 0 ||
    !d.network
  ){
    return {
      icon:'🟠',
      title:'Attention requise',
      text:
        'La situation reste sous contrôle mais certains éléments doivent être surveillés.'
    };
  }

  return {
    icon:'🟢',
    title:'Situation stable',
    text:
      'Aucune alerte critique détectée actuellement.'
  };
}

