function lp171051Refresh(){

  try{

    const box =
      document.getElementById(
        'lp171051Summary'
      );

    if(!box){
      return;
    }

    const d =
      lp171051Data();

    const status =
      lp171051Status(d);

    const statusTitle =
      box.querySelector(
        '.lp171051-status-title'
      );

    const statusText =
      box.querySelector(
        '.lp171051-status-text'
      );

    if(statusTitle){
      statusTitle.textContent =
        status.icon +
        ' ' +
        status.title;
    }

    if(statusText){
      statusText.textContent =
        status.text;
    }

    const values = {
      lp171051CA:
        lp171051Money(d.ca),

      lp171051Sales:
        String(d.ventes),

      lp171051Margin:
        lp171051Money(d.marge),

      lp171051Urgent:
        String(d.urgences),

      lp171051Watch:
        String(d.surveillance),

      lp171051Expiry:
        String(d.peremptions),

      lp171051Network:
        '🌐 Réseau : ' +
        (
          d.network
            ? '🟢 En ligne'
            : '🔴 Hors ligne'
        )
    };

    Object.entries(
      values
    ).forEach(
      ([id,value]) => {

        const el =
          document.getElementById(
            id
          );

        if(el){
          el.textContent =
            value;
        }

      }
    );

  }
  catch(e){}
}

function lp171051Apply(){

  try{

    if(
      typeof page ===
        'undefined' ||
      page !==
        'dgcontrol'
    ){
      return;
    }

    if(!lp171051IsDG()){
      return;
    }

    lp171051InstallStyle();

    const titles =
      Array.from(
        document.querySelectorAll(
          'h1'
        )
      );

    const title =
      titles.find(
        el =>
          lp171051Norm(
            el.textContent
          )
          .includes(
            'tableau de controle dg'
          )
      );

    if(!title){
      return;
    }

    const section =
      title.closest(
        'section'
      );

    if(!section){
      return;
    }

    const existing =
      document.getElementById(
        'lp171051Summary'
      );

    if(existing){
      lp171051Refresh();
      return;
    }

    const summary =
      lp171051Build();

    const priority =
      section.querySelector(
        '#lp17104Summary'
      );

    if(priority){

      priority.insertAdjacentElement(
        'beforebegin',
        summary
      );

    }
    else{

      const oldActions =
        section.querySelector(
          '#lp17103Actions'
        );

      if(oldActions){

        oldActions.insertAdjacentElement(
          'beforebegin',
          summary
        );

      }
      else{

        const firstGrid =
          Array.from(
            section.children
          )
          .find(
            el =>
              el.tagName ===
                'DIV' &&
              el.querySelectorAll(
                ':scope > .card'
              ).length >= 6
          );

        if(firstGrid){

          firstGrid.insertAdjacentElement(
            'afterend',
            summary
          );

        }
        else{

          section.appendChild(
            summary
          );

        }

      }

    }

  }
  catch(e){}
}

