/* ================================================
   LEADER PHARMA 17.10.6
   SYNTHESE FINANCIERE DG

   AJOUT :
   - CA du jour
   - marge / benefice estime
   - depenses du jour
   - creances ouvertes
   - resultat net estime
   - situation financiere par agence

   DG UNIQUEMENT

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - Sante DG
   - Surveillance DG
   - Journal audit
   ================================================ */

function lp17106Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp17106IsDG(){
  try{
    return (
      lp17106Norm(
        currentUser?.role
      ) === 'dg'
    );
  }
  catch(e){
    return false;
  }
}

function lp17106Arr(v){
  return Array.isArray(v)
    ? v
    : [];
}

function lp17106Money(v){
  try{
    return new Intl.NumberFormat(
      'fr-CD'
    ).format(
      Number(v || 0)
    ) + ' FC';
  }
  catch(e){
    return String(
      Number(v || 0)
    ) + ' FC';
  }
}

function lp17106Today(){
  return new Date()
    .toISOString()
    .slice(0,10);
}

function lp17106Date(v){
  if(!v){
    return '';
  }

  try{
    return new Date(v)
      .toISOString()
      .slice(0,10);
  }
  catch(e){
    return String(v)
      .slice(0,10);
  }
}

function lp17106SaleTotal(sale){

  const direct =
    Number(
      sale?.total ??
      sale?.amount ??
      sale?.montant ??
      0
    );

  if(direct){
    return direct;
  }

  return lp17106Arr(
    sale?.items
  ).reduce(
    (sum,item) =>
      sum +
      Number(
        item?.qty ||
        item?.quantity ||
        0
      ) *
      Number(
        item?.price ||
        item?.unitPrice ||
        0
      ),
    0
  );
}

function lp17106ExpenseTotal(exp){

  return Number(
    exp?.amount ??
    exp?.montant ??
    exp?.total ??
    exp?.value ??
    0
  );
}

function lp17106DebtTotal(row){

  return Number(
    row?.amount ??
    row?.montant ??
    row?.total ??
    row?.balance ??
    row?.reste ??
    0
  );
}

function lp17106AgencyId(row){

  return String(
    row?.agency ??
    row?.agencyId ??
    row?.agency_id ??
    row?.branch ??
    ''
  );
}

function lp17106Data(){

  const today =
    lp17106Today();

  const sales =
    lp17106Arr(
      db?.sales
    );

  const expenses =
    lp17106Arr(
      db?.expenses
    );

  const receivables =
    lp17106Arr(
      db?.receivables
    );

  const agencies =
    lp17106Arr(
      db?.agencies
    );

  const products =
    lp17106Arr(
      db?.products
    );

  const salesToday =
    sales.filter(
      x =>
        lp17106Date(
          x?.date ||
          x?.createdAt ||
          x?.created_at ||
          x?.datetime
        ) === today
    );

  const expensesToday =
    expenses.filter(
      x =>
        lp17106Date(
          x?.date ||
          x?.createdAt ||
          x?.created_at ||
          x?.datetime
        ) === today
    );

  const ca =
    salesToday.reduce(
      (sum,x) =>
        sum +
        lp17106SaleTotal(x),
      0
    );

  let margin = 0;

  try{
    if(
      typeof lp17100Data ===
      'function'
    ){
      margin =
        Number(
          lp17100Data()
            ?.marginToday || 0
        );
    }
  }
  catch(e){}

  const depenses =
    expensesToday.reduce(
      (sum,x) =>
        sum +
        lp17106ExpenseTotal(x),
      0
    );

  const creances =
    receivables.reduce(
      (sum,x) =>
        sum +
        lp17106DebtTotal(x),
      0
    );

  const resultat =
    margin -
    depenses;

  return {
    today,
    sales,
    expenses,
    receivables,
    agencies,
    products,
    salesToday,
    expensesToday,
    ca,
    margin,
    depenses,
    creances,
    resultat
  };
}

function lp17106AgencyRows(d){

  return d.agencies
    .map(
      agency => {

        const id =
          String(
            agency?.id || ''
          );

        const sales =
          d.salesToday.filter(
            x =>
              lp17106AgencyId(x) === id
          );

        const expenses =
          d.expensesToday.filter(
            x =>
              lp17106AgencyId(x) === id
          );

        const ca =
          sales.reduce(
            (sum,x) =>
              sum +
              lp17106SaleTotal(x),
            0
          );

        const depenses =
          expenses.reduce(
            (sum,x) =>
              sum +
              lp17106ExpenseTotal(x),
            0
          );

        return `
          <tr>
            <td>
              ${String(
                agency?.name ||
                agency?.id ||
                '-'
              )}
            </td>

            <td>
              ${sales.length}
            </td>

            <td>
              ${lp17106Money(ca)}
            </td>

            <td>
              ${lp17106Money(depenses)}
            </td>
          </tr>
        `;
      }
    )
    .join('');
}

