/* ================================================
   LEADER PHARMA 17.10.7
   PERFORMANCE PAR AGENCE DG

   AJOUT :
   - classement des agences
   - ventes du jour
   - chiffre d'affaires
   - depenses
   - resultat estime
   - indicateur de performance

   DG UNIQUEMENT

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - actions prioritaires
   - synthese financiere 17.10.6
   ================================================ */

function lp17107Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp17107IsDG(){
  try{
    return (
      lp17107Norm(
        currentUser?.role
      ) === 'dg'
    );
  }
  catch(e){
    return false;
  }
}

function lp17107Arr(v){
  return Array.isArray(v)
    ? v
    : [];
}

function lp17107Escape(v){
  return String(v ?? '')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;')
    .replace(/'/g,'&#039;');
}

function lp17107Money(v){
  try{
    return new Intl.NumberFormat(
      'fr-CD'
    ).format(
      Number(v || 0)
    ) + ' FC';
  }
  catch(e){
    return Number(v || 0) + ' FC';
  }
}

function lp17107Today(){
  const d = new Date();

  const y =
    d.getFullYear();

  const m =
    String(
      d.getMonth() + 1
    ).padStart(2,'0');

  const day =
    String(
      d.getDate()
    ).padStart(2,'0');

  return `${y}-${m}-${day}`;
}

function lp17107Date(v){

  if(!v){
    return '';
  }

  const d =
    new Date(v);

  if(
    Number.isNaN(
      d.getTime()
    )
  ){
    return String(v)
      .slice(0,10);
  }

  const y =
    d.getFullYear();

  const m =
    String(
      d.getMonth() + 1
    ).padStart(2,'0');

  const day =
    String(
      d.getDate()
    ).padStart(2,'0');

  return `${y}-${m}-${day}`;
}

function lp17107SaleTotal(row){

  const direct =
    Number(
      row?.total ??
      row?.amount ??
      row?.montant ??
      0
    );

  if(direct){
    return direct;
  }

  return lp17107Arr(
    row?.items
  ).reduce(
    (sum,item) =>
      sum +
      (
        Number(
          item?.qty ??
          item?.quantity ??
          0
        ) *
        Number(
          item?.price ??
          item?.unitPrice ??
          item?.sellingPrice ??
          0
        )
      ),
    0
  );
}

function lp17107ExpenseTotal(row){

  return Number(
    row?.amount ??
    row?.montant ??
    row?.total ??
    row?.value ??
    0
  );
}

function lp17107AgencyValue(row){

  return String(
    row?.agency ??
    row?.agencyId ??
    row?.agency_id ??
    row?.branch ??
    row?.branchId ??
    ''
  );
}

function lp17107AgencyMatch(row,agency){

  const raw =
    lp17107AgencyValue(row);

  const id =
    String(
      agency?.id ?? ''
    );

  const name =
    String(
      agency?.name ?? ''
    );

  if(!raw){
    return false;
  }

  return (
    raw === id ||
    lp17107Norm(raw) ===
      lp17107Norm(name)
  );
}

function lp17107Rows(){

  const today =
    lp17107Today();

  const agencies =
    lp17107Arr(
      db?.agencies
    );

  const salesToday =
    lp17107Arr(
      db?.sales
    ).filter(
      row =>
        lp17107Date(
          row?.date ??
          row?.createdAt ??
          row?.created_at ??
          row?.datetime
        ) === today
    );

  const expensesToday =
    lp17107Arr(
      db?.expenses
    ).filter(
      row =>
        lp17107Date(
          row?.date ??
          row?.createdAt ??
          row?.created_at ??
          row?.datetime
        ) === today
    );

  const rows =
    agencies.map(
      agency => {

        const sales =
          salesToday.filter(
            row =>
              lp17107AgencyMatch(
                row,
                agency
              )
          );

        const expenses =
          expensesToday.filter(
            row =>
              lp17107AgencyMatch(
                row,
                agency
              )
          );

        const ca =
          sales.reduce(
            (sum,row) =>
              sum +
              lp17107SaleTotal(row),
            0
          );

        const depenses =
          expenses.reduce(
            (sum,row) =>
              sum +
              lp17107ExpenseTotal(row),
            0
          );

        const resultat =
          ca -
          depenses;

        return {
          agency,
          ventes:sales.length,
          ca,
          depenses,
          resultat
        };
      }
    );

  rows.sort(
    (a,b) =>
      b.resultat -
      a.resultat ||
      b.ca -
      a.ca ||
      b.ventes -
      a.ventes
  );

  return rows;
}

function lp17107Status(row){

  if(
    row.ca <= 0 &&
    row.depenses <= 0
  ){
    return {
      icon:'⚪',
      text:'Sans activité'
    };
  }

  if(row.resultat < 0){
    return {
      icon:'🔴',
      text:'À corriger'
    };
  }

  if(row.resultat === 0){
    return {
      icon:'🟠',
      text:'À surveiller'
    };
  }

  return {
    icon:'🟢',
    text:'Positive'
  };
}

