function lp171010Apply(){

  try{

    if(
      typeof page ===
        'undefined' ||
      page !==
        'dgcontrol'
    ){
      return;
    }

    if(!lp171010IsDG()){
      return;
    }

    lp171010InstallStyle();

    if(
      document.getElementById(
        'lp171010Box'
      )
    ){
      return;
    }

    const titles =
      Array.from(
        document.querySelectorAll(
          'h1'
        )
      );

    const title =
      titles.find(
        el =>
          lp171010Norm(
            el.textContent
          ).includes(
            'tableau de controle dg'
          )
      );

    if(!title){
      return;
    }

    const section =
      title.closest(
        'section'
      );

    if(!section){
      return;
    }

    const wrapper =
      document.createElement(
        'div'
      );

    wrapper.innerHTML =
      lp171010Html();

    const box =
      wrapper.firstElementChild;

    const trends =
      section.querySelector(
        '#lp17109Box'
      );

    if(trends){

      trends.insertAdjacentElement(
        'afterend',
        box
      );

    }
    else{

      const priorities =
        section.querySelector(
          '#lp17104Summary'
        );

      if(priorities){

        priorities
          .insertAdjacentElement(
            'beforebegin',
            box
          );

      }
      else{

        section.appendChild(
          box
        );

      }

    }

  }
  catch(e){}
}

function lp171010Start(){

  lp171010InstallStyle();

  lp171010Apply();

  setTimeout(
    lp171010Apply,
    100
  );

  setTimeout(
    lp171010Apply,
    400
  );

  setTimeout(
    lp171010Apply,
    900
  );

}

document.addEventListener(
  'click',
  function(){

    setTimeout(
      lp171010Apply,
      80
    );

  },
  true
);

try{

  const observer171010 =
    new MutationObserver(
      function(){

        if(
          typeof page !==
            'undefined' &&
          page ===
            'dgcontrol'
        ){

          lp171010Apply();

        }

      }
    );

  observer171010.observe(
    document.body,
    {
      childList:true,
      subtree:true
    }
  );

}
catch(e){}

if(
  document.readyState ===
  'loading'
){

  document.addEventListener(
    'DOMContentLoaded',
    lp171010Start,
    {
      once:true
    }
  );

}
else{

  setTimeout(
    lp171010Start,
    0
  );

}

