/* ================================================
   LEADER PHARMA 17.10.11
   OBJECTIFS ET PREVISIONS DG

   AJOUT :
   - objectif CA mensuel
   - objectif modifiable par DG
   - realisation du mois
   - taux d'atteinte
   - montant restant
   - moyenne journaliere
   - projection fin de mois
   - indication avance / retard

   BASE :
   - 17.10.10 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - comparaison agences
   - tendances
   - pilotage 7 jours
   - actions prioritaires
   ================================================ */

function lp171011Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171011IsDG(){
  try{
    return lp171011Norm(
      currentUser?.role
    ) === 'dg';
  }
  catch(e){
    return false;
  }
}

function lp171011Arr(v){
  return Array.isArray(v)
    ? v
    : [];
}

function lp171011Money(v){

  const n =
    Number(v || 0);

  try{
    return Math.round(n)
      .toLocaleString(
        'fr-CD'
      ) + ' FC';
  }
  catch(e){
    return Math.round(n) +
      ' FC';
  }
}

function lp171011Sales(){

  try{
    return lp171011Arr(
      db?.sales ||
      db?.ventes ||
      db?.invoices
    );
  }
  catch(e){
    return [];
  }
}

function lp171011SaleDate(s){

  return (
    s?.date ||
    s?.createdAt ||
    s?.created_at ||
    s?.timestamp ||
    ''
  );
}

function lp171011SaleTotal(s){

  const direct =
    Number(
      s?.total ??
      s?.amount ??
      s?.montant ??
      s?.grandTotal ??
      0
    );

  if(direct){
    return direct;
  }

  return lp171011Arr(
    s?.items
  ).reduce(
    (sum,item) =>
      sum +
      Number(
        item?.qty ??
        item?.quantity ??
        0
      ) *
      Number(
        item?.price ??
        item?.unitPrice ??
        0
      ),
    0
  );
}

function lp171011Date(v){

  const d =
    new Date(v);

  if(
    Number.isNaN(
      d.getTime()
    )
  ){
    return null;
  }

  return d;
}

function lp171011Objective(){

  try{

    const raw =
      localStorage.getItem(
        'lp171011_monthly_target'
      );

    const n =
      Number(raw);

    if(
      Number.isFinite(n) &&
      n > 0
    ){
      return n;
    }

  }
  catch(e){}

  return 1000000;
}

function lp171011SaveObjective(v){

  const n =
    Number(v);

  if(
    !Number.isFinite(n) ||
    n <= 0
  ){
    return false;
  }

  try{
    localStorage.setItem(
      'lp171011_monthly_target',
      String(
        Math.round(n)
      )
    );

    return true;
  }
  catch(e){
    return false;
  }
}

function lp171011Data(){

  const now =
    new Date();

  const year =
    now.getFullYear();

  const month =
    now.getMonth();

  const elapsedDays =
    now.getDate();

  const daysInMonth =
    new Date(
      year,
      month + 1,
      0
    ).getDate();

  const monthSales =
    lp171011Sales()
      .filter(
        sale => {

          const d =
            lp171011Date(
              lp171011SaleDate(
                sale
              )
            );

          return (
            d &&
            d.getFullYear() ===
              year &&
            d.getMonth() ===
              month
          );

        }
      );

  const realized =
    monthSales.reduce(
      (sum,sale) =>
        sum +
        lp171011SaleTotal(
          sale
        ),
      0
    );

  const objective =
    lp171011Objective();

  const rate =
    objective > 0
      ? (
          realized /
          objective
        ) * 100
      : 0;

  const remaining =
    Math.max(
      0,
      objective -
      realized
    );

  const dailyAverage =
    elapsedDays > 0
      ? realized /
        elapsedDays
      : 0;

  const projection =
    dailyAverage *
    daysInMonth;

  const expectedToday =
    objective *
    (
      elapsedDays /
      daysInMonth
    );

  const advance =
    realized -
    expectedToday;

  const requiredDaily =
    (
      daysInMonth -
      elapsedDays
    ) > 0
      ? remaining /
        (
          daysInMonth -
          elapsedDays
        )
      : remaining;

  return {
    year,
    month,
    elapsedDays,
    daysInMonth,
    monthSales,
    realized,
    objective,
    rate,
    remaining,
    dailyAverage,
    projection,
    expectedToday,
    advance,
    requiredDaily
  };
}

function lp171011Status(d){

  if(
    d.realized >=
    d.objective
  ){
    return {
      icon:'🏆',
      title:'Objectif atteint',
      text:
        'Le chiffre d’affaires mensuel a déjà atteint ou dépassé l’objectif.'
    };
  }

  if(
    d.projection >=
    d.objective &&
    d.advance >= 0
  ){
    return {
      icon:'🟢',
      title:'Trajectoire favorable',
      text:
        'Le rythme actuel permet d’atteindre l’objectif mensuel.'
    };
  }

  if(
    d.projection >=
    d.objective
  ){
    return {
      icon:'🟠',
      title:'Objectif encore accessible',
      text:
        'La projection reste favorable mais le rythme doit être surveillé.'
    };
  }

  return {
    icon:'🔴',
    title:'Objectif sous pression',
    text:
      'Le rythme actuel est insuffisant pour atteindre l’objectif mensuel.'
  };
}

