/* ================================================
   LEADER PHARMA 17.10.12
   ALERTES OBJECTIFS & DECISIONS DG

   AJOUT :
   - alerte objectif mensuel
   - rythme requis
   - ecart de trajectoire
   - priorite du jour
   - lecture decisionnelle DG
   - recommandations simples

   BASE :
   - 17.10.11 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - pilotage 7 jours
   - tendances
   - comparaison agences
   - actions prioritaires
   ================================================ */

function lp171012Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171012IsDG(){
  try{
    return lp171012Norm(
      currentUser?.role
    ) === 'dg';
  }
  catch(e){
    return false;
  }
}

function lp171012Money(v){
  const n = Number(v || 0);

  try{
    return Math.round(n)
      .toLocaleString('fr-CD') +
      ' FC';
  }
  catch(e){
    return Math.round(n) +
      ' FC';
  }
}

function lp171012ObjectiveData(){
  try{
    if(
      typeof lp171011Data ===
      'function'
    ){
      return lp171011Data();
    }
  }
  catch(e){}

  return {
    objective:0,
    realized:0,
    rate:0,
    remaining:0,
    projection:0,
    advance:0,
    requiredDaily:0,
    elapsedDays:0,
    daysInMonth:0
  };
}

function lp171012PriorityData(){
  try{
    if(
      typeof lp17104PriorityData ===
      'function'
    ){
      return lp17104PriorityData();
    }
  }
  catch(e){}

  return {
    urgent:[],
    watch:[],
    normal:[],
    total:0
  };
}

function lp171012Decision(){

  const d =
    lp171012ObjectiveData();

  const p =
    lp171012PriorityData();

  let level =
    'normal';

  let icon =
    '🟢';

  let title =
    'Situation maîtrisée';

  let message =
    'Les principaux indicateurs sont sous contrôle.';

  let action =
    'Poursuivre le suivi régulier.';

  if(
    Number(d.realized || 0) >=
    Number(d.objective || 0) &&
    Number(d.objective || 0) > 0
  ){
    level =
      'success';

    icon =
      '🏆';

    title =
      'Objectif mensuel atteint';

    message =
      'Le chiffre d’affaires mensuel a atteint ou dépassé l’objectif.';

    action =
      'Consolider la performance et surveiller la marge.';
  }
  else if(
    p.urgent.length >= 5
  ){
    level =
      'urgent';

    icon =
      '🔴';

    title =
      'Priorité opérationnelle élevée';

    message =
      'Plusieurs actions urgentes nécessitent une intervention immédiate.';

    action =
      'Traiter en priorité les ruptures et produits critiques.';
  }
  else if(
    Number(d.projection || 0) <
    Number(d.objective || 0)
  ){
    level =
      'alert';

    icon =
      '🔴';

    title =
      'Objectif mensuel sous pression';

    message =
      'La projection actuelle reste inférieure à l’objectif mensuel.';

    action =
      'Augmenter le rythme commercial et suivre le CA quotidien.';
  }
  else if(
    Number(d.advance || 0) < 0
  ){
    level =
      'watch';

    icon =
      '🟠';

    title =
      'Retard sur trajectoire';

    message =
      'Le réalisé reste en dessous du niveau attendu à cette date.';

    action =
      'Surveiller le rythme quotidien jusqu’au retour sur trajectoire.';
  }
  else if(
    p.watch.length > 0
  ){
    level =
      'watch';

    icon =
      '🟠';

    title =
      'Points à surveiller';

    message =
      'Certains produits ou indicateurs nécessitent un suivi rapproché.';

    action =
      'Contrôler les alertes avant qu’elles deviennent urgentes.';
  }

  return {
    d,
    p,
    level,
    icon,
    title,
    message,
    action
  };
}

