function lp171013Refresh(){

  const d =
    lp171013Summary();

  const map = {
    lp171013Total:
      d.list.length,

    lp171013Open:
      d.open.length,

    lp171013Done:
      d.done.length,

    lp171013Urgent:
      d.urgent.length
  };

  Object.entries(
    map
  ).forEach(
    ([id,value]) => {

      const el =
        document.getElementById(
          id
        );

      if(el){
        el.textContent =
          String(value);
      }

    }
  );

  const list =
    document.getElementById(
      'lp171013List'
    );

  if(list){
    list.innerHTML =
      lp171013ListHtml();
  }

  lp171013BindControls();
}

function lp171013AddAction(){

  if(!lp171013IsDG()){
    return;
  }

  const title =
    String(
      document.getElementById(
        'lp171013Title'
      )?.value || ''
    ).trim();

  const owner =
    String(
      document.getElementById(
        'lp171013Owner'
      )?.value || ''
    ).trim();

  const due =
    String(
      document.getElementById(
        'lp171013Due'
      )?.value || ''
    ).trim();

  const priority =
    String(
      document.getElementById(
        'lp171013Priority'
      )?.value || 'normale'
    );

  const status =
    lp171013NormalizeStatus(
      document.getElementById(
        'lp171013Status'
      )?.value || 'afaire'
    );

  if(!title){

    try{
      toast(
        'Saisissez une action'
      );
    }
    catch(e){}

    return;
  }

  const list =
    lp171013Read();

  list.push(
    {
      id:
        lp171013Id(),

      title,
      owner:
        owner || 'DG',

      due:
        due ||
        lp171013DefaultDue(),

      priority,
      status,

      createdAt:
        new Date()
          .toISOString()
    }
  );

  if(
    !lp171013Write(
      list
    )
  ){

    try{
      toast(
        'Impossible d’enregistrer'
      );
    }
    catch(e){}

    return;
  }

  const titleInput =
    document.getElementById(
      'lp171013Title'
    );

  if(titleInput){
    titleInput.value = '';
  }

  lp171013Refresh();

  try{
    toast(
      'Action DG enregistrée'
    );
  }
  catch(e){}
}

function lp171013SetStatus(
  id,
  status
){

  if(!lp171013IsDG()){
    return;
  }

  const list =
    lp171013Read();

  const row =
    list.find(
      x =>
        String(x?.id) ===
        String(id)
    );

  if(!row){
    return;
  }

  row.status =
    lp171013NormalizeStatus(
      status
    );

  row.updatedAt =
    new Date()
      .toISOString();

  if(
    row.status ===
    'termine'
  ){
    row.completedAt =
      new Date()
        .toISOString();
  }

  lp171013Write(
    list
  );

  lp171013Refresh();
}

function lp171013BindControls(){

  document
    .querySelectorAll(
      '[data-lp171013-action]'
    )
    .forEach(
      btn => {

        btn.onclick =
          function(e){

            e.preventDefault();
            e.stopPropagation();

            const id =
              btn.getAttribute(
                'data-lp171013-id'
              );

            const action =
              btn.getAttribute(
                'data-lp171013-action'
              );

            if(
              action ===
              'doing'
            ){
              lp171013SetStatus(
                id,
                'encours'
              );
            }
            else if(
              action ===
              'done'
            ){
              lp171013SetStatus(
                id,
                'termine'
              );
            }
            else{
              lp171013SetStatus(
                id,
                'afaire'
              );
            }

          };

      }
    );
}

function lp171013Bind(){

  const add =
    document.getElementById(
      'lp171013Add'
    );

  if(add){

    add.onclick =
      function(e){

        e.preventDefault();
        e.stopPropagation();

        lp171013AddAction();

      };

  }

  lp171013BindControls();
}

function lp171013Apply(){

  try{

    if(
      typeof page ===
        'undefined' ||
      page !==
        'dgcontrol'
    ){
      return;
    }

    if(!lp171013IsDG()){
      return;
    }

    lp171013InstallStyle();

    if(
      document.getElementById(
        'lp171013Box'
      )
    ){
      return;
    }

    const title =
      Array.from(
        document.querySelectorAll(
          'h1'
        )
      ).find(
        el =>
          lp171013Norm(
            el.textContent
          ).includes(
            'tableau de controle dg'
          )
      );

    if(!title){
      return;
    }

    const section =
      title.closest(
        'section'
      );

    if(!section){
      return;
    }

    const wrapper =
      document.createElement(
        'div'
      );

    wrapper.innerHTML =
      lp171013Html();

    const box =
      wrapper.firstElementChild;

    const decisions =
      section.querySelector(
        '#lp171012Box'
      );

    if(decisions){

      decisions
        .insertAdjacentElement(
          'afterend',
          box
        );

    }
    else{

      const objectives =
        section.querySelector(
          '#lp171011Box'
        );

      if(objectives){

        objectives
          .insertAdjacentElement(
            'afterend',
            box
          );

      }
      else{

        const priorities =
          section.querySelector(
            '#lp17104Summary'
          );

        if(priorities){

          priorities
            .insertAdjacentElement(
              'beforebegin',
              box
            );

        }
        else{

          section.appendChild(
            box
          );

        }

      }

    }

    lp171013Bind();

  }
  catch(e){}
}

function lp171013Schedule(){

  setTimeout(
    lp171013Apply,
    80
  );

  setTimeout(
    lp171013Apply,
    300
  );

  setTimeout(
    lp171013Apply,
    700
  );
}

document.addEventListener(
  'click',
  function(){
    lp171013Schedule();
  },
  true
);

if(
  document.readyState ===
  'loading'
){

  document.addEventListener(
    'DOMContentLoaded',
    lp171013Schedule,
    {
      once:true
    }
  );

}
else{

  lp171013Schedule();

}

