function lp171014Apply(){

  try{

    if(
      typeof page ===
        'undefined' ||
      page !==
        'dgcontrol'
    ){
      return;
    }

    if(!lp171014IsDG()){
      return;
    }

    lp171014InstallStyle();

    const existing =
      document.getElementById(
        'lp171014Box'
      );

    if(existing){
      existing.outerHTML =
        lp171014Html();

      return;
    }

    const title =
      Array.from(
        document.querySelectorAll(
          'h1'
        )
      ).find(
        el =>
          lp171014Norm(
            el.textContent
          ).includes(
            'tableau de controle dg'
          )
      );

    if(!title){
      return;
    }

    const section =
      title.closest(
        'section'
      );

    if(!section){
      return;
    }

    const wrapper =
      document.createElement(
        'div'
      );

    wrapper.innerHTML =
      lp171014Html();

    const box =
      wrapper.firstElementChild;

    const actionPlan =
      section.querySelector(
        '#lp171013Box'
      );

    if(actionPlan){

      actionPlan
        .insertAdjacentElement(
          'afterend',
          box
        );

      return;
    }

    const decisions =
      section.querySelector(
        '#lp171012Box'
      );

    if(decisions){

      decisions
        .insertAdjacentElement(
          'afterend',
          box
        );

      return;
    }

    section.appendChild(
      box
    );

  }
  catch(e){}
}

function lp171014Schedule(){

  setTimeout(
    lp171014Apply,
    120
  );

  setTimeout(
    lp171014Apply,
    400
  );

  setTimeout(
    lp171014Apply,
    900
  );
}

document.addEventListener(
  'click',
  function(){
    lp171014Schedule();
  },
  true
);

document.addEventListener(
  'change',
  function(){
    lp171014Schedule();
  },
  true
);

if(
  document.readyState ===
  'loading'
){

  document.addEventListener(
    'DOMContentLoaded',
    lp171014Schedule,
    {
      once:true
    }
  );

}
else{

  lp171014Schedule();

}

