/* ================================================
   LEADER PHARMA 17.10.15
   CONTROLE RETARDS & ESCALADE DG

   AJOUT :
   - controle automatique des retards
   - niveaux de gravite
   - echeances proches
   - urgences non terminees
   - responsable concerne
   - recommandation d'escalade DG
   - suivi des escalades

   BASE :
   - 17.10.14 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - plan action DG
   - suivi execution DG
   - objectifs / previsions
   ================================================ */

function lp171015Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171015IsDG(){
  try{
    return lp171015Norm(
      currentUser?.role
    ) === 'dg';
  }
  catch(e){
    return false;
  }
}

function lp171015Actions(){
  try{
    if(
      typeof lp171013Read ===
      'function'
    ){
      const rows =
        lp171013Read();

      return Array.isArray(rows)
        ? rows
        : [];
    }
  }
  catch(e){}

  return [];
}

function lp171015Status(v){
  try{
    if(
      typeof lp171014Status ===
      'function'
    ){
      return lp171014Status(v);
    }
  }
  catch(e){}

  const s =
    lp171015Norm(v)
      .replace(/\s+/g,'');

  if(
    s === 'termine' ||
    s === 'terminee'
  ){
    return 'termine';
  }

  if(s === 'encours'){
    return 'encours';
  }

  return 'afaire';
}

function lp171015Days(v){
  try{
    if(
      typeof lp171014DaysUntil ===
      'function'
    ){
      return lp171014DaysUntil(v);
    }
  }
  catch(e){}

  if(!v){
    return null;
  }

  const d =
    new Date(
      String(v) +
      (
        String(v).length <= 10
          ? 'T12:00:00'
          : ''
      )
    );

  if(
    Number.isNaN(
      d.getTime()
    )
  ){
    return null;
  }

  const now =
    new Date();

  now.setHours(12,0,0,0);
  d.setHours(12,0,0,0);

  return Math.round(
    (
      d.getTime() -
      now.getTime()
    ) /
    86400000
  );
}

function lp171015FormatDate(v){
  try{
    if(
      typeof lp171014FormatDate ===
      'function'
    ){
      return lp171014FormatDate(v);
    }
  }
  catch(e){}

  if(!v){
    return '-';
  }

  try{
    return new Date(
      String(v) + 'T12:00:00'
    ).toLocaleDateString(
      'fr-CD'
    );
  }
  catch(e){
    return String(v);
  }
}

function lp171015EscalationKey(){
  return 'lp171015_escalations_dg';
}

function lp171015ReadEscalations(){

  try{

    const raw =
      localStorage.getItem(
        lp171015EscalationKey()
      );

    if(!raw){
      return {};
    }

    const parsed =
      JSON.parse(raw);

    return (
      parsed &&
      typeof parsed === 'object'
    )
      ? parsed
      : {};

  }
  catch(e){

    return {};

  }
}

function lp171015WriteEscalations(data){

  try{

    localStorage.setItem(
      lp171015EscalationKey(),
      JSON.stringify(data)
    );

    return true;

  }
  catch(e){

    return false;

  }
}

function lp171015Severity(action){

  const days =
    lp171015Days(
      action?.due
    );

  const urgent =
    lp171015Norm(
      action?.priority
    ) === 'urgent';

  if(
    days !== null &&
    days <= -7
  ){
    return {
      level:4,
      icon:'🚨',
      title:'Critique',
      text:
        'Retard supérieur ou égal à 7 jours'
    };
  }

  if(
    days !== null &&
    days <= -3
  ){
    return {
      level:3,
      icon:'🔴',
      title:'Très élevée',
      text:
        'Retard de 3 jours ou plus'
    };
  }

  if(
    days !== null &&
    days < 0
  ){
    return {
      level:2,
      icon:'🟠',
      title:'Élevée',
      text:
        'Action arrivée en retard'
    };
  }

  if(
    urgent &&
    days !== null &&
    days <= 3
  ){
    return {
      level:2,
      icon:'🟠',
      title:'Pré-alerte',
      text:
        'Action urgente proche de son échéance'
    };
  }

  if(
    days !== null &&
    days >= 0 &&
    days <= 3
  ){
    return {
      level:1,
      icon:'🟡',
      title:'Surveillance',
      text:
        'Échéance dans trois jours ou moins'
    };
  }

  return {
    level:0,
    icon:'🟢',
    title:'Normal',
    text:
      'Aucune escalade nécessaire'
  };
}

function lp171015Data(){

  const rows =
    lp171015Actions();

  const open =
    rows.filter(
      x =>
        lp171015Status(
          x?.status
        ) !== 'termine'
    );

  const escalations =
    lp171015ReadEscalations();

  const analysed =
    open.map(
      action => {

        const severity =
          lp171015Severity(
            action
          );

        return {
          action,
          severity,
          days:
            lp171015Days(
              action?.due
            ),
          escalated:
            Boolean(
              escalations[
                String(
                  action?.id || ''
                )
              ]
            )
        };

      }
    );

  const overdue =
    analysed.filter(
      x =>
        x.days !== null &&
        x.days < 0
    );

  const critical =
    analysed.filter(
      x =>
        x.severity.level >= 3
    );

  const watch =
    analysed.filter(
      x =>
        x.severity.level > 0 &&
        x.severity.level < 3
    );

  const escalated =
    analysed.filter(
      x =>
        x.escalated
    );

  return {
    rows,
    open,
    analysed,
    overdue,
    critical,
    watch,
    escalated
  };
}

function lp171015GlobalStatus(d){

  if(d.critical.length > 0){
    return {
      icon:'🚨',
      title:'Escalade DG immédiate',
      text:
        'Au moins une action présente un retard important nécessitant une intervention de direction.'
    };
  }

  if(d.overdue.length > 0){
    return {
      icon:'🔴',
      title:'Retards à traiter',
      text:
        'Des actions ouvertes ont dépassé leur échéance.'
    };
  }

  if(d.watch.length > 0){
    return {
      icon:'🟠',
      title:'Pré-alertes actives',
      text:
        'Des échéances proches nécessitent une surveillance renforcée.'
    };
  }

  if(d.open.length === 0){
    return {
      icon:'🏆',
      title:'Aucune escalade nécessaire',
      text:
        'Aucune action ouverte ne nécessite actuellement une escalade.'
    };
  }

  return {
    icon:'🟢',
    title:'Situation sous contrôle',
    text:
      'Les actions ouvertes restent dans les délais.'
  };
}

