/* ================================================
   LEADER PHARMA 17.10.16
   PERFORMANCE & RESPONSABILITE DG

   AJOUT :
   - performance par responsable
   - actions totales
   - actions terminees
   - actions ouvertes
   - actions en retard
   - actions urgentes ouvertes
   - taux d'execution
   - classement operationnel DG
   - lecture automatique de performance

   BASE :
   - 17.10.15 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - objectifs / previsions
   - alertes / decisions
   - plan d'action
   - suivi execution
   - controle retards
   - escalades
   ================================================ */

function lp171016Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171016IsDG(){
  try{
    return lp171016Norm(
      currentUser?.role
    ) === 'dg';
  }
  catch(e){
    return false;
  }
}

function lp171016Actions(){
  try{
    if(
      typeof lp171013Read ===
      'function'
    ){
      const rows =
        lp171013Read();

      return Array.isArray(rows)
        ? rows
        : [];
    }
  }
  catch(e){}

  return [];
}

function lp171016Status(v){

  try{
    if(
      typeof lp171013NormalizeStatus ===
      'function'
    ){
      return lp171013NormalizeStatus(v);
    }
  }
  catch(e){}

  const s =
    lp171016Norm(v)
      .replace(/\s+/g,'');

  if(
    s === 'termine' ||
    s === 'terminee'
  ){
    return 'termine';
  }

  if(s === 'encours'){
    return 'encours';
  }

  return 'afaire';
}

function lp171016DateKey(v){

  if(!v){
    return '';
  }

  const raw =
    String(v);

  const d =
    new Date(
      raw.length <= 10
        ? raw + 'T12:00:00'
        : raw
    );

  if(
    Number.isNaN(
      d.getTime()
    )
  ){
    return '';
  }

  return [
    d.getFullYear(),
    String(
      d.getMonth() + 1
    ).padStart(2,'0'),
    String(
      d.getDate()
    ).padStart(2,'0')
  ].join('-');
}

function lp171016Today(){

  return lp171016DateKey(
    new Date()
  );
}

function lp171016Data(){

  const rows =
    lp171016Actions();

  const owners = {};

  rows.forEach(
    x => {

      const owner =
        String(
          x?.owner ||
          'DG'
        ).trim() ||
        'DG';

      if(!owners[owner]){

        owners[owner] = {
          owner,
          total:0,
          done:0,
          open:0,
          overdue:0,
          urgent:0,
          rate:0
        };

      }

      const o =
        owners[owner];

      o.total += 1;

      const status =
        lp171016Status(
          x?.status
        );

      if(status === 'termine'){

        o.done += 1;

      }
      else{

        o.open += 1;

        const due =
          lp171016DateKey(
            x?.due
          );

        if(
          due &&
          due <
          lp171016Today()
        ){
          o.overdue += 1;
        }

        if(
          lp171016Norm(
            x?.priority
          ) === 'urgent'
        ){
          o.urgent += 1;
        }

      }

    }
  );

  const ranking =
    Object.values(
      owners
    )
    .map(
      o => {

        o.rate =
          o.total > 0
            ? (
                o.done /
                o.total
              ) * 100
            : 0;

        return o;

      }
    )
    .sort(
      (a,b) => {

        if(
          b.rate !==
          a.rate
        ){
          return (
            b.rate -
            a.rate
          );
        }

        if(
          a.overdue !==
          b.overdue
        ){
          return (
            a.overdue -
            b.overdue
          );
        }

        if(
          a.urgent !==
          b.urgent
        ){
          return (
            a.urgent -
            b.urgent
          );
        }

        return (
          b.total -
          a.total
        );

      }
    );

  const total =
    rows.length;

  const done =
    rows.filter(
      x =>
        lp171016Status(
          x?.status
        ) === 'termine'
    ).length;

  const open =
    total -
    done;

  const overdue =
    rows.filter(
      x => {

        if(
          lp171016Status(
            x?.status
          ) === 'termine'
        ){
          return false;
        }

        const due =
          lp171016DateKey(
            x?.due
          );

        return (
          due &&
          due <
          lp171016Today()
        );

      }
    ).length;

  const urgent =
    rows.filter(
      x =>
        lp171016Status(
          x?.status
        ) !== 'termine' &&
        lp171016Norm(
          x?.priority
        ) === 'urgent'
    ).length;

  const rate =
    total > 0
      ? (
          done /
          total
        ) * 100
      : 0;

  return {
    rows,
    ranking,
    total,
    done,
    open,
    overdue,
    urgent,
    rate
  };
}

function lp171016Message(d){

  if(d.total === 0){

    return {
      icon:'⚪',
      title:'Aucune performance à mesurer',
      text:
        'Aucune action DG n’est encore disponible pour établir la performance des responsables.'
    };

  }

  if(d.overdue > 0){

    return {
      icon:'🔴',
      title:'Responsabilités à renforcer',
      text:
        'Des actions en retard affectent actuellement la performance opérationnelle.'
    };

  }

  if(d.urgent > 0){

    return {
      icon:'🟠',
      title:'Actions urgentes à suivre',
      text:
        'Des actions urgentes restent ouvertes et nécessitent un suivi rapproché des responsables.'
    };

  }

  if(d.rate >= 100){

    return {
      icon:'🏆',
      title:'Exécution complète',
      text:
        'Toutes les actions enregistrées ont été exécutées.'
    };

  }

  if(d.rate >= 75){

    return {
      icon:'🟢',
      title:'Bonne performance',
      text:
        'Le niveau global d’exécution du plan d’action est satisfaisant.'
    };

  }

  if(d.rate >= 50){

    return {
      icon:'🟠',
      title:'Performance intermédiaire',
      text:
        'Une partie importante des actions reste encore à finaliser.'
    };

  }

  return {
    icon:'🔴',
    title:'Exécution à renforcer',
    text:
      'Le taux d’exécution reste faible et nécessite un suivi renforcé.'
  };
}

