/* ================================================
   LEADER PHARMA 17.10.17
   EVALUATION DES RESPONSABLES DG

   AJOUT :
   - score automatique /100
   - niveau de performance
   - taux d'execution
   - penalite retards
   - penalite urgences ouvertes
   - classement des responsables
   - recommandation manageriale DG

   BASE :
   - 17.10.16 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - plan action
   - suivi execution
   - escalades
   ================================================ */

function lp171017Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171017IsDG(){
  try{
    return lp171017Norm(
      currentUser?.role
    ) === 'dg';
  }
  catch(e){
    return false;
  }
}

function lp171017BaseData(){
  try{
    if(
      typeof lp171016Data ===
      'function'
    ){
      return lp171016Data();
    }
  }
  catch(e){}

  return {
    ranking:[],
    total:0,
    done:0,
    open:0,
    overdue:0,
    urgent:0,
    rate:0
  };
}

function lp171017Score(x){

  const total =
    Number(x?.total || 0);

  if(total <= 0){
    return 0;
  }

  const rate =
    Math.max(
      0,
      Math.min(
        100,
        Number(x?.rate || 0)
      )
    );

  const overdue =
    Number(
      x?.overdue || 0
    );

  const urgent =
    Number(
      x?.urgent || 0
    );

  const open =
    Number(
      x?.open || 0
    );

  let score =
    rate;

  score -=
    overdue * 15;

  score -=
    urgent * 7;

  if(
    open === 0 &&
    total > 0
  ){
    score += 10;
  }

  return Math.round(
    Math.max(
      0,
      Math.min(
        100,
        score
      )
    )
  );
}

function lp171017Level(score){

  const n =
    Number(score || 0);

  if(n >= 90){
    return {
      icon:'🏆',
      label:'Excellent',
      advice:
        'Performance exemplaire. Maintenir ce niveau d’exécution.'
    };
  }

  if(n >= 75){
    return {
      icon:'🟢',
      label:'Bon',
      advice:
        'Bonne performance. Finaliser les actions encore ouvertes.'
    };
  }

  if(n >= 50){
    return {
      icon:'🟠',
      label:'À surveiller',
      advice:
        'Renforcer le suivi et accélérer les actions en attente.'
    };
  }

  return {
    icon:'🔴',
    label:'Critique',
    advice:
      'Intervention managériale recommandée et suivi rapproché.'
  };
}

function lp171017Data(){

  const base =
    lp171017BaseData();

  const ranking =
    Array.isArray(
      base.ranking
    )
      ? base.ranking
          .map(
            x => {

              const score =
                lp171017Score(x);

              const level =
                lp171017Level(
                  score
                );

              return {
                ...x,
                score,
                level
              };

            }
          )
          .sort(
            (a,b) => {

              if(
                b.score !==
                a.score
              ){
                return (
                  b.score -
                  a.score
                );
              }

              return (
                Number(b.rate || 0) -
                Number(a.rate || 0)
              );

            }
          )
      : [];

  const average =
    ranking.length
      ? Math.round(
          ranking.reduce(
            (sum,x) =>
              sum +
              Number(
                x.score || 0
              ),
            0
          ) /
          ranking.length
        )
      : 0;

  const excellent =
    ranking.filter(
      x =>
        x.score >= 90
    ).length;

  const good =
    ranking.filter(
      x =>
        x.score >= 75 &&
        x.score < 90
    ).length;

  const watch =
    ranking.filter(
      x =>
        x.score >= 50 &&
        x.score < 75
    ).length;

  const critical =
    ranking.filter(
      x =>
        x.score < 50
    ).length;

  return {
    base,
    ranking,
    average,
    excellent,
    good,
    watch,
    critical
  };
}

function lp171017GlobalMessage(d){

  if(
    d.ranking.length === 0
  ){
    return {
      icon:'⚪',
      title:'Aucune évaluation disponible',
      text:
        'Ajoutez des actions et responsables pour commencer l’évaluation.'
    };
  }

  if(d.critical > 0){
    return {
      icon:'🔴',
      title:'Attention managériale requise',
      text:
        'Au moins un responsable présente un niveau de performance critique.'
    };
  }

  if(d.watch > 0){
    return {
      icon:'🟠',
      title:'Performance à surveiller',
      text:
        'Certains responsables nécessitent un accompagnement renforcé.'
    };
  }

  if(d.average >= 90){
    return {
      icon:'🏆',
      title:'Excellente performance globale',
      text:
        'Le niveau d’exécution des responsables est très élevé.'
    };
  }

  return {
    icon:'🟢',
    title:'Performance globale satisfaisante',
    text:
      'Les responsables maintiennent un niveau d’exécution satisfaisant.'
  };
}

