/* ================================================
   LEADER PHARMA 17.10.18
   EVOLUTION & PROGRESSION RESPONSABLES DG

   AJOUT :
   - historique local des scores
   - comparaison avec evaluation precedente
   - progression / regression / stable
   - variation du score
   - meilleur progres
   - responsable a surveiller
   - lecture automatique DG

   BASE :
   - 17.10.17 stable

   NE MODIFIE PAS :
   - stock
   - ventes
   - checkout()
   - factures
   - impression Z91
   - utilisateurs / roles
   - Supabase
   - objectifs
   - plan action
   - suivi execution
   - escalades
   - evaluation 17.10.17
   ================================================ */

const LP171018_KEY =
  'lpmp_dg_progression_171018';

function lp171018Norm(v){
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');
}

function lp171018IsDG(){
  try{
    return lp171018Norm(
      currentUser?.role
    ) === 'dg';
  }
  catch(e){
    return false;
  }
}

function lp171018Read(){

  try{
    const raw =
      localStorage.getItem(
        LP171018_KEY
      );

    if(!raw){
      return {};
    }

    const data =
      JSON.parse(raw);

    return (
      data &&
      typeof data === 'object'
    )
      ? data
      : {};
  }
  catch(e){
    return {};
  }
}

function lp171018Write(data){

  try{
    localStorage.setItem(
      LP171018_KEY,
      JSON.stringify(data)
    );
  }
  catch(e){}
}

function lp171018Evaluation(){

  try{
    if(
      typeof lp171017Data ===
      'function'
    ){
      const d =
        lp171017Data();

      return (
        d &&
        Array.isArray(d.ranking)
      )
        ? d.ranking
        : [];
    }
  }
  catch(e){}

  return [];
}

function lp171018Snapshot(){

  const rows =
    lp171018Evaluation();

  const history =
    lp171018Read();

  const now =
    Date.now();

  const result =
    rows.map(
      x => {

        const owner =
          String(
            x?.owner ||
            'DG'
          ).trim() ||
          'DG';

        const score =
          Math.round(
            Number(
              x?.score || 0
            )
          );

        const previous =
          history[owner] &&
          Number.isFinite(
            Number(
              history[owner].score
            )
          )
            ? Number(
                history[owner].score
              )
            : null;

        const delta =
          previous === null
            ? 0
            : score -
              previous;

        let trend =
          'stable';

        if(previous === null){
          trend =
            'nouveau';
        }
        else if(delta >= 5){
          trend =
            'progression';
        }
        else if(delta <= -5){
          trend =
            'regression';
        }

        return {
          owner,
          score,
          previous,
          delta,
          trend,
          rate:
            Math.round(
              Number(
                x?.rate || 0
              )
            ),
          total:
            Number(
              x?.total || 0
            ),
          done:
            Number(
              x?.done || 0
            ),
          open:
            Number(
              x?.open || 0
            ),
          overdue:
            Number(
              x?.overdue || 0
            ),
          urgent:
            Number(
              x?.urgent || 0
            ),
          level:
            x?.level || null,
          now
        };

      }
    );

  return {
    rows:result,
    history
  };
}

function lp171018SaveCurrent(rows){

  const history =
    lp171018Read();

  rows.forEach(
    x => {

      history[x.owner] = {
        score:x.score,
        rate:x.rate,
        done:x.done,
        open:x.open,
        overdue:x.overdue,
        urgent:x.urgent,
        savedAt:Date.now()
      };

    }
  );

  lp171018Write(
    history
  );
}

function lp171018Data(){

  const snap =
    lp171018Snapshot();

  const rows =
    snap.rows;

  const progressing =
    rows.filter(
      x =>
        x.trend ===
        'progression'
    );

  const regressing =
    rows.filter(
      x =>
        x.trend ===
        'regression'
    );

  const stable =
    rows.filter(
      x =>
        x.trend ===
        'stable'
    );

  const newRows =
    rows.filter(
      x =>
        x.trend ===
        'nouveau'
    );

  const bestProgress =
    progressing.length
      ? [...progressing]
          .sort(
            (a,b) =>
              b.delta -
              a.delta
          )[0]
      : null;

  const worstRegression =
    regressing.length
      ? [...regressing]
          .sort(
            (a,b) =>
              a.delta -
              b.delta
          )[0]
      : null;

  return {
    rows,
    progressing,
    regressing,
    stable,
    newRows,
    bestProgress,
    worstRegression
  };
}

function lp171018TrendMeta(x){

  if(
    x.trend ===
    'progression'
  ){
    return {
      icon:'📈',
      label:'En progression'
    };
  }

  if(
    x.trend ===
    'regression'
  ){
    return {
      icon:'📉',
      label:'En régression'
    };
  }

  if(
    x.trend ===
    'nouveau'
  ){
    return {
      icon:'🆕',
      label:'Première mesure'
    };
  }

  return {
    icon:'➡️',
    label:'Stable'
  };
}

function lp171018Message(d){

  if(
    d.rows.length === 0
  ){
    return {
      icon:'⚪',
      title:'Aucune évolution disponible',
      text:
        'Aucun responsable ne dispose encore d’une évaluation.'
    };
  }

  if(
    d.worstRegression
  ){
    return {
      icon:'📉',
      title:'Régression détectée',
      text:
        `${d.worstRegression.owner} présente une baisse de ${Math.abs(d.worstRegression.delta)} point(s).`
    };
  }

  if(
    d.bestProgress
  ){
    return {
      icon:'📈',
      title:'Progression détectée',
      text:
        `${d.bestProgress.owner} progresse de ${d.bestProgress.delta} point(s).`
    };
  }

  if(
    d.newRows.length ===
    d.rows.length
  ){
    return {
      icon:'🆕',
      title:'Point de référence créé',
      text:
        'Cette première mesure servira de base pour les prochaines comparaisons.'
    };
  }

  return {
    icon:'➡️',
    title:'Performance stable',
    text:
      'Aucune variation significative des scores n’est actuellement détectée.'
  };
}

