/* ============================================================
   LEADER PHARMA 17.10.19
   STOCK CENTRAL UNIQUE
   ------------------------------------------------------------
   REGLE :
   - le stock central Supabase est la reference commune
   - chaque vente cree un mouvement unique
   - la meme vente ne peut pas diminuer deux fois le stock
   - tous les appareils recuperent le meme stock central
   ============================================================ */

const LP171019_PENDING_KEY =
  'lp171019_stock_pending_v1';

function lp171019ReadPending(){

  try{

    const x =
      JSON.parse(
        localStorage.getItem(
          LP171019_PENDING_KEY
        ) || '[]'
      );

    return Array.isArray(x)
      ? x
      : [];

  }
  catch(e){

    return [];

  }

}

function lp171019WritePending(list){

  localStorage.setItem(
    LP171019_PENDING_KEY,
    JSON.stringify(
      Array.isArray(list)
        ? list
        : []
    )
  );

}

function lp171019ProductRef(product){

  if(!product){
    return '';
  }

  return String(
    product.id ?? ''
  ).trim();

}

function lp171019MovementFromSale(
  sale,
  item
){

  const product =
    db.products.find(
      p =>
        String(p.id) ===
        String(item.id)
    );

  const localStockAfter =
    Number(
      product?.stock || 0
    );

  return {

    mouvement_id:
      'vente:' +
      String(sale.id) +
      ':' +
      String(item.id),

    agence_id:
      String(
        sale.agency ||
        currentAgency ||
        'kamina'
      ),

    produit_ref:
      String(item.id),

    produit_nom:
      String(
        item.name ||
        product?.name ||
        ''
      ),

    lot:
      String(
        product?.lot ||
        ''
      ),

    quantite:
      Number(item.qty || 0),

    stock_avant:
      Math.max(
        0,
        localStockAfter +
        Number(item.qty || 0)
      ),

    vente_ref:
      String(
        sale.invoice ||
        sale.id ||
        ''
      )

  };

}

function lp171019QueueSale(
  sale
){

  if(
    !sale ||
    !Array.isArray(sale.items)
  ){
    return;
  }

  let pending =
    lp171019ReadPending();

  const known =
    new Set(
      pending.map(
        x =>
          String(
            x.mouvement_id
          )
      )
    );

  for(
    const item
    of sale.items
  ){

    const m =
      lp171019MovementFromSale(
        sale,
        item
      );

    if(
      !m.produit_ref ||
      !m.quantite ||
      m.quantite <= 0
    ){
      continue;
    }

    if(
      known.has(
        m.mouvement_id
      )
    ){
      continue;
    }

    pending.push(m);

    known.add(
      m.mouvement_id
    );

  }

  lp171019WritePending(
    pending
  );

}

async function lp171019RpcSale(
  movement
){

  const url =
    SUPABASE.url +
    '/rest/v1/rpc/' +
    'lp_apply_stock_sale';

  const body = {

    p_mouvement_id:
      movement.mouvement_id,

    p_agence_id:
      movement.agence_id,

    p_produit_ref:
      movement.produit_ref,

    p_produit_nom:
      movement.produit_nom,

    p_lot:
      movement.lot,

    p_quantite:
      Math.trunc(
        Number(
          movement.quantite
        )
      ),

    p_stock_avant:
      Math.max(
        0,
        Math.trunc(
          Number(
            movement.stock_avant
          )
        )
      ),

    p_vente_ref:
      movement.vente_ref

  };

  const r =
    await fetch(
      url,
      {
        method:'POST',
        headers:sbHeaders(),
        body:
          JSON.stringify(
            body
          )
      }
    );

  if(!r.ok){

    throw new Error(
      'Stock central RPC ' +
      r.status +
      ' ' +
      (
        await r.text()
      ).slice(
        0,
        180
      )
    );

  }

  const txt =
    await r.text();

  let stock = null;

  try{

    stock =
      JSON.parse(txt);

  }
  catch(e){

    stock =
      Number(txt);

  }

  stock =
    Number(stock);

  if(
    Number.isFinite(stock)
  ){

    const product =
      db.products.find(
        p =>
          String(p.id) ===
          String(
            movement.produit_ref
          )
      );

    if(product){

      product.stock =
        stock;

    }

  }

  return stock;

}

async function lp171019FlushPending(){

  const pending =
    lp171019ReadPending();

  if(
    !pending.length
  ){
    return true;
  }

  const remaining = [];

  for(
    const movement
    of pending
  ){

    try{

      await lp171019RpcSale(
        movement
      );

    }
    catch(e){

      console.warn(
        '17.10.19 mouvement en attente',
        movement,
        e
      );

      remaining.push(
        movement
      );

    }

  }

  lp171019WritePending(
    remaining
  );

  localStorage.setItem(
    'lpmp_v13',
    JSON.stringify(db)
  );

  return (
    remaining.length === 0
  );

}

async function lp171019CentralPull(){

  try{

    const url =
      SUPABASE.url +
      '/rest/v1/' +
      'lp_stock_central' +
      '?select=' +
      'agence_id,' +
      'produit_ref,' +
      'produit_nom,' +
      'lot,' +
      'stock,' +
      'updated_at';

    const r =
      await fetch(
        url,
        {
          headers:
            sbHeaders()
        }
      );

    if(!r.ok){

      throw new Error(
        'Lecture stock central ' +
        r.status +
        ' ' +
        (
          await r.text()
        ).slice(
          0,
          180
        )
      );

    }

    const rows =
      await r.json();

    if(
      !Array.isArray(rows)
    ){
      return false;
    }

    for(
      const row
      of rows
    ){

      const product =
        db.products.find(
          p =>
            String(
              p.id
            ) ===
            String(
              row.produit_ref
            ) &&
            String(
              p.agency ||
              'kamina'
            ) ===
            String(
              row.agence_id ||
              'kamina'
            )
        );

      if(!product){
        continue;
      }

      const centralStock =
        Number(
          row.stock
        );

      if(
        Number.isFinite(
          centralStock
        )
      ){

        product.stock =
          centralStock;

      }

    }

    localStorage.setItem(
      'lpmp_v13',
      JSON.stringify(db)
    );

    return true;

  }
  catch(e){

    console.warn(
      '17.10.19 stock central hors ligne',
      e
    );

    return false;

  }

}

const lp171019BaseSyncPull =
  syncPull;

const lp171019BaseSyncPush =
  syncPush;

const lp171019BaseCheckout =
  checkout;

syncPull =
  async function(){

    const result =
      await lp171019BaseSyncPull();

    await lp171019FlushPending();

    await lp171019CentralPull();

    localStorage.setItem(
      'lpmp_v13',
      JSON.stringify(db)
    );

    syncState =
      'Connecté • Stock central unique';

    return result;

  };

syncPush =
  async function(){

    await lp171019FlushPending();

    await lp171019CentralPull();

    const result =
      await lp171019BaseSyncPush();

    await lp171019CentralPull();

    localStorage.setItem(
      'lpmp_v13',
      JSON.stringify(db)
    );

    if(
      lp171019ReadPending()
        .length === 0
    ){

      syncState =
        'Synchronisé • Stock central unique';

    }
    else{

      syncState =
        'Stock en attente de synchronisation';

    }

    return result;

  };

checkout =
  function(){

    /*
     * LEADER PHARMA 17.10.25
     * UNE VENTE = UNE SEULE DIMINUTION.
     *
     * Le checkout original enregistre toujours
     * normalement la vente et diminue le stock local.
     *
     * L ancien mecanisme 17.10.19 ne transmet plus
     * cette meme vente une premiere fois a Supabase.
     *
     * Seul le mecanisme 17.10.21 transmet ensuite
     * le mouvement au stock central.
     */

    return lp171019BaseCheckout.apply(
      this,
      arguments
    );

  };

