/* ============================================================
   LEADER PHARMA 17.10.27
   FACTURE RESTE A L ECRAN
   ------------------------------------------------------------
   La facture reste affichee apres validation.
   Les synchronisations peuvent continuer en arriere-plan.
   Aucun render automatique de la page ventes ne peut
   remplacer la facture.
   ============================================================ */

let lp171027ReceiptLocked =
  false;


const lp171027BaseShowReceipt =
  showReceipt;


const lp171027BaseRender =
  render;


showReceipt =
  function(sale){

    lp171027ReceiptLocked =
      true;

    const result =
      lp171027BaseShowReceipt.apply(
        this,
        arguments
      );


    /*
     * Le bouton Nouvelle vente est la sortie normale
     * de l ecran facture.
     */

    const newSaleButton =
      document.querySelector(
        '#newSale'
      );

    if(newSaleButton){

      newSaleButton.onclick =
        function(){

          lp171027ReceiptLocked =
            false;

          page =
            'sales';

          lp171027BaseRender();

        };

    }


    /*
     * Impression ne ferme jamais la facture.
     */

    return result;

  };


render =
  function(){

    /*
     * Tant que la facture est verrouillee
     * et que nous sommes toujours sur la page ventes,
     * les render automatiques de synchronisation
     * sont ignores.
     */

    if(
      lp171027ReceiptLocked &&
      page === 'sales'
    ){

      console.log(
        '17.10.27 FACTURE CONSERVEE - RENDER AUTO IGNORE'
      );

      return;

    }


    /*
     * Si utilisateur choisit volontairement
     * Stock, Dashboard, etc., on autorise la navigation.
     */

    if(
      lp171027ReceiptLocked &&
      page !== 'sales'
    ){

      lp171027ReceiptLocked =
        false;

    }


    return lp171027BaseRender.apply(
      this,
      arguments
    );

  };


