function lp171031Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(
      /[\u0300-\u036f]/g,
      ''
    );

}


function lp171031Role(){

  try{

    return lp171031Norm(
      currentUser?.role || ''
    );

  }
  catch(e){

    return '';

  }

}


function lp171031IsDG(){

  return (
    lp171031Role() === 'dg'
  );

}


