/* =========================================================
   LEADER PHARMA 17.10.32
   SEPT RUBRIQUES UTILISATEURS
   ========================================================= */

function lp171032Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'');

}


function lp171032Role(){

  try{

    return lp171032Norm(
      currentUser?.role || ''
    );

  }catch(e){

    return '';

  }

}


function lp171032IsDG(){

  return lp171032Role() === 'dg';

}


const LP171032_OPEN = new Set([
  'dashboard',
  'sales',
  'stock',
  'inventory',
  'reports',
  'alerts',
  'settings',
  'payroll'
]);


const LP171032_READONLY = new Set([
  'stock',
  'inventory',
  'reports',
  'alerts',
  'settings'
]);


/*
 * ---------------------------------------------------------
 * ACCES AUX 7 RUBRIQUES
 * ---------------------------------------------------------
 */

function lp171032AllowPage(){

  if(
    !currentUser ||
    lp171032IsDG()
  ){
    return;
  }


  if(
    LP171032_OPEN.has(
      String(page || '')
    )
  ){

    /*
     * Neutralise l'ancien blocage
     * "Acces non autorise pour ce role"
     * pour les 7 pages communes.
     */

    try{

      window.__LP171032_ALLOWED_PAGE =
        String(page || '');

    }catch(e){}

  }

}


/*
 * ---------------------------------------------------------
 * SUPPRESSION DEMANDE MOT DE PASSE DG
 * UNIQUEMENT POUR OUVRIR LES RUBRIQUES COMMUNES.
 *
 * Une operation sensible reste protegee.
 * ---------------------------------------------------------
 */

const lp171032PromptOriginal =
  window.prompt.bind(window);


window.prompt =
  function(message,defaultValue){

    const msg =
      lp171032Norm(message);


    if(
      currentUser &&
      !lp171032IsDG() &&
      LP171032_OPEN.has(
        String(page || '')
      ) &&
      (
        msg.includes('mot de passe dg') ||
        msg.includes('securite dg')
      )
    ){

      /*
       * On autorise seulement l'ouverture.
       * Les boutons d'ecriture seront bloques
       * juste apres le rendu.
       */

      return '';

    }


    return lp171032PromptOriginal(
      message,
      defaultValue
    );

  };


/*
 * ---------------------------------------------------------
 * MODE CONSULTATION
 * ---------------------------------------------------------
 */

function lp171032ReadOnly(){

  if(
    !currentUser ||
    lp171032IsDG()
  ){
    return;
  }


  const currentPage =
    String(page || '');


  if(
    !LP171032_READONLY.has(
      currentPage
    )
  ){
    return;
  }


  const root =
    document.querySelector('#content') ||
    document.querySelector('main') ||
    document.body;


  if(!root){
    return;
  }


  /*
   * Mots correspondant aux operations
   * qui modifient les donnees.
   */

  const forbidden =
    /^(ajouter|modifier|supprimer|effacer|enregistrer|sauvegarder|créer|creer|nouveau|nouvelle|valider|ajuster|corriger|éditer|editer|importer|synchroniser|réinitialiser|reinitialiser)$/i;


  root
    .querySelectorAll(
      'button, input[type="submit"], input[type="button"]'
    )
    .forEach(function(el){

      /*
       * Ne jamais toucher au menu.
       */

      if(
        el.closest &&
        el.closest('#nav')
      ){
        return;
      }


            if(
        el.id === 'lpV11SavePrescription' ||
        el.id === 'lpV13SaveNote'
      ){
        el.disabled = false;
        el.removeAttribute('disabled');
        el.removeAttribute('data-lp171032-readonly');
        el.style.pointerEvents = 'auto';
        el.style.opacity = '';
        el.title = '';
        return;
      }

const txt =
        String(
          el.textContent ||
          el.value ||
          el.getAttribute('aria-label') ||
          ''
        ).trim();


      if(
        forbidden.test(txt)
      ){

        el.disabled = true;

        el.setAttribute(
          'data-lp171032-readonly',
          '1'
        );

        el.style.opacity = '0.45';

        el.style.pointerEvents = 'none';

        el.title =
          'Consultation uniquement';

      }

    });


  /*
   * Champs d'edition.
   *
   * Recherche et filtres restent utilisables.
   */

  root
    .querySelectorAll(
      'input, textarea, select'
    )
    .forEach(function(el){

      const type =
        String(
          el.type || ''
        ).toLowerCase();


      const placeholder =
        lp171032Norm(
          el.placeholder || ''
        );


      /*
       * Recherche autorisee.
       */

      if(
        type === 'search' ||
        placeholder.includes('recherch')
      ){
        return;
      }


      /*
       * Choix agence / filtres :
       * on conserve la consultation.
       */

      const name =
        lp171032Norm(
          el.name ||
          el.id ||
          ''
        );


      if(
        name.includes('agency') ||
        name.includes('agence') ||
        name.includes('filter') ||
        name.includes('filtre')
      ){
        return;
      }


      /*
       * Aucun formulaire de modification
       * dans les pages lecture seule.
       */

      if(
        el.closest &&
        el.closest('form')
      ){

        if(
          el.tagName === 'SELECT'
        ){

          el.disabled = true;

        }else{

          el.readOnly = true;

        }

      }

    });

}


