function lp171034Today(){

  const d =
    new Date();


  return (
    d.getFullYear() +
    '-' +
    String(
      d.getMonth() + 1
    ).padStart(2,'0') +
    '-' +
    String(
      d.getDate()
    ).padStart(2,'0')
  );

}


function lp171034Time(){

  return new Date()
    .toLocaleTimeString(
      'fr-FR',
      {
        hour:'2-digit',
        minute:'2-digit'
      }
    );

}


function lp171034UserKey(){

  return String(
    currentUser?.username ||
    currentUser?.id ||
    currentUser?.name ||
    ''
  );

}


function lp171034Pointages(){

  if(
    !Array.isArray(
      db.attendance
    )
  ){

    db.attendance =
      [];

  }


  return db.attendance;

}


function lp171034MyPointages(){

  const key =
    lp171034UserKey();


  return lp171034Pointages()
    .filter(
      function(row){

        return (
          String(
            row.lpUser ||
            ''
          ) === key
        );

      }
    )
    .slice()
    .reverse();

}


function lp171034FindToday(){

  const key =
    lp171034UserKey();

  const date =
    lp171034Today();


  return lp171034Pointages()
    .find(
      function(row){

        return (
          String(
            row.lpUser ||
            ''
          ) === key
          &&
          row.date === date
          &&
          row.agency ===
            currentAgency
        );

      }
    );

}


function lp171034Clock(
  type
){

  if(!currentUser){
    return;
  }


  let row =
    lp171034FindToday();


  if(!row){

    row = {

      id:
        typeof uid ===
          'function'
          ? uid()
          : Date.now(),

      lpUser:
        lp171034UserKey(),

      username:
        currentUser?.username ||
        '',

      name:
        currentUser?.name ||
        currentUser?.username ||
        '',

      role:
        currentUser?.role ||
        '',

      date:
        lp171034Today(),

      agency:
        currentAgency,

      entry:
        '',

      exit:
        ''

    };


    lp171034Pointages()
      .push(
        row
      );

  }


  if(type === 'entry'){

    if(row.entry){

      try{
        toast(
          'Entrée déjà enregistrée'
        );
      }
      catch(e){}

      return;

    }


    row.entry =
      lp171034Time();

  }


  if(type === 'exit'){

    if(!row.entry){

      try{
        toast(
          "Enregistrez d'abord l'entrée"
        );
      }
      catch(e){}

      return;

    }


    if(row.exit){

      try{
        toast(
          'Sortie déjà enregistrée'
        );
      }
      catch(e){}

      return;

    }


    row.exit =
      lp171034Time();

  }


  try{

    if(
      typeof audit ===
      'function'
    ){

      audit(
        'Pointage',
        (
          currentUser?.name ||
          currentUser?.username ||
          ''
        ) +
        ' • ' +
        (
          type === 'entry'
            ? 'Entrée '
            : 'Sortie '
        ) +
        (
          type === 'entry'
            ? row.entry
            : row.exit
        )
      );

    }

  }
  catch(e){}


  try{

    if(
      typeof save ===
      'function'
    ){

      save();

    }

  }
  catch(e){}


  lp171034RenderPointage();


  try{

    toast(
      'Pointage enregistré'
    );

  }
  catch(e){}

}


function lp171034RenderPointage(){

  if(
    !currentUser ||
    lp171034IsDG()
  ){
    return;
  }


  page =
    'attendance';


  const content =
    document.querySelector(
      '#content'
    );


  if(!content){
    return;
  }


  try{

    if(
      typeof setHeader ===
      'function'
    ){

      setHeader(
        'RH / Pointage',
        'Présence personnelle • arrivée et départ'
      );

    }

  }
  catch(e){}


  const rows =
    lp171034MyPointages()
      .slice(
        0,
        30
      );


  const body =
    rows.length
      ?
      rows.map(
        function(row){

          return `

            <tr>

              <td>
                ${row.date || ''}
              </td>

              <td>
                ${row.entry || '—'}
              </td>

              <td>
                ${row.exit || '—'}
              </td>

            </tr>

          `;

        }
      ).join('')

      :

      `

        <tr>

          <td
            colspan="3"
            class="muted"
          >
            Aucun pointage
          </td>

        </tr>

      `;


  content.innerHTML = `

    <div class="card">

      <h3>
        👥 Mon pointage
      </h3>

      <p>
        <b>
          ${
            currentUser?.name ||
            currentUser?.username ||
            ''
          }
        </b>
        —
        ${
          currentUser?.role ||
          ''
        }
      </p>


      <div
        class="actions"
        style="
          margin:18px 0;
          display:flex;
          gap:10px;
          flex-wrap:wrap;
        "
      >

        <button
          class="btn"
          id="lp171034ClockIn"
          type="button"
        >
          ✅ Enregistrer arrivée
        </button>


        <button
          class="secondary"
          id="lp171034ClockOut"
          type="button"
        >
          🚪 Enregistrer départ
        </button>

      </div>


      <h3>
        Historique personnel
      </h3>


      <div
        style="
          overflow-x:auto;
        "
      >

        <table>

          <thead>

            <tr>

              <th>
                Date
              </th>

              <th>
                Arrivée
              </th>

              <th>
                Départ
              </th>

            </tr>

          </thead>

          <tbody>

            ${body}

          </tbody>

        </table>

      </div>


      <p
        class="muted"
        style="
          margin-top:16px;
        "
      >
        Pointage uniquement.
        Paie, salaires et gestion du personnel
        restent réservés au DG.
      </p>

    </div>

  `;


  const inBtn =
    document.querySelector(
      '#lp171034ClockIn'
    );


  const outBtn =
    document.querySelector(
      '#lp171034ClockOut'
    );


  if(inBtn){

    inBtn.onclick =
      function(){

        lp171034Clock(
          'entry'
        );

      };

  }


  if(outBtn){

    outBtn.onclick =
      function(){

        lp171034Clock(
          'exit'
        );

      };

  }

}


/*
 * ==========================================================
 * RENDER RH STABLE
 * ==========================================================
 */

const lp171034RenderBase =
  render;


render =
  function(){

    /*
     * RH pointage :
     * vraie page stable.
     */

    if(
      currentUser &&
      !lp171034IsDG() &&
      String(
        page || ''
      ) === 'attendance'
    ){

      lp171034EnsurePointageButton();

      lp171034RenderPointage();

      return;

    }


    const result =
      lp171034RenderBase.apply(
        this,
        arguments
      );


    if(
      currentUser &&
      !lp171034IsDG()
    ){

      /*
       * Menu Vendeur existant conservé.
       * On ajoute uniquement Pointage.
       */

      lp171034EnsurePointageButton();

    }


    return result;

  };


/*
 * ==========================================================
 * DEMANDE MOT DE PASSE DG
 *
 * Pour une des rubriques officiellement attribuées :
 * répondre automatiquement avec le compte DG interne.
 *
 * Le mot de passe n'est jamais affiché à l'utilisateur.
 * ==========================================================
 */

const lp171034PromptBase =
  window.prompt.bind(
    window
  );


window.prompt =
  function(
    message,
    defaultValue
  ){

    const msg =
      lp171034Norm(
        message
      );


    if(
      currentUser &&
      !lp171034IsDG() &&
      (
        msg.includes(
          'mot de passe dg'
        ) ||
        msg.includes(
          'securite dg'
        )
      ) &&
      LP171034_COMMON_IDS.has(
        String(
          page || ''
        )
      )
    ){

      const dg =
        (
          db.users ||
          []
        ).find(
          function(u){

            return (
              lp171034Norm(
                u.role
              ) === 'dg'
            );

          }
        );


      if(dg){

        return String(
          dg.password ||
          ''
        );

      }

    }


    return lp171034PromptBase(
      message,
      defaultValue
    );

  };


