/*
 * ==========================================================
 * RH / POINTAGE
 *
 * Utilise directement le compte connecté.
 * Pas besoin de compte agent séparé.
 * ==========================================================
 */

function lp171035PointageUserKey(){

  return String(
    currentUser?.username ||
    currentUser?.id ||
    currentUser?.name ||
    ''
  );

}


function lp171035Today(){

  const d =
    new Date();


  return (
    d.getFullYear() +
    '-' +
    String(
      d.getMonth() + 1
    ).padStart(2,'0') +
    '-' +
    String(
      d.getDate()
    ).padStart(2,'0')
  );

}


function lp171035Time(){

  return new Date()
    .toLocaleTimeString(
      'fr-FR',
      {
        hour:'2-digit',
        minute:'2-digit'
      }
    );

}


function lp171035AttendanceList(){

  if(
    !Array.isArray(
      db.attendance
    )
  ){

    db.attendance =
      [];

  }


  return db.attendance;

}


function lp171035TodayRow(){

  const key =
    lp171035PointageUserKey();


  return lp171035AttendanceList()
    .find(
      function(row){

        return (
          row.lpUser === key &&
          row.date ===
            lp171035Today() &&
          row.agency ===
            currentAgency
        );

      }
    );

}


function lp171035Clock(type){

  if(!currentUser){
    return;
  }


  let row =
    lp171035TodayRow();


  if(!row){

    row = {

      id:
        typeof uid === 'function'
          ? uid()
          : Date.now(),

      lpUser:
        lp171035PointageUserKey(),

      name:
        currentUser?.name ||
        currentUser?.username ||
        '',

      username:
        currentUser?.username ||
        '',

      role:
        currentUser?.role ||
        '',

      agency:
        currentAgency,

      date:
        lp171035Today(),

      entry:
        '',

      exit:
        ''

    };


    lp171035AttendanceList()
      .push(
        row
      );

  }


  if(type === 'entry'){

    if(row.entry){

      try{
        toast(
          'Arrivée déjà enregistrée'
        );
      }
      catch(e){}

      return;

    }


    row.entry =
      lp171035Time();

  }


  if(type === 'exit'){

    if(!row.entry){

      try{
        toast(
          "Enregistrez d'abord l'arrivée"
        );
      }
      catch(e){}

      return;

    }


    if(row.exit){

      try{
        toast(
          'Départ déjà enregistré'
        );
      }
      catch(e){}

      return;

    }


    row.exit =
      lp171035Time();

  }


  try{

    save();

  }
  catch(e){}


  try{

    audit(
      'Pointage',
      (
        currentUser?.username ||
        ''
      ) +
      ' • ' +
      (
        type === 'entry'
          ? 'Arrivée'
          : 'Départ'
      )
    );

  }
  catch(e){}


  lp171035RenderPointage();


  try{

    toast(
      'Pointage enregistré'
    );

  }
  catch(e){}

}


