function lp171042FixButton(){

  const nav =
    document.querySelector('#nav');

  if(!nav){
    return null;
  }

  return Array.from(
    nav.querySelectorAll('.nav-btn')
  ).find(
    function(btn){

      const p =
        String(
          btn.dataset?.p ||
          btn.dataset?.page ||
          ''
        )
        .trim()
        .toLowerCase();

      return p === 'payroll';

    }
  ) || null;

}


