/* ==========================================================
   4. INTERCEPTION SPECIFIQUE VENDEUR RH

   Capture AVANT ancien bloc "Accès réservé Direction".

   UNIQUEMENT RH.
   ========================================================== */


document.addEventListener(
  'click',
  function(e){

    if(
      !currentUser ||
      lp171044IsDG()
    ){

      return;

    }


    const role =
      lp171044Norm(
        currentUser?.role ||
        ''
      );


    if(
      role !== 'vendeur'
    ){

      return;

    }


    const target =
      e.target?.closest?.(
        '#nav .nav-btn'
      );


    if(!target){

      return;

    }


    const p =
      lp171044Norm(
        target.dataset?.p ||
        target.dataset?.page ||
        ''
      );


    const text =
      lp171044Norm(
        target.textContent ||
        ''
      );


    if(
      p !== 'payroll' &&
      p !== 'attendance' &&
      !text.includes(
        'rh / pointage'
      ) &&
      !text.includes(
        'rh pointage'
      )
    ){

      return;

    }


    /*
     * On prend complètement la main
     * AVANT le vieux verrou Vendeur.
     */

    e.preventDefault();

    e.stopImmediatePropagation();


    page =
      'payroll';


    target.dataset.p =
      'payroll';


    document
      .querySelectorAll(
        '#nav .nav-btn'
      )
      .forEach(
        function(other){

          other.classList.toggle(
            'active',
            other === target
          );

        }
      );


    if(
      typeof lp171042RenderPointage ===
        'function'
    ){

      lp171042RenderPointage();

    }
    else if(
      typeof payroll ===
        'function'
    ){

      payroll();

    }

  },
  true
);


