/* ============================================================
   RH DIRECT V7.1
   ============================================================ */


let lpV71RHBusy =
  false;


document.addEventListener(
  'click',
  function(e){

    if(
      !currentUser ||
      lpV71IsDG()
    ){

      return;

    }


    const btn =
      e.target?.closest?.(
        '#nav .nav-btn'
      );


    if(!btn){
      return;
    }


    const destination =
      String(
        btn.dataset?.p ||
        btn.dataset?.page ||
        ''
      )
      .trim()
      .toLowerCase();


    const text =
      String(
        btn.textContent || ''
      )
      .trim()
      .toLowerCase();


    const isRH =
      destination === 'payroll'
      ||
      destination === 'attendance'
      ||
      text.includes(
        'rh / pointage'
      )
      ||
      text.includes(
        'rh pointage'
      );


    if(!isRH){
      return;
    }


    e.preventDefault();

    e.stopPropagation();


    if(
      typeof e.stopImmediatePropagation ===
        'function'
    ){

      e.stopImmediatePropagation();

    }


    if(lpV71RHBusy){
      return;
    }


    lpV71RHBusy =
      true;

    window.lpV71RHDirect =
      true;


    try{

      page =
        'payroll';


      /*
       * NE PAS RECONSTRUIRE LE MENU
       */

      document
        .querySelectorAll(
          '#nav .nav-btn'
        )
        .forEach(
          function(x){

            const p =
              String(
                x.dataset?.p ||
                x.dataset?.page ||
                ''
              )
              .trim()
              .toLowerCase();


            const t =
              String(
                x.textContent || ''
              )
              .trim()
              .toLowerCase();


            x.classList.toggle(
              'active',
              (
                p === 'payroll'
                ||
                p === 'attendance'
                ||
                t.includes(
                  'rh / pointage'
                )
              )
            );

          }
        );


      /*
       * UN SEUL RENDU RH
       */

      lp171042RenderPointage();


      lpV71Responsive();

    }
    finally{

      setTimeout(
        function(){

          window.lpV71RHDirect =
            false;

          lpV71RHBusy =
            false;

        },
        400
      );

    }

  },
  true
);


