/* V10 : anciennes couches RH V7.3-V8.2 retirees */



/* ============================================================
   LEADER PHARMA
   RH NETTOYAGE FINAL V10

   UN SEUL BOUTON RH
   UN SEUL RENDU POINTAGE
   DEPENSES CONSERVEES
   ============================================================ */


function lpV10Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase();

}


function lpV10IsDG(){

  return (
    currentUser
    &&
    lpV10Norm(
      currentUser.role
    ) === 'dg'
  );

}


/* ============================================================
   AUTORISATION PAYROLL UTILISATEURS
   ============================================================ */


const lpV10AllowedBase =
  allowed;


allowed =
  function(id){

    if(
      currentUser
      &&
      !lpV10IsDG()
      &&
      lpV10Norm(id) ===
        'payroll'
    ){

      return true;

    }


    return lpV10AllowedBase
      .apply(
        this,
        arguments
      );

  };


/* ============================================================
   BOUTON RH UNIQUE
   ============================================================ */


function lpV10FindRH(){

  const nav =
    document.querySelector(
      '#nav'
    );


  if(!nav){
    return null;
  }


  return Array.from(
    nav.querySelectorAll(
      '.nav-btn'
    )
  )
  .find(
    function(btn){

      return (
        lpV10Norm(
          btn.dataset?.p ||
          btn.dataset?.page
        ) === 'payroll'
      );

    }
  )
  || null;

}


function lpV10BindRH(btn){

  if(!btn){
    return null;
  }


  btn.dataset.p =
    'payroll';


  btn.textContent =
    '👥 RH / Pointage';


  /*
   * Un seul onclick.
   *
   * PAS DE buildNav().
   * PAS DE reconstruction menu.
   */

  btn.onclick =
    function(e){

      if(e){

        e.preventDefault();

        e.stopPropagation();

      }


      page =
        'payroll';


      const nav =
        document.querySelector(
          '#nav'
        );


      if(nav){

        nav
          .querySelectorAll(
            '.nav-btn'
          )
          .forEach(
            function(other){

              other.classList.toggle(
                'active',
                other === btn
              );

            }
          );

      }


      lpV10RenderRH();

    };


  return btn;

}


function lpV10EnsureRH(){

  if(
    !currentUser
    ||
    lpV10IsDG()
  ){

    return null;

  }


  const nav =
    document.querySelector(
      '#nav'
    );


  if(!nav){
    return null;
  }


  let rh =
    lpV10FindRH();


  if(rh){

    return lpV10BindRH(
      rh
    );

  }


  /*
   * Création SYNCHRONE.
   *
   * Elle se produit dans buildNav,
   * avant que le navigateur affiche
   * la nouvelle frame.
   */

  rh =
    document.createElement(
      'button'
    );


  rh.type =
    'button';


  rh.className =
    'nav-btn';


  rh.dataset.p =
    'payroll';


  rh.textContent =
    '👥 RH / Pointage';


  /*
   * Placer RH avant Rapports si possible.
   */

  const reports =
    Array.from(
      nav.querySelectorAll(
        '.nav-btn'
      )
    )
    .find(
      function(btn){

        return (
          lpV10Norm(
            btn.dataset?.p ||
            btn.dataset?.page
          ) === 'reports'
        );

      }
    );


  if(reports){

    nav.insertBefore(
      rh,
      reports
    );

  }
  else{

    nav.appendChild(
      rh
    );

  }


  return lpV10BindRH(
    rh
  );

}


