function lpV104FixExistingRH(){

  if(!currentUser){
    return null;
  }

  const role = String(
    currentUser.role || ''
  ).trim().toLowerCase();

  if(role === 'dg'){
    return null;
  }

  const nav = document.querySelector('#nav');

  if(!nav){
    return null;
  }

  let btn = nav.querySelector(
    '.nav-btn[data-p="payroll"]'
  );

  if(!btn){

    btn = Array.from(
      nav.querySelectorAll('.nav-btn')
    ).find(function(x){

      const id = String(
        x.dataset?.p || ''
      ).trim().toLowerCase();

      const txt = String(
        x.textContent || ''
      ).trim().toLowerCase();

      return (
        id === 'p' &&
        txt === 'a'
      );

    }) || null;

  }

  if(!btn){
    return null;
  }

  btn.dataset.p = 'payroll';
  btn.textContent = '👥 RH / Pointage';

  btn.style.animation = 'none';
  btn.style.transition = 'none';
  btn.style.transform = 'none';
  btn.style.opacity = '1';

  btn.onclick = function(e){

    if(e){
      e.preventDefault();
      e.stopPropagation();
    }

    page = 'payroll';

    if(typeof lpV10RenderRH === 'function'){
      lpV10RenderRH();
    }
    else{
      render();
    }

  };

  return btn;

}


