/* ============================================================
   LEADER PHARMA
   SECURITE PROTECTION V1

   COUCHE NON DESTRUCTIVE AUTOUR DE login()
   ============================================================ */

const LPSEC1_KEY =
  'leader_pharma_security_v1';

const LPSEC1_LOG_KEY =
  'leader_pharma_security_log_v1';

const LPSEC1_MAX_ATTEMPTS = 5;

const LPSEC1_LOCK_MS =
  5 * 60 * 1000;


function lpSec1Text(v){

  return String(v || '')
    .trim();

}


function lpSec1UserKey(){

  const field =
    document.querySelector('#username');

  return lpSec1Text(
    field?.value || 'inconnu'
  ).toLowerCase();

}


function lpSec1Read(){

  try{

    const raw = localStorage.getItem(
      LPSEC1_KEY
    );

    const data = raw
      ? JSON.parse(raw)
      : {};

    return (
      data &&
      typeof data === 'object'
    )
      ? data
      : {};

  }catch(e){

    return {};

  }

}


function lpSec1Write(data){

  try{

    localStorage.setItem(
      LPSEC1_KEY,
      JSON.stringify(data)
    );

  }catch(e){}

}


function lpSec1Log(
  type,
  detail
){

  try{

    const raw = localStorage.getItem(
      LPSEC1_LOG_KEY
    );

    let logs = raw
      ? JSON.parse(raw)
      : [];

    if(!Array.isArray(logs)){
      logs = [];
    }

    logs.push({
      date:new Date().toISOString(),
      type:lpSec1Text(type),
      detail:lpSec1Text(detail),
      user:lpSec1UserKey()
    });

    if(logs.length > 200){
      logs = logs.slice(-200);
    }

    localStorage.setItem(
      LPSEC1_LOG_KEY,
      JSON.stringify(logs)
    );

  }catch(e){}

}


function lpSec1State(user){

  const all = lpSec1Read();

  const state = all[user];

  if(
    state &&
    typeof state === 'object'
  ){

    return {
      attempts:Number(state.attempts || 0),
      lockedUntil:Number(
        state.lockedUntil || 0
      )
    };

  }

  return {
    attempts:0,
    lockedUntil:0
  };

}


function lpSec1SaveState(
  user,
  state
){

  const all = lpSec1Read();

  all[user] = {
    attempts:Number(
      state.attempts || 0
    ),
    lockedUntil:Number(
      state.lockedUntil || 0
    )
  };

  lpSec1Write(all);

}


function lpSec1Clear(user){

  const all = lpSec1Read();

  if(
    Object.prototype.hasOwnProperty.call(
      all,
      user
    )
  ){

    delete all[user];
    lpSec1Write(all);

  }

}


function lpSec1Error(message){

  const box =
    document.querySelector('#loginError');

  if(box){
    box.textContent = message;
  }

}


function lpSec1Minutes(ms){

  return Math.max(
    1,
    Math.ceil(ms / 60000)
  );

}


const lpSec1BaseLogin = login;

let lpSec1LoginBusy = false;


login = function(){

  if(lpSec1LoginBusy){
    return;
  }

  const user = lpSec1UserKey();

  const now = Date.now();

  let state = lpSec1State(user);


  if(
    state.lockedUntil > now
  ){

    const remaining =
      state.lockedUntil - now;

    lpSec1Error(
      'Sécurité : compte temporairement bloqué. Réessayez dans ' +
      lpSec1Minutes(remaining) +
      ' min.'
    );

    lpSec1Log(
      'connexion-bloquee',
      'Tentative pendant blocage'
    );

    return;

  }


  if(
    state.lockedUntil &&
    state.lockedUntil <= now
  ){

    state = {
      attempts:0,
      lockedUntil:0
    };

    lpSec1SaveState(
      user,
      state
    );

  }


  lpSec1LoginBusy = true;

  const before = currentUser;


  try{

    lpSec1BaseLogin.apply(
      this,
      arguments
    );

  }finally{

    lpSec1LoginBusy = false;

  }


  const success = !!(
    currentUser &&
    currentUser !== before
  );


  if(success){

    lpSec1Clear(user);

    lpSec1Log(
      'connexion-reussie',
      'Connexion autorisée'
    );

    return;

  }


  state = lpSec1State(user);

  state.attempts =
    Number(state.attempts || 0) + 1;


  const remaining =
    LPSEC1_MAX_ATTEMPTS -
    state.attempts;


  lpSec1Log(
    'connexion-echouee',
    'Echec ' +
    state.attempts +
    '/' +
    LPSEC1_MAX_ATTEMPTS
  );


  if(
    state.attempts >=
    LPSEC1_MAX_ATTEMPTS
  ){

    state.attempts = 0;

    state.lockedUntil =
      Date.now() +
      LPSEC1_LOCK_MS;

    lpSec1SaveState(
      user,
      state
    );

    lpSec1Error(
      'Sécurité : trop de tentatives. Connexion bloquée pendant 5 minutes.'
    );

    lpSec1Log(
      'blocage-active',
      '5 echecs de connexion'
    );

    return;

  }


  lpSec1SaveState(
    user,
    state
  );

  if(remaining > 0){

    lpSec1Error(
      'Identifiants incorrects ou compte désactivé. ' +
      remaining +
      ' tentative(s) restante(s).'
    );

  }

};


