/* ============================================================
   LEADER PHARMA
   RH DEPENSES UTILISATEURS DG V1

   AFFICHAGE UNIQUEMENT
   AUCUNE DUPLICATION DE db.expenses
   ============================================================ */

function lpRhExpenseNorm(v){

  return String(v || '')
    .trim();

}


function lpRhExpenseIsDG(){

  return !!(
    currentUser &&
    lpRhExpenseNorm(
      currentUser.role
    ).toLowerCase() === 'dg'
  );

}


function lpRhUserExpenses(){

  if(!Array.isArray(db.expenses)){
    return [];
  }

  return db.expenses
    .filter(function(x){

      const author = lpRhExpenseNorm(
        x.rhUser ||
        x.user ||
        x.username ||
        x.createdBy ||
        ''
      );

      const sameAgency = (
        !x.agency ||
        x.agency === currentAgency
      );

      return !!author && sameAgency;

    })
    .slice()
    .reverse()
    .slice(0, 100);

}


function lpRhMountUserExpensesDG(){

  if(!lpRhExpenseIsDG()){
    return;
  }

  const content =
    document.querySelector('#content');

  if(!content){
    return;
  }

  const previous =
    document.getElementById(
      'lp-rh-user-expenses-dg'
    );

  if(previous){
    previous.remove();
  }

  const rows =
    lpRhUserExpenses();

  const total =
    rows.reduce(function(sum,x){

      return sum +
        Number(x.amount || 0);

    },0);

  const card =
    document.createElement('div');

  card.id =
    'lp-rh-user-expenses-dg';

  card.className = 'card';

  card.style.marginTop = '16px';

  const body = rows.length
    ? rows.map(function(x){

        const author =
          lpRhExpenseNorm(
            x.rhUser ||
            x.user ||
            x.username ||
            x.createdBy ||
            '—'
          );

        const reason =
          lpRhExpenseNorm(
            x.reason ||
            x.desc ||
            x.category ||
            '—'
          );

        const agency =
          lpRhExpenseNorm(
            x.agency ||
            currentAgency ||
            '—'
          );

        let agencyLabel = agency;

        try{

          if(typeof agencyName === 'function'){
            agencyLabel = agencyName(agency);
          }

        }catch(e){}

        return (
          '<tr>' +
            '<td>' + esc(x.date || '—') + '</td>' +
            '<td>' + esc(author) + '</td>' +
            '<td>' + esc(reason) + '</td>' +
            '<td><b>' + money(Number(x.amount || 0)) + '</b></td>' +
            '<td>' + esc(agencyLabel) + '</td>' +
          '</tr>'
        );

      }).join('')
    : (
        '<tr>' +
          '<td colspan="5" class="muted">' +
            'Aucune dépense utilisateur enregistrée' +
          '</td>' +
        '</tr>'
      );

  card.innerHTML =
    '<div class="section-title">' +
      '<div>' +
        '<h3>💸 Dépenses effectuées par les utilisateurs</h3>' +
        '<p class="muted">Contrôle DG • dépenses enregistrées par le personnel</p>' +
      '</div>' +
      '<div><b>Total : ' + money(total) + '</b></div>' +
    '</div>' +
    '<div style="overflow-x:auto">' +
      '<table>' +
        '<thead>' +
          '<tr>' +
            '<th>Date</th>' +
            '<th>Utilisateur</th>' +
            '<th>Motif</th>' +
            '<th>Montant</th>' +
            '<th>Agence</th>' +
          '</tr>' +
        '</thead>' +
        '<tbody>' + body + '</tbody>' +
      '</table>' +
    '</div>';


  /*
   * Position choisie :
   * juste après la carte contenant
   * Présences / pointage.
   */

  const presenceTitle =
    Array.from(
      content.querySelectorAll('h3')
    ).find(function(h){

      return lpRhExpenseNorm(
        h.textContent
      ).toLowerCase()
       .includes('présences / pointage');

    });


  const presenceCard =
    presenceTitle
      ? presenceTitle.closest('.card')
      : null;


  if(
    presenceCard &&
    presenceCard.parentNode
  ){

    presenceCard.insertAdjacentElement(
      'afterend',
      card
    );

  }else{

    content.appendChild(card);

  }

}


const lpRhExpensePayrollBase = payroll;


payroll = function(){

  const result =
    lpRhExpensePayrollBase.apply(
      this,
      arguments
    );

  if(lpRhExpenseIsDG()){
    lpRhMountUserExpensesDG();
  }

  return result;

};


