/* ============================================================
   LEADER PHARMA
   SAUVEGARDE AUTOMATIQUE V1
   ============================================================ */

const LPBK1_KEY =
  'leader_pharma_auto_backups_v1';

const LPBK1_DAY_KEY =
  'leader_pharma_auto_backup_day_v1';

const LPBK1_MAX = 5;


function lpBk1IsDG(){

  return !!(
    currentUser &&
    String(currentUser.role || '')
      .trim()
      .toLowerCase() === 'dg'
  );

}


function lpBk1Read(){

  try{

    const raw =
      localStorage.getItem(LPBK1_KEY);

    const list = raw
      ? JSON.parse(raw)
      : [];

    return Array.isArray(list)
      ? list
      : [];

  }catch(e){

    return [];

  }

}


function lpBk1Write(list){

  try{

    localStorage.setItem(
      LPBK1_KEY,
      JSON.stringify(
        list.slice(0,LPBK1_MAX)
      )
    );

    return true;

  }catch(e){

    console.warn(
      'Sauvegarde locale impossible',
      e
    );

    return false;

  }

}


function lpBk1Signature(data){

  try{

    return JSON.stringify(data);

  }catch(e){

    return '';

  }

}


function lpBk1Snapshot(
  data,
  reason
){

  if(!data || typeof data !== 'object'){
    return false;
  }

  const payload =
    lpBk1Signature(data);

  if(!payload){
    return false;
  }

  let list = lpBk1Read();

  const last = list[0];

  if(
    last &&
    last.payload === payload
  ){
    return true;
  }

  list.unshift({

    id:
      'BKP-' +
      Date.now() +
      '-' +
      Math.random()
        .toString(36)
        .slice(2,7),

    createdAt:
      new Date().toISOString(),

    reason:
      String(reason || 'Automatique'),

    user:
      String(
        currentUser?.username ||
        currentUser?.name ||
        'systeme'
      ),

    agency:
      String(currentAgency || ''),

    payload:payload

  });

  list = list.slice(
    0,
    LPBK1_MAX
  );

  return lpBk1Write(list);

}


function lpBk1SnapshotPersisted(reason){

  try{

    const raw =
      localStorage.getItem('lpmp_v13');

    if(!raw){
      return false;
    }

    const previous =
      JSON.parse(raw);

    return lpBk1Snapshot(
      previous,
      reason
    );

  }catch(e){

    return false;

  }

}


function lpBk1Daily(){

  try{

    const day =
      typeof today === 'function'
        ? today()
        : new Date()
            .toISOString()
            .slice(0,10);

    const lastDay =
      localStorage.getItem(
        LPBK1_DAY_KEY
      );

    if(lastDay === day){
      return;
    }

    if(
      lpBk1Snapshot(
        db,
        'Sauvegarde quotidienne'
      )
    ){

      localStorage.setItem(
        LPBK1_DAY_KEY,
        day
      );

    }

  }catch(e){}

}


const lpBk1SaveBase = save;


save = function(){

  /*
   * Avant d'enregistrer le nouvel état,
   * conserver la version actuellement
   * stockée sur l'appareil.
   */

  lpBk1SnapshotPersisted(
    'Avant modification'
  );

  return lpBk1SaveBase.apply(
    this,
    arguments
  );

};


function lpBk1Restore(id){

  if(!lpBk1IsDG()){

    toast('Accès réservé au DG');
    return;

  }

  const list = lpBk1Read();

  const item = list.find(
    function(x){
      return x.id === id;
    }
  );

  if(!item){

    toast('Sauvegarde introuvable');
    return;

  }

  let restored;

  try{

    restored =
      JSON.parse(item.payload);

    restored = migrate(restored);

  }catch(e){

    toast('Sauvegarde invalide');
    return;

  }

  if(
    !restored ||
    typeof restored !== 'object'
  ){

    toast('Sauvegarde invalide');
    return;

  }

  if(
    !confirm(
      'Restaurer cette sauvegarde ? ' +
      'Une copie de l’état actuel sera créée avant restauration.'
    )
  ){
    return;
  }

  lpBk1Snapshot(
    db,
    'Avant restauration'
  );

  db = restored;

  lpBk1SaveBase();

  try{
    fillAgencies();
  }catch(e){}

  try{
    audit(
      'Restauration sécurité',
      item.createdAt
    );
  }catch(e){}

  toast('Sauvegarde restaurée');

  render();

}


function lpBk1Delete(id){

  if(!lpBk1IsDG()){
    return;
  }

  if(!confirm('Supprimer cette sauvegarde ?')){
    return;
  }

  const list = lpBk1Read()
    .filter(function(x){
      return x.id !== id;
    });

  lpBk1Write(list);

  lpBk1MountPanel();

}


function lpBk1DateLabel(value){

  try{

    return new Date(value)
      .toLocaleString('fr-FR');

  }catch(e){

    return String(value || '—');

  }

}


function lpBk1MountPanel(){

  if(!lpBk1IsDG()){
    return;
  }

  const content =
    document.querySelector('#content');

  if(!content){
    return;
  }

  const old =
    document.getElementById(
      'lp-auto-backup-v1'
    );

  if(old){
    old.remove();
  }

  const list = lpBk1Read();

  const card =
    document.createElement('div');

  card.id =
    'lp-auto-backup-v1';

  card.className = 'card';

  card.style.marginTop = '16px';

  const rows = list.length
    ? list.map(function(x,index){

        return (
          '<div class="list-item" ' +
               'style="align-items:flex-start;gap:12px">' +

            '<div style="flex:1">' +
              '<b>Sauvegarde ' +
                esc(String(index + 1)) +
              '</b><br>' +

              '<small class="muted">' +
                esc(lpBk1DateLabel(x.createdAt)) +
                ' • ' +
                esc(x.reason || 'Automatique') +
                ' • ' +
                esc(x.user || '—') +
              '</small>' +
            '</div>' +

            '<div class="actions">' +
              '<button type="button" ' +
                'class="secondary" ' +
                'data-lpbkrestore="' +
                esc(x.id) +
                '">Restaurer</button>' +

              '<button type="button" ' +
                'class="secondary" ' +
                'data-lpbkdelete="' +
                esc(x.id) +
                '">Supprimer</button>' +
            '</div>' +

          '</div>'
        );

      }).join('')
    : '<p class="muted">Aucune sauvegarde automatique disponible.</p>';

  card.innerHTML =
    '<h3>🛡️ Sauvegardes automatiques</h3>' +

    '<p class="muted">' +
      'Les 5 dernières copies locales sont conservées automatiquement. ' +
      'La restauration est réservée au DG.' +
    '</p>' +

    '<div class="actions" style="margin-bottom:14px">' +
      '<button type="button" class="btn" id="lpBkCreateNow">' +
        '💾 Sauvegarder maintenant' +
      '</button>' +
    '</div>' +

    '<div class="list">' +
      rows +
    '</div>';

  content.appendChild(card);


  const create =
    document.getElementById(
      'lpBkCreateNow'
    );

  if(create){

    create.onclick = function(){

      if(
        lpBk1Snapshot(
          db,
          'Sauvegarde manuelle DG'
        )
      ){

        try{
          audit(
            'Sauvegarde sécurité',
            'Copie locale DG'
          );
        }catch(e){}

        toast('Sauvegarde créée');

        lpBk1MountPanel();

      }

    };

  }


  card
    .querySelectorAll('[data-lpbkrestore]')
    .forEach(function(btn){

      btn.onclick = function(){
        lpBk1Restore(
          btn.dataset.lpbkrestore
        );
      };

    });


  card
    .querySelectorAll('[data-lpbkdelete]')
    .forEach(function(btn){

      btn.onclick = function(){
        lpBk1Delete(
          btn.dataset.lpbkdelete
        );
      };

    });

}


