function lpBk11IsSettingsPage(){

  return (
    typeof page !== 'undefined'
    &&
    String(page || '')
      .trim()
      .toLowerCase() === 'settings'
  );

}


function lpBk11Mount(){

  if(
    !currentUser
    ||
    !lpBk1IsDG()
    ||
    !lpBk11IsSettingsPage()
  ){
    return;
  }


  const content =
    document.querySelector(
      '#content'
    );


  if(!content){
    return;
  }


  /*
   * Le panneau V1 sait déjà :
   * - lire les sauvegardes
   * - créer une sauvegarde
   * - restaurer
   * - supprimer
   *
   * V1.1 ne fait que l'afficher
   * sur la vraie page Paramètres.
   */

  lpBk1MountPanel();

}


/*
 * On enveloppe le render FINAL actuel.
 *
 * Ainsi peu importe quelle ancienne fonction settings()
 * a construit la page :
 * une fois le rendu terminé,
 * V1.1 ajoute le panneau.
 */

const lpBk11RenderBase =
  render;


render =
  function(){

    const result =
      lpBk11RenderBase.apply(
        this,
        arguments
      );


    if(lpBk11IsSettingsPage()){

      lpBk11Mount();

    }


    return result;

  };


/*
 * Sécurité supplémentaire :
 * si une couche appelle directement settings()
 * sans passer par render(),
 * nous couvrons également ce cas.
 */

if(
  typeof settings ===
  'function'
){

  const lpBk11SettingsBase =
    settings;


  settings =
    function(){

      const result =
        lpBk11SettingsBase.apply(
          this,
          arguments
        );


      lpBk11Mount();


      return result;

    };

}


/*
 * Aucun timer.
 * Aucun MutationObserver.
 * Aucun changement du menu.
 */


