function lpBk12Text(v){

  return String(v || '')
    .trim()
    .toLowerCase();

}


function lpBk12FindModal(){

  if(
    !currentUser ||
    !lpBk1IsDG()
  ){
    return null;
  }


  const buttons =
    Array.from(
      document.querySelectorAll('button')
    );


  const closeBtn =
    buttons.find(function(btn){

      return (
        lpBk12Text(
          btn.textContent
        ) === 'fermer'
      );

    });


  if(!closeBtn){
    return null;
  }


  let node = closeBtn.parentElement;


  /*
   * On remonte jusqu'au conteneur
   * qui contient réellement les
   * paramètres DG.
   */

  for(let i = 0; i < 10 && node; i++){

    const text =
      lpBk12Text(
        node.textContent
      );


    if(
      text.includes(
        'journal de sécurité'
      )
      &&
      text.includes(
        'créer un compte agent'
      )
      &&
      text.includes(
        'fermer'
      )
    ){

      return {
        modal:node,
        closeBtn:closeBtn
      };

    }


    node =
      node.parentElement;

  }


  return null;

}


