/* ============================================================
   LEADER PHARMA
   SECURITE UTILISATEURS V2

   5 ECHECS = VERROUILLAGE 15 MINUTES
   DG = NON MODIFIE
   ============================================================ */


const LPSEC2_KEY =
  'leader_pharma_user_login_security_v2';


const LPSEC2_MAX_ATTEMPTS =
  5;


const LPSEC2_LOCK_MS =
  15 * 60 * 1000;


function lpSec2Norm(v){

  return String(v || '')
    .trim()
    .toLowerCase();

}


function lpSec2Read(){

  try{

    const raw =
      localStorage.getItem(
        LPSEC2_KEY
      );


    const obj =
      raw
      ? JSON.parse(raw)
      : {};


    return (
      obj &&
      typeof obj === 'object'
    )
      ? obj
      : {};

  }
  catch(e){

    return {};

  }

}


function lpSec2Write(data){

  try{

    localStorage.setItem(
      LPSEC2_KEY,
      JSON.stringify(data)
    );

    return true;

  }
  catch(e){

    return false;

  }

}


function lpSec2User(username){

  const key =
    lpSec2Norm(username);


  if(!key){
    return null;
  }


  return Array.isArray(db.users)
    ?
    db.users.find(
      function(u){

        return (
          lpSec2Norm(
            u.username
          ) === key
        );

      }
    ) || null
    :
    null;

}


function lpSec2IsDGUser(user){

  if(!user){
    return false;
  }


  return (
    lpSec2Norm(
      user.role
    ) === 'dg'
    ||
    lpSec2Norm(
      user.username
    ) === 'leader.fr'
  );

}


function lpSec2State(username){

  const key =
    lpSec2Norm(username);


  const all =
    lpSec2Read();


  const item =
    all[key] || {
      attempts:0,
      lockedUntil:0,
      lastAttempt:0
    };


  item.attempts =
    Number(
      item.attempts || 0
    );


  item.lockedUntil =
    Number(
      item.lockedUntil || 0
    );


  item.lastAttempt =
    Number(
      item.lastAttempt || 0
    );


  return item;

}


function lpSec2SaveState(
  username,
  state
){

  const key =
    lpSec2Norm(username);


  if(!key){
    return;
  }


  const all =
    lpSec2Read();


  all[key] =
    state;


  lpSec2Write(
    all
  );

}


function lpSec2Clear(username){

  const key =
    lpSec2Norm(username);


  if(!key){
    return;
  }


  const all =
    lpSec2Read();


  delete all[key];


  lpSec2Write(
    all
  );

}


function lpSec2RemainingMinutes(
  lockedUntil
){

  return Math.max(
    1,
    Math.ceil(
      (
        Number(lockedUntil || 0)
        -
        Date.now()
      )
      /
      60000
    )
  );

}


function lpSec2Audit(
  username,
  action,
  detail
){

  try{

    if(!Array.isArray(db.audit)){
      db.audit = [];
    }


    db.audit.push({

      id:
        typeof uid === 'function'
          ? uid()
          : (
              'SEC2-'
              +
              Date.now()
            ),

      date:
        typeof today === 'function'
          ? today()
          : new Date()
              .toISOString()
              .slice(0,10),

      time:
        new Date()
          .toLocaleTimeString(
            'fr-FR'
          ),

      user:
        String(
          username ||
          'inconnu'
        ),

      agency:
        currentAgency || '',

      action:
        action,

      detail:
        detail || ''

    });


    if(db.audit.length > 500){

      db.audit =
        db.audit.slice(-500);

    }


    /*
     * Enregistrer sans appeler audit()
     * afin de ne pas changer currentUser.
     */

    try{

      localStorage.setItem(
        'lpmp_v13',
        JSON.stringify(db)
      );

    }
    catch(e){}

  }
  catch(e){}

}


function lpSec2RegisterFailure(
  username
){

  const key =
    lpSec2Norm(username);


  if(!key){
    return null;
  }


  const user =
    lpSec2User(key);


  /*
   * La securite DG existante
   * reste totalement independante.
   */

  if(
    user &&
    lpSec2IsDGUser(user)
  ){

    return null;

  }


  const state =
    lpSec2State(key);


  const now =
    Date.now();


  if(
    state.lockedUntil &&
    state.lockedUntil > now
  ){

    return state;

  }


  state.attempts += 1;

  state.lastAttempt =
    now;


  if(
    state.attempts >=
    LPSEC2_MAX_ATTEMPTS
  ){

    state.lockedUntil =
      now +
      LPSEC2_LOCK_MS;


    lpSec2Audit(
      key,
      'Sécurité connexion',
      'Compte verrouillé 15 minutes après 5 échecs'
    );

  }
  else{

    lpSec2Audit(
      key,
      'Sécurité connexion',
      'Tentative de connexion refusée '
      +
      state.attempts
      +
      '/'
      +
      LPSEC2_MAX_ATTEMPTS
    );

  }


  lpSec2SaveState(
    key,
    state
  );


  return state;

}


function lpSec2Blocked(username){

  const key =
    lpSec2Norm(username);


  if(!key){
    return false;
  }


  const user =
    lpSec2User(key);


  if(
    user &&
    lpSec2IsDGUser(user)
  ){

    return false;

  }


  const state =
    lpSec2State(key);


  if(
    state.lockedUntil >
    Date.now()
  ){

    return state;

  }


  if(state.lockedUntil){

    lpSec2Clear(
      key
    );

  }


  return false;

}


function lpSec2SetError(message){

  const error =
    document.querySelector(
      '#loginError'
    );


  if(error){

    error.textContent =
      message;

  }

}


/* ============================================================
   ENVELOPPE LOGIN EXISTANT

   Le login original reste la seule fonction
   qui valide réellement le mot de passe.
   ============================================================ */


const lpSec2LoginBase =
  login;


login =
  function(){

    const username =
      lpSec2Norm(
        document.querySelector(
          '#username'
        )?.value
      );


    const candidate =
      lpSec2User(
        username
      );


    /*
     * DG :
     * laisser exactement la securite
     * actuelle travailler.
     */

    if(
      candidate &&
      lpSec2IsDGUser(
        candidate
      )
    ){

      return lpSec2LoginBase
        .apply(
          this,
          arguments
        );

    }


    const blocked =
      lpSec2Blocked(
        username
      );


    if(blocked){

      lpSec2SetError(
        'Compte temporairement verrouillé. Réessayez dans '
        +
        lpSec2RemainingMinutes(
          blocked.lockedUntil
        )
        +
        ' min ou contactez le DG.'
      );


      return;

    }


    const beforeUser =
      currentUser;


    const result =
      lpSec2LoginBase
        .apply(
          this,
          arguments
        );


    /*
     * Connexion réussie :
     * currentUser vient d'être défini.
     */

    if(
      currentUser &&
      currentUser !== beforeUser
    ){

      lpSec2Clear(
        username
      );


      return result;

    }


    /*
     * Echec :
     * enregistrer la tentative.
     */

    const state =
      lpSec2RegisterFailure(
        username
      );


    if(!state){

      return result;

    }


    if(
      state.lockedUntil >
      Date.now()
    ){

      lpSec2SetError(
        'Compte verrouillé pendant 15 minutes après trop de tentatives.'
      );

    }
    else{

      const remaining =
        Math.max(
          0,
          LPSEC2_MAX_ATTEMPTS
          -
          state.attempts
        );


      lpSec2SetError(
        'Identifiants incorrects. '
        +
        remaining
        +
        ' tentative(s) restante(s).'
      );

    }


    return result;

  };


/* ============================================================
   PANNEAU DG DEBLOCAGE
   DANS LA MODALE PARAMETRES EXISTANTE
   ============================================================ */


function lpSec2LockedAccounts(){

  const all =
    lpSec2Read();


  const now =
    Date.now();


  return Object.keys(all)
    .map(
      function(username){

        return {
          username:username,
          ...all[username]
        };

      }
    )
    .filter(
      function(x){

        return (
          Number(
            x.lockedUntil || 0
          )
          >
          now
        );

      }
    );

}


function lpSec2Unlock(username){

  if(
    !currentUser ||
    lpSec2Norm(
      currentUser.role
    ) !== 'dg'
  ){

    return;

  }


  lpSec2Clear(
    username
  );


  try{

    audit(
      'Sécurité connexion',
      'Déblocage manuel du compte '
      +
      username
    );

  }
  catch(e){}


  toast(
    'Compte débloqué'
  );


  lpSec2MountPanel();

}


function lpSec2MountPanel(){

  if(
    !currentUser ||
    lpSec2Norm(
      currentUser.role
    ) !== 'dg'
  ){

    return false;

  }


  const found =
    typeof lpBk12FindModal ===
      'function'
      ?
      lpBk12FindModal()
      :
      null;


  if(!found){
    return false;
  }


  const old =
    document.getElementById(
      'lp-security-users-v2'
    );


  if(old){
    old.remove();
  }


  const locked =
    lpSec2LockedAccounts();


  const card =
    document.createElement(
      'div'
    );


  card.id =
    'lp-security-users-v2';


  card.className =
    'card';


  card.style.marginTop =
    '16px';


  card.style.marginBottom =
    '16px';


  const rows =
    locked.length
      ?
      locked.map(
        function(x){

          return `

            <div
              class="list-item"
              style="
                display:flex;
                align-items:center;
                gap:10px;
                margin-top:10px;
              "
            >

              <div style="flex:1">

                <b>
                  ${esc(x.username)}
                </b>

                <br>

                <small class="muted">
                  Verrouillé •
                  ${
                    lpSec2RemainingMinutes(
                      x.lockedUntil
                    )
                  }
                  min restante(s)
                </small>

              </div>


              <button
                type="button"
                class="btn"
                data-lpsec2unlock="${esc(x.username)}"
              >
                Débloquer
              </button>

            </div>

          `;

        }
      )
      .join('')
      :
      `
        <p class="muted">
          Aucun compte utilisateur verrouillé.
        </p>
      `;


  card.innerHTML = `

    <h3>
      🔐 Sécurité des utilisateurs
    </h3>

    <p class="muted">
      Après 5 mots de passe incorrects,
      le compte est verrouillé pendant
      15 minutes. Le DG peut le débloquer ici.
    </p>

    <div class="list">
      ${rows}
    </div>

  `;


  card
    .querySelectorAll(
      '[data-lpsec2unlock]'
    )
    .forEach(
      function(btn){

        btn.onclick =
          function(){

            lpSec2Unlock(
              btn.dataset
                .lpsec2unlock
            );

          };

      }
    );


  /*
   * Placer la sécurité juste AVANT
   * la carte Sauvegardes automatiques
   * si elle existe.
   */

  const backupCard =
    document.getElementById(
      'lp-auto-backup-v12'
    );


  if(
    backupCard &&
    backupCard.parentElement
  ){

    backupCard
      .parentElement
      .insertBefore(
        card,
        backupCard
      );

  }
  else{

    const closeContainer =
      found.closeBtn
        ?.parentElement;


    if(
      closeContainer &&
      closeContainer.parentElement
    ){

      closeContainer
        .parentElement
        .insertBefore(
          card,
          closeContainer
        );

    }
    else{

      found.modal.appendChild(
        card
      );

    }

  }


  return true;

}


/*
 * La modale Paramètres est dynamique.
 * Comme V1.2, montage uniquement
 * après interaction utilisateur.
 *
 * Aucun setInterval.
 * Aucun MutationObserver.
 */

document.addEventListener(
  'click',
  function(){

    requestAnimationFrame(
      function(){

        requestAnimationFrame(
          lpSec2MountPanel
        );

      }
    );

  },
  true
);


