/* ============================================================
   LEADER PHARMA
   SECURITE UTILISATEURS V2.1
   LOGIN BUTTON FIXE
   ============================================================ */


function lpSec21Username(){

  return lpSec2Norm(
    document.querySelector(
      '#username'
    )?.value
  );

}


function lpSec21Password(){

  return String(
    document.querySelector(
      '#password'
    )?.value || ''
  );

}


function lpSec21Agency(){

  return String(
    document.querySelector(
      '#loginAgency'
    )?.value ||
    currentAgency ||
    ''
  );

}


function lpSec21SuccessfulLogin(user){

  /*
   * Ici nous reproduisons uniquement
   * la connexion AGENT standard.
   *
   * Le DG ne passe jamais ici.
   */

  currentUser =
    user;


  currentAgency =
    lpSec21Agency();


  const pass =
    document.querySelector(
      '#password'
    );


  if(pass){
    pass.value = '';
  }


  lpSec2SetError('');


  const loginView =
    document.querySelector(
      '#loginView'
    );


  const appView =
    document.querySelector(
      '#appView'
    );


  if(loginView){

    loginView.classList.add(
      'hidden'
    );

  }


  if(appView){

    appView.classList.remove(
      'hidden'
    );

  }


  const agencyLabel =
    document.querySelector(
      '#currentAgencyLabel'
    );


  if(agencyLabel){

    try{

      agencyLabel.textContent =
        agencyName()
        +
        ' • '
        +
        user.role;

    }
    catch(e){}

  }


  lpSec2Clear(
    user.username
  );


  try{

    buildNav();

  }
  catch(e){}


  try{

    audit(
      'Connexion',
      'Utilisateur '
      +
      user.username
    );

  }
  catch(e){}


  try{

    render();

  }
  catch(e){}

}


function lpSec21HandleAgentLogin(event){

  /*
   * V2.2 :
   * sécurité maintenant intégrée
   * directement dans login().
   */

  return;

}

function lpSec21HandleAgentLogin_DISABLED(event){

  const username =
    lpSec21Username();


  /*
   * DG :
   * NE RIEN INTERCEPTER.
   *
   * La couche DG existante garde
   * totalement la main.
   */

  if(
    username === 'leader.fr'
  ){

    return;

  }


  /*
   * A partir d'ici :
   * l'essai concerne un utilisateur.
   *
   * On bloque tous les anciens
   * gestionnaires du bouton afin
   * d'éviter le message générique.
   */

  if(event){

    event.preventDefault();

    event.stopPropagation();

    event.stopImmediatePropagation();

  }


  const blocked =
    lpSec2Blocked(
      username
    );


  if(blocked){

    lpSec2SetError(
      'Compte temporairement verrouillé. Réessayez dans '
      +
      lpSec2RemainingMinutes(
        blocked.lockedUntil
      )
      +
      ' min ou contactez le DG.'
    );


    return;

  }


  const password =
    lpSec21Password();


  const user =
    lpSec2User(
      username
    );


  /*
   * Si par sécurité un compte DG
   * possède un alias inattendu,
   * ne jamais appliquer le verrouillage.
   */

  if(
    user &&
    lpSec2IsDGUser(
      user
    )
  ){

    return;

  }


  const valid =
    !!(
      user
      &&
      user.active !== false
      &&
      String(
        user.password || ''
      ) === password
    );


  if(valid){

    lpSec21SuccessfulLogin(
      user
    );


    return;

  }


  const state =
    lpSec2RegisterFailure(
      username
    );


  if(!state){

    lpSec2SetError(
      'Identifiants incorrects ou compte désactivé'
    );


    return;

  }


  if(
    state.lockedUntil >
    Date.now()
  ){

    lpSec2SetError(
      'Compte verrouillé pendant 15 minutes après 5 tentatives incorrectes.'
    );


    return;

  }


  const remaining =
    Math.max(
      0,
      LPSEC2_MAX_ATTEMPTS
      -
      Number(
        state.attempts || 0
      )
    );


  lpSec2SetError(
    'Identifiants incorrects. '
    +
    remaining
    +
    ' tentative(s) restante(s).'
  );

}


function lpSec21Install(){

  const btn =
    document.querySelector(
      '#loginBtn'
    );


  if(!btn){

    return false;

  }


  if(
    btn.dataset
      .lpSec21Installed ===
    '1'
  ){

    return true;

  }


  /*
   * CAPTURE = priorité avant
   * onclick et anciens handlers.
   */

  btn.addEventListener(
    'click',
    lpSec21HandleAgentLogin,
    true
  );


  btn.dataset
    .lpSec21Installed =
    '1';


  return true;

}


/*
 * ENTER dans le mot de passe :
 * même protection que le bouton.
 */

function lpSec21InstallEnter(){

  const pass =
    document.querySelector(
      '#password'
    );


  if(!pass){

    return false;

  }


  if(
    pass.dataset
      .lpSec21EnterInstalled ===
    '1'
  ){

    return true;

  }


  pass.addEventListener(
    'keydown',
    function(e){

      if(
        e.key !== 'Enter'
      ){
        return;
      }


      const username =
        lpSec21Username();


      if(
        username ===
        'leader.fr'
      ){

        return;

      }


      lpSec21HandleAgentLogin(
        e
      );

    },
    true
  );


  pass.dataset
    .lpSec21EnterInstalled =
    '1';


  return true;

}


/*
 * Installation après init().
 * Aucun timer permanent.
 */

const lpSec21InitBase =
  init;


init =
  function(){

    const result =
      lpSec21InitBase.apply(
        this,
        arguments
      );


    lpSec21Install();

    lpSec21InstallEnter();


    return result;

  };


/*
 * Sécurité si init a déjà été
 * exécuté par une autre couche.
 */

if(
  document.readyState ===
  'loading'
){

  document.addEventListener(
    'DOMContentLoaded',
    function(){

      lpSec21Install();
      lpSec21InstallEnter();

    },
    {
      once:true
    }
  );

}
else{

  lpSec21Install();
  lpSec21InstallEnter();

}


