async function lp1510Detect(
  video,
  detector
){

  if(!lp1510Scanning){
    return;
  }

  try{

    if(video.readyState>=2){

      const result=
        await detector.detect(
          video
        );

      if(
        result &&
        result.length &&
        result[0].rawValue
      ){

        const code=
          result[0].rawValue;

        lp1510Stop();

        lp1510PutCode(
          code
        );

        return;
      }
    }

  }catch(error){}

  lp1510Timer=
    setTimeout(
      function(){

        lp1510Detect(
          video,
          detector
        );

      },
      180
    );
}

async function lp1510Open(){

  if(
    !navigator.mediaDevices ||
    !navigator.mediaDevices
      .getUserMedia
  ){

    toast(
      'Caméra indisponible'
    );

    return;
  }

  if(
    typeof BarcodeDetector===
    'undefined'
  ){

    toast(
      'Lecteur code-barres indisponible'
    );

    return;
  }

  let detector;

  try{

    detector=
      new BarcodeDetector({
        formats:[
          'ean_13',
          'ean_8',
          'upc_a',
          'upc_e',
          'code_128',
          'code_39',
          'itf'
        ]
      });

  }catch(error){

    detector=
      new BarcodeDetector();
  }

  const video=
    lp1510CreateModal();

  /*
   * R9
   *
   * ETAPE 1 :
   * demander uniquement la caméra.
   *
   * Si cette étape échoue réellement,
   * alors seulement il s'agit d'un
   * problème d'accès caméra.
   */

  try{

    lp1510Stream=
      await navigator
        .mediaDevices
        .getUserMedia({
          video:{
            facingMode:{
              ideal:'environment'
            }
          },
          audio:false
        });

  }catch(error){

    console.error(
      'LP R9 GET USER MEDIA',
      error
    );

    lp1510Stop();

    toast(
      'Autorisation caméra refusée'
    );

    return;
  }

  /*
   * Si nous arrivons ici :
   *
   * Android a donné la caméra.
   *
   * On ne doit donc PLUS fermer
   * le scanner à cause d'une erreur
   * indépendante de video.play().
   */

  if(
    !lp1510Stream
  ){

    lp1510Stop();

    toast(
      'Caméra indisponible'
    );

    return;
  }

  video.srcObject=
    lp1510Stream;

  /*
   * ETAPE 2 :
   * démarrer l'affichage vidéo.
   *
   * Une erreur play() ne signifie
   * PAS que la permission caméra
   * est refusée.
   *
   * Donc surtout :
   * AUCUN lp1510Stop() ici.
   */

  try{

    const playResult=
      video.play();

    if(
      playResult &&
      typeof playResult.then===
        'function'
    ){

      await playResult;
    }

  }catch(error){

    console.log(
      'LP R9 VIDEO PLAY NON BLOQUANT',
      error
    );

  }

  /*
   * La caméra a déjà été obtenue.
   * Garder le scanner ouvert.
   */

  lp1510Scanning=
    true;

  lp1510Detect(
    video,
    detector
  );
}


function lp1510InstallStockScanner(){

  const btn=
    document.getElementById(
      'lp1510ScanStock'
    );

  if(!btn){
    return;
  }

  if(
    btn.getAttribute(
      'data-ready'
    )==='1'
  ){
    return;
  }

  btn.setAttribute(
    'data-ready',
    '1'
  );

  btn.onclick=
    function(event){

      event.preventDefault();

      event.stopPropagation();

      lp1510Open();
    };
}

document.addEventListener(
  'click',
  function(){

    setTimeout(
      lp1510InstallStockScanner,
      50
    );

    setTimeout(
      lp1510InstallStockScanner,
      300
    );
  },
  true
);

