  function lp1516Capture(code){

    var clean =
      lp1516NormalizeCode(code);

    var field =
      document.getElementById(
        "lp1516Barcode"
      );

    if(field){
      field.value = code || "";
    }

    if(!clean){

      lp1516Product = null;

      lp1516ShowProduct();

      lp1516SetStatus(
        "Code-barres vide.",
        "error"
      );

      return;
    }

    var product =
      lp1516FindProduct(
        clean
      );

    if(!product){

      lp1516Product = null;

      lp1516ShowProduct();

      lp1516SetStatus(
        "Produit non enregistré dans le stock.",
        "error"
      );

      return;
    }

    lp1516Product =
      product;

    lp1516ShowProduct();

    lp1516SetStatus(
      "✅ Produit reconnu : " +
      String(
        product.name ||
        "Produit"
      ),
      "ok"
    );

    var cost =
      document.getElementById(
        "lp1516Cost"
      );

    if(cost){

      cost.value =
        Number(
          product.cost ||
          product.purchasePrice ||
          product.costPrice ||
          0
        ) || "";
    }
  }

  /*
   * On conserve le scanner stock
   * déjà validé.
   *
   * En mode réception, le code capturé
   * est envoyé au module réception.
   *
   * Hors mode réception, comportement
   * V1.5.12 original inchangé.
   */

  if(
    typeof lp1510PutCode ===
    "function"
  ){

    var lp1516OriginalPutCode =
      lp1510PutCode;

    lp1510PutCode =
      function(code){

        if(
          lp1516ReceptionActive
        ){

          lp1516ReceptionActive =
            false;

          lp1516Capture(
            code
          );

          return;
        }

        return lp1516OriginalPutCode(
          code
        );
      };
  }

  function lp1516LaunchScanner(){

    lp1516ReceptionActive =
      true;

    lp1516SetStatus(
      "📷 Scannez le produit...",
      ""
    );

    var buttons =
      Array.from(
        document.querySelectorAll(
          "button"
        )
      );

    var scanner =
      buttons.find(
        function(button){

          if(
            button.id ===
            "lp1516Scan"
          ){
            return false;
          }

          var text =
            String(
              button.textContent ||
              ""
            )
            .toLowerCase();

          return (
            text.includes(
              "scanner code-barres"
            )
          );
        }
      );

    if(scanner){

      scanner.click();

      return;
    }

    lp1516ReceptionActive =
      false;

    lp1516SetStatus(
      "Scanner stock introuvable sur cette page.",
      "error"
    );
  }

  function lp1516Persist(){

    var saved = false;

    /*
     * Utiliser en priorité les fonctions
     * de sauvegarde déjà présentes
     * dans Leader Pharma.
     */

    [
      "save",
      "saveDB",
      "saveDb",
      "persist",
      "saveData"
    ].forEach(
      function(name){

        if(saved){
          return;
        }

        try{

          if(
            typeof window[name] ===
            "function"
          ){

            window[name]();

            saved = true;
          }

        }catch(error){}
      }
    );

    /*
     * Sécurité locale :
     * retrouver automatiquement la clé
     * qui contient la base Leader Pharma.
     */

    try{

      for(
        var i = 0;
        i < localStorage.length;
        i++
      ){

        var key =
          localStorage.key(i);

        var raw =
          localStorage.getItem(
            key
          );

        if(!raw){
          continue;
        }

        var parsed;

        try{
          parsed =
            JSON.parse(raw);
        }catch(error){
          continue;
        }

        if(
          parsed &&
          Array.isArray(
            parsed.products
          )
        ){

          localStorage.setItem(
            key,
            JSON.stringify(db)
          );

          saved = true;

          break;
        }
      }

    }catch(error){}

    return saved;
  }

  function lp1516Receive(){

    if(!lp1516Product){

      lp1516SetStatus(
        "Scannez d'abord un produit existant.",
        "error"
      );

      return;
    }

    var qty =
      Number(
        document.getElementById(
          "lp1516Qty"
        ).value
      );

    var cost =
      Number(
        document.getElementById(
          "lp1516Cost"
        ).value
      );

    var lot =
      lp1516Text(
        document.getElementById(
          "lp1516Lot"
        ).value
      );

    var expiry =
      lp1516Text(
        document.getElementById(
          "lp1516Expiry"
        ).value
      );

    if(
      !Number.isFinite(qty) ||
      qty <= 0
    ){

      lp1516SetStatus(
        "Quantité reçue obligatoire.",
        "error"
      );

      return;
    }

    if(
      !Number.isInteger(qty)
    ){

      lp1516SetStatus(
        "La quantité doit être un nombre entier.",
        "error"
      );

      return;
    }

    if(
      !Number.isFinite(cost) ||
      cost < 0
    ){

      lp1516SetStatus(
        "Prix d'achat incorrect.",
        "error"
      );

      return;
    }

    if(!lot){

      lp1516SetStatus(
        "Numéro de lot obligatoire.",
        "error"
      );

      return;
    }

    if(!expiry){

      lp1516SetStatus(
        "Date de péremption obligatoire.",
        "error"
      );

      return;
    }

    var oldStock =
      Number(
        lp1516Product.stock ||
        0
      );

    var newStock =
      oldStock + qty;

    /*
     * Mise à jour du produit existant.
     * Aucun nouveau produit n'est créé.
     */

    lp1516Product.stock =
      newStock;

    lp1516Product.lot =
      lot;

    lp1516Product.expiry =
      expiry;

    lp1516Product.cost =
      cost;

    lp1516Product.purchasePrice =
      cost;

    /*
     * Historique interne des lots reçus.
     */

    if(
      !Array.isArray(
        lp1516Product.lots
      )
    ){
      lp1516Product.lots = [];
    }

    lp1516Product.lots.push({
      lot: lot,
      quantity: qty,
      cost: cost,
      expiry: expiry,
      receivedAt:
        new Date()
          .toISOString()
    });

    /*
     * Historique global des réceptions.
     */

    if(
      !Array.isArray(
        db.stockReceipts
      )
    ){
      db.stockReceipts = [];
    }

    db.stockReceipts.push({
      id:
        "REC-" +
        Date.now(),

      productId:
        lp1516Product.id,

      productName:
        lp1516Product.name,

      barcode:
        lp1516ProductCode(
          lp1516Product
        ),

      quantity:
        qty,

      oldStock:
        oldStock,

      newStock:
        newStock,

      cost:
        cost,

      lot:
        lot,

      expiry:
        expiry,

      date:
        new Date()
          .toISOString()
          .slice(0,10),

      time:
        new Date()
          .toTimeString()
          .slice(0,5)
    });

    var persisted =
      lp1516Persist();

    lp1516SetStatus(
      "✅ Réception enregistrée : " +
      oldStock +
      " → " +
      newStock +
      " unités",
      "ok"
    );

    lp1516ShowProduct();

    document.getElementById(
      "lp1516Qty"
    ).value = "";

    document.getElementById(
      "lp1516Lot"
    ).value = "";

    document.getElementById(
      "lp1516Expiry"
    ).value = "";

    if(!persisted){

      console.warn(
        "V1.5.16 : sauvegarde automatique non confirmée"
      );
    }
  }

