/* =========================================================
   LEADER PHARMA V1.5.18R10
   RECEPTION PRODUIT EXISTANT
   LOT EXISTANT AUTOMATIQUE SI LOT RECU VIDE
   ========================================================= */

(function(){

  "use strict";

  function lpR10Norm(value){

    return String(
      value || ""
    )
      .trim()
      .toLowerCase()
      .normalize("NFD")
      .replace(
        /[\u0300-\u036f]/g,
        ""
      );
  }

  function lpR10ReceptionRoot(button){

    if(!button){
      return null;
    }

    return (
      button.closest(
        "#lpR5Reception"
      ) ||
      button.closest(
        "#lp1518Reception"
      ) ||
      button.closest(
        ".card"
      ) ||
      document
    );
  }

  function lpR10LotInput(root){

    if(!root){
      return null;
    }

    const labels =
      Array.from(
        root.querySelectorAll(
          "label"
        )
      );

    for(
      const label of labels
    ){

      const txt =
        lpR10Norm(
          label.textContent
        );

      if(
        txt === "lot recu" ||
        txt.includes(
          "lot recu"
        )
      ){

        const field =
          label.closest(
            ".field"
          ) ||
          label.parentElement;

        if(field){

          const input =
            field.querySelector(
              "input"
            );

          if(input){
            return input;
          }
        }
      }
    }

    const inputs =
      Array.from(
        root.querySelectorAll(
          "input"
        )
      );

    return (
      inputs.find(
        function(input){

          const placeholder =
            lpR10Norm(
              input.placeholder
            );

          return (
            placeholder.includes(
              "lot-2026"
            ) ||
            placeholder.includes(
              "lot 2026"
            )
          );
        }
      ) ||
      null
    );
  }

  function lpR10ExistingLot(root){

    if(!root){
      return "";
    }

    const text =
      String(
        root.innerText ||
        root.textContent ||
        ""
      );

    /*
     * Exemple actuel :
     *
     * Stock actuel : 6 • Lot : 512
     */

    let match =
      text.match(
        /Stock\s+actuel\s*:\s*[^•\n]*[•·]\s*Lot\s*:\s*([^\n•]+)/i
      );

    if(
      match &&
      match[1]
    ){

      const lot =
        String(
          match[1]
        ).trim();

      if(
        lot &&
        lot !== "-" &&
        lot !== "—"
      ){
        return lot;
      }
    }

    /*
     * Deuxième lecture de secours :
     * chercher précisément "Lot : ..."
     */

    match =
      text.match(
        /(?:^|\n|\s)Lot\s*:\s*([A-Za-z0-9._\/-]+)/i
      );

    if(
      match &&
      match[1]
    ){

      const lot =
        String(
          match[1]
        ).trim();

      if(
        lot &&
        lot !== "-" &&
        lot !== "—"
      ){
        return lot;
      }
    }

    return "";
  }

  function lpR10PrepareLot(
    button
  ){

    const root =
      lpR10ReceptionRoot(
        button
      );

    if(!root){
      return;
    }

    const input =
      lpR10LotInput(
        root
      );

    if(!input){
      return;
    }

    /*
     * Si l'utilisateur a saisi
     * un nouveau lot :
     * NE RIEN MODIFIER.
     */

    if(
      String(
        input.value || ""
      ).trim()
    ){
      return;
    }

    /*
     * Lot reçu vide :
     * reprendre le lot actuel
     * du produit existant.
     */

    const existingLot =
      lpR10ExistingLot(
        root
      );

    if(!existingLot){
      return;
    }

    input.value =
      existingLot;

    try{

      input.dispatchEvent(
        new Event(
          "input",
          {
            bubbles:true
          }
        )
      );

      input.dispatchEvent(
        new Event(
          "change",
          {
            bubbles:true
          }
        )
      );

    }catch(error){}

    console.log(
      "LP R10 LOT EXISTANT UTILISE",
      existingLot
    );
  }

  /*
   * Capture AVANT le onclick
   * déjà existant.
   *
   * On ne remplace aucune
   * logique de réception.
   */

  document.addEventListener(
    "click",
    function(event){

      const target =
        event.target;

      if(
        !target ||
        !target.closest
      ){
        return;
      }

      const button =
        target.closest(
          "button"
        );

      if(!button){
        return;
      }

      const text =
        lpR10Norm(
          button.textContent
        );

      if(
        !text.includes(
          "ajouter au stock existant"
        )
      ){
        return;
      }

      lpR10PrepareLot(
        button
      );
    },
    true
  );

  console.log(
    "LEADER PHARMA V1.5.18R10 LOT EXISTANT AUTOMATIQUE ACTIF"
  );

})();


/* =====================================================
   LEADER PHARMA V1.5.18R11
   SESSION INVENTAIRE PROFESSIONNELLE
   ETAPE 1
   AUCUNE MODIFICATION DU STOCK
   ===================================================== */

(function(){

  function lpR11Sessions(){
    if(!Array.isArray(db.inventorySessions)){
      db.inventorySessions=[];
    }
    return db.inventorySessions;
  }

  function lpR11Date(){
    return new Date()
      .toISOString()
      .slice(0,10);
  }

  function lpR11Time(){
    return new Date()
      .toLocaleTimeString(
        'fr-FR',
        {
          hour:'2-digit',
          minute:'2-digit'
        }
      );
  }

  function lpR11AgencyName(){
    try{
      const a=db.agencies.find(
        x=>String(x.id)===String(currentAgency)
      );
      return a?.name||currentAgency||'Agence';
    }catch(e){
      return currentAgency||'Agence';
    }
  }

  function lpR11UserName(){
    try{
      return (
        currentUser?.name ||
        currentUser?.username ||
        currentUser?.login ||
        'Utilisateur'
      );
    }catch(e){
      return 'Utilisateur';
    }
  }

  function lpR11Current(){
    return lpR11Sessions()
      .slice()
      .reverse()
      .find(
        s =>
          String(s.agency)===String(currentAgency) &&
          s.status==='En cours'
      ) || null;
  }

  function lpR11Number(){
    const date=lpR11Date().replace(/-/g,'');
    const n=
      lpR11Sessions()
        .filter(s=>s.date===lpR11Date())
        .length + 1;

    return (
      'INV-' +
      date +
      '-' +
      String(n).padStart(3,'0')
    );
  }

  function lpR11Start(){

    const old=lpR11Current();

    if(old){
      toast(
        'Session déjà en cours : ' +
        old.number
      );
      lpR11Panel();
      return;
    }

    const session={
      id:Date.now(),
      number:lpR11Number(),
      date:lpR11Date(),
      time:lpR11Time(),
      agency:currentAgency,
      agencyName:lpR11AgencyName(),
      user:lpR11UserName(),
      status:'En cours',
      createdAt:new Date().toISOString()
    };

    lpR11Sessions().push(session);

    try{
      save();
    }catch(e){}

    try{
      audit(
        'Inventaire',
        'Ouverture session ' +
        session.number
      );
    }catch(e){}

    toast(
      'Session ' +
      session.number +
      ' démarrée'
    );

    lpR11Panel();
  }

  function lpR11Rows(){

    const rows=
      lpR11Sessions()
        .filter(
          s =>
            String(s.agency)===
            String(currentAgency)
        )
        .slice()
        .reverse();

    if(!rows.length){
      return '<p class="muted">Aucune session.</p>';
    }

    return `
      <div style="overflow:auto">
        <table style="width:100%;min-width:600px">
          <thead>
            <tr>
              <th>Session</th>
              <th>Date</th>
              <th>Heure</th>
              <th>Utilisateur</th>
              <th>Statut</th>
            </tr>
          </thead>
          <tbody>
            ${
              rows.map(
                s=>`
                  <tr>
                    <td><b>${s.number}</b></td>
                    <td>${s.date}</td>
                    <td>${s.time}</td>
                    <td>${s.user}</td>
                    <td><b>${s.status}</b></td>
                  </tr>
                `
              ).join('')
            }
          </tbody>
        </table>
      </div>
    `;
  }

  function lpR11Panel(){

    if(
      typeof page!=='undefined' &&
      page!=='inventory'
    ){
      return;
    }

    const content=
      document.getElementById('content');

    if(!content){
      return;
    }

    document
      .getElementById('lpR11Inventory')
      ?.remove();

    const current=
      lpR11Current();

    const card=
      document.createElement('div');

    card.id='lpR11Inventory';
    card.className='card';
    card.style.marginBottom='16px';

    card.innerHTML=`
      <div class="section-title">
        <div>
          <h3>📋 Session d'inventaire</h3>
          <small class="muted">
            Contrôle professionnel
          </small>
        </div>

        ${
          current
          ?
          '<span class="badge">● En cours</span>'
          :
          '<button class="btn" id="lpR11Start">+ Démarrer une session</button>'
        }
      </div>

      ${
        current
        ?
        `
          <div style="
            display:grid;
            grid-template-columns:
            repeat(auto-fit,minmax(140px,1fr));
            gap:10px;
            margin-top:14px
          ">

            <div class="card">
              <small>Numéro</small><br>
              <b>${current.number}</b>
            </div>

            <div class="card">
              <small>Date / heure</small><br>
              <b>${current.date} ${current.time}</b>
            </div>

            <div class="card">
              <small>Agence</small><br>
              <b>${current.agencyName}</b>
            </div>

            <div class="card">
              <small>Utilisateur</small><br>
              <b>${current.user}</b>
            </div>

          </div>

          <p class="muted">
            Session ouverte.
            Aucun stock n'est modifié.
          </p>
        `
        :
        `
          <p class="muted">
            Démarrez une session avant
            le comptage physique.
            Aucun stock ne sera modifié.
          </p>
        `
      }

      <hr>

      <h4>Historique des sessions</h4>

      ${lpR11Rows()}
    `;

    content.insertBefore(
      card,
      content.firstChild
    );

    const button=
      document.getElementById(
        'lpR11Start'
      );

    if(button){
      button.onclick=lpR11Start;
    }
  }

  if(typeof inventory==='function'){

    const lpR11InventoryBase=
      inventory;

    inventory=function(){

      const result=
        lpR11InventoryBase.apply(
          this,
          arguments
        );

      setTimeout(
        lpR11Panel,
        0
      );

      return result;
    };
  }

  setTimeout(
    lpR11Panel,
    300
  );

  console.log(
    'LEADER PHARMA V1.5.18R11 SESSION INVENTAIRE PROFESSIONNELLE ACTIF'
  );

})();


/* LEADER PHARMA V1.5.18R12 INVENTAIRE SCANNER COMPTAGE */

(function(){

  let lpR12Mode=false;
  let lpR12Product=null;
  let lpR12Code="";

  function lpR12Session(){
    if(!Array.isArray(db.inventorySessions))return null;
    return db.inventorySessions.slice().reverse().find(
      s=>String(s.agency)===String(currentAgency)&&s.status==="En cours"
    )||null;
  }

  function lpR12Products(){
    try{
      if(typeof productsHere==="function")return productsHere();
    }catch(e){}
    return Array.isArray(db.products)?db.products:[];
  }

  function lpR12Barcode(p){
    return String(
      p?.barcode||
      p?.barCode||
      p?.codebarre||
      p?.codeBarre||
      p?.code_barre||
      p?.ean||
      p?.ean13||
      p?.gtin||
      p?.code||
      ""
    ).trim();
  }

  function lpR12Find(code){
    code=String(code||"").trim();
    return lpR12Products().find(p=>lpR12Barcode(p)===code)||null;
  }

  function lpR12Counts(){
    const s=lpR12Session();
    if(!s)return [];
    if(!Array.isArray(s.counts))s.counts=[];
    return s.counts;
  }

  function lpR12Scan(){
    if(!lpR12Session()){
      toast("Démarrez d'abord une session d'inventaire");
      return;
    }

    if(typeof lp1510Open!=="function"){
      toast("Scanner indisponible");
      return;
    }

    lpR12Mode=true;
    lp1510Open();
  }

  function lpR12Receive(code){

    lpR12Mode=false;

    const p=lpR12Find(code);

    if(!p){
      toast("Code-barres non lié à un produit");
      return;
    }

    lpR12Product=p;
    lpR12Code=String(code||"").trim();

    try{
      const old=document.getElementById("invProduct");
      if(old){
        old.value=String(p.id);
        old.dispatchEvent(new Event("change",{bubbles:true}));
      }
    }catch(e){}

    lpR12Selection();

    setTimeout(()=>{
      document.getElementById("lpR12Physical")?.focus();
    },100);

    toast("Produit scanné : "+(p.name||"Produit"));
  }

  if(typeof lp1510PutCode==="function"){

    const original=lp1510PutCode;

    lp1510PutCode=function(code){

      if(
        lpR12Mode &&
        typeof page!=="undefined" &&
        page==="inventory" &&
        lpR12Session()
      ){
        lpR12Receive(code);
        return;
      }

      lpR12Mode=false;
      return original.apply(this,arguments);
    };
  }

  function lpR12Selection(){

    const box=document.getElementById("lpR12Selection");
    if(!box)return;

    if(!lpR12Product){
      box.innerHTML='<p class="muted">Aucun produit scanné.</p>';
      return;
    }

    box.innerHTML=`
      <div style="border:1px solid #ddd;border-radius:12px;padding:14px;margin-top:12px">
        <h3 style="margin:0 0 8px">${lpR12Product.name||"Produit"}</h3>

        <p class="muted">
          Lot : <b>${lpR12Product.lot||"—"}</b>
          • Stock théorique :
          <b>${Number(lpR12Product.stock||0)}</b>
        </p>

        <div class="field">
          <label>Quantité physique comptée</label>
          <input
            id="lpR12Physical"
            type="number"
            min="0"
            inputmode="numeric"
            placeholder="Ex. 12"
          >
        </div>

        <button
          type="button"
          class="btn"
          id="lpR12Save"
          style="width:100%;margin-top:12px"
        >
          ✅ Enregistrer le comptage
        </button>
      </div>
    `;

    document.getElementById("lpR12Save").onclick=lpR12Save;
  }

  function lpR12Save(){

    const s=lpR12Session();
    const p=lpR12Product;
    const input=document.getElementById("lpR12Physical");

    if(!s||!p||!input)return;

    if(String(input.value).trim()===""){
      toast("Saisissez la quantité physique");
      return;
    }

    const physical=Number(input.value);

    if(!Number.isFinite(physical)||physical<0){
      toast("Quantité invalide");
      return;
    }

    const counts=lpR12Counts();

    let row=counts.find(
      x=>String(x.productId)===String(p.id)
    );

    const data={
      id:row?.id||Date.now(),
      productId:p.id,
      productName:p.name,
      lot:p.lot||"",
      barcode:lpR12Code||lpR12Barcode(p),
      theoretical:Number(p.stock||0),
      physical:physical,
      user:currentUser?.name||currentUser?.username||"Utilisateur",
      countedAt:new Date().toISOString()
    };

    if(row)Object.assign(row,data);
    else counts.push(data);

    try{save();}catch(e){}

    try{
      audit(
        "Inventaire",
        "Comptage "+s.number+" • "+p.name+" • "+physical
      );
    }catch(e){}

    lpR12Product=null;
    lpR12Code="";

    toast("Comptage enregistré • stock inchangé");

    lpR12Install();
  }

  function lpR12Rows(){

    const rows=lpR12Counts().slice().reverse();

    if(!rows.length){
      return '<p class="muted">Aucun produit compté.</p>';
    }

    return `
      <div style="overflow:auto">
        <table style="width:100%;min-width:600px">
          <thead>
            <tr>
              <th>Produit</th>
              <th>Lot</th>
              <th>Théorique</th>
              <th>Physique</th>
            </tr>
          </thead>

          <tbody>
            ${rows.map(x=>`
              <tr>
                <td><b>${x.productName}</b></td>
                <td>${x.lot||"—"}</td>
                <td>${x.theoretical}</td>
                <td><b>${x.physical}</b></td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    `;
  }

  function lpR12Install(){

    if(typeof page!=="undefined"&&page!=="inventory"){
      lpR12Mode=false;
      return;
    }

    const session=lpR12Session();

    document.getElementById("lpR12Counter")?.remove();

    if(!session)return;

    const content=document.getElementById("content");
    if(!content)return;

    const panel=document.createElement("div");

    panel.id="lpR12Counter";
    panel.className="card";
    panel.style.marginBottom="16px";

    panel.innerHTML=`
      <div class="section-title">
        <div>
          <h3>📷 Comptage par scanner</h3>
          <small class="muted">
            Session : ${session.number}
          </small>
        </div>

        <button
          type="button"
          class="btn"
          id="lpR12Scan"
        >
          📷 Scanner un produit
        </button>
      </div>

      <p class="muted">
        Le comptage est enregistré dans la session.
        Aucun stock réel n'est encore modifié.
      </p>

      <div id="lpR12Selection"></div>

      <hr>

      <h4>Produits comptés dans la session</h4>

      ${lpR12Rows()}
    `;

    const r11=document.getElementById("lpR11Inventory");

    if(r11){
      r11.insertAdjacentElement("afterend",panel);
    }else{
      content.insertBefore(panel,content.firstChild);
    }

    document.getElementById("lpR12Scan").onclick=lpR12Scan;

    lpR12Selection();

    const old=document.getElementById("saveInventory");

    if(old){
      old.disabled=true;
      old.textContent="Validation finale après comptage";
      old.title="Le stock sera corrigé lors de la validation finale";
    }
  }

  if(typeof inventory==="function"){
    const baseInventory=inventory;

    inventory=function(){
      const result=baseInventory.apply(this,arguments);
      setTimeout(lpR12Install,0);
      return result;
    };
  }

  setTimeout(lpR12Install,300);

  console.log(
    "LEADER PHARMA V1.5.18R12 INVENTAIRE SCANNER COMPTAGE ACTIF"
  );

})();


/* =========================================================
   LEADER PHARMA V1.5.18R13
   ECART INVENTAIRE AUTOMATIQUE
   ECART = PHYSIQUE - THEORIQUE
   AUCUNE MODIFICATION DU STOCK
   ========================================================= */

(function(){

  "use strict";

  function lpR13Session(){

    if(
      !db ||
      !Array.isArray(
        db.inventorySessions
      )
    ){
      return null;
    }

    return db.inventorySessions
      .slice()
      .reverse()
      .find(
        function(s){
          return (
            String(s.agency||"") ===
            String(currentAgency||"")
            &&
            s.status === "En cours"
          );
        }
      ) || null;
  }

  function lpR13Counts(){

    const session=
      lpR13Session();

    if(
      !session ||
      !Array.isArray(
        session.counts
      )
    ){
      return [];
    }

    return session.counts;
  }

  function lpR13Diff(row){

    return (
      Number(
        row.physical || 0
      )
      -
      Number(
        row.theoretical || 0
      )
    );
  }

  function lpR13DiffText(diff){

    if(diff > 0){
      return "+" + diff;
    }

    return String(diff);
  }

  function lpR13Status(diff){

    if(diff === 0){
      return "Conforme";
    }

    if(diff > 0){
      return "Excédent";
    }

    return "Manquant";
  }

  function lpR13StatusStyle(diff){

    if(diff === 0){
      return (
        "background:#e8f7ed;" +
        "color:#157a36;"
      );
    }

    if(diff > 0){
      return (
        "background:#eef5ff;" +
        "color:#245a9c;"
      );
    }

    return (
      "background:#fff0f0;" +
      "color:#b42318;"
    );
  }

  function lpR13Rows(){

    const rows=
      lpR13Counts()
        .slice()
        .reverse();

    if(!rows.length){

      return `
        <p class="muted">
          Aucun écart à analyser.
        </p>
      `;
    }

    return `
      <div style="
        overflow:auto;
        margin-top:12px;
      ">

        <table style="
          width:100%;
          min-width:700px;
        ">

          <thead>
            <tr>
              <th>Produit</th>
              <th>Lot</th>
              <th>Théorique</th>
              <th>Physique</th>
              <th>Écart</th>
              <th>Statut</th>
            </tr>
          </thead>

          <tbody>

            ${
              rows.map(
                function(row){

                  const diff=
                    lpR13Diff(row);

                  return `
                    <tr>

                      <td>
                        <b>
                          ${
                            String(
                              row.productName ||
                              "Produit"
                            )
                          }
                        </b>
                      </td>

                      <td>
                        ${
                          String(
                            row.lot ||
                            "—"
                          )
                        }
                      </td>

                      <td>
                        ${
                          Number(
                            row.theoretical ||
                            0
                          )
                        }
                      </td>

                      <td>
                        <b>
                          ${
                            Number(
                              row.physical ||
                              0
                            )
                          }
                        </b>
                      </td>

                      <td>
                        <b>
                          ${
                            lpR13DiffText(
                              diff
                            )
                          }
                        </b>
                      </td>

                      <td>
                        <span style="
                          display:inline-block;
                          padding:5px 9px;
                          border-radius:999px;
                          font-weight:700;
                          ${lpR13StatusStyle(diff)}
                        ">
                          ${
                            lpR13Status(
                              diff
                            )
                          }
                        </span>
                      </td>

                    </tr>
                  `;
                }
              ).join("")
            }

          </tbody>
        </table>
      </div>
    `;
  }

  function lpR13Summary(){

    const rows=
      lpR13Counts();

    let conformes=0;
    let manquants=0;
    let excedents=0;

    rows.forEach(
      function(row){

        const diff=
          lpR13Diff(row);

        if(diff === 0){
          conformes++;
        }
        else if(diff < 0){
          manquants++;
        }
        else{
          excedents++;
        }
      }
    );

    return {
      total:rows.length,
      conformes,
      manquants,
      excedents
    };
  }

  function lpR13Install(){

    if(
      typeof page !==
        "undefined"
      &&
      page !== "inventory"
    ){
      return;
    }

    const session=
      lpR13Session();

    document
      .getElementById(
        "lpR13Differences"
      )
      ?.remove();

    if(!session){
      return;
    }

    const r12=
      document.getElementById(
        "lpR12Counter"
      );

    const content=
      document.getElementById(
        "content"
      );

    if(!content){
      return;
    }

    const summary=
      lpR13Summary();

    const panel=
      document.createElement(
        "div"
      );

    panel.id=
      "lpR13Differences";

    panel.className=
      "card";

    panel.style.marginBottom=
      "16px";

    panel.innerHTML=`

      <div class="section-title">

        <div>

          <h3>
            📊 Écarts d'inventaire
          </h3>

          <div class="muted">
            Session :
            <b>
              ${session.number}
            </b>
          </div>

        </div>

      </div>

      <p class="muted">
        Écart =
        quantité physique
        − stock théorique.
        Aucun stock réel
        n'est modifié.
      </p>

      <div style="
        display:grid;
        grid-template-columns:
          repeat(
            auto-fit,
            minmax(110px,1fr)
          );
        gap:8px;
        margin-top:12px;
      ">

        <div style="
          border:1px solid #e5e7eb;
          border-radius:10px;
          padding:10px;
        ">
          <small class="muted">
            Comptés
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.total}
          </div>
        </div>

        <div style="
          border:1px solid #e5e7eb;
          border-radius:10px;
          padding:10px;
        ">
          <small class="muted">
            Conformes
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.conformes}
          </div>
        </div>

        <div style="
          border:1px solid #e5e7eb;
          border-radius:10px;
          padding:10px;
        ">
          <small class="muted">
            Manquants
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.manquants}
          </div>
        </div>

        <div style="
          border:1px solid #e5e7eb;
          border-radius:10px;
          padding:10px;
        ">
          <small class="muted">
            Excédents
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.excedents}
          </div>
        </div>

      </div>

      <hr style="
        margin-top:16px;
        margin-bottom:12px;
      ">

      ${lpR13Rows()}

    `;

    if(r12){

      r12.insertAdjacentElement(
        "afterend",
        panel
      );

    }else{

      content.insertBefore(
        panel,
        content.firstChild
      );
    }
  }

  /*
   * Mise à jour après navigation.
   */

  if(
    typeof inventory ===
    "function"
  ){

    const lpR13InventoryBase=
      inventory;

    inventory=
      function(){

        const result=
          lpR13InventoryBase
            .apply(
              this,
              arguments
            );

        setTimeout(
          lpR13Install,
          20
        );

        return result;
      };
  }

  /*
   * Après Enregistrer le comptage,
   * actualiser les écarts.
   *
   * Aucun setInterval :
   * le clavier stable est conservé.
   */

  document.addEventListener(
    "click",
    function(event){

      const button=
        event.target
          ?.closest
          ?.("button");

      if(!button){
        return;
      }

      const text=
        String(
          button.textContent ||
          ""
        )
        .toLowerCase();

      if(
        text.includes(
          "enregistrer le comptage"
        )
      ){

        setTimeout(
          lpR13Install,
          150
        );
      }
    },
    false
  );

  setTimeout(
    lpR13Install,
    400
  );

  console.log(
    "LEADER PHARMA V1.5.18R13 ECART INVENTAIRE AUTOMATIQUE ACTIF"
  );

})();


/* =========================================================
   LEADER PHARMA V1.5.18R14
   MOTIF OBLIGATOIRE EN CAS D'ECART
   AUCUNE MODIFICATION DU STOCK
   ========================================================= */

(function(){

  "use strict";

  function lpR14Session(){

    if(
      !db ||
      !Array.isArray(
        db.inventorySessions
      )
    ){
      return null;
    }

    return db.inventorySessions
      .slice()
      .reverse()
      .find(
        function(s){
          return (
            String(s.agency||"") ===
            String(currentAgency||"")
            &&
            s.status === "En cours"
          );
        }
      ) || null;
  }

  function lpR14Product(){

    const select=
      document.getElementById(
        "invProduct"
      );

    if(
      !select ||
      !db ||
      !Array.isArray(db.products)
    ){
      return null;
    }

    return db.products.find(
      function(p){
        return (
          String(p.id) ===
          String(select.value)
        );
      }
    ) || null;
  }

  function lpR14Diff(){

    const product=
      lpR14Product();

    const input=
      document.getElementById(
        "lpR12Physical"
      );

    if(
      !product ||
      !input ||
      String(input.value).trim()===""
    ){
      return null;
    }

    const physical=
      Number(input.value);

    if(
      !Number.isFinite(physical)
    ){
      return null;
    }

    return (
      physical -
      Number(product.stock||0)
    );
  }

  function lpR14Options(diff){

    if(diff < 0){

      return `
        <option value="">
          — Choisir le motif —
        </option>
        <option value="Casse">
          Casse
        </option>
        <option value="Perte">
          Perte
        </option>
        <option value="Vol">
          Vol
        </option>
        <option value="Péremption">
          Péremption
        </option>
        <option value="Erreur de saisie">
          Erreur de saisie
        </option>
        <option value="Erreur de comptage">
          Erreur de comptage
        </option>
        <option value="Autre">
          Autre
        </option>
      `;
    }

    return `
      <option value="">
        — Choisir le motif —
      </option>
      <option value="Erreur de réception">
        Erreur de réception
      </option>
      <option value="Oubli entrée stock">
        Oubli d'entrée stock
      </option>
      <option value="Retour non enregistré">
        Retour non enregistré
      </option>
      <option value="Erreur de saisie">
        Erreur de saisie
      </option>
      <option value="Erreur de comptage">
        Erreur de comptage
      </option>
      <option value="Autre">
        Autre
      </option>
    `;
  }

  function lpR14ReasonBox(){

    const physical=
      document.getElementById(
        "lpR12Physical"
      );

    if(!physical){
      return;
    }

    const diff=
      lpR14Diff();

    let wrap=
      document.getElementById(
        "lpR14ReasonWrap"
      );

    if(
      diff === null ||
      diff === 0
    ){

      if(wrap){
        wrap.remove();
      }

      return;
    }

    const previous=
      document.getElementById(
        "lpR14Reason"
      )?.value || "";

    const previousOther=
      document.getElementById(
        "lpR14ReasonOther"
      )?.value || "";

    if(!wrap){

      wrap=
        document.createElement(
          "div"
        );

      wrap.id=
        "lpR14ReasonWrap";

      wrap.className=
        "field";

      wrap.style.marginTop=
        "12px";

      const field=
        physical.closest(
          ".field"
        );

      if(field){
        field.insertAdjacentElement(
          "afterend",
          wrap
        );
      }

    }

    const label=
      diff < 0
      ? "🔴 Motif du manquant obligatoire"
      : "🔵 Motif de l'excédent obligatoire";

    wrap.innerHTML=`

      <label>
        ${label}
      </label>

      <select
        id="lpR14Reason"
      >
        ${lpR14Options(diff)}
      </select>

      <div
        id="lpR14OtherBox"
        style="
          display:none;
          margin-top:10px;
        "
      >
        <label>
          Précisez le motif
        </label>

        <input
          id="lpR14ReasonOther"
          type="text"
          placeholder="Précisez..."
        >
      </div>

      <small
        class="muted"
        style="
          display:block;
          margin-top:8px;
        "
      >
        Écart détecté :
        <b>
          ${diff > 0 ? "+"+diff : diff}
        </b>
      </small>
    `;

    const select=
      document.getElementById(
        "lpR14Reason"
      );

    if(
      previous &&
      Array.from(
        select.options
      ).some(
        o=>o.value===previous
      )
    ){
      select.value=
        previous;
    }

    function updateOther(){

      const other=
        document.getElementById(
          "lpR14OtherBox"
        );

      if(!other){
        return;
      }

      other.style.display=
        select.value==="Autre"
          ? "block"
          : "none";

      const otherInput=
        document.getElementById(
          "lpR14ReasonOther"
        );

      if(
        otherInput &&
        previousOther
      ){
        otherInput.value=
          previousOther;
      }
    }

    select.onchange=
      updateOther;

    updateOther();
  }

  function lpR14ReasonValue(){

    const select=
      document.getElementById(
        "lpR14Reason"
      );

    if(!select){
      return "";
    }

    const value=
      String(
        select.value||""
      ).trim();

    if(!value){
      return "";
    }

    if(value!=="Autre"){
      return value;
    }

    const detail=
      String(
        document
          .getElementById(
            "lpR14ReasonOther"
          )
          ?.value || ""
      ).trim();

    if(!detail){
      return "";
    }

    return (
      "Autre : " +
      detail
    );
  }

  function lpR14SaveReason(
    productId,
    reason
  ){

    const session=
      lpR14Session();

    if(
      !session ||
      !Array.isArray(
        session.counts
      )
    ){
      return;
    }

    const row=
      session.counts.find(
        function(c){
          return (
            String(c.productId) ===
            String(productId)
          );
        }
      );

    if(!row){
      return;
    }

    row.reason=
      reason;

    row.reasonUser=
      (
        currentUser?.name ||
        currentUser?.username ||
        "Utilisateur"
      );

    row.reasonAt=
      new Date()
        .toISOString();

    try{
      save();
    }catch(e){}

    try{

      audit(
        "Inventaire",
        "Justification écart "
        + row.productName
        + " • "
        + reason
      );

    }catch(e){}

    lpR14Panel();
  }

  /*
   * Mise à jour immédiate
   * lorsqu'on saisit la quantité.
   */

  document.addEventListener(
    "input",
    function(event){

      if(
        event.target?.id ===
        "lpR12Physical"
      ){
        lpR14ReasonBox();
      }

    },
    false
  );

  document.addEventListener(
    "change",
    function(event){

      if(
        event.target?.id ===
        "lpR12Physical"
        ||
        event.target?.id ===
        "invProduct"
      ){
        lpR14ReasonBox();
      }

    },
    false
  );

  /*
   * CONTRÔLE AVANT le onclick R12.
   *
   * Si écart :
   * impossible d'enregistrer
   * sans motif.
   */

  document.addEventListener(
    "click",
    function(event){

      const button=
        event.target
          ?.closest
          ?.("#lpR12Save");

      if(!button){
        return;
      }

      lpR14ReasonBox();

      const diff=
        lpR14Diff();

      if(
        diff === null ||
        diff === 0
      ){
        return;
      }

      const product=
        lpR14Product();

      const reason=
        lpR14ReasonValue();

      if(!reason){

        event.preventDefault();

        event.stopImmediatePropagation();

        toast(
          "Motif obligatoire pour cet écart"
        );

        const select=
          document.getElementById(
            "lpR14Reason"
          );

        if(select){
          select.focus();
        }

        return;
      }

      const productId=
        product?.id;

      /*
       * Laisser R12 enregistrer
       * le comptage normalement,
       * puis attacher le motif.
       */

      setTimeout(
        function(){

          lpR14SaveReason(
            productId,
            reason
          );

        },
        180
      );

    },
    true
  );

  function lpR14Rows(){

    const session=
      lpR14Session();

    if(
      !session ||
      !Array.isArray(
        session.counts
      )
    ){
      return `
        <p class="muted">
          Aucun écart à justifier.
        </p>
      `;
    }

    const rows=
      session.counts
        .filter(
          function(row){

            return (
              Number(
                row.physical||0
              )
              -
              Number(
                row.theoretical||0
              )
            ) !== 0;
          }
        )
        .slice()
        .reverse();

    if(!rows.length){

      return `
        <p class="muted">
          Aucun écart à justifier.
        </p>
      `;
    }

    return `
      <div style="
        overflow:auto;
        margin-top:12px;
      ">

        <table style="
          width:100%;
          min-width:700px;
        ">

          <thead>
            <tr>
              <th>Produit</th>
              <th>Écart</th>
              <th>Motif</th>
              <th>Utilisateur</th>
            </tr>
          </thead>

          <tbody>

            ${
              rows.map(
                function(row){

                  const diff=
                    Number(
                      row.physical||0
                    )
                    -
                    Number(
                      row.theoretical||0
                    );

                  return `
                    <tr>

                      <td>
                        <b>
                          ${row.productName||"Produit"}
                        </b>
                      </td>

                      <td>
                        <b>
                          ${
                            diff > 0
                              ? "+"+diff
                              : diff
                          }
                        </b>
                      </td>

                      <td>
                        ${
                          row.reason
                            ? row.reason
                            : "À justifier"
                        }
                      </td>

                      <td>
                        ${
                          row.reasonUser ||
                          row.user ||
                          "—"
                        }
                      </td>

                    </tr>
                  `;
                }
              ).join("")
            }

          </tbody>
        </table>
      </div>
    `;
  }

  function lpR14Panel(){

    if(
      typeof page !==
        "undefined"
      &&
      page !== "inventory"
    ){
      return;
    }

    const session=
      lpR14Session();

    document
      .getElementById(
        "lpR14Reasons"
      )
      ?.remove();

    if(!session){
      return;
    }

    const r13=
      document.getElementById(
        "lpR13Differences"
      );

    const content=
      document.getElementById(
        "content"
      );

    if(!content){
      return;
    }

    const panel=
      document.createElement(
        "div"
      );

    panel.id=
      "lpR14Reasons";

    panel.className=
      "card";

    panel.style.marginBottom=
      "16px";

    panel.innerHTML=`

      <div class="section-title">

        <div>

          <h3>
            📝 Justification des écarts
          </h3>

          <div class="muted">
            Session :
            <b>
              ${session.number}
            </b>
          </div>

        </div>

      </div>

      <p class="muted">
        Tout manquant ou excédent
        doit avoir un motif
        avant son enregistrement.
        Le stock réel reste inchangé.
      </p>

      ${lpR14Rows()}

    `;

    if(r13){

      r13.insertAdjacentElement(
        "afterend",
        panel
      );

    }else{

      content.insertBefore(
        panel,
        content.firstChild
      );
    }
  }

  if(
    typeof inventory ===
    "function"
  ){

    const base=
      inventory;

    inventory=
      function(){

        const result=
          base.apply(
            this,
            arguments
          );

        setTimeout(
          lpR14Panel,
          40
        );

        return result;
      };
  }

  setTimeout(
    lpR14Panel,
    450
  );

  console.log(
    "LEADER PHARMA V1.5.18R14 MOTIF ECART INVENTAIRE ACTIF"
  );

})();


/* =========================================================
   LEADER PHARMA V1.5.18R15
   VALIDATION FINALE INVENTAIRE
   - applique physique au stock
   - ferme session
   - historique et audit
   ========================================================= */

(function(){

  "use strict";

  let lpR15Busy=false;

  function lpR15Session(){

    if(
      !db ||
      !Array.isArray(db.inventorySessions)
    ){
      return null;
    }

    return db.inventorySessions
      .slice()
      .reverse()
      .find(
        s =>
          String(s.agency||"")===
          String(currentAgency||"")
          &&
          s.status==="En cours"
      ) || null;
  }

  function lpR15Counts(){

    const s=lpR15Session();

    if(
      !s ||
      !Array.isArray(s.counts)
    ){
      return [];
    }

    return s.counts;
  }

  function lpR15Diff(row){

    return (
      Number(row.physical||0)
      -
      Number(row.theoretical||0)
    );
  }

  function lpR15MissingReasons(){

    return lpR15Counts()
      .filter(
        row =>
          lpR15Diff(row)!==0
          &&
          !String(
            row.reason||""
          ).trim()
      );
  }

  function lpR15Summary(){

    const rows=lpR15Counts();

    let conformes=0;
    let manquants=0;
    let excedents=0;

    rows.forEach(row=>{

      const diff=
        lpR15Diff(row);

      if(diff===0){
        conformes++;
      }
      else if(diff<0){
        manquants++;
      }
      else{
        excedents++;
      }
    });

    return {
      total:rows.length,
      conformes,
      manquants,
      excedents
    };
  }

  function lpR15Validator(){

    return (
      currentUser?.name ||
      currentUser?.username ||
      "Utilisateur"
    );
  }

  function lpR15Validate(){

    if(lpR15Busy){
      return;
    }

    const session=
      lpR15Session();

    const counts=
      lpR15Counts();

    if(!session){
      toast(
        "Aucune session en cours"
      );
      return;
    }

    if(!counts.length){

      toast(
        "Aucun produit compté"
      );

      return;
    }

    const missing=
      lpR15MissingReasons();

    if(missing.length){

      toast(
        "Motif manquant pour "
        + missing.length
        + " écart(s)"
      );

      return;
    }

    /*
     * Contrôles de sécurité
     * AVANT toute modification.
     */

    const prepared=[];
    const conflicts=[];

    for(const row of counts){

      const product=
        Array.isArray(db.products)
          ? db.products.find(
              p =>
                String(p.id)===
                String(row.productId)
            )
          : null;

      if(!product){

        toast(
          "Produit introuvable : "
          + String(
            row.productName||
            row.productId
          )
        );

        return;
      }

      const physical=
        Number(row.physical);

      const theoretical=
        Number(row.theoretical);

      const current=
        Number(product.stock||0);

      if(
        !Number.isFinite(physical)
        ||
        physical<0
        ||
        !Number.isFinite(theoretical)
      ){

        toast(
          "Comptage invalide : "
          + String(
            row.productName||
            "Produit"
          )
        );

        return;
      }

      /*
       * Si le stock a bougé
       * depuis le comptage,
       * ne surtout pas écraser
       * une vente/réception récente.
       */

      if(current!==theoretical){

        conflicts.push(
          String(
            row.productName||
            "Produit"
          )
        );

        continue;
      }

      prepared.push({
        row,
        product,
        physical,
        theoretical,
        diff:
          physical-
          theoretical
      });
    }

    if(conflicts.length){

      toast(
        "Stock modifié depuis comptage : "
        + conflicts[0]
        + ". Recomptez ce produit."
      );

      return;
    }

    const ok=
      window.confirm(
        "VALIDATION DÉFINITIVE\n\n"
        + session.number
        + "\n"
        + prepared.length
        + " produit(s) compté(s).\n\n"
        + "Les quantités physiques vont devenir le stock officiel.\n"
        + "Continuer ?"
      );

    if(!ok){
      return;
    }

    lpR15Busy=true;

    try{

      if(
        !Array.isArray(
          db.inventories
        )
      ){
        db.inventories=[];
      }

      const now=
        new Date();

      const date=
        now
          .toISOString()
          .slice(0,10);

      const time=
        now
          .toLocaleTimeString(
            "fr-FR",
            {
              hour:"2-digit",
              minute:"2-digit"
            }
          );

      const validator=
        lpR15Validator();

      /*
       * UNE SEULE ET UNIQUE
       * APPLICATION DU STOCK.
       */

      prepared.forEach(item=>{

        const row=item.row;
        const p=item.product;

        row.appliedBefore=
          item.theoretical;

        row.appliedAfter=
          item.physical;

        row.diff=
          item.diff;

        row.appliedAt=
          now.toISOString();

        row.appliedBy=
          validator;

        p.stock=
          item.physical;

        const already=
          db.inventories.find(
            x =>
              String(
                x.sessionNumber||""
              )===
              String(session.number)
              &&
              String(x.productId)===
              String(p.id)
          );

        if(!already){

          db.inventories.push({

            id:
              Date.now()
              +
              Math.floor(
                Math.random()*100000
              ),

            date:date,

            time:time,

            agency:
              currentAgency,

            sessionNumber:
              session.number,

            productId:
              p.id,

            productName:
              p.name,

            lot:
              row.lot ||
              p.lot ||
              "",

            expected:
              item.theoretical,

            actual:
              item.physical,

            diff:
              item.diff,

            reason:
              row.reason || "",

            user:
              row.user || "",

            validator:
              validator,

            validatedAt:
              now.toISOString()

          });
        }
      });

      const summary=
        lpR15Summary();

      session.status=
        "Validée";

      session.validatedAt=
        now.toISOString();

      session.validatedDate=
        date;

      session.validatedTime=
        time;

      session.validatedBy=
        validator;

      session.summary={
        total:summary.total,
        conformes:summary.conformes,
        manquants:summary.manquants,
        excedents:summary.excedents
      };

      try{
        save();
      }catch(error){

        console.error(
          "R15 SAVE",
          error
        );

        throw error;
      }

      try{

        audit(
          "Inventaire",
          "Validation définitive "
          + session.number
          + " • "
          + summary.total
          + " produit(s)"
          + " • manquants "
          + summary.manquants
          + " • excédents "
          + summary.excedents
        );

      }catch(e){}

      try{
        save();
      }catch(e){}

      toast(
        "Inventaire validé • stock mis à jour"
      );

      /*
       * Recharge Inventaires :
       * R11 montrera maintenant
       * la session Validée.
       */

      setTimeout(
        function(){

          try{
            inventory();
          }catch(e){
            try{
              render();
            }catch(err){}
          }

        },
        300
      );

    }catch(error){

      console.error(
        "R15 VALIDATION",
        error
      );

      toast(
        "Validation impossible"
      );

    }finally{

      setTimeout(
        function(){
          lpR15Busy=false;
        },
        500
      );
    }
  }

  function lpR15Install(){

    if(
      typeof page!=="undefined"
      &&
      page!=="inventory"
    ){
      return;
    }

    document
      .getElementById(
        "lpR15Final"
      )
      ?.remove();

    const session=
      lpR15Session();

    if(!session){
      return;
    }

    const content=
      document.getElementById(
        "content"
      );

    if(!content){
      return;
    }

    const counts=
      lpR15Counts();

    const summary=
      lpR15Summary();

    const missing=
      lpR15MissingReasons();

    const panel=
      document.createElement(
        "div"
      );

    panel.id=
      "lpR15Final";

    panel.className=
      "card";

    panel.style.marginBottom=
      "16px";

    panel.innerHTML=`

      <div class="section-title">

        <div>

          <h3>
            ✅ Validation finale
          </h3>

          <div class="muted">
            Session :
            <b>
              ${session.number}
            </b>
          </div>

        </div>

      </div>

      <p class="muted">
        Cette validation clôture
        définitivement la session
        et applique les quantités
        physiques au stock officiel.
      </p>

      <div style="
        display:grid;
        grid-template-columns:
        repeat(
          auto-fit,
          minmax(110px,1fr)
        );
        gap:8px;
        margin:14px 0;
      ">

        <div class="card">
          <small class="muted">
            Comptés
          </small>
          <div style="
            font-size:22px;
            font-weight:800
          ">
            ${summary.total}
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Conformes
          </small>
          <div style="
            font-size:22px;
            font-weight:800
          ">
            ${summary.conformes}
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Manquants
          </small>
          <div style="
            font-size:22px;
            font-weight:800
          ">
            ${summary.manquants}
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Excédents
          </small>
          <div style="
            font-size:22px;
            font-weight:800
          ">
            ${summary.excedents}
          </div>
        </div>

      </div>

      ${
        missing.length
        ?
        `
          <p style="
            color:#b42318;
            font-weight:700;
          ">
            ⚠️ ${missing.length}
            écart(s) sans motif.
            Validation impossible.
          </p>
        `
        :
        `
          <p style="
            color:#157a36;
            font-weight:700;
          ">
            ✓ Tous les contrôles
            sont prêts pour validation.
          </p>
        `
      }

      <button
        type="button"
        class="btn"
        id="lpR15Validate"
        style="
          width:100%;
          margin-top:10px;
        "
        ${counts.length ? "" : "disabled"}
      >
        ✅ Valider définitivement l'inventaire
      </button>

    `;

    const r14=
      document.getElementById(
        "lpR14Reasons"
      );

    const r13=
      document.getElementById(
        "lpR13Differences"
      );

    if(r14){

      r14.insertAdjacentElement(
        "afterend",
        panel
      );

    }else if(r13){

      r13.insertAdjacentElement(
        "afterend",
        panel
      );

    }else{

      content.insertBefore(
        panel,
        content.firstChild
      );
    }

    const button=
      document.getElementById(
        "lpR15Validate"
      );

    if(button){
      button.onclick=
        lpR15Validate;
    }
  }

  if(typeof inventory==="function"){

    const base=
      inventory;

    inventory=
      function(){

        const result=
          base.apply(
            this,
            arguments
          );

        setTimeout(
          lpR15Install,
          60
        );

        return result;
      };
  }

  document.addEventListener(
    "click",
    function(event){

      const text=
        String(
          event.target
            ?.textContent ||
          ""
        ).toLowerCase();

      if(
        text.includes(
          "enregistrer le comptage"
        )
      ){

        setTimeout(
          lpR15Install,
          300
        );
      }

    },
    false
  );

  setTimeout(
    lpR15Install,
    500
  );

  console.log(
    "LEADER PHARMA V1.5.18R15 VALIDATION FINALE INVENTAIRE ACTIF"
  );

})();


/* =========================================================
   LEADER PHARMA V1.5.18R16
   RAPPORT INVENTAIRE PROFESSIONNEL
   - sessions validees
   - ecarts
   - motifs
   - valeur financiere au cout d'achat
   - aucune modification du stock
   ========================================================= */

(function(){

  "use strict";

  let lpR16Selected="";

  function lpR16Esc(value){

    return String(
      value == null ? "" : value
    )
    .replace(/&/g,"&amp;")
    .replace(/</g,"&lt;")
    .replace(/>/g,"&gt;")
    .replace(/"/g,"&quot;")
    .replace(/'/g,"&#039;");
  }

  function lpR16Money(value){

    try{

      return new Intl.NumberFormat(
        "fr-CD"
      ).format(
        Number(value||0)
      ) + " FC";

    }catch(e){

      return (
        Number(value||0) +
        " FC"
      );
    }
  }

  function lpR16Sessions(){

    if(
      !db ||
      !Array.isArray(
        db.inventorySessions
      )
    ){
      return [];
    }

    return db.inventorySessions
      .filter(
        function(session){

          return (
            session.status ===
            "Validée"
            &&
            String(
              session.agency||""
            ) ===
            String(
              currentAgency||""
            )
          );
        }
      )
      .slice()
      .reverse();
  }

  function lpR16FindSession(){

    const sessions=
      lpR16Sessions();

    if(!sessions.length){
      return null;
    }

    if(lpR16Selected){

      const found=
        sessions.find(
          function(session){

            return (
              String(
                session.number
              ) ===
              String(
                lpR16Selected
              )
            );
          }
        );

      if(found){
        return found;
      }
    }

    lpR16Selected=
      sessions[0].number;

    return sessions[0];
  }

  function lpR16Product(
    productId
  ){

    if(
      !db ||
      !Array.isArray(
        db.products
      )
    ){
      return null;
    }

    return db.products.find(
      function(product){

        return (
          String(product.id) ===
          String(productId)
        );
      }
    ) || null;
  }

  function lpR16Rows(
    session
  ){

    if(!session){
      return [];
    }

    if(
      Array.isArray(
        session.counts
      )
      &&
      session.counts.length
    ){

      return session.counts;
    }

    if(
      Array.isArray(
        db.inventories
      )
    ){

      return db.inventories
        .filter(
          function(row){

            return (
              String(
                row.sessionNumber||""
              ) ===
              String(
                session.number||""
              )
            );
          }
        )
        .map(
          function(row){

            return {
              productId:
                row.productId,

              productName:
                row.productName,

              lot:
                row.lot,

              theoretical:
                row.expected,

              physical:
                row.actual,

              reason:
                row.reason,

              user:
                row.user,

              appliedBy:
                row.validator
            };
          }
        );
    }

    return [];
  }

  function lpR16PrepareRows(
    session
  ){

    return lpR16Rows(
      session
    ).map(
      function(row){

        const product=
          lpR16Product(
            row.productId
          );

        const theoretical=
          Number(
            row.theoretical||0
          );

        const physical=
          Number(
            row.physical||0
          );

        const diff=
          physical -
          theoretical;

        const cost=
          Number(
            row.cost != null
              ? row.cost
              : (
                  product?.cost ||
                  0
                )
          );

        const value=
          diff * cost;

        return {
          productId:
            row.productId,

          productName:
            row.productName ||
            product?.name ||
            "Produit",

          lot:
            row.lot ||
            product?.lot ||
            "",

          theoretical,
          physical,
          diff,
          cost,
          value,

          reason:
            row.reason || "",

          user:
            row.user || "",

          validator:
            row.appliedBy ||
            session.validatedBy ||
            ""
        };
      }
    );
  }

  function lpR16Status(
    diff
  ){

    if(diff===0){
      return "Conforme";
    }

    if(diff<0){
      return "Manquant";
    }

    return "Excédent";
  }

  function lpR16DiffText(
    diff
  ){

    return (
      diff > 0
        ? "+" + diff
        : String(diff)
    );
  }

  function lpR16ValueText(
    value
  ){

    if(value>0){

      return (
        "+" +
        lpR16Money(value)
      );
    }

    if(value<0){

      return (
        "-" +
        lpR16Money(
          Math.abs(value)
        )
      );
    }

    return lpR16Money(0);
  }

  function lpR16Summary(
    rows
  ){

    let conformes=0;
    let manquants=0;
    let excedents=0;

    let qteManquante=0;
    let qteExcedentaire=0;

    let valeurManquante=0;
    let valeurExcedentaire=0;

    rows.forEach(
      function(row){

        if(row.diff===0){

          conformes++;

        }else if(
          row.diff<0
        ){

          manquants++;

          qteManquante +=
            Math.abs(
              row.diff
            );

          valeurManquante +=
            Math.abs(
              row.value
            );

        }else{

          excedents++;

          qteExcedentaire +=
            row.diff;

          valeurExcedentaire +=
            row.value;
        }
      }
    );

    return {
      total:
        rows.length,

      conformes,
      manquants,
      excedents,

      qteManquante,
      qteExcedentaire,

      valeurManquante,
      valeurExcedentaire,

      valeurNette:
        valeurExcedentaire -
        valeurManquante
    };
  }

  function lpR16SelectHtml(){

    const sessions=
      lpR16Sessions();

    if(!sessions.length){
      return "";
    }

    return `
      <select
        id="lpR16SessionSelect"
        style="
          min-width:210px;
        "
      >
        ${
          sessions.map(
            function(session){

              const selected=
                String(
                  session.number
                ) ===
                String(
                  lpR16Selected
                )
                ? "selected"
                : "";

              return `
                <option
                  value="${lpR16Esc(
                    session.number
                  )}"
                  ${selected}
                >
                  ${lpR16Esc(
                    session.number
                  )}
                  •
                  ${lpR16Esc(
                    session.validatedDate ||
                    session.date ||
                    ""
                  )}
                </option>
              `;
            }
          ).join("")
        }
      </select>
    `;
  }

  function lpR16RowsHtml(
    rows
  ){

    if(!rows.length){

      return `
        <p class="muted">
          Aucun produit dans ce rapport.
        </p>
      `;
    }

    return `
      <div style="
        overflow:auto;
        margin-top:14px;
      ">

        <table style="
          width:100%;
          min-width:980px;
        ">

          <thead>
            <tr>
              <th>Produit</th>
              <th>Lot</th>
              <th>Théorique</th>
              <th>Physique</th>
              <th>Écart</th>
              <th>Statut</th>
              <th>Motif</th>
              <th>Coût achat</th>
              <th>Valeur écart</th>
            </tr>
          </thead>

          <tbody>

            ${
              rows.map(
                function(row){

                  return `
                    <tr>

                      <td>
                        <b>
                          ${lpR16Esc(
                            row.productName
                          )}
                        </b>
                      </td>

                      <td>
                        ${lpR16Esc(
                          row.lot ||
                          "—"
                        )}
                      </td>

                      <td>
                        ${row.theoretical}
                      </td>

                      <td>
                        <b>
                          ${row.physical}
                        </b>
                      </td>

                      <td>
                        <b>
                          ${lpR16DiffText(
                            row.diff
                          )}
                        </b>
                      </td>

                      <td>
                        ${lpR16Status(
                          row.diff
                        )}
                      </td>

                      <td>
                        ${lpR16Esc(
                          row.reason ||
                          "—"
                        )}
                      </td>

                      <td>
                        ${lpR16Money(
                          row.cost
                        )}
                      </td>

                      <td>
                        <b>
                          ${lpR16ValueText(
                            row.value
                          )}
                        </b>
                      </td>

                    </tr>
                  `;
                }
              ).join("")
            }

          </tbody>
        </table>
      </div>
    `;
  }

  function lpR16Install(){

    if(
      typeof page!=="undefined"
      &&
      page!=="inventory"
    ){
      return;
    }

    document
      .getElementById(
        "lpR16Report"
      )
      ?.remove();

    const content=
      document.getElementById(
        "content"
      );

    if(!content){
      return;
    }

    const sessions=
      lpR16Sessions();

    if(!sessions.length){
      return;
    }

    const session=
      lpR16FindSession();

    if(!session){
      return;
    }

    const rows=
      lpR16PrepareRows(
        session
      );

    const summary=
      lpR16Summary(
        rows
      );

    const panel=
      document.createElement(
        "div"
      );

    panel.id=
      "lpR16Report";

    panel.className=
      "card";

    panel.style.marginBottom=
      "16px";

    panel.innerHTML=`

      <div
        class="section-title"
        style="
          gap:10px;
          flex-wrap:wrap;
        "
      >

        <div>

          <h3>
            📑 Rapport d'inventaire professionnel
          </h3>

          <div class="muted">
            Session validée
          </div>

        </div>

        ${lpR16SelectHtml()}

      </div>

      <div style="
        display:grid;
        grid-template-columns:
        repeat(
          auto-fit,
          minmax(150px,1fr)
        );
        gap:8px;
        margin-top:14px;
      ">

        <div class="card">
          <small class="muted">
            Session
          </small>
          <div>
            <b>
              ${lpR16Esc(
                session.number
              )}
            </b>
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Agence
          </small>
          <div>
            <b>
              ${lpR16Esc(
                session.agencyName ||
                currentAgency ||
                ""
              )}
            </b>
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Date validation
          </small>
          <div>
            <b>
              ${lpR16Esc(
                session.validatedDate ||
                session.date ||
                ""
              )}
              ${lpR16Esc(
                session.validatedTime ||
                ""
              )}
            </b>
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Validé par
          </small>
          <div>
            <b>
              ${lpR16Esc(
                session.validatedBy ||
                "—"
              )}
            </b>
          </div>
        </div>

      </div>

      <div style="
        display:grid;
        grid-template-columns:
        repeat(
          auto-fit,
          minmax(110px,1fr)
        );
        gap:8px;
        margin-top:10px;
      ">

        <div class="card">
          <small class="muted">
            Comptés
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.total}
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Conformes
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.conformes}
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Manquants
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.manquants}
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Excédents
          </small>
          <div style="
            font-size:22px;
            font-weight:800;
          ">
            ${summary.excedents}
          </div>
        </div>

      </div>

      <div style="
        display:grid;
        grid-template-columns:
        repeat(
          auto-fit,
          minmax(150px,1fr)
        );
        gap:8px;
        margin-top:10px;
      ">

        <div class="card">
          <small class="muted">
            Qté manquante
          </small>
          <div>
            <b>
              ${summary.qteManquante}
            </b>
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Valeur manquante
          </small>
          <div>
            <b>
              ${lpR16Money(
                summary.valeurManquante
              )}
            </b>
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Qté excédentaire
          </small>
          <div>
            <b>
              ${summary.qteExcedentaire}
            </b>
          </div>
        </div>

        <div class="card">
          <small class="muted">
            Valeur excédentaire
          </small>
          <div>
            <b>
              ${lpR16Money(
                summary.valeurExcedentaire
              )}
            </b>
          </div>
        </div>

      </div>

      <p
        style="
          margin-top:12px;
          font-weight:700;
        "
      >
        Valeur nette des écarts :
        ${
          lpR16ValueText(
            summary.valeurNette
          )
        }
      </p>

      <hr>

      ${lpR16RowsHtml(rows)}

      <p
        class="muted"
        style="
          margin-top:12px;
        "
      >
        Valeur calculée sur le coût
        d'achat enregistré du produit.
        Ce rapport est en lecture seule.
      </p>

    `;

    const r11=
      document.getElementById(
        "lpR11Inventory"
      );

    if(r11){

      r11.insertAdjacentElement(
        "afterend",
        panel
      );

    }else{

      content.insertBefore(
        panel,
        content.firstChild
      );
    }

    const select=
      document.getElementById(
        "lpR16SessionSelect"
      );

    if(select){

      select.onchange=
        function(){

          lpR16Selected=
            this.value;

          lpR16Install();
        };
    }
  }

  if(
    typeof inventory===
    "function"
  ){

    const base=
      inventory;

    inventory=
      function(){

        const result=
          base.apply(
            this,
            arguments
          );

        setTimeout(
          lpR16Install,
          80
        );

        return result;
      };
  }

  setTimeout(
    lpR16Install,
    550
  );

  console.log(
    "LEADER PHARMA V1.5.18R16 RAPPORT INVENTAIRE PROFESSIONNEL ACTIF"
  );

})();


/* =========================================================
   LEADER PHARMA V1.5.18R17
   IMPRESSION RAPPORT INVENTAIRE Z91 58 MM
   AUCUNE MODIFICATION DU STOCK
   ========================================================= */

(function(){

  "use strict";

  const LP_R17_WIDTH = 32;

  function lpR17Sessions(){

    if(
      !db ||
      !Array.isArray(db.inventorySessions)
    ){
      return [];
    }

    return db.inventorySessions
      .filter(function(s){

        return (
          s.status === "Validée"
          &&
          String(s.agency || "") ===
          String(currentAgency || "")
        );
      })
      .slice()
      .reverse();
  }

  function lpR17Session(){

    const sessions =
      lpR17Sessions();

    if(!sessions.length){
      return null;
    }

    const selected =
      document.getElementById(
        "lpR16SessionSelect"
      )?.value;

    if(selected){

      const found =
        sessions.find(function(s){

          return (
            String(s.number) ===
            String(selected)
          );
        });

      if(found){
        return found;
      }
    }

    return sessions[0];
  }

  function lpR17Rows(session){

    if(
      Array.isArray(session?.counts)
      &&
      session.counts.length
    ){
      return session.counts;
    }

    if(
      !Array.isArray(db.inventories)
    ){
      return [];
    }

    return db.inventories
      .filter(function(row){

        return (
          String(
            row.sessionNumber || ""
          ) ===
          String(
            session?.number || ""
          )
        );
      })
      .map(function(row){

        return {
          productId:
            row.productId,

          productName:
            row.productName,

          lot:
            row.lot,

          theoretical:
            row.expected,

          physical:
            row.actual,

          reason:
            row.reason
        };
      });
  }

  function lpR17Product(id){

    if(!Array.isArray(db.products)){
      return null;
    }

    return db.products.find(
      function(p){

        return (
          String(p.id) ===
          String(id)
        );
      }
    ) || null;
  }

  function lpR17Data(session){

    return lpR17Rows(session)
      .map(function(row){

        const product =
          lpR17Product(
            row.productId
          );

        const theoretical =
          Number(
            row.theoretical || 0
          );

        const physical =
          Number(
            row.physical || 0
          );

        const diff =
          physical -
          theoretical;

        const cost =
          Number(
            row.cost != null
              ? row.cost
              : (
                  product?.cost ||
                  0
                )
          );

        return {
          name:
            String(
              row.productName ||
              product?.name ||
              "Produit"
            ),

          lot:
            String(
              row.lot ||
              product?.lot ||
              "-"
            ),

          theoretical,
          physical,
          diff,
          cost,

          value:
            diff * cost,

          reason:
            String(
              row.reason || "-"
            )
        };
      });
  }

  function lpR17Money(value){

    return (
      Math.round(
        Number(value || 0)
      )
      .toLocaleString("fr-FR")
      .replace(/\u202f/g," ")
      + " FC"
    );
  }

  function lpR17Summary(rows){

    let conformes = 0;
    let manquants = 0;
    let excedents = 0;

    let qteManquante = 0;
    let qteExcedentaire = 0;

    let valeurManquante = 0;
    let valeurExcedentaire = 0;

    rows.forEach(function(row){

      if(row.diff === 0){

        conformes++;

      }else if(row.diff < 0){

        manquants++;

        qteManquante +=
          Math.abs(row.diff);

        valeurManquante +=
          Math.abs(row.value);

      }else{

        excedents++;

        qteExcedentaire +=
          row.diff;

        valeurExcedentaire +=
          row.value;
      }
    });

    return {
      total:
        rows.length,

      conformes,
      manquants,
      excedents,

      qteManquante,
      qteExcedentaire,

      valeurManquante,
      valeurExcedentaire,

      valeurNette:
        valeurExcedentaire -
        valeurManquante
    };
  }

  function lpR17Cut(text){

    text =
      String(text ?? "");

    if(text.length <= LP_R17_WIDTH){
      return text;
    }

    return text.slice(
      0,
      LP_R17_WIDTH
    );
  }

  function lpR17Separator(){

    return "-".repeat(
      LP_R17_WIDTH
    );
  }

  function lpR17Agency(session){

    if(session?.agencyName){
      return session.agencyName;
    }

    const agency =
      Array.isArray(db.agencies)
        ? db.agencies.find(
            function(a){

              return (
                String(a.id) ===
                String(
                  session?.agency
                )
              );
            }
          )
        : null;

    return (
      agency?.name ||
      "Leader Pharma Kamina"
    );
  }

  function lpR17Text(session){

    const rows =
      lpR17Data(session);

    const summary =
      lpR17Summary(rows);

    const lines = [];

    lines.push(
      lpR17Cut(
        ID?.name ||
        "LEADER PHARMA"
      )
    );

    if(ID?.slogan){

      lines.push(
        lpR17Cut(ID.slogan)
      );
    }

    lines.push(
      lpR17Separator()
    );

    lines.push(
      "RAPPORT INVENTAIRE"
    );

    lines.push(
      lpR17Separator()
    );

    lines.push(
      lpR17Cut(
        "Session: " +
        String(
          session.number || "-"
        )
      )
    );

    lines.push(
      lpR17Cut(
        "Agence: " +
        lpR17Agency(session)
      )
    );

    lines.push(
      lpR17Cut(
        "Date: " +
        String(
          session.validatedDate ||
          session.date ||
          "-"
        )
      )
    );

    if(session.validatedTime){

      lines.push(
        lpR17Cut(
          "Heure: " +
          session.validatedTime
        )
      );
    }

    lines.push(
      lpR17Cut(
        "Valide par: " +
        String(
          session.validatedBy ||
          "-"
        )
      )
    );

    lines.push(
      lpR17Separator()
    );

    lines.push(
      "Comptes: " +
      summary.total
    );

    lines.push(
      "Conformes: " +
      summary.conformes
    );

    lines.push(
      "Manquants: " +
      summary.manquants
    );

    lines.push(
      "Excedents: " +
      summary.excedents
    );

    lines.push(
      "Qte manquante: " +
      summary.qteManquante
    );

    lines.push(
      "Qte excedentaire: " +
      summary.qteExcedentaire
    );

    lines.push(
      lpR17Cut(
        "Val. manquante: " +
        lpR17Money(
          summary.valeurManquante
        )
      )
    );

    lines.push(
      lpR17Cut(
        "Val. excedentaire: " +
        lpR17Money(
          summary.valeurExcedentaire
        )
      )
    );

    lines.push(
      lpR17Cut(
        "Valeur nette: " +
        (
          summary.valeurNette > 0
            ? "+"
            : ""
        ) +
        lpR17Money(
          summary.valeurNette
        )
      )
    );

    lines.push(
      lpR17Separator()
    );

    lines.push(
      "DETAIL PRODUITS"
    );

    lines.push(
      lpR17Separator()
    );

    rows.forEach(
      function(row,index){

        lines.push(
          lpR17Cut(
            (index + 1) +
            ". " +
            row.name
          )
        );

        lines.push(
          lpR17Cut(
            "Lot: " +
            row.lot
          )
        );

        lines.push(
          lpR17Cut(
            "Theo: " +
            row.theoretical +
            "  Phys: " +
            row.physical
          )
        );

        lines.push(
          lpR17Cut(
            "Ecart: " +
            (
              row.diff > 0
                ? "+"
                : ""
            ) +
            row.diff
          )
        );

        lines.push(
          lpR17Cut(
            "Statut: " +
            (
              row.diff === 0
                ? "Conforme"
                : (
                    row.diff < 0
                      ? "Manquant"
                      : "Excedent"
                  )
            )
          )
        );

        if(row.diff !== 0){

          lines.push(
            lpR17Cut(
              "Motif: " +
              row.reason
            )
          );
        }

        lines.push(
          lpR17Cut(
            "Cout: " +
            lpR17Money(
              row.cost
            )
          )
        );

        lines.push(
          lpR17Cut(
            "Valeur ecart: " +
            (
              row.value > 0
                ? "+"
                : ""
            ) +
            lpR17Money(
              row.value
            )
          )
        );

        lines.push(
          lpR17Separator()
        );
      }
    );

    if(ID?.website){

      lines.push(
        lpR17Cut(
          ID.website
        )
      );
    }

    lines.push("");
    lines.push("");
    lines.push("");

    return lines.join("\n");
  }

  async function lpR17Print(){

    const session =
      lpR17Session();

    if(!session){

      toast(
        "Aucune session validée"
      );

      return;
    }

    const rows =
      lpR17Data(session);

    if(!rows.length){

      toast(
        "Rapport sans produit"
      );

      return;
    }

    const button =
      document.getElementById(
        "lpR17Print"
      );

    if(button){
      button.disabled = true;
    }

    try{

      const printer =
        window.Capacitor
          ?.Plugins
          ?.Z91Printer;

      if(!printer){

        throw new Error(
          "Pilote Z91 non disponible"
        );
      }

      const text =
        lpR17Text(session);

      const result =
        await printer.printReceipt({
          text
        });

      if(
        result?.printed === false
      ){

        throw new Error(
          "Statut imprimante : " +
          String(
            result.status ||
            "échec"
          )
        );
      }

      try{

        audit(
          "Impression",
          "Rapport inventaire " +
          session.number
        );

      }catch(e){}

      toast(
        "Rapport inventaire imprimé sur Z91"
      );

    }catch(error){

      console.error(
        "R17 IMPRESSION",
        error
      );

      toast(
        error?.message ||
        "Impression impossible"
      );

    }finally{

      if(button){
        button.disabled = false;
      }
    }
  }

  function lpR17Install(){

    if(
      typeof page !== "undefined"
      &&
      page !== "inventory"
    ){
      return;
    }

    const report =
      document.getElementById(
        "lpR16Report"
      );

    if(!report){
      return;
    }

    if(
      document.getElementById(
        "lpR17PrintWrap"
      )
    ){
      return;
    }

    const wrap =
      document.createElement(
        "div"
      );

    wrap.id =
      "lpR17PrintWrap";

    wrap.style.marginTop =
      "16px";

    wrap.innerHTML = `
      <button
        type="button"
        class="btn"
        id="lpR17Print"
        style="
          width:100%;
          min-height:52px;
          font-weight:800;
        "
      >
        🖨️ Imprimer le rapport sur Z91
      </button>

      <div
        class="muted"
        style="
          margin-top:8px;
          text-align:center;
        "
      >
        Format thermique 58 mm
      </div>
    `;

    report.appendChild(wrap);

    document
      .getElementById(
        "lpR17Print"
      )
      .onclick =
        lpR17Print;
  }

  if(
    typeof inventory ===
    "function"
  ){

    const baseInventory =
      inventory;

    inventory =
      function(){

        const result =
          baseInventory.apply(
            this,
            arguments
          );

        setTimeout(
          lpR17Install,
          180
        );

        return result;
      };
  }

  document.addEventListener(
    "change",
    function(event){

      if(
        event.target?.id ===
        "lpR16SessionSelect"
      ){

        setTimeout(
          lpR17Install,
          180
        );
      }
    },
    false
  );

  setTimeout(
    lpR17Install,
    700
  );

  console.log(
    "LEADER PHARMA V1.5.18R17 IMPRESSION RAPPORT INVENTAIRE Z91 ACTIF"
  );

})();


