(function(){

  "use strict";

  function lpR18Sessions(){

    if(
      !db ||
      !Array.isArray(
        db.inventorySessions
      )
    ){
      return [];
    }

    return db.inventorySessions
      .filter(function(session){

        return (
          session.status === "Validée"
          &&
          String(
            session.agency || ""
          ) ===
          String(
            currentAgency || ""
          )
        );
      })
      .slice()
      .reverse();
  }

  function lpR18Session(){

    const sessions =
      lpR18Sessions();

    if(!sessions.length){
      return null;
    }

    const selected =
      document.getElementById(
        "lpR16SessionSelect"
      )?.value;

    if(selected){

      const found =
        sessions.find(
          function(session){

            return (
              String(
                session.number
              ) ===
              String(selected)
            );
          }
        );

      if(found){
        return found;
      }
    }

    return sessions[0];
  }

  function lpR18SourceRows(session){

    if(
      Array.isArray(
        session?.counts
      )
      &&
      session.counts.length
    ){
      return session.counts;
    }

    if(
      !Array.isArray(
        db.inventories
      )
    ){
      return [];
    }

    return db.inventories
      .filter(function(row){

        return (
          String(
            row.sessionNumber || ""
          ) ===
          String(
            session?.number || ""
          )
        );
      })
      .map(function(row){

        return {

          productId:
            row.productId,

          productName:
            row.productName,

          lot:
            row.lot,

          theoretical:
            row.expected,

          physical:
            row.actual,

          reason:
            row.reason,

          user:
            row.user,

          cost:
            row.cost
        };
      });
  }

  function lpR18Product(id){

    if(
      !Array.isArray(
        db.products
      )
    ){
      return null;
    }

    return db.products.find(
      function(product){

        return (
          String(product.id) ===
          String(id)
        );
      }
    ) || null;
  }

  function lpR18Rows(session){

    return lpR18SourceRows(
      session
    ).map(function(row){

      const product =
        lpR18Product(
          row.productId
        );

      const theoretical =
        Number(
          row.theoretical || 0
        );

      const physical =
        Number(
          row.physical || 0
        );

      const diff =
        physical -
        theoretical;

      const cost =
        Number(
          row.cost != null
            ? row.cost
            : (
                product?.cost ||
                0
              )
        );

      return {

        product:
          String(
            row.productName ||
            product?.name ||
            "Produit"
          ),

        lot:
          String(
            row.lot ||
            product?.lot ||
            ""
          ),

        theoretical:
          theoretical,

        physical:
          physical,

        diff:
          diff,

        status:
          diff === 0
            ? "Conforme"
            : (
                diff < 0
                  ? "Manquant"
                  : "Excédent"
              ),

        reason:
          String(
            row.reason || ""
          ),

        cost:
          cost,

        value:
          diff * cost
      };
    });
  }

  function lpR18Agency(session){

    if(session?.agencyName){
      return session.agencyName;
    }

    const agency =
      Array.isArray(
        db.agencies
      )
        ? db.agencies.find(
            function(item){

              return (
                String(item.id) ===
                String(
                  session?.agency
                )
              );
            }
          )
        : null;

    return (
      agency?.name ||
      "Leader Pharma Kamina"
    );
  }

  function lpR18CsvCell(value){

    const text =
      String(
        value == null
          ? ""
          : value
      );

    return (
      '"' +
      text.replace(
        /"/g,
        '""'
      ) +
      '"'
    );
  }

  function lpR18Line(values){

    return values
      .map(lpR18CsvCell)
      .join(";");
  }

  function lpR18Csv(session){

    const rows =
      lpR18Rows(session);

    const output = [];

    output.push(
      lpR18Line([
        "LEADER PHARMA",
        "RAPPORT INVENTAIRE PROFESSIONNEL"
      ])
    );

    output.push(
      lpR18Line([
        "Session",
        session.number || ""
      ])
    );

    output.push(
      lpR18Line([
        "Agence",
        lpR18Agency(session)
      ])
    );

    output.push(
      lpR18Line([
        "Date validation",
        session.validatedDate ||
        session.date ||
        ""
      ])
    );

    output.push(
      lpR18Line([
        "Heure validation",
        session.validatedTime ||
        ""
      ])
    );

    output.push(
      lpR18Line([
        "Validé par",
        session.validatedBy ||
        ""
      ])
    );

    output.push("");

    output.push(
      lpR18Line([
        "Produit",
        "Lot",
        "Stock théorique",
        "Quantité physique",
        "Écart",
        "Statut",
        "Motif",
        "Coût achat FC",
        "Valeur écart FC"
      ])
    );

    rows.forEach(
      function(row){

        output.push(
          lpR18Line([
            row.product,
            row.lot,
            row.theoretical,
            row.physical,
            row.diff,
            row.status,
            row.reason,
            row.cost,
            row.value
          ])
        );
      }
    );

    output.push("");

    const conformes =
      rows.filter(
        function(row){
          return row.diff === 0;
        }
      ).length;

    const manquants =
      rows.filter(
        function(row){
          return row.diff < 0;
        }
      ).length;

    const excedents =
      rows.filter(
        function(row){
          return row.diff > 0;
        }
      ).length;

    const valeurManquante =
      rows
        .filter(
          function(row){
            return row.value < 0;
          }
        )
        .reduce(
          function(total,row){

            return (
              total +
              Math.abs(
                row.value
              )
            );
          },
          0
        );

    const valeurExcedentaire =
      rows
        .filter(
          function(row){
            return row.value > 0;
          }
        )
        .reduce(
          function(total,row){

            return (
              total +
              row.value
            );
          },
          0
        );

    output.push(
      lpR18Line([
        "RÉSUMÉ",
        ""
      ])
    );

    output.push(
      lpR18Line([
        "Produits comptés",
        rows.length
      ])
    );

    output.push(
      lpR18Line([
        "Conformes",
        conformes
      ])
    );

    output.push(
      lpR18Line([
        "Manquants",
        manquants
      ])
    );

    output.push(
      lpR18Line([
        "Excédents",
        excedents
      ])
    );

    output.push(
      lpR18Line([
        "Valeur manquante FC",
        valeurManquante
      ])
    );

    output.push(
      lpR18Line([
        "Valeur excédentaire FC",
        valeurExcedentaire
      ])
    );

    output.push(
      lpR18Line([
        "Valeur nette FC",
        valeurExcedentaire -
        valeurManquante
      ])
    );

    return (
      "\uFEFF" +
      output.join("\r\n")
    );
  }

  function lpR18Filename(session){

    const number =
      String(
        session.number ||
        "INVENTAIRE"
      )
      .replace(
        /[^A-Za-z0-9_-]/g,
        "-"
      );

    return (
      "Leader-Pharma-Rapport-" +
      number +
      ".csv"
    );
  }

  async function lpR18Export(){

    const session =
      lpR18Session();

    if(!session){

      toast(
        "Aucune session validée"
      );

      return;
    }

    const rows =
      lpR18Rows(session);

    if(!rows.length){

      toast(
        "Aucune donnée à exporter"
      );

      return;
    }

    const button =
      document.getElementById(
        "lpR18Export"
      );

    if(button){
      button.disabled = true;
    }

    try{

      const csv =
        lpR18Csv(session);

      const filename =
        lpR18Filename(session);

      const blob =
        new Blob(
          [csv],
          {
            type:
              "text/csv;charset=utf-8"
          }
        );

      let shared = false;

      try{

        if(
          typeof File !==
          "undefined"
        ){

          const file =
            new File(
              [blob],
              filename,
              {
                type:
                  "text/csv;charset=utf-8"
              }
            );

          if(
            navigator.share
            &&
            navigator.canShare
            &&
            navigator.canShare({
              files:[file]
            })
          ){

            await navigator.share({

              title:
                "Rapport inventaire " +
                String(
                  session.number ||
                  ""
                ),

              text:
                "Rapport d'inventaire Leader Pharma",

              files:[
                file
              ]
            });

            shared = true;
          }
        }

      }catch(error){

        if(
          error?.name ===
          "AbortError"
        ){

          toast(
            "Export annulé"
          );

          return;
        }

        console.warn(
          "R18 PARTAGE",
          error
        );
      }

      if(!shared){

        const url =
          URL.createObjectURL(
            blob
          );

        const link =
          document.createElement(
            "a"
          );

        link.href =
          url;

        link.download =
          filename;

        link.style.display =
          "none";

        document.body.appendChild(
          link
        );

        link.click();

        link.remove();

        setTimeout(
          function(){

            URL.revokeObjectURL(
              url
            );
          },
          3000
        );
      }

      try{

        audit(
          "Export",
          "Rapport inventaire CSV " +
          String(
            session.number ||
            ""
          )
        );

      }catch(e){}

      toast(
        shared
          ? "Rapport CSV prêt à partager"
          : "Rapport CSV exporté"
      );

    }catch(error){

      console.error(
        "R18 EXPORT CSV",
        error
      );

      toast(
        "Export CSV impossible"
      );

    }finally{

      if(button){
        button.disabled = false;
      }
    }
  }

  function lpR18Install(){

    if(
      typeof page !==
      "undefined"
      &&
      page !== "inventory"
    ){
      return;
    }

    const report =
      document.getElementById(
        "lpR16Report"
      );

    if(!report){
      return;
    }

    if(
      document.getElementById(
        "lpR18ExportWrap"
      )
    ){
      return;
    }

    const wrap =
      document.createElement(
        "div"
      );

    wrap.id =
      "lpR18ExportWrap";

    wrap.style.marginTop =
      "10px";

    wrap.innerHTML = `

      <button
        type="button"
        class="secondary"
        id="lpR18Export"
        style="
          width:100%;
          min-height:52px;
          font-weight:800;
        "
      >
        📊 Exporter le rapport CSV
      </button>

      <div
        class="muted"
        style="
          margin-top:7px;
          text-align:center;
        "
      >
        CSV UTF-8 • compatible tableur
      </div>
    `;

    const printWrap =
      document.getElementById(
        "lpR17PrintWrap"
      );

    if(
      printWrap &&
      printWrap.parentNode
    ){

      printWrap.insertAdjacentElement(
        "afterend",
        wrap
      );

    }else{

      report.appendChild(
        wrap
      );
    }

    document
      .getElementById(
        "lpR18Export"
      )
      .onclick =
        lpR18Export;
  }

  if(
    typeof inventory ===
    "function"
  ){

    const baseInventory =
      inventory;

    inventory =
      function(){

        const result =
          baseInventory.apply(
            this,
            arguments
          );

        setTimeout(
          lpR18Install,
          250
        );

        return result;
      };
  }

  document.addEventListener(
    "change",
    function(event){

      if(
        event.target?.id ===
        "lpR16SessionSelect"
      ){

        setTimeout(
          lpR18Install,
          250
        );
      }
    },
    false
  );

  setTimeout(
    lpR18Install,
    900
  );

  console.log(
    "LEADER PHARMA V1.5.18R18 EXPORT CSV INVENTAIRE ACTIF"
  );

})();

