/* LP_C10_COMPARATIF_FINANCIER_START */
(function(){

  function c10n(v){
    const n=Number(v||0);
    return Number.isFinite(n)?n:0;
  }

  function c10m(v){
    return new Intl.NumberFormat('fr-CD').format(
      Math.round(c10n(v))
    )+' FC';
  }

  function c10p(v){
    if(!Number.isFinite(v)){
      return '—';
    }

    return new Intl.NumberFormat(
      'fr-CD',
      {
        minimumFractionDigits:1,
        maximumFractionDigits:1
      }
    ).format(v)+' %';
  }

  function c10t(v){
    return String(v??'')
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'');
  }

  function c10dateOnly(v){

    if(!v)return '';

    const s=String(v);

    const iso=s.match(/^(\d{4}-\d{2}-\d{2})/);

    if(iso){
      return iso[1];
    }

    const d=new Date(v);

    if(Number.isNaN(d.getTime())){
      return '';
    }

    const y=d.getFullYear();
    const m=String(d.getMonth()+1).padStart(2,'0');
    const day=String(d.getDate()).padStart(2,'0');

    return `${y}-${m}-${day}`;
  }

  function c10ymd(d){

    const y=d.getFullYear();
    const m=String(d.getMonth()+1).padStart(2,'0');
    const day=String(d.getDate()).padStart(2,'0');

    return `${y}-${m}-${day}`;
  }

  function c10monthPeriods(){

    const now=new Date();

    const currentStart=
      new Date(
        now.getFullYear(),
        now.getMonth(),
        1
      );

    const currentEnd=
      new Date(
        now.getFullYear(),
        now.getMonth()+1,
        0
      );

    const previousStart=
      new Date(
        now.getFullYear(),
        now.getMonth()-1,
        1
      );

    const previousEnd=
      new Date(
        now.getFullYear(),
        now.getMonth(),
        0
      );

    return {
      current:{
        start:c10ymd(currentStart),
        end:c10ymd(currentEnd)
      },
      previous:{
        start:c10ymd(previousStart),
        end:c10ymd(previousEnd)
      }
    };
  }

  function c10inPeriod(v,start,end){

    const d=c10dateOnly(v);

    if(!d)return false;

    return (
      d>=start &&
      d<=end
    );
  }

  function c10summary(start,end){

    const sales=(db.sales||[])
      .filter(x=>
        String(x.agency||'')===String(currentAgency||'') &&
        c10t(x.status)!=='annulee' &&
        c10inPeriod(x.date,start,end)
      );

    const purchases=(db.purchases||[])
      .filter(x=>
        String(x.agency||'')===String(currentAgency||'') &&
        c10inPeriod(x.date,start,end)
      );

    const expenses=(db.expenses||[])
      .filter(x=>
        String(x.agency||'')===String(currentAgency||'') &&
        c10inPeriod(x.date,start,end)
      );

    const ca=sales.reduce(
      (s,x)=>s+c10n(x.total),
      0
    );

    const achats=purchases.reduce(
      (s,x)=>s+c10n(x.total),
      0
    );

    const charges=expenses.reduce(
      (s,x)=>s+c10n(x.amount),
      0
    );

    const encaissements=sales
      .filter(x=>!c10t(x.payment).includes('credit'))
      .reduce(
        (s,x)=>s+c10n(x.total),
        0
      );

    const paiementsAchats=purchases
      .filter(x=>!c10t(x.payment).includes('credit'))
      .reduce(
        (s,x)=>s+c10n(x.total),
        0
      );

    const resultat=
      ca-
      achats-
      charges;

    const fluxNet=
      encaissements-
      paiementsAchats-
      charges;

    return {
      ca,
      achats,
      charges,
      resultat,
      fluxNet,
      ventes:sales.length,
      nbAchats:purchases.length,
      nbDepenses:expenses.length
    };
  }

  function c10variation(current,previous){

    const diff=
      c10n(current)-
      c10n(previous);

    let pct=null;

    if(previous!==0){
      pct=(diff/Math.abs(previous))*100;
    }else if(current===0){
      pct=0;
    }

    return {
      diff,
      pct
    };
  }

  function c10trend(v){

    if(v>0){
      return '⬆️';
    }

    if(v<0){
      return '⬇️';
    }

    return '➡️';
  }

  function c10row(label,current,previous){

    const v=
      c10variation(
        current,
        previous
      );

    return `
      <tr>
        <td>
          <b>${label}</b>
        </td>

        <td>
          ${c10m(previous)}
        </td>

        <td>
          ${c10m(current)}
        </td>

        <td>
          <b>
            ${c10trend(v.diff)}
            ${c10m(v.diff)}
          </b>
        </td>

        <td>
          <b>
            ${v.pct===null?'N/A':c10p(v.pct)}
          </b>
        </td>
      </tr>
    `;
  }

  function c10install(){

    const content=
      document.getElementById('content');

    if(!content)return;

    document.getElementById(
      'lpC10FinancialComparison'
    )?.remove();

    const periods=
      c10monthPeriods();

    const current=
      c10summary(
        periods.current.start,
        periods.current.end
      );

    const previous=
      c10summary(
        periods.previous.start,
        periods.previous.end
      );

    const caVar=
      c10variation(
        current.ca,
        previous.ca
      );

    const resultVar=
      c10variation(
        current.resultat,
        previous.resultat
      );

    const flowVar=
      c10variation(
        current.fluxNet,
        previous.fluxNet
      );

    const expenseVar=
      c10variation(
        current.charges,
        previous.charges
      );

    const panel=
      document.createElement('div');

    panel.id=
      'lpC10FinancialComparison';

    panel.className=
      'card';

    panel.style.marginTop=
      '16px';

    panel.innerHTML=`

      <div
        class="section-title"
        style="gap:12px;flex-wrap:wrap"
      >

        <div>

          <h3>
            📊 Comparatif financier mensuel
          </h3>

          <div class="muted">
            C10 • Mois courant • Mois précédent • Évolution
          </div>

        </div>

      </div>


      <div
        class="card"
        style="margin-top:16px"
      >

        <h4>
          🗓️ Périodes comparées
        </h4>

        <div
          style="
            display:grid;
            grid-template-columns:1fr auto;
            gap:12px;
            margin-top:12px
          "
        >

          <div>
            Mois précédent
          </div>

          <b>
            ${periods.previous.start}
            →
            ${periods.previous.end}
          </b>


          <div>
            Mois courant
          </div>

          <b>
            ${periods.current.start}
            →
            ${periods.current.end}
          </b>

        </div>

      </div>


      <div
        class="grid kpis"
        style="margin-top:14px"
      >

        <div class="card kpi">

          <div class="label">
            💵 Évolution CA
          </div>

          <div class="value">
            ${c10trend(caVar.diff)}
            ${caVar.pct===null?'N/A':c10p(caVar.pct)}
          </div>

          <small class="muted">
            ${c10m(caVar.diff)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            📈 Évolution résultat
          </div>

          <div class="value">
            ${c10trend(resultVar.diff)}
            ${resultVar.pct===null?'N/A':c10p(resultVar.pct)}
          </div>

          <small class="muted">
            ${c10m(resultVar.diff)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            💰 Évolution flux net
          </div>

          <div class="value">
            ${c10trend(flowVar.diff)}
            ${flowVar.pct===null?'N/A':c10p(flowVar.pct)}
          </div>

          <small class="muted">
            ${c10m(flowVar.diff)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            🧾 Évolution charges
          </div>

          <div class="value">
            ${c10trend(expenseVar.diff)}
            ${expenseVar.pct===null?'N/A':c10p(expenseVar.pct)}
          </div>

          <small class="muted">
            ${c10m(expenseVar.diff)}
          </small>

        </div>

      </div>


      <h4
        style="margin-top:22px"
      >
        ⚖️ Tableau comparatif
      </h4>


      <div
        style="
          overflow:auto;
          margin-top:10px
        "
      >

        <table
          style="
            min-width:850px;
            width:100%
          "
        >

          <thead>

            <tr>
              <th>Indicateur</th>
              <th>Mois précédent</th>
              <th>Mois courant</th>
              <th>Écart</th>
              <th>Variation</th>
            </tr>

          </thead>

          <tbody>

            ${c10row(
              "Chiffre d'affaires",
              current.ca,
              previous.ca
            )}

            ${c10row(
              "Achats",
              current.achats,
              previous.achats
            )}

            ${c10row(
              "Charges",
              current.charges,
              previous.charges
            )}

            ${c10row(
              "Résultat",
              current.resultat,
              previous.resultat
            )}

            ${c10row(
              "Flux net",
              current.fluxNet,
              previous.fluxNet
            )}

          </tbody>

        </table>

      </div>


      <div
        class="card"
        style="margin-top:18px"
      >

        <h4>
          📋 Activité comparée
        </h4>

        <div
          style="
            display:grid;
            grid-template-columns:1fr auto auto;
            gap:12px;
            margin-top:14px
          "
        >

          <b>
            Indicateur
          </b>

          <b>
            Précédent
          </b>

          <b>
            Courant
          </b>


          <div>
            Nombre de ventes
          </div>

          <b>
            ${previous.ventes}
          </b>

          <b>
            ${current.ventes}
          </b>


          <div>
            Nombre d'achats
          </div>

          <b>
            ${previous.nbAchats}
          </b>

          <b>
            ${current.nbAchats}
          </b>


          <div>
            Nombre de dépenses
          </div>

          <b>
            ${previous.nbDepenses}
          </b>

          <b>
            ${current.nbDepenses}
          </b>

        </div>

      </div>


      <div
        class="card"
        style="margin-top:18px"
      >

        <h4>
          🧠 Lecture automatique
        </h4>

        <p
          style="margin-top:12px"
        >

          ${
            caVar.diff>0
            ? '✅ Le chiffre d’affaires progresse par rapport au mois précédent.'
            : caVar.diff<0
            ? '⚠️ Le chiffre d’affaires diminue par rapport au mois précédent.'
            : '➡️ Le chiffre d’affaires est stable.'
          }

        </p>

        <p>

          ${
            resultVar.diff>0
            ? '✅ Le résultat financier s’améliore.'
            : resultVar.diff<0
            ? '⚠️ Le résultat financier recule.'
            : '➡️ Le résultat financier est stable.'
          }

        </p>

        <p>

          ${
            flowVar.diff>0
            ? '✅ Le flux net de trésorerie s’améliore.'
            : flowVar.diff<0
            ? '⚠️ Le flux net de trésorerie diminue.'
            : '➡️ Le flux net de trésorerie est stable.'
          }

        </p>

      </div>


      <p
        class="muted"
        style="margin-top:14px"
      >
        C10 compare automatiquement les données
        du mois courant avec celles du mois précédent.

        Fonctionnement en lecture seule :
        aucune vente, aucun achat, aucune dépense,
        aucun produit et aucun stock ne sont modifiés.
      </p>

    `;

    content.appendChild(panel);

  }


  if(typeof accounting==='function'){

    const c10BaseAccounting=
      accounting;

    accounting=function(){

      const r=
        c10BaseAccounting.apply(
          this,
          arguments
        );

      setTimeout(
        c10install,
        420
      );

      return r;

    };

  }


  console.log(
    'LEADER PHARMA C10 COMPARATIF FINANCIER MENSUEL ACTIF'
  );

})();
