/* LP_C11_BUDGET_PREVISIONS_START */
(function(){

  function c11n(v){
    const n=Number(v||0);
    return Number.isFinite(n)?n:0;
  }

  function c11m(v){
    return new Intl.NumberFormat('fr-CD').format(
      Math.round(c11n(v))
    )+' FC';
  }

  function c11p(v){
    return new Intl.NumberFormat(
      'fr-CD',
      {
        minimumFractionDigits:1,
        maximumFractionDigits:1
      }
    ).format(c11n(v))+' %';
  }

  function c11t(v){
    return String(v??'')
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'');
  }

  function c11date(v){

    if(!v)return null;

    const d=new Date(v);

    if(Number.isNaN(d.getTime())){
      return null;
    }

    return d;
  }

  function c11monthKey(v){

    const d=c11date(v);

    if(!d)return '';

    return (
      d.getFullYear()+
      '-'+
      String(d.getMonth()+1).padStart(2,'0')
    );
  }

  function c11monthLabel(key){

    if(!key)return '—';

    const parts=key.split('-');

    const y=Number(parts[0]);
    const m=Number(parts[1])-1;

    const d=new Date(y,m,1);

    return d.toLocaleDateString(
      'fr-CD',
      {
        month:'long',
        year:'numeric'
      }
    );
  }

  function c11nextMonthLabel(){

    const d=new Date();

    const n=new Date(
      d.getFullYear(),
      d.getMonth()+1,
      1
    );

    return n.toLocaleDateString(
      'fr-CD',
      {
        month:'long',
        year:'numeric'
      }
    );
  }

  function c11validAgency(x){

    return (
      String(x.agency||'')===
      String(currentAgency||'')
    );
  }

  function c11monthlyData(){

    const map={};

    function ensure(key){

      if(!key)return null;

      if(!map[key]){
        map[key]={
          month:key,
          sales:0,
          purchases:0,
          expenses:0,
          cashIn:0,
          cashOut:0
        };
      }

      return map[key];
    }

    (db.sales||[])
      .filter(x=>
        c11validAgency(x) &&
        c11t(x.status)!=='annulee'
      )
      .forEach(x=>{

        const key=
          c11monthKey(x.date);

        const row=
          ensure(key);

        if(!row)return;

        const amount=
          c11n(x.total);

        row.sales+=amount;

        if(!c11t(x.payment).includes('credit')){
          row.cashIn+=amount;
        }

      });

    (db.purchases||[])
      .filter(c11validAgency)
      .forEach(x=>{

        const key=
          c11monthKey(x.date);

        const row=
          ensure(key);

        if(!row)return;

        const amount=
          c11n(x.total);

        row.purchases+=amount;

        if(!c11t(x.payment).includes('credit')){
          row.cashOut+=amount;
        }

      });

    (db.expenses||[])
      .filter(c11validAgency)
      .forEach(x=>{

        const key=
          c11monthKey(x.date);

        const row=
          ensure(key);

        if(!row)return;

        const amount=
          c11n(x.amount);

        row.expenses+=amount;
        row.cashOut+=amount;

      });

    return Object.values(map)
      .map(x=>({
        ...x,
        result:
          x.sales-
          x.purchases-
          x.expenses,
        cashFlow:
          x.cashIn-
          x.cashOut
      }))
      .sort(
        (a,b)=>
          String(a.month)
            .localeCompare(
              String(b.month)
            )
      );
  }

  function c11average(rows,field){

    if(!rows.length)return 0;

    return rows.reduce(
      (s,x)=>s+c11n(x[field]),
      0
    )/rows.length;
  }

  function c11trend(rows,field){

    if(rows.length<2){
      return 0;
    }

    const last=
      c11n(
        rows[rows.length-1][field]
      );

    const previous=
      c11n(
        rows[rows.length-2][field]
      );

    if(previous===0){
      return 0;
    }

    return (
      (last-previous)/
      Math.abs(previous)
    )*100;
  }

  function c11projection(avg,trend){

    let factor=
      1+(trend/100);

    if(factor<0){
      factor=0;
    }

    if(factor>2){
      factor=2;
    }

    return avg*factor;
  }

  function c11install(){

    const content=
      document.getElementById('content');

    if(!content)return;

    document.getElementById(
      'lpC11BudgetForecast'
    )?.remove();

    const allMonths=
      c11monthlyData();

    const history=
      allMonths.slice(-6);

    const avgSales=
      c11average(
        history,
        'sales'
      );

    const avgPurchases=
      c11average(
        history,
        'purchases'
      );

    const avgExpenses=
      c11average(
        history,
        'expenses'
      );

    const avgCashFlow=
      c11average(
        history,
        'cashFlow'
      );

    const salesTrend=
      c11trend(
        history,
        'sales'
      );

    const purchaseTrend=
      c11trend(
        history,
        'purchases'
      );

    const expenseTrend=
      c11trend(
        history,
        'expenses'
      );

    const projectedSales=
      c11projection(
        avgSales,
        salesTrend
      );

    const projectedPurchases=
      c11projection(
        avgPurchases,
        purchaseTrend
      );

    const projectedExpenses=
      c11projection(
        avgExpenses,
        expenseTrend
      );

    const projectedResult=
      projectedSales-
      projectedPurchases-
      projectedExpenses;

    const projectedCashFlow=
      c11projection(
        avgCashFlow,
        salesTrend
      );

    const projectedMargin=
      projectedSales>0
      ? (
          projectedResult/
          projectedSales
        )*100
      : 0;

    const historyBody=
      history.length
      ? history.slice().reverse().map(x=>`

          <tr>

            <td>
              <b>
                ${c11monthLabel(x.month)}
              </b>
            </td>

            <td>
              ${c11m(x.sales)}
            </td>

            <td>
              ${c11m(x.purchases)}
            </td>

            <td>
              ${c11m(x.expenses)}
            </td>

            <td>
              <b>
                ${c11m(x.result)}
              </b>
            </td>

            <td>
              ${c11m(x.cashFlow)}
            </td>

          </tr>

        `).join('')
      : `
          <tr>
            <td colspan="6" class="muted">
              Historique mensuel insuffisant
            </td>
          </tr>
        `;

    const panel=
      document.createElement('div');

    panel.id=
      'lpC11BudgetForecast';

    panel.className=
      'card';

    panel.style.marginTop=
      '16px';

    panel.innerHTML=`

      <div
        class="section-title"
        style="gap:12px;flex-wrap:wrap"
      >

        <div>

          <h3>
            🎯 Budget & Prévisions financières
          </h3>

          <div class="muted">
            C11 • Historique • Moyennes • Projection automatique
          </div>

        </div>

      </div>


      <div
        class="card"
        style="margin-top:16px"
      >

        <h4>
          🔮 Prévision
          ${c11nextMonthLabel()}
        </h4>

        <p
          class="muted"
          style="margin-top:8px"
        >
          Projection indicative calculée à partir
          des derniers mois disponibles.
        </p>

      </div>


      <div
        class="grid kpis"
        style="margin-top:14px"
      >

        <div class="card kpi">

          <div class="label">
            💵 CA prévisionnel
          </div>

          <div class="value">
            ${c11m(projectedSales)}
          </div>

          <small class="muted">
            Tendance :
            ${c11p(salesTrend)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            📦 Achats prévisionnels
          </div>

          <div class="value">
            ${c11m(projectedPurchases)}
          </div>

          <small class="muted">
            Tendance :
            ${c11p(purchaseTrend)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            🧾 Charges prévisionnelles
          </div>

          <div class="value">
            ${c11m(projectedExpenses)}
          </div>

          <small class="muted">
            Tendance :
            ${c11p(expenseTrend)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            📈 Résultat prévisionnel
          </div>

          <div class="value">
            ${c11m(projectedResult)}
          </div>

          <small class="muted">
            Marge indicative :
            ${c11p(projectedMargin)}
          </small>

        </div>


        <div class="card kpi">

          <div class="label">
            💰 Flux de trésorerie prévisionnel
          </div>

          <div class="value">
            ${c11m(projectedCashFlow)}
          </div>

          <small class="muted">
            ${
              projectedCashFlow>=0
              ? '✅ Positif'
              : '⚠️ Négatif'
            }
          </small>

        </div>

      </div>


      <div
        class="card"
        style="margin-top:18px"
      >

        <h4>
          📊 Budget moyen mensuel
        </h4>

        <div
          style="
            display:grid;
            grid-template-columns:1fr auto;
            gap:12px;
            margin-top:14px
          "
        >

          <div>
            CA moyen
          </div>

          <b>
            ${c11m(avgSales)}
          </b>


          <div>
            Achats moyens
          </div>

          <b>
            ${c11m(avgPurchases)}
          </b>


          <div>
            Charges moyennes
          </div>

          <b>
            ${c11m(avgExpenses)}
          </b>


          <div>
            Flux net moyen
          </div>

          <b>
            ${c11m(avgCashFlow)}
          </b>

        </div>

      </div>


      <h4
        style="margin-top:22px"
      >
        📅 Historique financier utilisé
      </h4>


      <div
        style="
          overflow:auto;
          margin-top:10px
        "
      >

        <table
          style="
            min-width:900px;
            width:100%
          "
        >

          <thead>

            <tr>
              <th>Mois</th>
              <th>CA</th>
              <th>Achats</th>
              <th>Charges</th>
              <th>Résultat</th>
              <th>Flux net</th>
            </tr>

          </thead>

          <tbody>
            ${historyBody}
          </tbody>

        </table>

      </div>


      <div
        class="card"
        style="margin-top:18px"
      >

        <h4>
          🧠 Lecture prévisionnelle
        </h4>

        <p style="margin-top:12px">

          ${
            salesTrend>0
            ? '✅ La tendance récente du chiffre d’affaires est positive.'
            : salesTrend<0
            ? '⚠️ La tendance récente du chiffre d’affaires est en baisse.'
            : '➡️ La tendance du chiffre d’affaires est stable ou l’historique est encore insuffisant.'
          }

        </p>

        <p>

          ${
            projectedResult>=0
            ? '✅ Le résultat prévisionnel simplifié reste positif.'
            : '⚠️ Le résultat prévisionnel simplifié est négatif.'
          }

        </p>

        <p>

          ${
            projectedCashFlow>=0
            ? '✅ La projection de trésorerie reste positive.'
            : '⚠️ La projection signale un besoin potentiel de trésorerie.'
          }

        </p>

      </div>


      <p
        class="muted"
        style="margin-top:14px"
      >
        C11 fournit des prévisions internes
        indicatives à partir de l'historique existant.
        Elles constituent une aide à la gestion
        et non une garantie de résultat futur.

        Fonctionnement en lecture seule :
        aucune vente, aucun achat, aucune dépense,
        aucun produit et aucun stock ne sont modifiés.
      </p>

    `;

    content.appendChild(panel);

  }


  if(typeof accounting==='function'){

    const c11BaseAccounting=
      accounting;

    accounting=function(){

      const r=
        c11BaseAccounting.apply(
          this,
          arguments
        );

      setTimeout(
        c11install,
        460
      );

      return r;

    };

  }


  console.log(
    'LEADER PHARMA C11 BUDGET PREVISIONS FINANCIERES ACTIF'
  );

})();
