  /*
   * FIX PRINCIPAL :
   * plusieurs tentatives après le rendu.
   * Ainsi C23 n'est plus dépendant d'un
   * seul délai de 620 ms.
   */

  function c23Schedule(){

    [
      150,
      350,
      650,
      1000,
      1500,
      2200,
      3200
    ].forEach(delay=>{

      setTimeout(
        c23Install,
        delay
      );

    });

  }

