  async function lp29f3ExportCSV(){

    const csv=
      lp29f3CSV();

    const filename=
      lp29f3Filename();

    const blob=
      new Blob(
        [csv],
        {
          type:
            'text/csv;charset=utf-8'
        }
      );

    try{

      if(
        typeof File!=='undefined' &&
        navigator.share
      ){

        const file=
          new File(
            [blob],
            filename,
            {
              type:
                'text/csv'
            }
          );

        const shareData={
          title:
            'Rapport DG Leader Pharma',
          text:
            'Rapport exécutif DG Leader Pharma',
          files:[
            file
          ]
        };

        let allowed=true;

        if(
          navigator.canShare
        ){
          allowed=
            navigator.canShare(
              shareData
            );
        }

        if(allowed){

          await navigator.share(
            shareData
          );

          lp29f3Status(
            'Rapport CSV créé. Partage Android ouvert.',
            true
          );

          return;
        }

      }

    }
    catch(e){

      console.log(
        'LP C29 FIX3 SHARE',
        e
      );
    }

    try{

      const url=
        URL.createObjectURL(
          blob
        );

      const link=
        document.createElement(
          'a'
        );

      link.href=url;

      link.download=
        filename;

      link.style.display=
        'none';

      document.body
        .appendChild(
          link
        );

      link.click();

      setTimeout(()=>{

        link.remove();

        URL.revokeObjectURL(
          url
        );

      },3000);

      lp29f3Status(
        'Rapport CSV créé. Téléchargement demandé à Android.',
        true
      );

      return;

    }
    catch(e){

      console.log(
        'LP C29 FIX3 DOWNLOAD',
        e
      );
    }

    lp29f3PreviewCSV();
  }

