/* LP_C29_FIX6_IMPRESSION_ANDROID_PDF_START */
(function(){

  function f6s(v){
    return String(v ?? '');
  }

  function f6norm(v){
    return f6s(v)
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'');
  }

  function f6Status(message, ok){

    const preview =
      document.getElementById(
        'lpC29Fix5PdfPreview'
      );

    if(!preview){
      return;
    }

    let box =
      document.getElementById(
        'lpC29Fix6PrintStatus'
      );

    if(!box){

      box =
        document.createElement(
          'div'
        );

      box.id =
        'lpC29Fix6PrintStatus';

      box.style.width =
        'min(100%,794px)';

      box.style.margin =
        '12px auto';

      box.style.background =
        '#ffffff';

      box.style.borderRadius =
        '14px';

      box.style.padding =
        '16px';

      box.style.boxSizing =
        'border-box';

      box.style.textAlign =
        'center';

      box.style.fontWeight =
        '800';

      const actions =
        document.getElementById(
          'lpC29Fix5Actions'
        );

      if(actions){

        actions.insertAdjacentElement(
          'beforebegin',
          box
        );

      }else{

        preview.appendChild(
          box
        );
      }
    }

    box.innerHTML =
      (ok ? '✅ ' : '⚠️ ') +
      message;
  }

  function f6Prepare(){

    const preview =
      document.getElementById(
        'lpC29Fix5PdfPreview'
      );

    if(!preview){

      if(
        typeof window.lpC29Fix5Preview ===
        'function'
      ){

        window.lpC29Fix5Preview();

      }

      return false;
    }

    document.body.classList.add(
      'lp-c29-fix5-print'
    );

    return true;
  }

  async function f6NativeBridge(){

    try{

      if(
        window.AndroidPrint &&
        typeof window.AndroidPrint.print ===
        'function'
      ){

        f6Status(
          "Ouverture de l'impression Android...",
          true
        );

        window.AndroidPrint.print();

        return true;
      }

    }catch(e){}

    try{

      if(
        window.AndroidPrint &&
        typeof window.AndroidPrint.printPage ===
        'function'
      ){

        f6Status(
          "Ouverture de l'impression Android...",
          true
        );

        window.AndroidPrint.printPage();

        return true;
      }

    }catch(e){}

    try{

      if(
        window.Android &&
        typeof window.Android.printPage ===
        'function'
      ){

        f6Status(
          "Ouverture de l'impression Android...",
          true
        );

        window.Android.printPage();

        return true;
      }

    }catch(e){}

    return false;
  }

  async function f6Capacitor(){

    try{

      if(
        !window.Capacitor ||
        !window.Capacitor.Plugins
      ){
        return false;
      }

      const plugins =
        window.Capacitor.Plugins;

      const candidates = [
        plugins.Print,
        plugins.Printer,
        plugins.PrintService,
        plugins.AndroidPrint
      ];

      for(const plugin of candidates){

        if(!plugin){
          continue;
        }

        if(
          typeof plugin.print ===
          'function'
        ){

          f6Status(
            "Ouverture de l'impression Android...",
            true
          );

          await plugin.print();

          return true;
        }

        if(
          typeof plugin.printPage ===
          'function'
        ){

          f6Status(
            "Ouverture de l'impression Android...",
            true
          );

          await plugin.printPage();

          return true;
        }
      }

    }catch(e){

      console.log(
        'FIX6 CAPACITOR PRINT',
        e
      );

    }

    return false;
  }

  async function f6Print(){

    if(!f6Prepare()){

      setTimeout(
        f6Print,
        350
      );

      return false;
    }

    /*
     * IMPORTANT
     *
     * FIX6 concerne uniquement
     * le rapport A4 / PDF C29.
     *
     * Aucune fonction ticket,
     * vente, facture ou impression
     * thermique Z91 n'est remplacee.
     */

    f6Status(
      "Préparation du rapport A4...",
      true
    );

    const nativeDone =
      await f6NativeBridge();

    if(nativeDone){
      return false;
    }

    const capacitorDone =
      await f6Capacitor();

    if(capacitorDone){
      return false;
    }

    try{

      if(
        typeof window.print ===
        'function'
      ){

        f6Status(
          "Ouverture impression / Enregistrer PDF...",
          true
        );

        setTimeout(
          function(){

            try{

              window.focus();

              window.print();

            }catch(e){

              console.log(
                'FIX6 WINDOW PRINT',
                e
              );

              f6Status(
                "Le WebView bloque l'impression système.",
                false
              );

            }

          },
          200
        );

        return false;
      }

    }catch(e){}

    f6Status(
      "Service d'impression Android indisponible.",
      false
    );

    return false;
  }

  window.lpC29Fix6Print =
    f6Print;

  window.lpC29Fix5Print =
    f6Print;

  function f6Install(){

    const preview =
      document.getElementById(
        'lpC29Fix5PdfPreview'
      );

    if(!preview){
      return false;
    }

    const buttons =
      Array.from(
        preview.querySelectorAll(
          'button'
        )
      );

    const printButton =
      buttons.find(
        b => {

          const text =
            f6norm(
              b.textContent
            );

          return (
            text.includes(
              'imprimer / enregistrer en pdf'
            ) ||
            text.includes(
              'ouvrir impression / enregistrer pdf'
            )
          );

        }
      );

    if(!printButton){
      return false;
    }

    if(
      printButton.dataset.lpFix6 ===
      '1'
    ){
      return true;
    }

    printButton.onclick =
      function(e){

        if(e){

          e.preventDefault();

          e.stopPropagation();

        }

        f6Print();

        return false;
      };

    printButton.setAttribute(
      'onclick',
      'return window.lpC29Fix6Print(event);'
    );

    printButton.innerHTML =
      '🖨️ Ouvrir impression / Enregistrer PDF';

    printButton.dataset.lpFix6 =
      '1';

    return true;
  }

  function f6Schedule(){

    [
      100,
      250,
      500,
      900,
      1500,
      2400,
      3600
    ].forEach(
      delay =>
        setTimeout(
          f6Install,
          delay
        )
    );
  }

  f6Schedule();

  let timer = null;

  const observer =
    new MutationObserver(
      function(){

        clearTimeout(
          timer
        );

        timer =
          setTimeout(
            f6Install,
            80
          );

      }
    );

  function start(){

    if(!document.body){

      setTimeout(
        start,
        300
      );

      return;
    }

    observer.observe(
      document.body,
      {
        childList:true,
        subtree:true
      }
    );

    f6Schedule();
  }

  if(
    document.readyState ===
    'loading'
  ){

    document.addEventListener(
      'DOMContentLoaded',
      start,
      {
        once:true
      }
    );

  }else{

    start();

  }

  console.log(
    'LEADER PHARMA C29 FIX6 IMPRESSION ANDROID PDF ACTIF'
  );

})();
/* LP_C29_FIX6_IMPRESSION_ANDROID_PDF_END */


