/* LP_TRESORERIE_DG_FIX6_END */


/* ==========================================================
   LEADER PHARMA MANAGER PRO
   FIX7 ORGANISATION RUBRIQUES
   
   COMPTABILITE :
   - retirer seulement Caisse & Tresorerie
   
   TRESORERIE :
   - garder Tresorerie & caisse
   - garder Synthese Tresorerie & caisse
   - retirer Comparaison comptable
   - retirer Synthese comptable
   
   AUCUNE FONCTION METIER MODIFIEE
   ========================================================== */

/* LP_FIX7_ORGANISATION_RUBRIQUES_START */

(function(){

  const LP_FIX7_MARKER =
    'LEADER PHARMA FIX7 ORGANISATION COMPTABILITE TRESORERIE ACTIF';

  function lpFix7Norm(v){

    try{

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(
          /[\u0300-\u036f]/g,
          ''
        );

    }
    catch(e){

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase();

    }

  }

  function lpFix7Visible(el){

    if(!el){
      return false;
    }

    try{

      const style =
        window.getComputedStyle(el);

      if(
        style.display === 'none'
        ||
        style.visibility === 'hidden'
      ){
        return false;
      }

    }
    catch(e){}

    return true;

  }

  function lpFix7ExactText(
    el
  ){

    return lpFix7Norm(
      el.innerText
      ||
      el.textContent
      ||
      ''
    );

  }

  function lpFix7FindSection(
    names
  ){

    const wanted =
      names.map(
        lpFix7Norm
      );

    const candidates =
      Array.from(
        document.querySelectorAll(
          'nav,aside,section,div,ul'
        )
      );

    let best = null;

    for(
      const el
      of candidates
    ){

      if(
        !lpFix7Visible(el)
      ){
        continue;
      }

      const text =
        lpFix7ExactText(el);

      if(!text){
        continue;
      }

      const hasTitle =
        wanted.some(
          function(name){

            return (
              text === name
              ||
              text.startsWith(
                name + ' '
              )
              ||
              text.includes(
                ' ' + name + ' '
              )
            );

          }
        );

      if(!hasTitle){
        continue;
      }

      const links =
        el.querySelectorAll(
          'a,button,[role="button"],li'
        ).length;

      if(
        links === 0
      ){
        continue;
      }

      if(
        !best
        ||
        text.length
        <
        best.textLength
      ){

        best = {
          element:el,
          textLength:text.length
        };

      }

    }

    return best
      ? best.element
      : null;

  }

  function lpFix7FindMenuItem(
    section,
    labels
  ){

    if(!section){
      return null;
    }

    const wanted =
      labels.map(
        lpFix7Norm
      );

    const nodes =
      Array.from(
        section.querySelectorAll(
          'a,button,[role="button"],li,div'
        )
      );

    let best = null;

    for(
      const el
      of nodes
    ){

      if(
        !lpFix7Visible(el)
      ){
        continue;
      }

      const text =
        lpFix7ExactText(el);

      if(
        !wanted.includes(text)
      ){
        continue;
      }

      if(
        !best
        ||
        el.children.length
        <
        best.children
      ){

        best = {
          element:el,
          children:el.children.length
        };

      }

    }

    return best
      ? best.element
      : null;

  }

  function lpFix7HideItem(
    section,
    labels
  ){

    const item =
      lpFix7FindMenuItem(
        section,
        labels
      );

    if(!item){
      return false;
    }

    /*
     * On ne supprime pas le code,
     * la route ni la fonction.
     * On masque uniquement l'entrée
     * qui se trouve dans la mauvaise
     * rubrique.
     */

    item.style.setProperty(
      'display',
      'none',
      'important'
    );

    item.setAttribute(
      'data-lp-fix7-hidden',
      '1'
    );

    return true;

  }

  function lpFix7ProtectItem(
    section,
    labels
  ){

    const item =
      lpFix7FindMenuItem(
        section,
        labels
      );

    if(!item){
      return false;
    }

    /*
     * Ces deux entrées doivent rester
     * visibles dans TRESORERIE.
     */

    if(
      item.getAttribute(
        'data-lp-fix7-hidden'
      )
      ===
      '1'
    ){

      item.style.removeProperty(
        'display'
      );

      item.removeAttribute(
        'data-lp-fix7-hidden'
      );

    }

    return true;

  }

  function lpFix7Apply(){

    const accounting =
      lpFix7FindSection([
        'Comptabilité',
        'Comptabilite'
      ]);

    const treasury =
      lpFix7FindSection([
        'Trésorerie',
        'Tresorerie'
      ]);

    if(accounting){

      /*
       * COMPTABILITE
       *
       * Retirer uniquement :
       * Caisse & Trésorerie
       */

      lpFix7HideItem(
        accounting,
        [
          'Caisse & Trésorerie',
          'Caisse et Trésorerie',
          'Caisse & Tresorerie',
          'Caisse et Tresorerie'
        ]
      );

    }

    if(treasury){

      /*
       * TRESORERIE
       *
       * Retirer uniquement les deux
       * éléments comptables placés ici
       * par erreur.
       */

      lpFix7HideItem(
        treasury,
        [
          'Comparaison comptable'
        ]
      );

      lpFix7HideItem(
        treasury,
        [
          'Synthèse comptable',
          'Synthese comptable',
          'Synthèse finale Comptabilité',
          'Synthese finale Comptabilite'
        ]
      );

      /*
       * Protéger les deux rubriques
       * qui doivent rester ici.
       */

      lpFix7ProtectItem(
        treasury,
        [
          'Trésorerie & caisse',
          'Trésorerie et caisse',
          'Tresorerie & caisse',
          'Tresorerie et caisse'
        ]
      );

      lpFix7ProtectItem(
        treasury,
        [
          'Synthèse Trésorerie & caisse',
          'Synthèse Trésorerie et caisse',
          'Synthese Tresorerie & caisse',
          'Synthese Tresorerie et caisse',
          'Synthèse Trésorerie DG',
          'Synthese Tresorerie DG'
        ]
      );

    }

    return true;

  }

  window.lpFix7OrganisationRubriques =
    lpFix7Apply;

  /*
   * Application après navigation.
   */

  setTimeout(
    lpFix7Apply,
    250
  );

  setTimeout(
    lpFix7Apply,
    700
  );

  setTimeout(
    lpFix7Apply,
    1500
  );

  document.addEventListener(
    'click',
    function(){

      setTimeout(
        lpFix7Apply,
        100
      );

      setTimeout(
        lpFix7Apply,
        400
      );

    },
    true
  );

  /*
   * Si le menu est reconstruit,
   * on réapplique uniquement
   * l'organisation visuelle.
   */

  try{

    const observer =
      new MutationObserver(
        function(){

          setTimeout(
            lpFix7Apply,
            50
          );

        }
      );

    observer.observe(
      document.documentElement,
      {
        childList:true,
        subtree:true
      }
    );

  }
  catch(e){}

  console.log(
    LP_FIX7_MARKER
  );

})();

