/* ==========================================================
   LEADER PHARMA MANAGER PRO
   FIX8
   RETIRER UNIQUEMENT "SYNTHESE COMPTABLE"
   DE LA PAGE TRESORERIE

   NE PAS TOUCHER A LA SYNTHESE COMPTABLE
   DE LA PAGE COMPTABILITE
   ========================================================== */

/* LP_FIX8_SYNTHESE_COMPTABLE_TRESORERIE_START */

(function(){

  const LP_FIX8_MARKER =
    'LEADER PHARMA FIX8 SYNTHESE COMPTABLE RETIREE DE TRESORERIE';

  function lpF8Norm(v){

    try{

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');

    }
    catch(e){

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase();

    }

  }

  function lpF8Visible(el){

    if(!el){
      return false;
    }

    try{

      const s =
        window.getComputedStyle(el);

      return (
        s.display !== 'none'
        &&
        s.visibility !== 'hidden'
      );

    }
    catch(e){

      return true;

    }

  }

  function lpF8Text(el){

    return lpF8Norm(
      el
      ?
      (
        el.innerText
        ||
        el.textContent
        ||
        ''
      )
      :
      ''
    );

  }

  function lpF8TreasuryActive(){

    /*
     * Chercher le vrai titre de page.
     * On privilégie les titres courts.
     */

    const titles =
      Array.from(
        document.querySelectorAll(
          'h1,h2,h3,h4,[role="heading"]'
        )
      );

    for(
      const el
      of titles
    ){

      if(!lpF8Visible(el)){
        continue;
      }

      const t =
        lpF8Text(el);

      if(
        t === 'tresorerie & caisse'
        ||
        t === 'tresorerie et caisse'
        ||
        t === 'tresorerie caisse'
      ){

        return true;

      }

    }

    /*
     * Deuxième contrôle :
     * page native avec Entrées + Sorties + Solde.
     */

    const mains =
      Array.from(
        document.querySelectorAll(
          'main,section,article'
        )
      );

    for(
      const el
      of mains
    ){

      if(!lpF8Visible(el)){
        continue;
      }

      const t =
        lpF8Text(el);

      if(
        t.includes('tresorerie')
        &&
        t.includes('caisse')
        &&
        t.includes('entrees')
        &&
        t.includes('sorties')
        &&
        t.includes('solde')
      ){

        return true;

      }

    }

    return false;

  }

  function lpF8IsExactSyntheseComptable(el){

    const t =
      lpF8Text(el);

    return (
      t === 'synthese comptable'
      ||
      t === 'synthese finale comptabilite'
    );

  }

  function lpF8HideTarget(el){

    if(!el){
      return false;
    }

    /*
     * Remonter uniquement vers le petit
     * bouton/carte/entrée correspondant.
     * Ne jamais supprimer un grand parent.
     */

    let target = el;

    for(
      let i = 0;
      i < 4 && target;
      i++
    ){

      const tag =
        String(
          target.tagName || ''
        )
        .toLowerCase();

      const role =
        String(
          target.getAttribute
          ?
          (
            target.getAttribute('role')
            ||
            ''
          )
          :
          ''
        )
        .toLowerCase();

      const text =
        lpF8Text(target);

      if(
        (
          tag === 'button'
          ||
          tag === 'a'
          ||
          tag === 'li'
          ||
          role === 'button'
        )
        &&
        (
          text === 'synthese comptable'
          ||
          text === 'synthese finale comptabilite'
        )
      ){

        target.style.setProperty(
          'display',
          'none',
          'important'
        );

        target.setAttribute(
          'data-lp-fix8-hidden',
          '1'
        );

        return true;

      }

      target =
        target.parentElement;

    }

    /*
     * Si le texte lui-même est l'élément
     * de menu/carte, masquer seulement lui.
     */

    el.style.setProperty(
      'display',
      'none',
      'important'
    );

    el.setAttribute(
      'data-lp-fix8-hidden',
      '1'
    );

    return true;

  }

  function lpF8RestoreOutsideTreasury(){

    /*
     * IMPORTANT :
     * Si l'utilisateur quitte Trésorerie,
     * on restaure uniquement les éléments
     * masqués par FIX8.
     *
     * Ainsi la Synthèse comptable reste
     * disponible dans Comptabilité.
     */

    const hidden =
      document.querySelectorAll(
        '[data-lp-fix8-hidden="1"]'
      );

    hidden.forEach(
      function(el){

        el.style.removeProperty(
          'display'
        );

        el.removeAttribute(
          'data-lp-fix8-hidden'
        );

      }
    );

  }

  function lpF8Apply(){

    if(
      !lpF8TreasuryActive()
    ){

      lpF8RestoreOutsideTreasury();

      return false;

    }

    const nodes =
      Array.from(
        document.querySelectorAll(
          'a,button,li,[role="button"],h1,h2,h3,h4,h5,h6,span,strong,p,div'
        )
      );

    let changed = false;

    for(
      const el
      of nodes
    ){

      if(!lpF8Visible(el)){
        continue;
      }

      if(
        !lpF8IsExactSyntheseComptable(el)
      ){
        continue;
      }

      /*
       * Ne jamais toucher à notre synthèse
       * Trésorerie.
       */

      if(
        el.closest
        &&
        (
          el.closest('#lpTreasuryDGFix6')
          ||
          el.closest(
            '[id*="TreasuryDG"]'
          )
        )
      ){
        continue;
      }

      lpF8HideTarget(el);

      changed = true;

    }

    return changed;

  }

  window.lpFix8RetirerSyntheseComptableTresorerie =
    lpF8Apply;

  setTimeout(
    lpF8Apply,
    100
  );

  setTimeout(
    lpF8Apply,
    300
  );

  setTimeout(
    lpF8Apply,
    700
  );

  setTimeout(
    lpF8Apply,
    1500
  );

  document.addEventListener(
    'click',
    function(){

      setTimeout(
        lpF8Apply,
        50
      );

      setTimeout(
        lpF8Apply,
        250
      );

      setTimeout(
        lpF8Apply,
        700
      );

    },
    true
  );

  try{

    const observer =
      new MutationObserver(
        function(){

          setTimeout(
            lpF8Apply,
            30
          );

        }
      );

    observer.observe(
      document.documentElement,
      {
        childList:true,
        subtree:true
      }
    );

  }
  catch(e){}

  console.log(
    LP_FIX8_MARKER
  );

})();

/* LP_FIX8_SYNTHESE_COMPTABLE_TRESORERIE_END */


/* ==========================================================
   LEADER PHARMA MANAGER PRO

   FIX9 RANGEMENT CIBLE

   COMPTABILITE
   - masquer uniquement Caisse & Tresorerie C2

   TRESORERIE
   - masquer uniquement Comparaison comptable C30
   - masquer uniquement Synthese finale Comptabilite C31

   AUCUNE DONNEE
   AUCUN CALCUL
   AUCUNE ROUTE
   AUCUN STOCK
   ========================================================== */

/* LP_FIX9_RANGEMENT_CIBLE_START */

(function(){

  const LP_FIX9_MARKER =
    'LEADER PHARMA FIX9 RANGEMENT CIBLE ACTIF';

  function lpF9Norm(v){

    try{

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(
          /[\u0300-\u036f]/g,
          ''
        );

    }
    catch(e){

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase();

    }

  }

  function lpF9Text(el){

    if(!el){
      return '';
    }

    return lpF9Norm(
      el.innerText
      ||
      el.textContent
      ||
      ''
    );

  }

  function lpF9Visible(el){

    if(!el){
      return false;
    }

    try{

      const cs =
        window.getComputedStyle(el);

      if(
        cs.display === 'none'
        ||
        cs.visibility === 'hidden'
      ){
        return false;
      }

      const r =
        el.getBoundingClientRect();

      return (
        r.width > 0
        &&
        r.height > 0
      );

    }
    catch(e){

      return true;

    }

  }

  function lpF9Restore(){

    document
      .querySelectorAll(
        '[data-lp-fix9-hidden="1"]'
      )
      .forEach(
        function(el){

          el.style.removeProperty(
            'display'
          );

          el.removeAttribute(
            'data-lp-fix9-hidden'
          );

        }
      );

  }

  function lpF9FindVisibleHeading(
    names
  ){

    const wanted =
      names.map(
        lpF9Norm
      );

    const els =
      Array.from(
        document.querySelectorAll(
          'h1,h2,h3,h4,[role="heading"]'
        )
      );

    for(
      const el
      of els
    ){

      if(
        !lpF9Visible(el)
      ){
        continue;
      }

      const t =
        lpF9Text(el);

      if(
        wanted.includes(t)
      ){
        return el;
      }

    }

    return null;

  }

  function lpF9FindPageFromHeading(
    heading,
    requiredWords
  ){

    if(!heading){
      return null;
    }

    let node =
      heading.parentElement;

    let best = null;

    for(
      let i = 0;
      i < 10 && node;
      i++
    ){

      const t =
        lpF9Text(node);

      const allPresent =
        requiredWords.every(
          function(word){

            return t.includes(
              lpF9Norm(word)
            );

          }
        );

      if(allPresent){

        best = node;

        if(
          node.tagName === 'MAIN'
          ||
          node.tagName === 'SECTION'
          ||
          node.tagName === 'ARTICLE'
        ){
          break;
        }

      }

      node =
        node.parentElement;

    }

    return best;

  }

  function lpF9TreasuryPage(){

    const heading =
      lpF9FindVisibleHeading([
        'Trésorerie & caisse',
        'Trésorerie et caisse',
        'Tresorerie & caisse',
        'Tresorerie et caisse'
      ]);

    if(!heading){
      return null;
    }

    return (
      lpF9FindPageFromHeading(
        heading,
        [
          'Entrées',
          'Sorties',
          'Solde'
        ]
      )
      ||
      heading.parentElement
    );

  }

  function lpF9AccountingPage(){

    const heading =
      lpF9FindVisibleHeading([
        'Comptabilité',
        'Comptabilite'
      ]);

    if(!heading){
      return null;
    }

    return (
      lpF9FindPageFromHeading(
        heading,
        [
          'comptable'
        ]
      )
      ||
      heading.parentElement
    );

  }

  function lpF9BestCard(
    root,
    mustHave,
    optional
  ){

    if(!root){
      return null;
    }

    const must =
      mustHave.map(
        lpF9Norm
      );

    const opt =
      optional.map(
        lpF9Norm
      );

    const candidates =
      Array.from(
        root.querySelectorAll(
          'section,article,div,li'
        )
      );

    let best = null;

    for(
      const el
      of candidates
    ){

      if(
        !lpF9Visible(el)
      ){
        continue;
      }

      if(
        el.closest(
          '[data-lp-fix9-hidden="1"]'
        )
      ){
        continue;
      }

      const raw =
        String(
          el.innerText
          ||
          el.textContent
          ||
          ''
        )
        .trim();

      if(!raw){
        continue;
      }

      const t =
        lpF9Norm(raw);

      const hasAll =
        must.every(
          function(word){

            return t.includes(word);

          }
        );

      if(!hasAll){
        continue;
      }

      if(
        opt.length
        &&
        !opt.some(
          function(word){

            return t.includes(word);

          }
        )
      ){
        continue;
      }

      /*
       * On exclut les très gros conteneurs.
       * Une carte ciblée doit rester compacte.
       */

      if(
        raw.length > 3500
      ){
        continue;
      }

      const score =
        raw.length;

      if(
        !best
        ||
        score < best.score
      ){

        best = {
          element:el,
          score:score
        };

      }

    }

    return best
      ? best.element
      : null;

  }

  function lpF9Hide(el){

    if(!el){
      return false;
    }

    el.style.setProperty(
      'display',
      'none',
      'important'
    );

    el.setAttribute(
      'data-lp-fix9-hidden',
      '1'
    );

    return true;

  }

  function lpF9Apply(){

    lpF9Restore();

    /*
     * =====================================
     * PAGE TRESORERIE
     * =====================================
     */

    const treasury =
      lpF9TreasuryPage();

    if(treasury){

      /*
       * C30 Comparaison comptable
       */

      const c30 =
        lpF9BestCard(
          treasury,
          [
            'comparaison comptable'
          ],
          [
            'c30',
            'deux périodes',
            'deux periodes'
          ]
        );

      lpF9Hide(c30);

      /*
       * C31 Synthèse finale Comptabilité
       */

      const c31 =
        lpF9BestCard(
          treasury,
          [
            'synthèse finale comptabilité'
          ],
          [
            'c31',
            'tableau de pilotage comptable',
            'score'
          ]
        )
        ||
        lpF9BestCard(
          treasury,
          [
            'synthese finale comptabilite'
          ],
          [
            'c31',
            'tableau de pilotage comptable',
            'score'
          ]
        );

      lpF9Hide(c31);

      /*
       * Ne rien faire d'autre sur Trésorerie.
       */

      return true;

    }

    /*
     * =====================================
     * PAGE COMPTABILITE
     * =====================================
     */

    const accounting =
      lpF9AccountingPage();

    if(accounting){

      /*
       * C2 Caisse & Trésorerie
       */

      const c2 =
        lpF9BestCard(
          accounting,
          [
            'caisse',
            'trésorerie'
          ],
          [
            'c2',
            'entrées',
            'entrees',
            'sorties',
            'soldes automatiques'
          ]
        )
        ||
        lpF9BestCard(
          accounting,
          [
            'caisse',
            'tresorerie'
          ],
          [
            'c2',
            'entrees',
            'sorties',
            'soldes automatiques'
          ]
        );

      lpF9Hide(c2);

      return true;

    }

    return false;

  }

  window.lpFix9RangementCible =
    lpF9Apply;

  setTimeout(
    lpF9Apply,
    150
  );

  setTimeout(
    lpF9Apply,
    400
  );

  setTimeout(
    lpF9Apply,
    900
  );

  setTimeout(
    lpF9Apply,
    1600
  );

  document.addEventListener(
    'click',
    function(){

      setTimeout(
        lpF9Apply,
        100
      );

      setTimeout(
        lpF9Apply,
        350
      );

      setTimeout(
        lpF9Apply,
        800
      );

    },
    true
  );

  /*
   * Certaines pages sont recréées
   * après navigation.
   */

  try{

    const observer =
      new MutationObserver(
        function(){

          setTimeout(
            lpF9Apply,
            60
          );

        }
      );

    observer.observe(
      document.documentElement,
      {
        childList:true,
        subtree:true
      }
    );

  }
  catch(e){}

  console.log(
    LP_FIX9_MARKER
  );

})();

/* LP_FIX9_RANGEMENT_CIBLE_END */


/* ==========================================================
   LEADER PHARMA MANAGER PRO
   FIX10 TRESORERIE FINALE

   UNIQUEMENT RUBRIQUE TRESORERIE

   AJOUT :
   - Tresorerie caisse nette
   - Synthese de la tresorerie

   MASQUER DANS TRESORERIE :
   - Comparaison comptable C30
   - Synthese finale Comptabilite C31

   COMPTABILITE = INTOUCHABLE
   DONNEES = LECTURE SEULE
   ========================================================== */

/* LP_FIX10_TRESORERIE_FINALE_START */

(function(){

  const LP10_MARKER =
    'LEADER PHARMA FIX10 TRESORERIE FINALE ACTIF';

  let lp10Timer = null;

  function lp10Norm(v){

    try{

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');

    }catch(e){

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase();

    }

  }

  function lp10Text(el){

    if(!el){
      return '';
    }

    return lp10Norm(
      el.innerText ||
      el.textContent ||
      ''
    );

  }

  function lp10Visible(el){

    if(!el){
      return false;
    }

    try{

      const style =
        window.getComputedStyle(el);

      if(
        style.display === 'none' ||
        style.visibility === 'hidden'
      ){
        return false;
      }

      const r =
        el.getBoundingClientRect();

      return (
        r.width > 0 &&
        r.height > 0
      );

    }catch(e){

      return true;

    }

  }

  function lp10MoneyNumber(v){

    let s =
      String(v || '')
        .replace(/\s/g,'')
        .replace(/FC/gi,'')
        .replace(/CDF/gi,'')
        .replace(/[^0-9,.\-]/g,'');

    if(
      s.includes(',') &&
      !s.includes('.')
    ){
      s = s.replace(/,/g,'.');
    }else{
      s = s.replace(/,/g,'');
    }

    const n = Number(s);

    return Number.isFinite(n)
      ? n
      : 0;

  }

  function lp10Money(v){

    const n =
      Number.isFinite(Number(v))
        ? Number(v)
        : 0;

    try{

      return (
        new Intl.NumberFormat(
          'fr-CD',
          {
            maximumFractionDigits:0
          }
        ).format(Math.round(n))
        + ' FC'
      );

    }catch(e){

      return Math.round(n) + ' FC';

    }

  }

  function lp10Pct(v){

    const n = Number(v);

    if(!Number.isFinite(n)){
      return '0,0 %';
    }

    try{

      return (
        n.toLocaleString(
          'fr-CD',
          {
            minimumFractionDigits:1,
            maximumFractionDigits:1
          }
        )
        + ' %'
      );

    }catch(e){

      return n.toFixed(1) + ' %';

    }

  }

  function lp10Page(){

    const headings =
      Array.from(
        document.querySelectorAll(
          'h1,h2,h3,h4,[role="heading"]'
        )
      );

    let heading = null;

    for(const el of headings){

      if(!lp10Visible(el)){
        continue;
      }

      const t = lp10Text(el);

      if(
        t === 'tresorerie & caisse' ||
        t === 'tresorerie et caisse'
      ){
        heading = el;
        break;
      }

    }

    if(!heading){
      return null;
    }

    let node =
      heading.parentElement;

    let best = null;

    for(
      let i = 0;
      i < 10 && node;
      i++
    ){

      const t = lp10Text(node);

      if(
        t.includes('entrees') &&
        t.includes('sorties') &&
        t.includes('solde')
      ){

        best = node;

        if(
          node.tagName === 'MAIN' ||
          node.tagName === 'SECTION' ||
          node.tagName === 'ARTICLE'
        ){
          break;
        }

      }

      node = node.parentElement;

    }

    return best || heading.parentElement;

  }

  function lp10Restore(){

    document
      .querySelectorAll(
        '[data-lp-fix10-hidden="1"]'
      )
      .forEach(function(el){

        el.style.removeProperty('display');

        el.removeAttribute(
          'data-lp-fix10-hidden'
        );

      });

  }

  function lp10HideCard(
    page,
    required
  ){

    const wanted =
      required.map(lp10Norm);

    const all =
      Array.from(
        page.querySelectorAll(
          'section,article,div'
        )
      );

    let best = null;

    for(const el of all){

      if(
        el.id === 'lpFix10Treasury' ||
        el.closest('#lpFix10Treasury')
      ){
        continue;
      }

      const raw =
        String(
          el.innerText ||
          el.textContent ||
          ''
        ).trim();

      if(!raw){
        continue;
      }

      if(raw.length > 3500){
        continue;
      }

      const t =
        lp10Norm(raw);

      const ok =
        wanted.every(function(x){
          return t.includes(x);
        });

      if(!ok){
        continue;
      }

      if(
        !best ||
        raw.length < best.length
      ){

        best = {
          el:el,
          length:raw.length
        };

      }

    }

    if(best){

      best.el.style.setProperty(
        'display',
        'none',
        'important'
      );

      best.el.setAttribute(
        'data-lp-fix10-hidden',
        '1'
      );

      return true;

    }

    return false;

  }

  function lp10ReadAmount(
    page,
    label
  ){

    const wanted =
      lp10Norm(label);

    const els =
      Array.from(
        page.querySelectorAll(
          'div,section,article,p,span,strong,b'
        )
      );

    let best = null;

    for(const el of els){

      if(
        el.id === 'lpFix10Treasury' ||
        el.closest('#lpFix10Treasury')
      ){
        continue;
      }

      const raw =
        String(
          el.innerText ||
          el.textContent ||
          ''
        ).trim();

      if(!raw){
        continue;
      }

      const t =
        lp10Norm(raw);

      if(!t.includes(wanted)){
        continue;
      }

      const labelCount =
        [
          'entrees',
          'sorties',
          'solde'
        ].filter(function(x){
          return t.includes(x);
        }).length;

      if(labelCount !== 1){
        continue;
      }

      const match =
        raw.match(
          /(-?[0-9][0-9\s.,]*)\s*(?:FC|CDF)/i
        );

      if(!match){
        continue;
      }

      if(
        !best ||
        raw.length < best.length
      ){

        best = {
          length:raw.length,
          value:lp10MoneyNumber(
            match[1]
          )
        };

      }

    }

    if(!best){

      return {
        found:false,
        value:0
      };

    }

    return {
      found:true,
      value:best.value
    };

  }

  function lp10SmallCard(
    title,
    value,
    subtitle
  ){

    return `
      <div style="
        border:1px solid #e5e7eb;
        border-radius:16px;
        padding:15px;
        background:#fff;
        box-sizing:border-box;
        min-width:0;
      ">

        <div style="
          font-size:13px;
          font-weight:800;
          color:#64748b;
        ">
          ${title}
        </div>

        <div style="
          margin-top:7px;
          font-size:21px;
          font-weight:900;
          color:#17212b;
        ">
          ${value}
        </div>

        <div style="
          margin-top:5px;
          font-size:12px;
          color:#64748b;
        ">
          ${subtitle}
        </div>

      </div>
    `;

  }

  function lp10Insert(
    page,
    box
  ){

    const table =
      Array.from(
        page.querySelectorAll('table')
      ).find(function(el){

        const t = lp10Text(el);

        return (
          t.includes('date') &&
          t.includes('type') &&
          (
            t.includes('montant') ||
            t.includes('description')
          )
        );

      });

    if(
      table &&
      table.parentNode
    ){

      let target = table;

      if(
        table.parentElement &&
        table.parentElement !== page
      ){
        target = table.parentElement;
      }

      if(target.parentNode){

        target.parentNode.insertBefore(
          box,
          target
        );

        return;

      }

    }

    page.appendChild(box);

  }

  function lp10Render(){

    const page =
      lp10Page();

    if(!page){

      lp10Restore();
      return false;

    }

    lp10Restore();

    /*
     * Masquer uniquement les deux
     * modules comptables mal placés
     * dans la rubrique Trésorerie.
     */

    lp10HideCard(
      page,
      [
        'comparaison comptable',
        'c30'
      ]
    );

    lp10HideCard(
      page,
      [
        'synthese finale comptabilite',
        'c31'
      ]
    );

    const entree =
      lp10ReadAmount(
        page,
        'Entrées'
      );

    const sortie =
      lp10ReadAmount(
        page,
        'Sorties'
      );

    const solde =
      lp10ReadAmount(
        page,
        'Solde'
      );

    let box =
      document.getElementById(
        'lpFix10Treasury'
      );

    if(!box){

      box =
        document.createElement(
          'section'
        );

      box.id =
        'lpFix10Treasury';

      lp10Insert(
        page,
        box
      );

    }

    if(
      !entree.found ||
      !sortie.found ||
      !solde.found
    ){

      box.innerHTML = `
        <div style="
          margin:20px 0;
          padding:18px;
          border:1px solid #e5e7eb;
          border-radius:20px;
          background:#fff;
        ">

          <div style="
            font-size:22px;
            font-weight:900;
          ">
            💰 Trésorerie caisse nette
          </div>

          <div style="
            margin-top:9px;
            color:#64748b;
          ">
            Lecture des valeurs de trésorerie…
          </div>

        </div>
      `;

      return false;

    }

    const entrees =
      entree.value;

    const sorties =
      sortie.value;

    const soldeDisponible =
      solde.value;

    const caisseNette =
      entrees - sorties;

    const poidsSorties =
      entrees > 0
        ? (sorties / entrees) * 100
        : 0;

    const disponibilite =
      entrees > 0
        ? (soldeDisponible / entrees) * 100
        : 0;

    let etat = 'SAINE';

    let commentaire =
      'La trésorerie disponible reste positive.';

    if(soldeDisponible < 0){

      etat = 'TENSION';

      commentaire =
        'La trésorerie est négative. Une action est nécessaire.';

    }else if(
      entrees > 0 &&
      poidsSorties >= 80
    ){

      etat = 'À SURVEILLER';

      commentaire =
        'Les sorties représentent une part élevée des entrées.';

    }

    const signature =
      [
        entrees,
        sorties,
        soldeDisponible,
        caisseNette,
        etat
      ].join('|');

    if(
      box.getAttribute(
        'data-lp-signature'
      ) === signature
    ){
      return true;
    }

    box.setAttribute(
      'data-lp-signature',
      signature
    );

    box.innerHTML = `

      <div style="
        margin:20px 0;
        padding:18px;
        border:1px solid #e5e7eb;
        border-radius:20px;
        background:#fff;
      ">

        <div style="
          font-size:23px;
          font-weight:900;
          color:#17212b;
        ">
          💰 Trésorerie caisse nette
        </div>

        <div style="
          margin-top:4px;
          font-size:14px;
          color:#64748b;
        ">
          Position nette de la caisse
        </div>

        <div style="
          display:grid;
          grid-template-columns:repeat(2,minmax(0,1fr));
          gap:10px;
          margin-top:15px;
        ">

          ${lp10SmallCard(
            '📥 Entrées',
            lp10Money(entrees),
            'Mouvements entrants'
          )}

          ${lp10SmallCard(
            '📤 Sorties',
            lp10Money(sorties),
            'Mouvements sortants'
          )}

          ${lp10SmallCard(
            '💵 Caisse nette',
            lp10Money(caisseNette),
            'Entrées - Sorties'
          )}

          ${lp10SmallCard(
            '🏦 Solde disponible',
            lp10Money(soldeDisponible),
            'Solde actuel'
          )}

        </div>

      </div>

      <div style="
        margin:20px 0;
        padding:18px;
        border:1px solid #e5e7eb;
        border-radius:20px;
        background:#fff;
      ">

        <div style="
          font-size:23px;
          font-weight:900;
          color:#17212b;
        ">
          📊 Synthèse de la trésorerie
        </div>

        <div style="
          margin-top:4px;
          font-size:14px;
          color:#64748b;
        ">
          Vue rapide de la situation de trésorerie
        </div>

        <div style="
          margin-top:15px;
          padding:16px;
          border-radius:16px;
          background:#f8fafc;
          text-align:center;
        ">

          <div style="
            font-size:13px;
            font-weight:800;
            color:#64748b;
          ">
            SITUATION DE TRÉSORERIE
          </div>

          <div style="
            margin-top:7px;
            font-size:26px;
            font-weight:900;
          ">
            ${etat}
          </div>

        </div>

        <div style="
          display:grid;
          grid-template-columns:repeat(2,minmax(0,1fr));
          gap:10px;
          margin-top:14px;
        ">

          ${lp10SmallCard(
            '📊 Poids des sorties',
            lp10Pct(poidsSorties),
            'Sorties / Entrées'
          )}

          ${lp10SmallCard(
            '💚 Disponibilité',
            lp10Pct(disponibilite),
            'Solde / Entrées'
          )}

          ${lp10SmallCard(
            '💰 Solde disponible',
            lp10Money(soldeDisponible),
            'Liquidité actuelle'
          )}

          ${lp10SmallCard(
            '🧮 Caisse nette',
            lp10Money(caisseNette),
            'Entrées - Sorties'
          )}

        </div>

        <div style="
          margin-top:14px;
          padding:14px;
          border:1px solid #e5e7eb;
          border-radius:15px;
          line-height:1.5;
          font-weight:700;
        ">
          ${commentaire}
        </div>

        <button
          id="lpFix10Refresh"
          type="button"
          style="
            width:100%;
            margin-top:15px;
            padding:14px;
            border:0;
            border-radius:14px;
            background:#11795e;
            color:#fff;
            font-size:16px;
            font-weight:900;
          "
        >
          🔄 Actualiser la trésorerie
        </button>

        <div style="
          margin-top:11px;
          font-size:12px;
          color:#64748b;
        ">
          Leader Pharma Manager Pro • Lecture seule
        </div>

      </div>
    `;

    const refresh =
      document.getElementById(
        'lpFix10Refresh'
      );

    if(refresh){

      refresh.onclick =
        function(){

          box.removeAttribute(
            'data-lp-signature'
          );

          lp10Render();

        };

    }

    return true;

  }

  function lp10Schedule(){

    if(lp10Timer){
      clearTimeout(lp10Timer);
    }

    lp10Timer =
      setTimeout(
        lp10Render,
        120
      );

  }

  window.lpFix10TreasuryRender =
    lp10Render;

  setTimeout(lp10Render,200);
  setTimeout(lp10Render,600);
  setTimeout(lp10Render,1200);

  document.addEventListener(
    'click',
    function(){

      lp10Schedule();

    },
    true
  );

  try{

    const observer =
      new MutationObserver(
        function(){

          lp10Schedule();

        }
      );

    observer.observe(
      document.documentElement,
      {
        childList:true,
        subtree:true
      }
    );

  }catch(e){}

  console.log(LP10_MARKER);

})();

/* LP_FIX10_TRESORERIE_FINALE_END */


/* ==========================================================
   LEADER PHARMA MANAGER PRO
   FIX11 NETTOYAGE TRESORERIE

   CORRECTION UNIQUEMENT DANS TRESORERIE

   A MASQUER :
   - C30 Comparaison comptable entre deux periodes
   - C31 Synthese finale Comptabilite

   A CONSERVER :
   - Tresorerie & caisse
   - Tresorerie caisse nette
   - Synthese de la tresorerie

   COMPTABILITE = INTOUCHABLE
   ========================================================== */

/* LP_FIX11_NETTOYAGE_TRESORERIE_START */

(function(){

  const MARKER =
    'LEADER PHARMA FIX11 NETTOYAGE TRESORERIE ACTIF';

  let timer = null;

  function norm(v){

    try{

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');

    }catch(e){

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase();

    }

  }

  function text(el){

    return norm(
      el
        ? (
            el.innerText ||
            el.textContent ||
            ''
          )
        : ''
    );

  }

  function visible(el){

    if(!el){
      return false;
    }

    try{

      const s =
        window.getComputedStyle(el);

      if(
        s.display === 'none' ||
        s.visibility === 'hidden' ||
        s.opacity === '0'
      ){
        return false;
      }

      const r =
        el.getBoundingClientRect();

      return (
        r.width > 0 &&
        r.height > 0
      );

    }catch(e){

      return true;

    }

  }

  /*
   * CSS FIX11 indépendant de FIX10.
   * Même si FIX10 retire son propre style,
   * FIX11 reste appliqué.
   */

  function installStyle(){

    if(
      document.getElementById(
        'lpFix11Style'
      )
    ){
      return;
    }

    const style =
      document.createElement('style');

    style.id =
      'lpFix11Style';

    style.textContent = `
      [data-lp-fix11-hide="1"] {
        display:none !important;
        visibility:hidden !important;
      }
    `;

    document.head.appendChild(style);

  }

  function restore(){

    document
      .querySelectorAll(
        '[data-lp-fix11-hide="1"]'
      )
      .forEach(function(el){

        el.removeAttribute(
          'data-lp-fix11-hide'
        );

      });

  }

  /*
   * Vérifie que la vraie page
   * Trésorerie & caisse est visible.
   */

  function treasuryActive(){

    const headings =
      Array.from(
        document.querySelectorAll(
          'h1,h2,h3,h4,h5,h6,[role="heading"]'
        )
      );

    for(const el of headings){

      if(!visible(el)){
        continue;
      }

      const t =
        text(el);

      if(
        t === 'tresorerie & caisse' ||
        t === 'tresorerie et caisse'
      ){

        return true;

      }

    }

    return false;

  }

  /*
   * Cherche la RACINE complète du module.
   *
   * On ne se limite plus au petit conteneur
   * autour du titre Trésorerie.
   */

  function findModule(required){

    const wanted =
      required.map(norm);

    const candidates =
      Array.from(
        document.querySelectorAll(
          'section,article,main,div'
        )
      );

    let best = null;

    for(const el of candidates){

      if(!visible(el)){
        continue;
      }

      if(
        el.id === 'lpFix10Treasury' ||
        (
          el.closest &&
          el.closest('#lpFix10Treasury')
        )
      ){
        continue;
      }

      const raw =
        String(
          el.innerText ||
          el.textContent ||
          ''
        ).trim();

      if(!raw){
        continue;
      }

      /*
       * Éviter BODY / écran complet.
       */

      if(raw.length > 10000){
        continue;
      }

      const t =
        norm(raw);

      const ok =
        wanted.every(function(x){
          return t.includes(x);
        });

      if(!ok){
        continue;
      }

      /*
       * On choisit le plus petit conteneur
       * contenant toute la signature du module.
       */

      if(
        !best ||
        raw.length < best.length
      ){

        best = {
          el:el,
          length:raw.length
        };

      }

    }

    return best
      ? best.el
      : null;

  }

  function hide(el){

    if(!el){
      return false;
    }

    el.setAttribute(
      'data-lp-fix11-hide',
      '1'
    );

    return true;

  }

  function apply(){

    installStyle();

    /*
     * Toujours restaurer d'abord.
     * Si on est dans Comptabilité,
     * aucun C30/C31 ne reste masqué.
     */

    restore();

    if(!treasuryActive()){
      return false;
    }

    /*
     * =====================================
     * C30
     * Signature forte :
     * - Comparaison comptable
     * - C30
     * - Période A
     * - Période B
     * - Comparer les deux périodes
     * =====================================
     */

    const c30 =
      findModule([
        'comparaison comptable',
        'c30',
        'période a',
        'période b',
        'comparer les deux périodes'
      ])
      ||
      findModule([
        'comparaison comptable',
        'c30',
        'periode a',
        'periode b'
      ]);

    hide(c30);

    /*
     * =====================================
     * C31
     * Signature forte :
     * - Synthèse finale Comptabilité
     * - C31
     * - Score de pilotage
     * - Situation comptable
     * =====================================
     */

    const c31 =
      findModule([
        'synthèse finale comptabilité',
        'c31',
        'score de pilotage',
        'situation comptable'
      ])
      ||
      findModule([
        'synthese finale comptabilite',
        'c31',
        'score de pilotage',
        'situation comptable'
      ]);

    hide(c31);

    return true;

  }

  function schedule(){

    if(timer){
      clearTimeout(timer);
    }

    timer =
      setTimeout(
        apply,
        120
      );

  }

  window.lpFix11NettoyageTresorerie =
    apply;

  /*
   * Appliquer après FIX10.
   */

  setTimeout(apply,300);
  setTimeout(apply,700);
  setTimeout(apply,1300);
  setTimeout(apply,2200);

  document.addEventListener(
    'click',
    function(){

      setTimeout(apply,150);
      setTimeout(apply,450);
      setTimeout(apply,900);

    },
    true
  );

  try{

    const observer =
      new MutationObserver(
        function(){

          schedule();

        }
      );

    observer.observe(
      document.documentElement,
      {
        childList:true,
        subtree:true
      }
    );

  }catch(e){}

  console.log(MARKER);

})();

/* LP_FIX11_NETTOYAGE_TRESORERIE_END */


/* ==========================================================
   LEADER PHARMA MANAGER PRO
   FIX13 TRESORERIE DIRECTE

   BASE = FIX11

   UNIQUEMENT RUBRIQUE TRESORERIE

   AJOUT :
   - Caisse et trésorerie automatique
   - Synthèse trésorerie

   DETECTION :
   - Entrées
   - Sorties
   - Solde
   - contenu natif de la vraie page trésorerie

   AUCUNE DEPENDANCE H1/H2/H3
   LECTURE SEULE
   ========================================================== */

/* LP_FIX13_TRESORERIE_DIRECTE_START */

(function(){

  const LP13_MARKER =
    'LEADER PHARMA FIX13 TRESORERIE DIRECTE ACTIF';

  let lp13Timer = null;

  function lp13Norm(v){

    try{

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');

    }catch(e){

      return String(v || '')
        .replace(/\s+/g,' ')
        .trim()
        .toLowerCase();

    }

  }

  function lp13Text(el){

    if(!el){
      return '';
    }

    return lp13Norm(
      el.innerText ||
      el.textContent ||
      ''
    );

  }

  function lp13Visible(el){

    if(!el){
      return false;
    }

    try{

      const s =
        window.getComputedStyle(el);

      if(
        s.display === 'none' ||
        s.visibility === 'hidden'
      ){
        return false;
      }

      const r =
        el.getBoundingClientRect();

      return (
        r.width > 0 &&
        r.height > 0
      );

    }catch(e){

      return true;

    }

  }

  function lp13MoneyNumber(v){

    let s =
      String(v || '')
        .replace(/\s/g,'')
        .replace(/CDF/gi,'')
        .replace(/FC/gi,'')
        .replace(/[^0-9,.\-]/g,'');

    if(
      s.includes(',') &&
      !s.includes('.')
    ){

      s = s.replace(/,/g,'.');

    }else{

      s = s.replace(/,/g,'');

    }

    const n = Number(s);

    return Number.isFinite(n)
      ? n
      : 0;

  }

  function lp13Money(v){

    const n =
      Number.isFinite(Number(v))
        ? Number(v)
        : 0;

    try{

      return (
        new Intl.NumberFormat(
          'fr-CD',
          {
            maximumFractionDigits:0
          }
        ).format(Math.round(n))
        + ' FC'
      );

    }catch(e){

      return Math.round(n) + ' FC';

    }

  }

  function lp13Pct(v){

    const n = Number(v);

    if(!Number.isFinite(n)){
      return '0,0 %';
    }

    try{

      return (
        n.toLocaleString(
          'fr-CD',
          {
            minimumFractionDigits:1,
            maximumFractionDigits:1
          }
        )
        + ' %'
      );

    }catch(e){

      return n.toFixed(1) + ' %';

    }

  }

  /*
   * ==========================================
   * TROUVER LE VRAI TITRE, QUELLE QUE SOIT
   * SA BALISE HTML
   * ==========================================
   */

  function lp13FindTitle(){

    const all =
      Array.from(
        document.querySelectorAll(
          'div,span,p,strong,b,label,' +
          'header,section,article,' +
          'h1,h2,h3,h4,h5,h6'
        )
      );

    let best = null;

    for(const el of all){

      if(!lp13Visible(el)){
        continue;
      }

      if(
        el.closest &&
        (
          el.closest('#lpFix10Treasury') ||
          el.closest('#lpFix13Treasury')
        )
      ){
        continue;
      }

      const raw =
        String(
          el.innerText ||
          el.textContent ||
          ''
        ).trim();

      const t =
        lp13Norm(raw);

      if(
        t !== 'tresorerie & caisse' &&
        t !== 'tresorerie et caisse'
      ){
        continue;
      }

      if(
        !best ||
        raw.length < best.raw.length
      ){

        best = {
          el:el,
          raw:raw
        };

      }

    }

    return best
      ? best.el
      : null;

  }

  /*
   * ==========================================
   * DETECTION DE LA PAGE PAR CONTENU NATIF
   * ==========================================
   */

  function lp13FindPage(){

    const title =
      lp13FindTitle();

    /*
     * Première méthode :
     * partir du vrai titre trouvé.
     */

    if(title){

      let node =
        title.parentElement;

      let best =
        title.parentElement;

      for(
        let i = 0;
        i < 15 && node;
        i++
      ){

        const t =
          lp13Text(node);

        if(
          t.includes('entrees') &&
          t.includes('sorties') &&
          t.includes('solde')
        ){

          best = node;

        }

        if(
          node.tagName === 'MAIN'
        ){

          best = node;
          break;

        }

        node =
          node.parentElement;

      }

      if(best){
        return best;
      }

    }

    /*
     * Deuxième méthode :
     * recherche directe d'un conteneur visible
     * avec Entrées + Sorties + Solde.
     */

    const candidates =
      Array.from(
        document.querySelectorAll(
          'main,section,article,div'
        )
      );

    let winner = null;

    for(const el of candidates){

      if(!lp13Visible(el)){
        continue;
      }

      if(
        el.id === 'lpFix10Treasury' ||
        el.id === 'lpFix13Treasury'
      ){
        continue;
      }

      if(
        el.closest &&
        (
          el.closest('#lpFix10Treasury') ||
          el.closest('#lpFix13Treasury')
        )
      ){
        continue;
      }

      const raw =
        String(
          el.innerText ||
          el.textContent ||
          ''
        ).trim();

      if(
        !raw ||
        raw.length > 20000
      ){
        continue;
      }

      const t =
        lp13Norm(raw);

      if(
        !t.includes('entrees') ||
        !t.includes('sorties') ||
        !t.includes('solde')
      ){
        continue;
      }

      /*
       * Renforcer la reconnaissance avec
       * des éléments réels de la trésorerie.
       */

      const hasTreasurySignal =
        t.includes('tresorerie') ||
        t.includes('sauvegarder') ||
        t.includes('restaurer') ||
        (
          t.includes('date') &&
          t.includes('type') &&
          t.includes('montant')
        );

      if(!hasTreasurySignal){
        continue;
      }

      if(
        !winner ||
        raw.length < winner.length
      ){

        winner = {
          el:el,
          length:raw.length
        };

      }

    }

    return winner
      ? winner.el
      : null;

  }

  /*
   * ==========================================
   * LECTURE DES TROIS CARTES NATIVES
   * ==========================================
   */

  function lp13ReadAmount(
    page,
    label
  ){

    const wanted =
      lp13Norm(label);

    const all =
      Array.from(
        page.querySelectorAll(
          'div,section,article,' +
          'p,span,strong,b'
        )
      );

    let best = null;

    for(const el of all){

      if(!lp13Visible(el)){
        continue;
      }

      if(
        el.closest &&
        (
          el.closest('#lpFix10Treasury') ||
          el.closest('#lpFix13Treasury')
        )
      ){
        continue;
      }

      if(
        el.hasAttribute &&
        el.hasAttribute(
          'data-lp-fix11-hide'
        )
      ){
        continue;
      }

      const raw =
        String(
          el.innerText ||
          el.textContent ||
          ''
        ).trim();

      if(!raw){
        continue;
      }

      if(raw.length > 500){
        continue;
      }

      const t =
        lp13Norm(raw);

      if(!t.includes(wanted)){
        continue;
      }

      /*
       * Une carte native ne doit pas mélanger
       * les trois libellés.
       */

      const count =
        [
          'entrees',
          'sorties',
          'solde'
        ]
        .filter(function(x){
          return t.includes(x);
        })
        .length;

      if(count !== 1){
        continue;
      }

      const m =
        raw.match(
          /(-?[0-9][0-9\s.,]*)\s*(?:FC|CDF)/i
        );

      if(!m){
        continue;
      }

      const value =
        lp13MoneyNumber(
          m[1]
        );

      if(
        !best ||
        raw.length < best.length
      ){

        best = {
          value:value,
          length:raw.length
        };

      }

    }

    if(!best){

      return {
        found:false,
        value:0
      };

    }

    return {
      found:true,
      value:best.value
    };

  }

  function lp13Card(
    title,
    value,
    subtitle
  ){

    return `
      <div style="
        border:1px solid #e5e7eb;
        border-radius:16px;
        background:#ffffff;
        padding:15px;
        box-sizing:border-box;
        min-width:0;
      ">

        <div style="
          font-size:13px;
          font-weight:800;
          color:#64748b;
        ">
          ${title}
        </div>

        <div style="
          margin-top:7px;
          font-size:21px;
          font-weight:900;
          color:#17212b;
          overflow-wrap:anywhere;
        ">
          ${value}
        </div>

        <div style="
          margin-top:5px;
          font-size:12px;
          color:#64748b;
        ">
          ${subtitle}
        </div>

      </div>
    `;

  }

  /*
   * ==========================================
   * PLACER AVANT LE JOURNAL DES MOUVEMENTS
   * ==========================================
   */

  function lp13Insert(
    page,
    box
  ){

    const tables =
      Array.from(
        page.querySelectorAll(
          'table'
        )
      );

    for(const table of tables){

      const t =
        lp13Text(table);

      if(
        t.includes('date') &&
        t.includes('type') &&
        (
          t.includes('montant') ||
          t.includes('description')
        )
      ){

        let target = table;

        if(
          table.parentElement &&
          table.parentElement !== page
        ){
          target =
            table.parentElement;
        }

        if(target.parentNode){

          target.parentNode.insertBefore(
            box,
            target
          );

          return;

        }

      }

    }

    /*
     * Sinon placer après FIX10 s'il existe.
     */

    const old =
      document.getElementById(
        'lpFix10Treasury'
      );

    if(
      old &&
      old.parentNode
    ){

      old.parentNode.insertBefore(
        box,
        old.nextSibling
      );

      return;

    }

    page.appendChild(box);

  }

  function lp13Render(){

    const page =
      lp13FindPage();

    let box =
      document.getElementById(
        'lpFix13Treasury'
      );

    if(!page){

      if(box){
        box.style.display = 'none';
      }

      return false;

    }

    const entree =
      lp13ReadAmount(
        page,
        'Entrées'
      );

    const sortie =
      lp13ReadAmount(
        page,
        'Sorties'
      );

    const solde =
      lp13ReadAmount(
        page,
        'Solde'
      );

    if(!box){

      box =
        document.createElement(
          'section'
        );

      box.id =
        'lpFix13Treasury';

      lp13Insert(
        page,
        box
      );

    }

    box.style.display = '';

    /*
     * Ne pas afficher de faux zéros
     * si les vraies cartes n'ont pas
     * encore été détectées.
     */

    if(
      !entree.found ||
      !sortie.found ||
      !solde.found
    ){

      box.innerHTML = `
        <div style="
          margin:20px 0;
          padding:18px;
          border:1px solid #e5e7eb;
          border-radius:20px;
          background:#ffffff;
        ">

          <div style="
            font-size:22px;
            font-weight:900;
            color:#17212b;
          ">
            💰 Caisse et trésorerie automatique
          </div>

          <div style="
            margin-top:8px;
            color:#64748b;
          ">
            Lecture automatique des données de trésorerie…
          </div>

        </div>
      `;

      return false;

    }

    const entrees =
      entree.value;

    const sorties =
      sortie.value;

    const soldeActuel =
      solde.value;

    const caisseNette =
      entrees - sorties;

    const tauxSorties =
      entrees > 0
        ? (sorties / entrees) * 100
        : 0;

    const tauxDisponible =
      entrees > 0
        ? (soldeActuel / entrees) * 100
        : 0;

    let statut =
      'SAINE';

    let commentaire =
      'La situation de trésorerie est positive et maîtrisée.';

    if(soldeActuel < 0){

      statut =
        'CRITIQUE';

      commentaire =
        'Le solde disponible est négatif. Vérifier immédiatement les décaissements.';

    }else if(
      entrees > 0 &&
      tauxSorties >= 80
    ){

      statut =
        'À SURVEILLER';

      commentaire =
        'Les sorties représentent une part élevée des entrées.';

    }

    const signature =
      [
        entrees,
        sorties,
        soldeActuel,
        caisseNette,
        statut
      ].join('|');

    if(
      box.getAttribute(
        'data-lp13-signature'
      ) === signature
    ){
      return true;
    }

    box.setAttribute(
      'data-lp13-signature',
      signature
    );

    box.innerHTML = `

      <div style="
        margin:20px 0;
        padding:18px;
        border:1px solid #e5e7eb;
        border-radius:21px;
        background:#ffffff;
        box-shadow:0 4px 16px rgba(15,23,42,.05);
      ">

        <div style="
          font-size:23px;
          font-weight:900;
          color:#17212b;
        ">
          💰 Caisse et trésorerie automatique
        </div>

        <div style="
          margin-top:5px;
          font-size:14px;
          color:#64748b;
        ">
          Entrées • Sorties • Solde • Caisse nette
        </div>

        <div style="
          display:grid;
          grid-template-columns:repeat(2,minmax(0,1fr));
          gap:10px;
          margin-top:15px;
        ">

          ${lp13Card(
            '📥 Entrées',
            lp13Money(entrees),
            'Mouvements entrants'
          )}

          ${lp13Card(
            '📤 Sorties',
            lp13Money(sorties),
            'Mouvements sortants'
          )}

          ${lp13Card(
            '💵 Caisse nette',
            lp13Money(caisseNette),
            'Entrées - Sorties'
          )}

          ${lp13Card(
            '🏦 Solde trésorerie',
            lp13Money(soldeActuel),
            'Disponible actuellement'
          )}

        </div>

      </div>

      <div style="
        margin:20px 0;
        padding:18px;
        border:1px solid #e5e7eb;
        border-radius:21px;
        background:#ffffff;
        box-shadow:0 4px 16px rgba(15,23,42,.05);
      ">

        <div style="
          font-size:23px;
          font-weight:900;
          color:#17212b;
        ">
          📊 Synthèse trésorerie
        </div>

        <div style="
          margin-top:5px;
          font-size:14px;
          color:#64748b;
        ">
          Pilotage automatique de la trésorerie
        </div>

        <div style="
          margin-top:15px;
          padding:17px;
          border-radius:17px;
          background:#f8fafc;
          text-align:center;
        ">

          <div style="
            font-size:13px;
            font-weight:800;
            color:#64748b;
          ">
            SITUATION DE TRÉSORERIE
          </div>

          <div style="
            margin-top:7px;
            font-size:27px;
            font-weight:900;
            color:#17212b;
          ">
            ${statut}
          </div>

        </div>

        <div style="
          display:grid;
          grid-template-columns:repeat(2,minmax(0,1fr));
          gap:10px;
          margin-top:14px;
        ">

          ${lp13Card(
            '📊 Sorties / Entrées',
            lp13Pct(tauxSorties),
            'Poids des décaissements'
          )}

          ${lp13Card(
            '💚 Disponibilité',
            lp13Pct(tauxDisponible),
            'Solde / Entrées'
          )}

          ${lp13Card(
            '💰 Solde disponible',
            lp13Money(soldeActuel),
            'Liquidité actuelle'
          )}

          ${lp13Card(
            '🧮 Caisse nette',
            lp13Money(caisseNette),
            'Entrées - Sorties'
          )}

        </div>

        <div style="
          margin-top:15px;
          padding:15px;
          border:1px solid #e5e7eb;
          border-radius:16px;
          font-weight:700;
          line-height:1.5;
          color:#334155;
        ">
          ${commentaire}
        </div>

        <button
          id="lpFix13Refresh"
          type="button"
          style="
            width:100%;
            margin-top:15px;
            padding:14px;
            border:0;
            border-radius:14px;
            background:#11795e;
            color:#ffffff;
            font-size:16px;
            font-weight:900;
          "
        >
          🔄 Actualiser la trésorerie
        </button>

        <div style="
          margin-top:11px;
          font-size:12px;
          color:#64748b;
        ">
          Leader Pharma Manager Pro • Lecture seule
        </div>

      </div>
    `;

    const refresh =
      document.getElementById(
        'lpFix13Refresh'
      );

    if(refresh){

      refresh.onclick =
        function(){

          box.removeAttribute(
            'data-lp13-signature'
          );

          lp13Render();

        };

    }

    return true;

  }

  function lp13Schedule(){

    if(lp13Timer){
      clearTimeout(lp13Timer);
    }

    lp13Timer =
      setTimeout(
        lp13Render,
        150
      );

  }

  window.lpFix13TresorerieRender =
    lp13Render;

  setTimeout(lp13Render,200);
  setTimeout(lp13Render,500);
  setTimeout(lp13Render,900);
  setTimeout(lp13Render,1500);
  setTimeout(lp13Render,2500);

  document.addEventListener(
    'click',
    function(){

      setTimeout(
        lp13Render,
        100
      );

      setTimeout(
        lp13Render,
        400
      );

      setTimeout(
        lp13Render,
        900
      );

    },
    true
  );

  try{

    const observer =
      new MutationObserver(
        function(){

          lp13Schedule();

        }
      );

    observer.observe(
      document.documentElement,
      {
        childList:true,
        subtree:true
      }
    );

  }catch(e){}

  console.log(LP13_MARKER);

})();

