/* LP_U4_MASQUE_RAPPORT_DG_USERS_START */
(function(){
  'use strict';

  const U4_CLASS = 'lp-u4-non-dg';
  const U4_STYLE_ID = 'lpU4RapportDGUsersStyle';
  const R1_ID = 'lpR1RapportsDG';

  function lpU4Norm(v){
    try{
      return String(v == null ? '' : v)
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');
    }catch(e){
      return String(v == null ? '' : v).trim().toLowerCase();
    }
  }

  function lpU4IsDG(){
    if(!currentUser){
      return false;
    }

    const role = lpU4Norm(currentUser.role);
    const username = lpU4Norm(currentUser.username);

    return (
      role === 'dg' ||
      role === 'direction' ||
      role === 'directeur general' ||
      username === 'leader.fr'
    );
  }

  function lpU4InstallStyle(){
    if(document.getElementById(U4_STYLE_ID)){
      return;
    }

    const style = document.createElement('style');
    style.id = U4_STYLE_ID;
    style.textContent = `
      html.${U4_CLASS} #${R1_ID} {
        display:none !important;
        visibility:hidden !important;
        opacity:0 !important;
        pointer-events:none !important;
      }
    `;
    document.head.appendChild(style);
  }

  function lpU4Sync(){
    lpU4InstallStyle();

    const nonDG = !!currentUser && !lpU4IsDG();
    document.documentElement.classList.toggle(U4_CLASS, nonDG);

    const root = document.getElementById(R1_ID);

    if(nonDG && root){
      root.classList.remove('lp-r3-rapport-final-actif');
    }

    if(nonDG){
      try{
        if(typeof window.lpR3RapportFinal === 'function'){
          window.lpR3RapportFinal();
        }
      }catch(e){}
    }

    return nonDG;
  }

  window.lpU4SyncRapportsDG = lpU4Sync;

  try{
    if(typeof dashboard === 'function'){
      const lpU4DashboardBase = dashboard;
      dashboard = function(){
        lpU4Sync();
        const result = lpU4DashboardBase.apply(this,arguments);
        setTimeout(lpU4Sync,0);
        setTimeout(lpU4Sync,80);
        setTimeout(lpU4Sync,300);
        return result;
      };
    }
  }catch(e){}

  document.addEventListener('click',function(){
    setTimeout(lpU4Sync,0);
    setTimeout(lpU4Sync,120);
    setTimeout(lpU4Sync,450);
  },true);

  try{
    let u4Timer = null;
    const observer = new MutationObserver(function(){
      clearTimeout(u4Timer);
      u4Timer = setTimeout(lpU4Sync,35);
    });

    observer.observe(document.documentElement,{
      childList:true,
      subtree:true
    });
  }catch(e){}

  setTimeout(lpU4Sync,0);
  setTimeout(lpU4Sync,150);
  setTimeout(lpU4Sync,500);
  setTimeout(lpU4Sync,1200);

  console.log('LEADER PHARMA U4 RAPPORTS DG MASQUES CHEZ UTILISATEURS ACTIF');
})();
/* LP_U4_MASQUE_RAPPORT_DG_USERS_END */


/* LP_U5_RAPPORT_DG_SEULEMENT_RAPPORTS_START */
(function(){
  'use strict';

  const U5_CLASS = 'lp-u5-hors-rapports';
  const U5_STYLE_ID = 'lpU5RapportDGSeulementRapportsStyle';
  const R1_ID = 'lpR1RapportsDG';

  function lpU5OnReports(){
    try{
      return String(page || '') === 'reports';
    }catch(e){
      return false;
    }
  }

  function lpU5InstallStyle(){
    if(document.getElementById(U5_STYLE_ID)){
      return;
    }

    const style = document.createElement('style');
    style.id = U5_STYLE_ID;
    style.textContent = `
      html.${U5_CLASS} #${R1_ID} {
        display:none !important;
        visibility:hidden !important;
        opacity:0 !important;
        pointer-events:none !important;
        position:static !important;
        width:auto !important;
        height:auto !important;
        max-height:none !important;
        overflow:visible !important;
        z-index:auto !important;
      }
    `;
    document.head.appendChild(style);
  }

  function lpU5Sync(){
    lpU5InstallStyle();

    const onReports = lpU5OnReports();
    document.documentElement.classList.toggle(U5_CLASS,!onReports);

    const root = document.getElementById(R1_ID);

    if(!onReports && root){
      root.classList.remove('lp-r3-rapport-final-actif');
      root.style.display = 'none';
    }

    if(onReports && root){
      root.style.display = '';
    }

    return onReports;
  }

  window.lpU5SyncRapportDGRoute = lpU5Sync;

  /*
    Sécurité principale : à chaque rendu de rubrique,
    la synthèse DG est autorisée seulement si page === reports.
    Comptabilité reste donc exclusivement la page Comptabilité.
  */
  try{
    if(typeof render === 'function'){
      const lpU5RenderBase = render;
      render = function(){
        lpU5Sync();
        const result = lpU5RenderBase.apply(this,arguments);
        lpU5Sync();
        setTimeout(lpU5Sync,0);
        setTimeout(lpU5Sync,80);
        setTimeout(lpU5Sync,250);
        return result;
      };
    }
  }catch(e){}

  /*
    Sécurité spécifique Comptabilité : même si l'ancien R1
    croit détecter le mot "rapport" dans un sous-module comptable,
    il ne peut plus prendre l'écran.
  */
  try{
    if(typeof accounting === 'function'){
      const lpU5AccountingBase = accounting;
      accounting = function(){
        document.documentElement.classList.add(U5_CLASS);
        const result = lpU5AccountingBase.apply(this,arguments);
        lpU5Sync();
        setTimeout(lpU5Sync,0);
        setTimeout(lpU5Sync,120);
        setTimeout(lpU5Sync,400);
        return result;
      };
    }
  }catch(e){}

  document.addEventListener('click',function(){
    setTimeout(lpU5Sync,0);
    setTimeout(lpU5Sync,100);
    setTimeout(lpU5Sync,350);
  },true);

  try{
    let u5Timer = null;
    const observer = new MutationObserver(function(){
      clearTimeout(u5Timer);
      u5Timer = setTimeout(lpU5Sync,30);
    });

    observer.observe(document.documentElement,{
      childList:true,
      subtree:true,
      attributes:true,
      attributeFilter:['class','style']
    });
  }catch(e){}

  setTimeout(lpU5Sync,0);
  setTimeout(lpU5Sync,150);
  setTimeout(lpU5Sync,600);

  console.log('LEADER PHARMA U5 RAPPORT DG UNIQUEMENT RUBRIQUE RAPPORTS ACTIF');
})();
/* LP_U5_RAPPORT_DG_SEULEMENT_RAPPORTS_END */


/* LP_U6_HISTORIQUE_VENTES_SEULEMENT_SALES_START */
(function(){
  'use strict';

  const U6_HIDE_CLASS = 'lp-u6-hide-sales-history';
  const U6_STYLE_ID = 'lpU6SalesHistoryOnlyStyle';

  function lpU6Norm(v){
    try{
      return String(v || '')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');
    }catch(e){
      return String(v || '').trim().toLowerCase();
    }
  }

  function lpU6OnSales(){
    try{
      return String(page || '') === 'sales';
    }catch(e){
      return false;
    }
  }

  function lpU6InstallStyle(){
    if(document.getElementById(U6_STYLE_ID)){
      return;
    }
    const style = document.createElement('style');
    style.id = U6_STYLE_ID;
    style.textContent = `
      .${U6_HIDE_CLASS} {
        display:none !important;
        visibility:hidden !important;
        opacity:0 !important;
        pointer-events:none !important;
      }
    `;
    document.head.appendChild(style);
  }

  function lpU6FindHistoryRoots(){
    const roots = [];
    const candidates = document.querySelectorAll('h1,h2,h3,h4,.section-title,.card-title,strong,b');

    candidates.forEach(function(el){
      const txt = lpU6Norm(el.textContent || '');
      if(!txt.includes('historique des ventes avance')){
        return;
      }

      let root = el.closest('.card,section,article');
      if(!root){
        root = el.parentElement;
      }
      if(root && !roots.includes(root)){
        roots.push(root);
      }
    });

    return roots;
  }

  function lpU6Sync(){
    lpU6InstallStyle();
    const onSales = lpU6OnSales();
    const roots = lpU6FindHistoryRoots();

    roots.forEach(function(root){
      root.classList.toggle(U6_HIDE_CLASS,!onSales);
      if(onSales){
        root.style.removeProperty('display');
        root.style.removeProperty('visibility');
        root.style.removeProperty('opacity');
        root.style.removeProperty('pointer-events');
      }
    });

    return onSales;
  }

  try{
    if(typeof render === 'function'){
      const lpU6RenderBase = render;
      render = function(){
        const result = lpU6RenderBase.apply(this,arguments);
        lpU6Sync();
        setTimeout(lpU6Sync,0);
        setTimeout(lpU6Sync,80);
        setTimeout(lpU6Sync,250);
        return result;
      };
    }
  }catch(e){}

  try{
    if(typeof sales === 'function'){
      const lpU6SalesBase = sales;
      sales = function(){
        const result = lpU6SalesBase.apply(this,arguments);
        setTimeout(lpU6Sync,0);
        setTimeout(lpU6Sync,120);
        return result;
      };
    }
  }catch(e){}

  document.addEventListener('click',function(){
    setTimeout(lpU6Sync,0);
    setTimeout(lpU6Sync,100);
    setTimeout(lpU6Sync,300);
  },true);

  try{
    let u6Timer = null;
    const observer = new MutationObserver(function(){
      clearTimeout(u6Timer);
      u6Timer = setTimeout(lpU6Sync,30);
    });
    observer.observe(document.documentElement,{
      childList:true,
      subtree:true
    });
  }catch(e){}

  setTimeout(lpU6Sync,0);
  setTimeout(lpU6Sync,150);
  setTimeout(lpU6Sync,600);

  console.log('LEADER PHARMA U6 HISTORIQUE VENTES AVANCE UNIQUEMENT VENTES FACTURES ACTIF');
})();
/* LP_U6_HISTORIQUE_VENTES_SEULEMENT_SALES_END */


