(function(){
  'use strict';

  let lpU8ContinueId = '';
  let lpU8Saving = false;

  function lpU8Norm(v){
    try{
      return String(v || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
    }catch(e){
      return String(v || '').trim().toLowerCase();
    }
  }

  function lpU8Esc(v){
    try{
      return typeof esc === 'function' ? esc(String(v ?? '')) : String(v ?? '');
    }catch(e){
      return String(v ?? '');
    }
  }

  function lpU8Money(v){
    try{
      return typeof money === 'function'
        ? money(Number(v || 0))
        : new Intl.NumberFormat('fr-CD').format(Number(v || 0)) + ' FC';
    }catch(e){
      return String(Number(v || 0)) + ' FC';
    }
  }

  function lpU8Today(){
    try{
      return typeof today === 'function' ? today() : new Date().toISOString().slice(0,10);
    }catch(e){
      return new Date().toISOString().slice(0,10);
    }
  }

  function lpU8Uid(){
    try{
      return typeof uid === 'function' ? uid() : Date.now()+Math.floor(Math.random()*1000);
    }catch(e){
      return Date.now()+Math.floor(Math.random()*1000);
    }
  }

  function lpU8Toast(msg){
    try{ if(typeof toast === 'function') toast(msg); }catch(e){}
  }

  function lpU8Audit(action,detail){
    try{ if(typeof audit === 'function') audit(action,detail || ''); }catch(e){}
  }

  function lpU8Save(){
    try{ if(typeof save === 'function') save(); }catch(e){}
  }

  function lpU8NextSeq(){
    const n = Number(db?.purchaseSeq || 1);
    return Number.isFinite(n) && n > 0 ? n : 1;
  }

  function lpU8NextOrderRef(){
    return 'BC-' + new Date().getFullYear() + '-' + String(lpU8NextSeq()).padStart(5,'0');
  }

  function lpU8SupplierName(id){
    const s = (db.suppliers || []).find(function(x){ return String(x.id) === String(id); });
    return s?.name || '—';
  }

  function lpU8ProductName(row){
    const p = (db.products || []).find(function(x){ return String(x.id) === String(row?.productId); });
    return p?.name || row?.productName || '—';
  }

  function lpU8PurchaseRows(){
    return (db.purchases || []).filter(function(x){
      return String(x.agency || '') === String(currentAgency || '');
    });
  }

  function lpU8Ordered(row){
    return Number(row?.orderedQty || row?.qty || 0);
  }

  function lpU8Received(row){
    return Number(row?.receivedQty || row?.qty || 0);
  }

  function lpU8Remaining(row){
    const explicit = Number(row?.remainingQty);
    if(Number.isFinite(explicit) && explicit >= 0) return explicit;
    return Math.max(0,lpU8Ordered(row)-lpU8Received(row));
  }

  function lpU8Status(row){
    return lpU8Remaining(row) > 0 ? 'Partielle' : 'Complète';
  }

  function lpU8Receipts(row){
    if(Array.isArray(row?.receptions) && row.receptions.length){
      return row.receptions;
    }
    return [{
      id: row?.id,
      date: row?.date,
      qty: lpU8Received(row),
      cost: Number(row?.cost || 0),
      total: Number(row?.total || 0),
      supplierInvoice: row?.supplierInvoice || '',
      invoiceDate: row?.invoiceDate || row?.date || '',
      payment: row?.payment || '',
      paidAmount: Number(row?.paidAmount || (lpU8Norm(row?.payment)==='paye' ? row?.total || 0 : 0)),
      balance: Number(row?.balance || 0),
      lot: row?.lot || '',
      expiry: row?.expiry || ''
    }];
  }

  function lpU8Unique(values){
    const out = [];
    values.forEach(function(v){
      const s = String(v || '').trim();
      if(s && !out.some(function(x){ return lpU8Norm(x) === lpU8Norm(s); })) out.push(s);
    });
    return out;
  }

  function lpU8Invoices(row){
    if(Array.isArray(row?.receptions) && row.receptions.length){
      return lpU8Unique(row.receptions.map(function(r){ return r?.supplierInvoice || ''; }));
    }
    return lpU8Unique([row?.supplierInvoice || '']);
  }

  function lpU8Lots(row){
    if(Array.isArray(row?.receptions) && row.receptions.length){
      return lpU8Unique(row.receptions.map(function(r){ return r?.lot || ''; }));
    }
    return lpU8Unique([row?.lot || '']);
  }

  function lpU8Expiries(row){
    if(Array.isArray(row?.receptions) && row.receptions.length){
      return lpU8Unique(row.receptions.map(function(r){ return r?.expiry || ''; }));
    }
    return lpU8Unique([row?.expiry || '']);
  }

  function lpU8DebtTotal(){
    return (db.debts || [])
      .filter(function(x){
        return String(x.agency || '') === String(currentAgency || '') && lpU8Norm(x.status) !== 'paye';
      })
      .reduce(function(a,x){ return a + Number(x.balance || 0); },0);
  }

  function lpU8Kpis(rows){
    const total = rows.reduce(function(a,x){ return a + Number(x.total || 0); },0);
    const partials = rows.filter(function(x){ return lpU8Remaining(x) > 0; }).length;
    const remaining = rows.reduce(function(a,x){ return a + lpU8Remaining(x); },0);
    return {total,partials,remaining,debt:lpU8DebtTotal()};
  }

  function lpU8SupplierPerformance(rows){
    const map = new Map();
    rows.forEach(function(x){
      const key = String(x.supplierId || '');
      if(!key) return;
      if(!map.has(key)){
        map.set(key,{supplierId:x.supplierId,receipts:0,total:0,ordered:0,received:0,delayDays:0,delayCount:0,partials:0});
      }
      const m = map.get(key);
      const receipts = lpU8Receipts(x);
      m.receipts += Math.max(1,receipts.length);
      m.total += Number(x.total || 0);
      m.ordered += lpU8Ordered(x);
      m.received += lpU8Received(x);
      if(lpU8Remaining(x) > 0) m.partials++;
      const lastDate = receipts.map(function(r){ return r.date || ''; }).filter(Boolean).sort().slice(-1)[0] || x.date;
      if(x.orderDate && lastDate){
        const a = new Date(x.orderDate+'T00:00:00');
        const b = new Date(lastDate+'T00:00:00');
        const d = Math.round((b-a)/86400000);
        if(Number.isFinite(d) && d >= 0){ m.delayDays += d; m.delayCount++; }
      }
    });
    return Array.from(map.values()).sort(function(a,b){ return b.total-a.total; }).slice(0,8);
  }

  function lpU8FindOrCreateLotProduct(baseProduct,lot,expiry,cost,qty){
    const same = (db.products || []).find(function(x){
      return String(x.agency || '') === String(currentAgency || '') &&
        lpU8Norm(x.name) === lpU8Norm(baseProduct.name) &&
        lpU8Norm(x.lot) === lpU8Norm(lot);
    });

    if(same){
      same.stock = Number(same.stock || 0) + qty;
      same.cost = cost;
      same.lot = lot;
      if(expiry) same.expiry = expiry;
      return same;
    }

    const created = {
      ...baseProduct,
      id: lpU8Uid(),
      agency: currentAgency,
      lot: lot,
      expiry: expiry || '',
      cost: cost,
      stock: qty
    };
    db.products.push(created);
    return created;
  }

  function lpU8InvoiceExists(supplierId,invoice,orderRef){
    const target = lpU8Norm(invoice);
    if(!supplierId || !target) return false;
    return lpU8PurchaseRows().some(function(row){
      if(String(row.supplierId || '') !== String(supplierId || '')) return false;
      if(orderRef && String(row.orderRef || '') !== String(orderRef || '')) return false;
      return lpU8Invoices(row).some(function(inv){ return lpU8Norm(inv) === target; });
    });
  }

  function lpU8InstallStyle(){
    if(document.getElementById('lpU8PurchasesResponsiveStyle')) return;
    const style = document.createElement('style');
    style.id = 'lpU8PurchasesResponsiveStyle';
    style.textContent = `
      .lp-u8-mobile-cards{display:none}
      .lp-u8-order-card{border:1px solid #e3e8e5;border-radius:14px;padding:12px;margin-top:10px;background:#fff}
      .lp-u8-order-line{display:flex;justify-content:space-between;gap:12px;padding:5px 0;border-bottom:1px solid #f0f2f1}
      .lp-u8-order-line:last-child{border-bottom:0}
      .lp-u8-order-line span{color:#6f7d84}
      .lp-u8-order-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
      .lp-u8-status-ok{color:#087a59;font-weight:800}
      .lp-u8-status-warn{color:#a86b00;font-weight:800}
      .lp-u8-inline-supplier{border:1px dashed #b8c8c0;border-radius:12px;padding:12px;margin-top:8px;background:#f8faf9}
      .lp-u8-invoice-msg{font-size:13px;margin-top:6px;min-height:18px}
      @media (max-width:760px){
        .lp-u8-desktop-table{display:none!important}
        .lp-u8-mobile-cards{display:block!important}
        .lp-u8-form-grid{grid-template-columns:1fr!important}
        .lp-u8-supplier-head{align-items:flex-start!important;flex-direction:column!important}
        .lp-u8-supplier-head button{width:100%}
      }
    `;
    document.head.appendChild(style);
  }

  function lpU8Render(){
    lpU8InstallStyle();
    try{
      setHeader('Achats & approvisionnements','Commande • réception • lot • péremption • facture • paiement • contrôle fournisseur');
    }catch(e){}

    const rows = lpU8PurchaseRows();
    const k = lpU8Kpis(rows);
    const perf = lpU8SupplierPerformance(rows);
    const defaultBc = lpU8NextOrderRef();
    const isDG = lpU8Norm(currentUser?.role) === 'dg';

    const desktopHistory = rows.slice().reverse().map(function(x){
      const remaining = lpU8Remaining(x);
      const approval = x.validationStatus || 'À contrôler DG';
      const approveButton = isDG && !lpU8Norm(approval).includes('valide dg')
        ? `<button class="secondary" data-u8-approve="${x.id}">Valider DG</button>`
        : lpU8Esc(approval);
      const continueButton = remaining > 0
        ? `<button class="secondary" data-u8-continue="${x.id}">Compléter</button>`
        : '';
      return `<tr>
        <td>${lpU8Esc(x.ref || '—')}</td>
        <td>${lpU8Esc(x.orderRef || '—')}</td>
        <td>${lpU8Esc(lpU8Invoices(x).join(' / ') || '—')}</td>
        <td>${lpU8Esc(x.date || '—')}</td>
        <td>${lpU8Esc(lpU8SupplierName(x.supplierId))}</td>
        <td>${lpU8Esc(lpU8ProductName(x))}</td>
        <td>${lpU8Esc(lpU8Lots(x).join(' / ') || '—')}</td>
        <td>${lpU8Esc(lpU8Expiries(x).join(' / ') || '—')}</td>
        <td>${lpU8Ordered(x)}</td>
        <td>${lpU8Received(x)}</td>
        <td>${remaining}</td>
        <td>${lpU8Money(x.total)}</td>
        <td>${lpU8Esc(lpU8Status(x))}</td>
        <td><div style="display:flex;gap:6px;flex-wrap:wrap">${continueButton}${approveButton}</div></td>
      </tr>`;
    }).join('') || '<tr><td colspan="14" class="muted">Aucun achat</td></tr>';

    const mobileHistory = rows.slice().reverse().map(function(x){
      const remaining = lpU8Remaining(x);
      const statusClass = remaining > 0 ? 'lp-u8-status-warn' : 'lp-u8-status-ok';
      const approval = x.validationStatus || 'À contrôler DG';
      const continueButton = remaining > 0
        ? `<button class="secondary" data-u8-continue="${x.id}">Compléter les ${remaining} restant(s)</button>`
        : '';
      const approveButton = isDG && !lpU8Norm(approval).includes('valide dg')
        ? `<button class="secondary" data-u8-approve="${x.id}">Valider DG</button>`
        : '';
      return `<div class="lp-u8-order-card">
        <div style="font-weight:900;font-size:17px">${lpU8Esc(x.orderRef || x.ref || 'Achat')}</div>
        <div class="lp-u8-order-line"><span>Réf.</span><b>${lpU8Esc(x.ref || '—')}</b></div>
        <div class="lp-u8-order-line"><span>Fournisseur</span><b>${lpU8Esc(lpU8SupplierName(x.supplierId))}</b></div>
        <div class="lp-u8-order-line"><span>Produit</span><b>${lpU8Esc(lpU8ProductName(x))}</b></div>
        <div class="lp-u8-order-line"><span>Facture(s)</span><b>${lpU8Esc(lpU8Invoices(x).join(' / ') || '—')}</b></div>
        <div class="lp-u8-order-line"><span>Commandée</span><b>${lpU8Ordered(x)}</b></div>
        <div class="lp-u8-order-line"><span>Reçue cumulée</span><b>${lpU8Received(x)}</b></div>
        <div class="lp-u8-order-line"><span>Reste</span><b>${remaining}</b></div>
        <div class="lp-u8-order-line"><span>Total reçu</span><b>${lpU8Money(x.total)}</b></div>
        <div class="lp-u8-order-line"><span>Statut</span><b class="${statusClass}">${lpU8Esc(lpU8Status(x))}</b></div>
        <div class="lp-u8-order-actions">${continueButton}${approveButton}</div>
      </div>`;
    }).join('') || '<p class="muted">Aucun achat</p>';

    const pending = rows.filter(function(x){ return lpU8Remaining(x) > 0; }).slice().reverse();
    const pendingHtml = pending.length ? `<div class="card" style="margin-bottom:16px">
      <h3>Bons de commande à compléter</h3>
      <p class="muted">Reprenez le même bon : le stock augmentera uniquement de la nouvelle quantité reçue.</p>
      <div class="lp-u8-mobile-cards" style="display:block!important">
        ${pending.map(function(x){
          return `<div class="lp-u8-order-card">
            <div style="display:flex;justify-content:space-between;gap:10px;align-items:center">
              <b>${lpU8Esc(x.orderRef || x.ref || '—')}</b>
              <span class="lp-u8-status-warn">Reste ${lpU8Remaining(x)}</span>
            </div>
            <div class="muted" style="margin-top:5px">${lpU8Esc(lpU8SupplierName(x.supplierId))} • ${lpU8Esc(lpU8ProductName(x))}</div>
            <button class="secondary" data-u8-continue="${x.id}" style="width:100%;margin-top:10px">Continuer cette réception</button>
          </div>`;
        }).join('')}
      </div>
    </div>` : '';

    const supplierPerfRows = perf.map(function(x){
      const rate = x.ordered > 0 ? Math.round((x.received/x.ordered)*100) : 0;
      const delay = x.delayCount > 0 ? (x.delayDays/x.delayCount).toFixed(1) : '—';
      return `<tr><td>${lpU8Esc(lpU8SupplierName(x.supplierId))}</td><td>${x.receipts}</td><td>${lpU8Money(x.total)}</td><td>${rate}%</td><td>${delay}</td><td>${x.partials}</td></tr>`;
    }).join('') || '<tr><td colspan="6" class="muted">Pas encore de données fournisseur</td></tr>';

    const supplierPerfCards = perf.map(function(x){
      const rate = x.ordered > 0 ? Math.round((x.received/x.ordered)*100) : 0;
      const delay = x.delayCount > 0 ? (x.delayDays/x.delayCount).toFixed(1) : '—';
      return `<div class="lp-u8-order-card">
        <div style="font-weight:900">${lpU8Esc(lpU8SupplierName(x.supplierId))}</div>
        <div class="lp-u8-order-line"><span>Réceptions</span><b>${x.receipts}</b></div>
        <div class="lp-u8-order-line"><span>Montant</span><b>${lpU8Money(x.total)}</b></div>
        <div class="lp-u8-order-line"><span>Taux livré</span><b>${rate}%</b></div>
        <div class="lp-u8-order-line"><span>Délai moyen</span><b>${delay} j</b></div>
        <div class="lp-u8-order-line"><span>Bons partiels</span><b>${x.partials}</b></div>
      </div>`;
    }).join('') || '<p class="muted">Pas encore de données fournisseur</p>';

    const products = (typeof productsHere === 'function' ? productsHere() : (db.products || []))
      .map(function(p){
        return `<option value="${p.id}">${lpU8Esc(p.name)}${p.lot ? ' • Lot '+lpU8Esc(p.lot) : ''}</option>`;
      }).join('');

    const suppliers = (db.suppliers || []).map(function(s){
      return `<option value="${s.id}">${lpU8Esc(s.name)}</option>`;
    }).join('');

    const content = document.querySelector('#content');
    if(!content) return;

    content.innerHTML = `
      <div class="grid kpis" style="margin-bottom:16px">
        <div class="card kpi"><div class="label">Achats enregistrés</div><div class="value">${lpU8Money(k.total)}</div></div>
        <div class="card kpi"><div class="label">Quantité restant à recevoir</div><div class="value">${k.remaining}</div></div>
        <div class="card kpi"><div class="label">Bons partiels ouverts</div><div class="value">${k.partials}</div></div>
        <div class="card kpi"><div class="label">Dettes fournisseurs</div><div class="value">${lpU8Money(k.debt)}</div></div>
      </div>

      ${pendingHtml}

      <div class="card" style="margin-bottom:16px">
        <h3>Historique achats professionnel</h3>
        <div class="lp-u8-desktop-table" style="overflow-x:auto">
          <table style="min-width:1450px">
            <thead><tr>
              <th>Réf.</th><th>Bon commande</th><th>Facture(s)</th><th>Date</th><th>Fournisseur</th><th>Produit</th>
              <th>Lot(s)</th><th>Péremption</th><th>Commandée</th><th>Reçue</th><th>Reste</th><th>Total</th><th>Réception</th><th>Actions</th>
            </tr></thead>
            <tbody>${desktopHistory}</tbody>
          </table>
        </div>
        <div class="lp-u8-mobile-cards">${mobileHistory}</div>
      </div>

      <div class="grid two-col">
        <div class="card">
          <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap">
            <h3 id="u8FormTitle" style="margin:0">Nouvel achat / réception contrôlée</h3>
            <button class="secondary" id="u8CancelContinuation" style="display:none">Annuler reprise</button>
          </div>
          <div id="u8AlreadyReceivedWrap" class="card" style="display:none;margin-top:12px;background:#fff8e8">
            <div class="list-item"><span>Déjà reçu sur ce bon</span><b id="u8AlreadyReceived">0</b></div>
          </div>

          <div class="form-grid lp-u8-form-grid" style="margin-top:10px">
            <div class="field"><label>Bon de commande</label><input id="buyOrderRef" value="${lpU8Esc(defaultBc)}"></div>
            <div class="field"><label>Date commande</label><input id="buyOrderDate" type="date" value="${lpU8Today()}"></div>

            <div class="field" style="grid-column:1/-1">
              <div class="lp-u8-supplier-head" style="display:flex;justify-content:space-between;gap:8px;align-items:end">
                <label style="margin:0">Fournisseur *</label>
                <button type="button" class="secondary" id="u8ToggleSupplier">+ Nouveau fournisseur</button>
              </div>
              <select id="buySupplier" style="margin-top:6px"><option value="">— Choisir —</option>${suppliers}</select>
              <div id="u8SupplierQuick" class="lp-u8-inline-supplier" style="display:none">
                <b>Créer le fournisseur sans quitter l'achat</b>
                <div class="form-grid lp-u8-form-grid" style="margin-top:8px">
                  <div class="field"><label>Nom *</label><input id="u8NewSupplierName" placeholder="Nom du fournisseur"></div>
                  <div class="field"><label>Téléphone</label><input id="u8NewSupplierPhone" placeholder="Téléphone"></div>
                  <div class="field"><label>Adresse</label><input id="u8NewSupplierAddress" placeholder="Adresse"></div>
                </div>
                <button type="button" class="btn" id="u8CreateSupplier" style="width:100%;margin-top:8px">Créer et sélectionner</button>
              </div>
            </div>

            <div class="field"><label>Produit *</label><select id="buyProduct">${products}</select></div>
            <div class="field"><label>Quantité commandée *</label><input id="buyOrderedQty" type="number" min="1" value="1"></div>
            <div class="field"><label id="u8ReceivedLabel">Quantité reçue *</label><input id="buyQty" type="number" min="1" value="1"></div>
            <div class="field"><label>Coût unitaire *</label><input id="buyCost" type="number" min="0"></div>
            <div class="field"><label>N° lot *</label><input id="buyLot" placeholder="Ex. AMX-2026-08"></div>
            <div class="field"><label>Péremption</label><input id="buyExpiry" type="date"></div>
            <div class="field" style="display:flex;align-items:end"><label style="display:flex;gap:8px;align-items:center"><input id="buyNoExpiry" type="checkbox" style="width:auto"> Produit sans péremption</label></div>

            <div class="field" style="grid-column:1/-1">
              <label>N° facture fournisseur *</label>
              <input id="buyInvoiceNo" placeholder="Ex. FAC-4587" autocomplete="off">
              <div id="buyInvoiceCheck" class="lp-u8-invoice-msg muted">Contrôle anti-doublon actif.</div>
            </div>
            <div class="field"><label>Date facture</label><input id="buyInvoiceDate" type="date" value="${lpU8Today()}"></div>
            <div class="field"><label>Paiement</label><select id="buyPay"><option>Payé</option><option>Partiellement payé / crédit</option><option>À crédit</option></select></div>
            <div class="field" id="buyPaidWrap" style="display:none"><label>Montant déjà payé</label><input id="buyPaidAmount" type="number" min="0" value="0"></div>
          </div>

          <div class="card" style="margin-top:14px;background:#f8faf9">
            <div class="list">
              <div class="list-item"><span>Montant réception actuelle</span><b id="buyPreviewTotal">0 FC</b></div>
              <div class="list-item"><span>Reçu cumulé après validation</span><b id="buyPreviewCumulative">0</b></div>
              <div class="list-item"><span>Reste à recevoir</span><b id="buyPreviewRemaining">0</b></div>
              <div class="list-item"><span>Statut réception</span><b id="buyPreviewStatus">Complète</b></div>
            </div>
          </div>

          <button class="btn" id="savePurchase" style="width:100%;margin-top:14px">Enregistrer réception contrôlée</button>
          <p class="muted" style="margin-top:10px">Le stock augmente uniquement de la quantité réellement reçue. Pour un bon partiel, utilisez « Compléter » afin de conserver le même bon jusqu'à réception complète.</p>
        </div>

        <div class="card">
          <h3>Performance fournisseurs</h3>
          <p class="muted">Suivi automatique des volumes, taux de livraison, délais et bons partiels ouverts.</p>
          <div class="lp-u8-desktop-table" style="overflow-x:auto">
            <table style="min-width:720px">
              <thead><tr><th>Fournisseur</th><th>Réceptions</th><th>Montant</th><th>Taux livré</th><th>Délai moy. (j)</th><th>Partiels</th></tr></thead>
              <tbody>${supplierPerfRows}</tbody>
            </table>
          </div>
          <div class="lp-u8-mobile-cards">${supplierPerfCards}</div>
          <div class="card" style="margin-top:14px;background:#f8faf9">
            <b>Contrôles automatiques actifs</b>
            <p class="muted" style="margin-top:8px">✓ Fournisseur créé depuis l'achat<br>✓ Protection double clic<br>✓ Facture fournisseur anti-doublon visible<br>✓ Reprise du même bon de commande<br>✓ Passage Partielle → Complète automatique<br>✓ Historique adapté au téléphone<br>✓ Lot et péremption traçables<br>✓ Dette et trésorerie automatiques<br>✓ Journal d’audit<br>✓ Contrôle / validation DG</p>
          </div>
        </div>
      </div>`;

    const buyProduct = document.querySelector('#buyProduct');
    const buySupplier = document.querySelector('#buySupplier');
    const buyCost = document.querySelector('#buyCost');
    const buyLot = document.querySelector('#buyLot');
    const buyExpiry = document.querySelector('#buyExpiry');
    const buyOrdered = document.querySelector('#buyOrderedQty');
    const buyQty = document.querySelector('#buyQty');
    const buyPay = document.querySelector('#buyPay');
    const buyPaidWrap = document.querySelector('#buyPaidWrap');
    const buyPaid = document.querySelector('#buyPaidAmount');
    const buyNoExpiry = document.querySelector('#buyNoExpiry');
    const buyInvoiceNo = document.querySelector('#buyInvoiceNo');
    const buyOrderRef = document.querySelector('#buyOrderRef');
    const saveBtn = document.querySelector('#savePurchase');

    function currentMaster(){
      if(!lpU8ContinueId) return null;
      return (db.purchases || []).find(function(x){ return String(x.id) === String(lpU8ContinueId); }) || null;
    }

    function alreadyReceived(){
      const row = currentMaster();
      return row ? lpU8Received(row) : 0;
    }

    function syncProduct(){
      const p = (db.products || []).find(function(x){ return String(x.id) === String(buyProduct?.value || ''); });
      if(!p) return;
      if(buyCost) buyCost.value = Number(p.cost || 0);
      if(buyLot) buyLot.value = p.lot || '';
      if(buyExpiry) buyExpiry.value = p.expiry || '';
      if(buyNoExpiry) buyNoExpiry.checked = !p.expiry;
      syncExpiry();
      syncPreview();
    }

    function syncPayment(){
      const partial = lpU8Norm(buyPay?.value).includes('partiellement');
      if(buyPaidWrap) buyPaidWrap.style.display = partial ? '' : 'none';
      if(!partial && buyPaid) buyPaid.value = '0';
    }

    function syncExpiry(){
      if(!buyExpiry || !buyNoExpiry) return;
      buyExpiry.disabled = !!buyNoExpiry.checked;
      if(buyNoExpiry.checked) buyExpiry.value = '';
    }

    function syncInvoiceCheck(){
      const msg = document.querySelector('#buyInvoiceCheck');
      const supplierId = Number(buySupplier?.value || 0) || null;
      const invoice = String(buyInvoiceNo?.value || '').trim();
      const orderRef = String(buyOrderRef?.value || '').trim();
      const duplicate = lpU8InvoiceExists(supplierId,invoice,orderRef);
      if(msg){
        if(!invoice){
          msg.textContent = 'Contrôle anti-doublon actif.';
          msg.style.color = '';
        }else if(duplicate){
          msg.textContent = '⚠ Cette facture est déjà enregistrée pour ce fournisseur et ce bon.';
          msg.style.color = '#a33';
        }else{
          msg.textContent = '✓ Numéro de facture disponible.';
          msg.style.color = '#087a59';
        }
      }
      if(saveBtn && !lpU8Saving) saveBtn.disabled = duplicate;
      return duplicate;
    }

    function syncPreview(){
      const oq = Number(buyOrdered?.value || 0);
      const rqNow = Number(buyQty?.value || 0);
      const prior = alreadyReceived();
      const cumulative = Math.max(0,prior) + Math.max(0,rqNow);
      const remaining = Math.max(0,oq-cumulative);
      const total = Math.max(0,rqNow)*Math.max(0,Number(buyCost?.value || 0));
      const e1 = document.querySelector('#buyPreviewTotal');
      const e2 = document.querySelector('#buyPreviewCumulative');
      const e3 = document.querySelector('#buyPreviewRemaining');
      const e4 = document.querySelector('#buyPreviewStatus');
      if(e1) e1.textContent = lpU8Money(total);
      if(e2) e2.textContent = String(cumulative);
      if(e3) e3.textContent = String(remaining);
      if(e4) e4.textContent = remaining > 0 ? 'Partielle' : 'Complète';
    }

    function enterContinuation(row){
      if(!row || lpU8Remaining(row) <= 0) return;
      lpU8ContinueId = String(row.id);
      const title = document.querySelector('#u8FormTitle');
      const cancel = document.querySelector('#u8CancelContinuation');
      const wrap = document.querySelector('#u8AlreadyReceivedWrap');
      const prior = document.querySelector('#u8AlreadyReceived');
      const label = document.querySelector('#u8ReceivedLabel');
      const orderDate = document.querySelector('#buyOrderDate');

      if(title) title.textContent = 'Compléter le bon ' + (row.orderRef || row.ref || '');
      if(cancel) cancel.style.display = '';
      if(wrap) wrap.style.display = '';
      if(prior) prior.textContent = String(lpU8Received(row));
      if(label) label.textContent = 'Quantité reçue maintenant *';

      if(buyOrderRef){ buyOrderRef.value = row.orderRef || ''; buyOrderRef.readOnly = true; }
      if(orderDate){ orderDate.value = row.orderDate || row.date || lpU8Today(); orderDate.readOnly = true; }
      if(buySupplier){ buySupplier.value = String(row.supplierId || ''); buySupplier.disabled = true; }
      if(buyProduct){ buyProduct.value = String(row.productId || ''); buyProduct.disabled = true; }
      if(buyOrdered){ buyOrdered.value = String(lpU8Ordered(row)); buyOrdered.readOnly = true; }
      if(buyQty){ buyQty.value = String(lpU8Remaining(row)); buyQty.max = String(lpU8Remaining(row)); }
      if(buyCost) buyCost.value = Number(row.cost || 0);
      if(buyLot) buyLot.value = lpU8Lots(row).slice(-1)[0] || row.lot || '';
      if(buyExpiry) buyExpiry.value = lpU8Expiries(row).slice(-1)[0] || row.expiry || '';
      if(buyNoExpiry) buyNoExpiry.checked = !String(buyExpiry?.value || '').trim();
      if(buyInvoiceNo) buyInvoiceNo.value = '';
      if(saveBtn) saveBtn.textContent = 'Enregistrer réception complémentaire';

      syncExpiry();
      syncPayment();
      syncInvoiceCheck();
      syncPreview();
      document.querySelector('#u8FormTitle')?.scrollIntoView({behavior:'smooth',block:'start'});
    }

    document.querySelectorAll('[data-u8-continue]').forEach(function(btn){
      btn.onclick = function(){
        const row = (db.purchases || []).find(function(x){ return String(x.id) === String(btn.dataset.u8Continue); });
        enterContinuation(row);
      };
    });

    document.querySelectorAll('[data-u8-approve]').forEach(function(btn){
      btn.onclick = function(){
        if(!isDG) return lpU8Toast('Validation réservée au DG');
        const row = (db.purchases || []).find(function(x){ return String(x.id) === String(btn.dataset.u8Approve); });
        if(!row) return;
        row.validationStatus = 'Validé DG';
        row.validatedBy = currentUser?.username || currentUser?.name || 'DG';
        row.validatedAt = new Date().toISOString();
        lpU8Audit('Validation achat DG',(row.ref || 'Achat') + ' • ' + (row.orderRef || ''));
        lpU8Save();
        lpU8Render();
        lpU8Toast('Achat validé par le DG');
      };
    });

    const cancelContinuation = document.querySelector('#u8CancelContinuation');
    if(cancelContinuation){
      cancelContinuation.onclick = function(){
        lpU8ContinueId = '';
        lpU8Render();
      };
    }

    const toggleSupplier = document.querySelector('#u8ToggleSupplier');
    const supplierQuick = document.querySelector('#u8SupplierQuick');
    if(toggleSupplier && supplierQuick){
      toggleSupplier.onclick = function(){
        supplierQuick.style.display = supplierQuick.style.display === 'none' ? '' : 'none';
      };
    }

    const createSupplier = document.querySelector('#u8CreateSupplier');
    if(createSupplier){
      createSupplier.onclick = function(){
        const name = String(document.querySelector('#u8NewSupplierName')?.value || '').trim();
        const phone = String(document.querySelector('#u8NewSupplierPhone')?.value || '').trim();
        const address = String(document.querySelector('#u8NewSupplierAddress')?.value || '').trim();
        if(!name) return lpU8Toast('Nom du fournisseur obligatoire');
        const existing = (db.suppliers || []).find(function(s){ return lpU8Norm(s.name) === lpU8Norm(name); });
        let supplier = existing;
        if(!supplier){
          supplier = {id:lpU8Uid(),name,phone,address};
          if(!Array.isArray(db.suppliers)) db.suppliers = [];
          db.suppliers.push(supplier);
          lpU8Audit('Fournisseur','Ajout depuis Achats • ' + name);
          lpU8Save();
          const opt = document.createElement('option');
          opt.value = String(supplier.id);
          opt.textContent = supplier.name;
          buySupplier?.appendChild(opt);
        }
        if(buySupplier) buySupplier.value = String(supplier.id);
        if(supplierQuick) supplierQuick.style.display = 'none';
        lpU8Toast(existing ? 'Fournisseur existant sélectionné' : 'Fournisseur créé et sélectionné');
        syncInvoiceCheck();
      };
    }

    if(buyProduct) buyProduct.onchange = syncProduct;
    if(buySupplier) buySupplier.onchange = syncInvoiceCheck;
    if(buyOrderRef) buyOrderRef.oninput = syncInvoiceCheck;
    if(buyInvoiceNo) buyInvoiceNo.oninput = syncInvoiceCheck;
    if(buyPay) buyPay.onchange = function(){ syncPayment(); syncPreview(); };
    if(buyNoExpiry) buyNoExpiry.onchange = function(){ syncExpiry(); syncPreview(); };
    [buyOrdered,buyQty,buyCost,buyPaid].forEach(function(el){ if(el) el.oninput = syncPreview; });

    syncProduct();
    syncPayment();
    syncExpiry();
    syncPreview();
    syncInvoiceCheck();

    /*
      LP_U9_FIX_REPRISE_BC_AUTO_REHYDRATE
      Si la page Achats est reconstruite pendant une reprise,
      on recharge automatiquement le meme bon deja selectionne.
    */
    const lpU8ResumeMaster = currentMaster();
    if(lpU8ResumeMaster && lpU8Remaining(lpU8ResumeMaster) > 0){
      enterContinuation(lpU8ResumeMaster);
    }

    if(saveBtn){
      saveBtn.onclick = function(){
        if(lpU8Saving) return lpU8Toast('Enregistrement déjà en cours');

        const master = currentMaster();
        const supplierId = master ? master.supplierId : (Number(document.querySelector('#buySupplier')?.value || 0) || null);
        const baseProduct = (db.products || []).find(function(x){
          return String(x.id) === String(master ? master.productId : (document.querySelector('#buyProduct')?.value || ''));
        });
        const orderedQty = master ? lpU8Ordered(master) : Number(document.querySelector('#buyOrderedQty')?.value || 0);
        const priorReceived = master ? lpU8Received(master) : 0;
        const receivedNow = Number(document.querySelector('#buyQty')?.value || 0);
        const cost = Number(document.querySelector('#buyCost')?.value || 0);
        const lot = String(document.querySelector('#buyLot')?.value || '').trim();
        const noExpiry = !!document.querySelector('#buyNoExpiry')?.checked;
        const expiry = noExpiry ? '' : String(document.querySelector('#buyExpiry')?.value || '').trim();
        const supplierInvoice = String(document.querySelector('#buyInvoiceNo')?.value || '').trim();
        const invoiceDate = String(document.querySelector('#buyInvoiceDate')?.value || lpU8Today()).trim();
        const orderDate = master ? (master.orderDate || master.date || lpU8Today()) : String(document.querySelector('#buyOrderDate')?.value || lpU8Today()).trim();
        const orderRef = master ? String(master.orderRef || '') : String(document.querySelector('#buyOrderRef')?.value || lpU8NextOrderRef()).trim();
        const payment = String(document.querySelector('#buyPay')?.value || 'Payé');
        const maxReceivable = Math.max(0,orderedQty-priorReceived);

        function fail(msg){
          lpU8Saving = false;
          if(saveBtn){ saveBtn.disabled = false; saveBtn.textContent = master ? 'Enregistrer réception complémentaire' : 'Enregistrer réception contrôlée'; }
          lpU8Toast(msg);
          syncInvoiceCheck();
          return false;
        }

        if(!supplierId) return fail('Fournisseur obligatoire');
        if(!baseProduct) return fail('Produit obligatoire');
        if(!(orderedQty > 0)) return fail('Quantité commandée invalide');
        if(!(receivedNow > 0)) return fail('Quantité reçue invalide');
        if(receivedNow > maxReceivable) return fail('Quantité reçue supérieure au reste à recevoir : ' + maxReceivable);
        if(!(cost >= 0)) return fail('Coût unitaire invalide');
        if(!lot) return fail('Numéro de lot obligatoire');
        if(!noExpiry && !expiry) return fail('Péremption obligatoire ou cochez Produit sans péremption');
        if(!supplierInvoice) return fail('Numéro de facture fournisseur obligatoire');
        if(lpU8InvoiceExists(supplierId,supplierInvoice,orderRef)) return fail('Facture déjà enregistrée pour ce fournisseur et ce bon');

        const receiptTotal = receivedNow * cost;
        let paidAmount = 0;
        const payNorm = lpU8Norm(payment);
        if(payNorm === 'paye'){
          paidAmount = receiptTotal;
        }else if(payNorm.includes('partiellement')){
          paidAmount = Number(document.querySelector('#buyPaidAmount')?.value || 0);
          if(!(paidAmount >= 0) || paidAmount >= receiptTotal){
            return fail('Montant partiel invalide : il doit être inférieur au total');
          }
        }
        const balance = Math.max(0,receiptTotal-paidAmount);

        lpU8Saving = true;
        saveBtn.disabled = true;
        saveBtn.textContent = 'Enregistrement...';

        try{
          const stockProduct = lpU8FindOrCreateLotProduct(baseProduct,lot,expiry,cost,receivedNow);
          const receipt = {
            id:lpU8Uid(),
            date:lpU8Today(),
            qty:receivedNow,
            cost,
            total:receiptTotal,
            supplierInvoice,
            invoiceDate,
            payment,
            paidAmount,
            balance,
            lot,
            expiry,
            createdBy:currentUser?.username || currentUser?.name || '—'
          };

          let purchaseRow = master;
          if(master){
            const receipts = Array.isArray(master.receptions) && master.receptions.length
              ? master.receptions
              : lpU8Receipts(master).map(function(r){ return {...r}; });
            receipts.push(receipt);
            master.receptions = receipts;
            master.receivedQty = priorReceived + receivedNow;
            master.qty = master.receivedQty;
            master.remainingQty = Math.max(0,orderedQty-master.receivedQty);
            master.receiptStatus = master.remainingQty > 0 ? 'Partielle' : 'Complète';
            master.total = Number(master.total || 0) + receiptTotal;
            master.cost = cost;
            master.supplierInvoice = master.supplierInvoice || supplierInvoice;
            master.invoiceDate = invoiceDate;
            master.lot = master.lot || lot;
            master.expiry = master.expiry || expiry;
            master.payment = receipts.length > 1 ? 'Multiple' : payment;
            master.paidAmount = Number(master.paidAmount || 0) + paidAmount;
            master.balance = Number(master.balance || 0) + balance;
            master.productId = master.productId || stockProduct.id;
            if(lpU8Norm(currentUser?.role) !== 'dg') master.validationStatus = 'À contrôler DG';
          }else{
            const seqNow = lpU8NextSeq();
            const ref = 'ACH-' + String(seqNow).padStart(5,'0');
            db.purchaseSeq = seqNow + 1;
            const remainingQty = Math.max(0,orderedQty-receivedNow);
            purchaseRow = {
              id:lpU8Uid(),
              ref,
              date:lpU8Today(),
              agency:currentAgency,
              supplierId,
              productId:stockProduct.id,
              productName:stockProduct.name,
              qty:receivedNow,
              orderedQty,
              receivedQty:receivedNow,
              remainingQty,
              cost,
              total:receiptTotal,
              payment,
              paidAmount,
              balance,
              orderRef,
              orderDate,
              supplierInvoice,
              invoiceDate,
              lot,
              expiry,
              receiptStatus:remainingQty > 0 ? 'Partielle' : 'Complète',
              validationStatus:lpU8Norm(currentUser?.role) === 'dg' ? 'Validé DG' : 'À contrôler DG',
              createdBy:currentUser?.username || currentUser?.name || '—',
              receptions:[receipt]
            };
            db.purchases.push(purchaseRow);
          }

          if(paidAmount > 0){
            db.treasury.push({
              id:lpU8Uid(),date:lpU8Today(),agency:currentAgency,type:'Sortie',category:'Achat',
              desc:(purchaseRow.ref || 'Achat') + ' • ' + supplierInvoice + (master ? ' • Réception complémentaire' : ''),
              amount:paidAmount
            });
          }

          if(balance > 0){
            db.debts.push({
              id:lpU8Uid(),date:lpU8Today(),agency:currentAgency,supplierId,ref:purchaseRow.ref,
              amount:receiptTotal,paid:paidAmount,balance,status:'Ouvert',orderRef,supplierInvoice
            });
          }

          lpU8Audit(
            master ? 'Réception achat complémentaire' : 'Achat',
            (purchaseRow.ref || 'Achat') + ' • ' + orderRef + ' • Facture ' + supplierInvoice +
            ' • ' + stockProduct.name + ' • Lot ' + lot +
            ' • Reçu maintenant ' + receivedNow +
            ' • Reçu cumulé ' + lpU8Received(purchaseRow) + '/' + orderedQty +
            ' • Reste ' + lpU8Remaining(purchaseRow) + ' • ' + lpU8Money(receiptTotal)
          );

          lpU8Save();
          const finalStatus = lpU8Status(purchaseRow);
          lpU8ContinueId = '';
          lpU8Render();
          lpU8Toast(finalStatus === 'Complète'
            ? 'Réception complète • bon soldé • stock et finances mis à jour'
            : 'Réception partielle enregistrée • reste ' + lpU8Remaining(purchaseRow));
        }catch(e){
          console.error(e);
          fail('Erreur pendant l’enregistrement de la réception');
        }finally{
          setTimeout(function(){ lpU8Saving = false; },900);
        }
      };
    }
  }

  try{
    purchases = lpU8Render;
  }catch(e){
    try{ window.purchases = lpU8Render; }catch(x){}
  }

  window.lpU8PurchasesPro = lpU8Render;
  console.log('LEADER PHARMA U8 ACHATS PROFESSIONNELS COMBINES V2 MOBILE FOURNISSEUR REPRISE BC ACTIF');
})();
/* LP_U8_ACHATS_PRO_COMBINES_END */


/* LP_V16_REPRISE_BC_PARTIEL_ROBUSTE_START */
(function(){
  'use strict';

  const LP_V16_KEY = 'lpV16ResumePurchaseId';

  let lpV16MemoryId = '';

  function lpV16Norm(v){
    try{
      return String(v == null ? '' : v)
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');
    }catch(e){
      return String(v == null ? '' : v)
        .trim()
        .toLowerCase();
    }
  }

  function lpV16SetId(id){
    lpV16MemoryId = String(id || '');

    try{
      if(lpV16MemoryId){
        sessionStorage.setItem(
          LP_V16_KEY,
          lpV16MemoryId
        );
      }else{
        sessionStorage.removeItem(
          LP_V16_KEY
        );
      }
    }catch(e){}
  }

  function lpV16GetId(){
    try{
      const saved =
        sessionStorage.getItem(LP_V16_KEY);

      if(saved){
        lpV16MemoryId = String(saved);
      }
    }catch(e){}

    return String(lpV16MemoryId || '');
  }

  function lpV16Clear(){
    lpV16SetId('');
  }

  function lpV16All(selector){
    try{
      return Array.from(
        document.querySelectorAll(selector)
      );
    }catch(e){
      return [];
    }
  }

  function lpV16Purchase(id){
    const rows =
      db && Array.isArray(db.purchases)
        ? db.purchases
        : [];

    return rows.find(function(row){
      return (
        String(row?.id || '') ===
        String(id || '')
      );
    }) || null;
  }

  function lpV16Ordered(row){
    return Number(
      row?.orderedQty ??
      row?.qty ??
      0
    ) || 0;
  }

  function lpV16Received(row){
    return Number(
      row?.receivedQty ??
      row?.qty ??
      0
    ) || 0;
  }

  function lpV16Remaining(row){
    const explicit =
      Number(row?.remainingQty);

    if(
      Number.isFinite(explicit) &&
      explicit >= 0
    ){
      return explicit;
    }

    return Math.max(
      0,
      lpV16Ordered(row) -
      lpV16Received(row)
    );
  }

  function lpV16Supplier(row){
    const rows =
      db && Array.isArray(db.suppliers)
        ? db.suppliers
        : [];

    return rows.find(function(s){
      return (
        String(s?.id || '') ===
        String(row?.supplierId || '')
      );
    }) || null;
  }

  function lpV16Product(row){
    const rows =
      db && Array.isArray(db.products)
        ? db.products
        : [];

    return rows.find(function(p){
      return (
        String(p?.id || '') ===
        String(row?.productId || '')
      );
    }) || null;
  }

  function lpV16LastReceipt(row){
    const rows =
      Array.isArray(row?.receptions)
        ? row.receptions
        : [];

    if(!rows.length){
      return null;
    }

    return rows[rows.length - 1] || null;
  }

  function lpV16Select(
    select,
    wantedValue,
    fallbackText
  ){
    if(!select){
      return;
    }

    const wanted =
      String(wantedValue || '');

    const options =
      Array.from(select.options || []);

    const direct =
      options.find(function(o){
        return (
          String(o.value || '') ===
          wanted
        );
      });

    if(direct){
      select.value = String(direct.value);
      return;
    }

    const fallback =
      lpV16Norm(fallbackText);

    if(!fallback){
      return;
    }

    const byText =
      options.find(function(o){
        const txt =
          lpV16Norm(o.textContent || '');

        return (
          txt === fallback ||
          txt.includes(fallback)
        );
      });

    if(byText){
      select.value = String(byText.value);
    }
  }

  function lpV16Apply(){
    const id = lpV16GetId();

    if(!id){
      return false;
    }

    const row = lpV16Purchase(id);

    if(!row){
      lpV16Clear();
      return false;
    }

    const remaining =
      lpV16Remaining(row);

    if(remaining <= 0){
      lpV16Clear();
      return false;
    }

    const ordered =
      lpV16Ordered(row);

    const received =
      lpV16Received(row);

    const receipt =
      lpV16LastReceipt(row);

    const supplier =
      lpV16Supplier(row);

    const product =
      lpV16Product(row);

    const orderRef =
      String(
        row?.orderRef ||
        row?.ref ||
        ''
      );

    let needsInit = false;

    lpV16All('#buyOrderRef')
      .forEach(function(el){
        if(
          String(
            el.dataset.lpV16ResumeId ||
            ''
          ) !== id
        ){
          needsInit = true;
        }

        el.value = orderRef;
        el.readOnly = true;

        el.dataset.lpV16ResumeId = id;
      });

    lpV16All('#u8FormTitle')
      .forEach(function(el){
        el.textContent =
          'Compléter le bon ' +
          orderRef;
      });

    lpV16All('#u8CancelContinuation')
      .forEach(function(el){
        el.style.display = '';
      });

    lpV16All('#u8AlreadyReceivedWrap')
      .forEach(function(el){
        el.style.display = '';
      });

    lpV16All('#u8AlreadyReceived')
      .forEach(function(el){
        el.textContent =
          String(received);
      });

    lpV16All('#u8ReceivedLabel')
      .forEach(function(el){
        el.textContent =
          'Quantité reçue maintenant *';
      });

    lpV16All('#buyOrderDate')
      .forEach(function(el){
        el.value =
          row?.orderDate ||
          row?.date ||
          el.value;

        el.readOnly = true;
      });

    lpV16All('#buySupplier')
      .forEach(function(el){
        lpV16Select(
          el,
          row?.supplierId,
          supplier?.name || ''
        );

        el.disabled = true;
      });

    lpV16All('#buyProduct')
      .forEach(function(el){
        lpV16Select(
          el,
          row?.productId,
          product?.name ||
          row?.productName ||
          ''
        );

        el.disabled = true;
      });

    lpV16All('#buyOrderedQty')
      .forEach(function(el){
        el.value =
          String(ordered);

        el.readOnly = true;
      });

    if(needsInit){
      lpV16All('#buyQty')
        .forEach(function(el){
          el.value =
            String(remaining);

          el.min = '1';
          el.max =
            String(remaining);
        });

      lpV16All('#buyCost')
        .forEach(function(el){
          el.value =
            String(
              Number(
                receipt?.cost ??
                row?.cost ??
                product?.cost ??
                0
              ) || 0
            );
        });

      const lot =
        String(
          receipt?.lot ||
          row?.lot ||
          product?.lot ||
          ''
        );

      const expiry =
        String(
          receipt?.expiry ||
          row?.expiry ||
          product?.expiry ||
          ''
        );

      lpV16All('#buyLot')
        .forEach(function(el){
          el.value = lot;
        });

      lpV16All('#buyExpiry')
        .forEach(function(el){
          el.value = expiry;

          el.disabled = !expiry;
        });

      lpV16All('#buyNoExpiry')
        .forEach(function(el){
          el.checked = !expiry;
        });

      lpV16All('#buyInvoiceNo')
        .forEach(function(el){
          el.value = '';
        });
    }

    lpV16All('#savePurchase')
      .forEach(function(el){
        el.textContent =
          'Enregistrer réception complémentaire';
      });

    return true;
  }

  function lpV16Schedule(){
    [
      0,
      40,
      100,
      220,
      450,
      800,
      1300
    ].forEach(function(ms){
      setTimeout(
        lpV16Apply,
        ms
      );
    });
  }

  document.addEventListener(
    'click',
    function(e){
      const target = e.target;

      const continueBtn =
        target?.closest?.(
          '[data-u8-continue]'
        );

      if(continueBtn){
        const id =
          String(
            continueBtn.dataset
              .u8Continue || ''
          );

        if(id){
          lpV16SetId(id);
          lpV16Schedule();
        }

        return;
      }

      const cancel =
        target?.closest?.(
          '#u8CancelContinuation'
        );

      if(cancel){
        lpV16Clear();
        return;
      }

      const saveBtn =
        target?.closest?.(
          '#savePurchase'
        );

      if(saveBtn){
        /*
          Le U8 original conserve lui-même
          l'identifiant interne nécessaire
          pendant l'enregistrement.

          On libère seulement notre mémoire
          visuelle après le clic.
        */
        setTimeout(
          lpV16Clear,
          300
        );
      }
    },
    true
  );

  /*
    Si un autre rendu de l'application
    reconstruit le formulaire après le clic,
    cette surveillance légère remet
    automatiquement le même BC.
  */
  setInterval(
    function(){
      if(lpV16GetId()){
        lpV16Apply();
      }
    },
    500
  );

  try{
    if(typeof purchases === 'function'){
      const lpV16PurchasesBase =
        purchases;

      purchases = function(){
        const result =
          lpV16PurchasesBase.apply(
            this,
            arguments
          );

        lpV16Schedule();

        return result;
      };
    }
  }catch(e){}

  try{
    if(
      typeof window.lpU8PurchasesPro ===
      'function'
    ){
      const lpV16U8Base =
        window.lpU8PurchasesPro;

      window.lpU8PurchasesPro =
        function(){
          const result =
            lpV16U8Base.apply(
              this,
              arguments
            );

          lpV16Schedule();

          return result;
        };
    }
  }catch(e){}

  lpV16Schedule();

  console.log(
    'LEADER PHARMA V16 REPRISE BC PARTIEL ROBUSTE ACTIF'
  );

})();
/* LP_V16_REPRISE_BC_PARTIEL_ROBUSTE_END */


/* LP_V17_TRANSFERTS_INTER_AGENCES_PRO_LEGER_START */
(function(){
  'use strict';

  let lpV17ReceiveId = '';
  let lpV17Busy = false;

  function lpV17Norm(v){
    try{
      return String(v == null ? '' : v)
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g,'');
    }catch(e){
      return String(v == null ? '' : v).trim().toLowerCase();
    }
  }

  function lpV17Esc(v){
    try{
      return typeof esc === 'function'
        ? esc(String(v == null ? '' : v))
        : String(v == null ? '' : v)
            .replace(/&/g,'&amp;')
            .replace(/</g,'&lt;')
            .replace(/>/g,'&gt;')
            .replace(/"/g,'&quot;')
            .replace(/'/g,'&#39;');
    }catch(e){
      return String(v == null ? '' : v);
    }
  }

  function lpV17Uid(){
    try{
      if(typeof uid === 'function'){
        return uid();
      }
    }catch(e){}
    return Date.now() + Math.floor(Math.random()*100000);
  }

  function lpV17Today(){
    try{
      if(typeof today === 'function'){
        return today();
      }
    }catch(e){}

    const d = new Date();

    return d.getFullYear() + '-' +
      String(d.getMonth()+1).padStart(2,'0') + '-' +
      String(d.getDate()).padStart(2,'0');
  }

  function lpV17Now(){
    return new Date().toISOString();
  }

  function lpV17DateTime(v){
    if(!v){
      return '—';
    }

    try{
      return new Date(v).toLocaleString(
        'fr-FR',
        {
          day:'2-digit',
          month:'2-digit',
          year:'numeric',
          hour:'2-digit',
          minute:'2-digit'
        }
      );
    }catch(e){
      return String(v);
    }
  }

  function lpV17Toast(msg){
    try{
      if(typeof toast === 'function'){
        toast(msg);
      }
    }catch(e){}
  }

  function lpV17Save(){
    try{
      if(typeof save === 'function'){
        save();
      }
    }catch(e){}
  }

  function lpV17Audit(action,detail){
    try{
      if(typeof audit === 'function'){
        audit(
          action,
          detail || ''
        );
      }
    }catch(e){}
  }

  function lpV17IsDG(){
    if(!currentUser){
      return false;
    }

    const role =
      lpV17Norm(currentUser.role);

    const username =
      lpV17Norm(currentUser.username);

    return (
      role === 'dg' ||
      role === 'direction' ||
      role === 'directeur general' ||
      username === 'leader.fr'
    );
  }

  function lpV17User(){
    return String(
      currentUser?.username ||
      currentUser?.name ||
      currentUser?.id ||
      '—'
    );
  }

  function lpV17AgencyName(id){
    try{
      if(typeof agencyName === 'function'){
        const n = agencyName(id);

        if(n){
          return String(n);
        }
      }
    }catch(e){}

    const row =
      (db.agencies || []).find(
        function(a){
          return (
            String(a.id) ===
            String(id)
          );
        }
      );

    return (
      row?.name ||
      String(id || '—')
    );
  }

  function lpV17Transfers(){
    if(!Array.isArray(db.transfers)){
      db.transfers = [];
    }

    return db.transfers;
  }

  function lpV17Phase(row){
    if(row?.v17){
      return String(
        row.phase ||
        row.status ||
        'Préparé'
      );
    }

    return String(
      row?.status ||
      'Historique'
    );
  }

  function lpV17Pending(row){
    const p = lpV17Phase(row);

    return (
      row?.v17 &&
      [
        'Préparé',
        'Expédié',
        'En transit'
      ].includes(p)
    );
  }

  function lpV17DifferenceOpen(row){
    return (
      row?.v17 &&
      lpV17Phase(row) ===
        'Écart constaté'
    );
  }

  function lpV17VisibleRows(){
    const all = lpV17Transfers();

    if(lpV17IsDG()){
      return all;
    }

    return all.filter(
      function(row){
        return (
          String(
            row?.from || ''
          ) ===
          String(
            currentAgency || ''
          ) ||
          String(
            row?.to || ''
          ) ===
          String(
            currentAgency || ''
          )
        );
      }
    );
  }

  function lpV17NextRef(){
    const year =
      new Date().getFullYear();

    let seq =
      Number(
        db.transferSeq || 1
      );

    if(
      !Number.isFinite(seq) ||
      seq < 1
    ){
      seq = 1;
    }

    const used =
      new Set(
        lpV17Transfers()
          .map(function(x){
            return String(
              x?.ref || ''
            );
          })
          .filter(Boolean)
      );

    let ref = '';

    do{
      ref =
        'BT-' +
        year +
        '-' +
        String(seq)
          .padStart(5,'0');

      seq++;
    }while(used.has(ref));

    db.transferSeq = seq;

    return ref;
  }

  function lpV17Event(
    row,
    phase,
    detail
  ){
    if(!Array.isArray(row.events)){
      row.events = [];
    }

    row.events.push({
      phase:phase,
      at:lpV17Now(),
      by:lpV17User(),
      detail:detail || ''
    });
  }

  function lpV17InstallStyle(){
    if(
      document.getElementById(
        'lpV17TransfersStyle'
      )
    ){
      return;
    }

    const style =
      document.createElement(
        'style'
      );

    style.id =
      'lpV17TransfersStyle';

    style.textContent = `
      .lp-v17-mobile{
        display:none
      }

      .lp-v17-card{
        border:1px solid #e5e9e7;
        border-radius:16px;
        padding:14px;
        margin-top:12px;
        background:#fff
      }

      .lp-v17-row{
        display:flex;
        justify-content:space-between;
        gap:14px;
        padding:6px 0;
        border-bottom:1px solid #eef1ef
      }

      .lp-v17-row:last-child{
        border-bottom:0
      }

      .lp-v17-row span{
        color:#708087
      }

      .lp-v17-actions{
        display:flex;
        gap:8px;
        flex-wrap:wrap;
        margin-top:12px
      }

      .lp-v17-status{
        font-weight:900
      }

      .lp-v17-ok{
        color:#087a59
      }

      .lp-v17-warn{
        color:#a86b00
      }

      .lp-v17-danger{
        color:#a33
      }

      .lp-v17-info{
        color:#315c99
      }

      .lp-v17-receive{
        margin-top:12px;
        padding:12px;
        border-radius:14px;
        background:#f8faf9;
        border:1px solid #e5e9e7
      }

      @media (max-width:760px){
        .lp-v17-desktop{
          display:none!important
        }

        .lp-v17-mobile{
          display:block!important
        }

        .lp-v17-form-grid{
          grid-template-columns:1fr!important
        }
      }
    `;

    document.head.appendChild(
      style
    );
  }

  function lpV17StatusClass(
    phase
  ){
    if(
      phase === 'Clôturé' ||
      phase === 'Reçu'
    ){
      return 'lp-v17-ok';
    }

    if(
      phase ===
      'Écart constaté'
    ){
      return 'lp-v17-danger';
    }

    if(
      phase === 'Préparé' ||
      phase === 'Expédié' ||
      phase === 'En transit'
    ){
      return 'lp-v17-warn';
    }

    return 'lp-v17-info';
  }

  function lpV17CanShip(row){
    return (
      lpV17IsDG() ||
      String(
        row?.from || ''
      ) ===
      String(
        currentAgency || ''
      )
    );
  }

  function lpV17CanReceive(row){
    return (
      lpV17IsDG() ||
      String(
        row?.to || ''
      ) ===
      String(
        currentAgency || ''
      )
    );
  }

  function lpV17ActionButtons(
    row
  ){
    if(!row?.v17){
      return (
        '<span class="muted">' +
        'Historique antérieur' +
        '</span>'
      );
    }

    const phase =
      lpV17Phase(row);

    const buttons = [];

    if(
      phase === 'Préparé' &&
      lpV17CanShip(row)
    ){
      buttons.push(
        `<button
          class="secondary"
          data-v17-action="ship"
          data-id="${lpV17Esc(row.id)}"
        >
          Expédier
        </button>`
      );

      buttons.push(
        `<button
          class="secondary"
          data-v17-action="cancel"
          data-id="${lpV17Esc(row.id)}"
        >
          Annuler
        </button>`
      );
    }

    if(
      phase === 'Expédié' &&
      lpV17CanShip(row)
    ){
      buttons.push(
        `<button
          class="secondary"
          data-v17-action="transit"
          data-id="${lpV17Esc(row.id)}"
        >
          Mettre en transit
        </button>`
      );
    }

    if(
      phase === 'En transit' &&
      lpV17CanReceive(row)
    ){
      buttons.push(
        `<button
          class="btn"
          data-v17-action="receive"
          data-id="${lpV17Esc(row.id)}"
        >
          Réceptionner
        </button>`
      );
    }

    if(
      phase === 'Reçu' &&
      lpV17CanReceive(row)
    ){
      buttons.push(
        `<button
          class="secondary"
          data-v17-action="close"
          data-id="${lpV17Esc(row.id)}"
        >
          Clôturer
        </button>`
      );
    }

    if(
      phase ===
        'Écart constaté' &&
      lpV17IsDG()
    ){
      buttons.push(
        `<button
          class="secondary"
          data-v17-action="close-diff"
          data-id="${lpV17Esc(row.id)}"
        >
          Clôturer l'écart DG
        </button>`
      );
    }

    return (
      buttons.join('') ||
      '<span class="muted">' +
      'Aucune action' +
      '</span>'
    );
  }

  function lpV17ReceiveForm(
    row
  ){
    if(
      String(
        lpV17ReceiveId || ''
      ) !==
      String(
        row?.id || ''
      )
    ){
      return '';
    }

    const sent =
      Number(
        row?.sentQty ||
        row?.qty ||
        0
      );

    return `
      <div class="lp-v17-receive">

        <b>
          Réception contrôlée •
          ${lpV17Esc(
            row.ref || ''
          )}
        </b>

        <div
          class="form-grid lp-v17-form-grid"
          style="margin-top:10px"
        >

          <div class="field">
            <label>
              Quantité envoyée
            </label>

            <input
              id="lpV17SentQty"
              value="${sent}"
              readonly
            >
          </div>

          <div class="field">
            <label>
              Quantité réellement reçue *
            </label>

            <input
              id="lpV17ReceivedQty"
              type="number"
              min="0"
              max="${sent}"
              value="${sent}"
            >
          </div>

          <div
            class="field"
            style="grid-column:1/-1"
          >
            <label>
              Motif de l'écart si nécessaire
            </label>

            <input
              id="lpV17DiffReason"
              placeholder="Ex. casse, perte, colis manquant"
            >
          </div>

        </div>

        <div
          class="list-item"
          style="margin-top:8px"
        >
          <span>
            Écart calculé
          </span>

          <b id="lpV17DiffPreview">
            0
          </b>
        </div>

        <div class="lp-v17-actions">

          <button
            class="btn"
            id="lpV17ConfirmReceipt"
          >
            Confirmer la réception
          </button>

          <button
            class="secondary"
            id="lpV17CancelReceipt"
          >
            Annuler
          </button>

        </div>
      </div>
    `;
  }

  function lpV17Card(row){
    const phase =
      lpV17Phase(row);

    const planned =
      Number(
        row?.plannedQty ||
        row?.qty ||
        row?.sentQty ||
        0
      );

    const sent =
      (
        phase === 'Préparé' &&
        !row?.sourceStockDebited
      )
        ? 0
        : Number(
            row?.sentQty ||
            0
          );

    const received =
      Number(
        row?.receivedQty ||
        0
      );

    const diff =
      (
        phase === 'Reçu' ||
        phase === 'Clôturé' ||
        phase === 'Écart constaté'
      )
        ? Number(
            row?.difference ||
            Math.max(
              0,
              sent-received
            )
          )
        : 0;

    return `
      <div class="lp-v17-card">

        <div
          style="
            display:flex;
            justify-content:space-between;
            gap:10px;
            align-items:center
          "
        >

          <b style="font-size:17px">
            ${lpV17Esc(
              row?.ref ||
              'Transfert antérieur'
            )}
          </b>

          <span
            class="
              lp-v17-status
              ${lpV17StatusClass(phase)}
            "
          >
            ${lpV17Esc(phase)}
          </span>

        </div>

        <div class="lp-v17-row">
          <span>Produit</span>

          <b>
            ${lpV17Esc(
              row?.productName ||
              '—'
            )}
          </b>
        </div>

        <div class="lp-v17-row">
          <span>Lot</span>

          <b>
            ${lpV17Esc(
              row?.lot ||
              row?.productSnapshot?.lot ||
              '—'
            )}
          </b>
        </div>

        <div class="lp-v17-row">
          <span>Péremption</span>

          <b>
            ${lpV17Esc(
              row?.expiry ||
              row?.productSnapshot?.expiry ||
              '—'
            )}
          </b>
        </div>

        <div class="lp-v17-row">
          <span>Départ</span>

          <b>
            ${lpV17Esc(
              lpV17AgencyName(
                row?.from
              )
            )}
          </b>
        </div>

        <div class="lp-v17-row">
          <span>Destination</span>

          <b>
            ${lpV17Esc(
              lpV17AgencyName(
                row?.to
              )
            )}
          </b>
        </div>

        <div class="lp-v17-row">
          <span>Prévue</span>
          <b>${planned}</b>
        </div>

        <div class="lp-v17-row">
          <span>Envoyée</span>
          <b>${sent}</b>
        </div>

        <div class="lp-v17-row">
          <span>Reçue</span>
          <b>${received}</b>
        </div>

        <div class="lp-v17-row">
          <span>Écart</span>
          <b>${diff}</b>
        </div>

        ${
          row?.reason
            ? `
              <div class="lp-v17-row">
                <span>
                  Motif transfert
                </span>

                <b>
                  ${lpV17Esc(
                    row.reason
                  )}
                </b>
              </div>
            `
            : ''
        }

        ${
          row?.differenceReason
            ? `
              <div class="lp-v17-row">
                <span>
                  Motif écart
                </span>

                <b>
                  ${lpV17Esc(
                    row.differenceReason
                  )}
                </b>
              </div>
            `
            : ''
        }

        <div
          class="muted"
          style="margin-top:8px"
        >
          Préparé :
          ${lpV17Esc(
            lpV17DateTime(
              row?.preparedAt ||
              row?.createdAt
            )
          )}
          <br>

          ${
            row?.shippedAt
              ? `
                Expédié :
                ${lpV17Esc(
                  lpV17DateTime(
                    row.shippedAt
                  )
                )}
                <br>
              `
              : ''
          }

          ${
            row?.receivedAt
              ? `
                Reçu :
                ${lpV17Esc(
                  lpV17DateTime(
                    row.receivedAt
                  )
                )}
              `
              : ''
          }
        </div>

        <div class="lp-v17-actions">
          ${lpV17ActionButtons(row)}
        </div>

        ${lpV17ReceiveForm(row)}

      </div>
    `;
  }

  function lpV17Render(){
    lpV17InstallStyle();

    try{
      if(
        typeof setHeader ===
        'function'
      ){
        setHeader(
          'Transferts inter-agences contrôlés',
          'Bon • expédition • stock en transit • réception • écarts • lots • audit'
        );
      }
    }catch(e){}

    const all =
      lpV17VisibleRows();

    const rows =
      all
        .slice()
        .reverse()
        .slice(0,60);

    const pending =
      all.filter(
        lpV17Pending
      );

    const transitQty =
      pending.reduce(
        function(sum,row){
          const phase =
            lpV17Phase(row);

          return sum + (
            phase === 'Expédié' ||
            phase === 'En transit'
              ? Number(
                  row?.sentQty ||
                  row?.qty ||
                  0
                )
              : 0
          );
        },
        0
      );

    const differences =
      all.filter(
        lpV17DifferenceOpen
      ).length;

    const closed =
      all.filter(
        function(row){
          return (
            row?.v17 &&
            lpV17Phase(row) ===
              'Clôturé'
          );
        }
      ).length;

    const products =
      (
        typeof productsHere ===
          'function'
          ? productsHere()
          : (
            db.products || []
          ).filter(
            function(p){
              return (
                !p.agency ||
                String(p.agency) ===
                String(
                  currentAgency || ''
                )
              );
            }
          )
      ).filter(
        function(p){
          return (
            Number(
              p?.stock || 0
            ) > 0
          );
        }
      );

    const destinations =
      (
        db.agencies || []
      ).filter(
        function(a){
          return (
            String(a.id) !==
            String(
              currentAgency || ''
            )
          );
        }
      );

    const desktopRows =
      rows.map(
        function(row){

          const phase =
            lpV17Phase(row);

          const sent =
            Number(
              row?.sentQty ||
              row?.qty ||
              0
            );

          const received =
            Number(
              row?.receivedQty ||
              (
                phase === 'Reçu' ||
                phase === 'Clôturé'
                  ? sent
                  : 0
              )
            );

          const diff =
            Number(
              row?.difference ||
              Math.max(
                0,
                sent-received
              )
            );

          return `
            <tr>

              <td>
                ${lpV17Esc(
                  row?.ref ||
                  '—'
                )}
              </td>

              <td>
                ${lpV17Esc(
                  row?.date ||
                  '—'
                )}
              </td>

              <td>
                ${lpV17Esc(
                  row?.productName ||
                  '—'
                )}
              </td>

              <td>
                ${lpV17Esc(
                  row?.lot ||
                  row?.productSnapshot?.lot ||
                  '—'
                )}
              </td>

              <td>
                ${lpV17Esc(
                  lpV17AgencyName(
                    row?.from
                  )
                )}
              </td>

              <td>
                ${lpV17Esc(
                  lpV17AgencyName(
                    row?.to
                  )
                )}
              </td>

              <td>
                ${sent}
              </td>

              <td>
                ${received}
              </td>

              <td>
                ${diff}
              </td>

              <td>
                <span
                  class="
                    lp-v17-status
                    ${lpV17StatusClass(phase)}
                  "
                >
                  ${lpV17Esc(phase)}
                </span>
              </td>

              <td>
                <div class="lp-v17-actions">
                  ${lpV17ActionButtons(row)}
                </div>
              </td>

            </tr>
          `;
        }
      ).join('') ||
      `
        <tr>
          <td
            colspan="11"
            class="muted"
          >
            Aucun transfert
          </td>
        </tr>
      `;

    const mobileRows =
      rows
        .map(lpV17Card)
        .join('') ||
      '<p class="muted">Aucun transfert</p>';

    const productOptions =
      products.map(
        function(p){
          return `
            <option
              value="${lpV17Esc(p.id)}"
            >
              ${lpV17Esc(p.name)}
              • Lot
              ${lpV17Esc(
                p.lot || '—'
              )}
              • Stock
              ${Number(
                p.stock || 0
              )}
            </option>
          `;
        }
      ).join('');

    const agencyOptions =
      destinations.map(
        function(a){
          return `
            <option
              value="${lpV17Esc(a.id)}"
            >
              ${lpV17Esc(a.name)}
            </option>
          `;
        }
      ).join('');

    const content =
      document.querySelector(
        '#content'
      );

    if(!content){
      return;
    }

    content.innerHTML = `

      <div
        class="grid kpis"
        style="margin-bottom:16px"
      >

        <div class="card kpi">
          <div class="label">
            Bons ouverts
          </div>

          <div class="value">
            ${pending.length}
          </div>
        </div>

        <div class="card kpi">
          <div class="label">
            Quantité en transit
          </div>

          <div class="value">
            ${transitQty}
          </div>
        </div>

        <div class="card kpi">
          <div class="label">
            Écarts à contrôler
          </div>

          <div class="value">
            ${differences}
          </div>
        </div>

        <div class="card kpi">
          <div class="label">
            Transferts clôturés
          </div>

          <div class="value">
            ${closed}
          </div>
        </div>

      </div>

      <div class="grid two-col">

        <div class="card">

          <h3>
            Nouveau bon de transfert
          </h3>

          <p class="muted">
            La préparation ne modifie aucun stock.
            Le stock source diminue uniquement lors
            de l'expédition et le stock destination
            augmente uniquement à la réception.
          </p>

          ${
            destinations.length &&
            products.length

              ? `
                <div
                  class="
                    form-grid
                    lp-v17-form-grid
                  "
                >

                  <div class="field">
                    <label>
                      Produit / lot *
                    </label>

                    <select
                      id="lpV17Product"
                    >
                      ${productOptions}
                    </select>
                  </div>

                  <div class="field">
                    <label>
                      Agence destination *
                    </label>

                    <select
                      id="lpV17To"
                    >
                      ${agencyOptions}
                    </select>
                  </div>

                  <div class="field">
                    <label>
                      Quantité à transférer *
                    </label>

                    <input
                      id="lpV17Qty"
                      type="number"
                      min="1"
                      value="1"
                    >
                  </div>

                  <div class="field">
                    <label>
                      Motif *
                    </label>

                    <select
                      id="lpV17Reason"
                    >
                      <option>
                        Réapprovisionnement
                      </option>

                      <option>
                        Rupture agence
                      </option>

                      <option>
                        Équilibrage du stock
                      </option>

                      <option>
                        Demande agence
                      </option>

                      <option>
                        Urgence
                      </option>

                      <option>
                        Autre
                      </option>
                    </select>
                  </div>

                </div>

                <button
                  class="btn"
                  id="lpV17Prepare"
                  style="
                    width:100%;
                    margin-top:12px
                  "
                >
                  Préparer le bon de transfert
                </button>
              `

              : `
                <p class="muted">
                  ${
                    !destinations.length
                      ? 'Ajoutez au moins une autre agence.'
                      : 'Aucun produit disponible en stock.'
                  }
                </p>
              `
          }

          <div
            class="card"
            style="
              margin-top:14px;
              background:#f8faf9
            "
          >

            <b>
              Contrôle logistique actif
            </b>

            <p
              class="muted"
              style="margin-top:8px"
            >
              ✓ Aucun double stock
              <br>
              ✓ Débit source uniquement à la mise en transit
              <br>
              ✓ Stock en transit séparé
              <br>
              ✓ Crédit destination uniquement à la réception
              <br>
              ✓ Lot et péremption conservés
              <br>
              ✓ Écart justifié obligatoirement
              <br>
              ✓ Réception impossible deux fois
              <br>
              ✓ Journal d'audit DG
            </p>

          </div>

        </div>

        <div class="card">

          <h3>
            Historique des transferts
          </h3>

          <p class="muted">
            Affichage des 60 mouvements
            les plus récents pour garder
            l'application légère.
          </p>

          <div
            class="lp-v17-desktop"
            style="overflow-x:auto"
          >

            <table
              style="min-width:1100px"
            >

              <thead>
                <tr>
                  <th>Bon</th>
                  <th>Date</th>
                  <th>Produit</th>
                  <th>Lot</th>
                  <th>Départ</th>
                  <th>Destination</th>
                  <th>Envoyée</th>
                  <th>Reçue</th>
                  <th>Écart</th>
                  <th>Statut</th>
                  <th>Actions</th>
                </tr>
              </thead>

              <tbody>
                ${desktopRows}
              </tbody>

            </table>

          </div>

          <div class="lp-v17-mobile">
            ${mobileRows}
          </div>

        </div>

      </div>
    `;

    const prepare =
      document.querySelector(
        '#lpV17Prepare'
      );

    if(prepare){
      prepare.onclick =
        function(){

          if(lpV17Busy){
            return;
          }

          const productId =
            String(
              document
                .querySelector(
                  '#lpV17Product'
                )
                ?.value ||
              ''
            );

          const to =
            String(
              document
                .querySelector(
                  '#lpV17To'
                )
                ?.value ||
              ''
            );

          const qty =
            Number(
              document
                .querySelector(
                  '#lpV17Qty'
                )
                ?.value ||
              0
            );

          const reason =
            String(
              document
                .querySelector(
                  '#lpV17Reason'
                )
                ?.value ||
              ''
            ).trim();

          const p =
            (
              db.products || []
            ).find(
              function(x){
                return (
                  String(x.id) ===
                  productId
                );
              }
            );

          if(!p){
            return lpV17Toast(
              'Produit introuvable'
            );
          }

          if(
            !to ||
            to ===
              String(
                currentAgency || ''
              )
          ){
            return lpV17Toast(
              'Agence destination invalide'
            );
          }

          if(!(qty > 0)){
            return lpV17Toast(
              'Quantité invalide'
            );
          }

          if(
            qty >
            Number(
              p.stock || 0
            )
          ){
            return lpV17Toast(
              'Stock insuffisant : disponible ' +
              Number(
                p.stock || 0
              )
            );
          }

          if(
            !String(
              p.lot || ''
            ).trim()
          ){
            return lpV17Toast(
              'Lot obligatoire avant le transfert'
            );
          }

          if(!reason){
            return lpV17Toast(
              'Motif obligatoire'
            );
          }

          if(p.expiry){

            const expiry =
              new Date(
                String(p.expiry) +
                'T23:59:59'
              );

            if(
              Number.isFinite(
                expiry.getTime()
              ) &&
              expiry.getTime() <
                Date.now()
            ){
              return lpV17Toast(
                'Transfert bloqué : produit périmé'
              );
            }
          }

          const ref =
            lpV17NextRef();

          const now =
            lpV17Now();

          const row = {
            id:lpV17Uid(),
            v17:true,
            ref:ref,
            date:lpV17Today(),
            createdAt:now,
            preparedAt:now,
            from:currentAgency,
            to:to,
            productId:p.id,
            productName:p.name,
            lot:p.lot || '',
            expiry:p.expiry || '',
            qty:qty,
            plannedQty:qty,
            sentQty:0,
            receivedQty:0,
            difference:0,
            reason:reason,
            differenceReason:'',
            status:'En attente',
            phase:'Préparé',
            createdBy:lpV17User(),
            sourceStockDebited:false,
            destStockCredited:false,
            productSnapshot:{
              ...p
            },
            events:[]
          };

          lpV17Event(
            row,
            'Préparé',
            'Bon créé sans mouvement de stock'
          );

          lpV17Transfers()
            .push(row);

          lpV17Audit(
            'Transfert préparé',
            ref +
            ' • ' +
            p.name +
            ' • Lot ' +
            p.lot +
            ' • ' +
            qty +
            ' • ' +
            lpV17AgencyName(
              currentAgency
            ) +
            ' → ' +
            lpV17AgencyName(to)
          );

          lpV17Save();

          lpV17Render();

          lpV17Toast(
            'Bon ' +
            ref +
            ' préparé'
          );
        };
    }

    document
      .querySelectorAll(
        '[data-v17-action]'
      )
      .forEach(
        function(btn){

          btn.onclick =
            function(){

              if(lpV17Busy){
                return;
              }

              const id =
                String(
                  btn.dataset.id ||
                  ''
                );

              const action =
                String(
                  btn.dataset
                    .v17Action ||
                  ''
                );

              const row =
                lpV17Transfers()
                  .find(
                    function(x){
                      return (
                        String(x.id) ===
                        id
                      );
                    }
                  );

              if(
                !row ||
                !row.v17
              ){
                return;
              }

              if(
                action ===
                'receive'
              ){
                lpV17ReceiveId =
                  id;

                lpV17Render();

                return;
              }

              lpV17Busy = true;

              try{

                if(
                  action ===
                  'cancel'
                ){

                  if(
                    lpV17Phase(row) !==
                      'Préparé' ||
                    !lpV17CanShip(row)
                  ){
                    return lpV17Toast(
                      'Annulation non autorisée'
                    );
                  }

                  row.phase =
                    'Annulé';

                  row.status =
                    'Annulé';

                  row.cancelledAt =
                    lpV17Now();

                  row.cancelledBy =
                    lpV17User();

                  lpV17Event(
                    row,
                    'Annulé',
                    'Bon annulé avant expédition'
                  );

                  lpV17Audit(
                    'Transfert annulé',
                    row.ref || ''
                  );

                  lpV17Save();

                  lpV17Render();

                  lpV17Toast(
                    'Bon annulé sans mouvement de stock'
                  );

                  return;
                }

                if(
                  action ===
                  'ship'
                ){

                  if(
                    lpV17Phase(row) !==
                      'Préparé' ||
                    !lpV17CanShip(row)
                  ){
                    return lpV17Toast(
                      'Expédition non autorisée'
                    );
                  }

                  const source =
                    (
                      db.products ||
                      []
                    ).find(
                      function(p){
                        return (
                          String(p.id) ===
                          String(
                            row.productId
                          )
                        );
                      }
                    );

                  if(!source){
                    return lpV17Toast(
                      'Produit source introuvable'
                    );
                  }

                  const qty =
                    Number(
                      row.plannedQty ||
                      row.qty ||
                      row.sentQty ||
                      0
                    );

                  if(
                    !(qty > 0) ||
                    qty >
                      Number(
                        source.stock ||
                        0
                      )
                  ){
                    return lpV17Toast(
                      'Stock source insuffisant au moment de l’expédition'
                    );
                  }

                  if(
                    row.sourceStockDebited
                  ){
                    return lpV17Toast(
                      'Ce bon a déjà été expédié'
                    );
                  }

                  source.stock =
                    Number(
                      source.stock ||
                      0
                    ) -
                    qty;

                  row.sentQty =
                    qty;

                  row.sourceStockDebited =
                    true;

                  row.phase =
                    'Expédié';

                  row.status =
                    'En attente';

                  row.shippedAt =
                    lpV17Now();

                  row.shippedBy =
                    lpV17User();

                  lpV17Event(
                    row,
                    'Expédié',
                    'Stock source débité de ' +
                    qty
                  );

                  lpV17Audit(
                    'Transfert expédié',
                    row.ref +
                    ' • ' +
                    row.productName +
                    ' x' +
                    qty +
                    ' • vers ' +
                    lpV17AgencyName(
                      row.to
                    )
                  );

                  lpV17Save();

                  lpV17Render();

                  lpV17Toast(
                    'Expédition enregistrée • stock source conservé jusqu’à la mise en transit'
                  );

                  return;
                }

                if(
                  action ===
                  'transit'
                ){

                  if(
                    lpV17Phase(row) !==
                      'Expédié' ||
                    !lpV17CanShip(row)
                  ){
                    return lpV17Toast(
                      'Mise en transit non autorisée'
                    );
                  }

                  
                  /* =========================================
                     TRANSFERT STOCK A LA MISE EN TRANSIT
                     ========================================= */

                  const lpTransitNorm =
                    function(v){
                      try{
                        return String(
                          v == null ? '' : v
                        )
                          .trim()
                          .toLowerCase()
                          .normalize('NFD')
                          .replace(
                            /[\u0300-\u036f]/g,
                            ''
                          );
                      }catch(e){
                        return String(
                          v == null ? '' : v
                        )
                          .trim()
                          .toLowerCase();
                      }
                    };

                  const lpTransitQty =
                    Number(
                      row.sentQty ||
                      row.plannedQty ||
                      row.qty ||
                      0
                    );

                  if(
                    !Number.isFinite(
                      lpTransitQty
                    ) ||
                    lpTransitQty <= 0
                  ){
                    return lpV17Toast(
                      'Quantité de transfert invalide'
                    );
                  }

                  const lpTransitSourceRaw =
                    String(
                      row.source ||
                      row.from ||
                      ''
                    );

                  const lpTransitAgencyRow =
                    (
                      db &&
                      Array.isArray(
                        db.agencies
                      )
                    )
                      ? db.agencies.find(
                          function(a){
                            return (
                              String(
                                a?.id || ''
                              ) ===
                                lpTransitSourceRaw
                              ||
                              String(
                                a?.name || ''
                              ) ===
                                lpTransitSourceRaw
                            );
                          }
                        )
                      : null;

                  const lpTransitSourceId =
                    String(
                      lpTransitAgencyRow?.id ||
                      currentAgency ||
                      lpTransitSourceRaw ||
                      ''
                    );

                  const lpTransitProducts =
                    (
                      db &&
                      Array.isArray(
                        db.products
                      )
                    )
                      ? db.products
                      : [];

                  let lpTransitProduct =
                    lpTransitProducts.find(
                      function(p){
                        return (
                          String(
                            p?.id || ''
                          ) ===
                            String(
                              row.productId || ''
                            )
                          &&
                          (
                            !p?.agency ||
                            String(
                              p.agency
                            ) ===
                              lpTransitSourceId
                          )
                        );
                      }
                    );

                  if(!lpTransitProduct){
                    lpTransitProduct =
                      lpTransitProducts.find(
                        function(p){
                          return (
                            (
                              !p?.agency ||
                              String(
                                p.agency
                              ) ===
                                lpTransitSourceId
                            )
                            &&
                            lpTransitNorm(
                              p?.name
                            ) ===
                              lpTransitNorm(
                                row.productName
                              )
                            &&
                            (
                              !row.lot ||
                              lpTransitNorm(
                                p?.lot
                              ) ===
                                lpTransitNorm(
                                  row.lot
                                )
                            )
                          );
                        }
                      );
                  }

                  if(!lpTransitProduct){
                    return lpV17Toast(
                      'Produit source introuvable'
                    );
                  }

                  /*
                    Protection :
                    le même bon ne retire
                    jamais deux fois le stock.
                  */
                  if(
                    !row.transitStockDebited
                  ){
                    const lpTransitStockBefore =
                      Number(
                        lpTransitProduct.stock ||
                        0
                      );

                    if(
                      lpTransitStockBefore <
                        lpTransitQty
                    ){
                      return lpV17Toast(
                        'Stock source insuffisant'
                      );
                    }

                    /*
                      Stock local :
                      diminution au moment
                      de la mise en transit.
                    */
                    lpTransitProduct.stock =
                      Math.max(
                        0,
                        lpTransitStockBefore -
                          lpTransitQty
                      );

                    row.transitStockDebited =
                      true;

                    row.transitStockDebitedAt =
                      new Date()
                        .toISOString();

                    row.transitCentralPending =
                      true;

                    /*
                      Stock central Supabase :
                      même mouvement unique.
                    */
                    try{
                      const lpTransitMovementId =
                        'TRANSFERT-' +
                        String(
                          row.ref ||
                          row.id ||
                          ''
                        ) +
                        '-SOURCE';

                      const lpTransitBody = {
                        p_mouvement_id:
                          lpTransitMovementId,

                        p_agence_id:
                          lpTransitSourceId,

                        p_produit_ref:
                          String(
                            lpTransitProduct.id ||
                            row.productId ||
                            ''
                          ),

                        p_produit_nom:
                          String(
                            lpTransitProduct.name ||
                            row.productName ||
                            ''
                          ),

                        p_lot:
                          String(
                            lpTransitProduct.lot ||
                            row.lot ||
                            ''
                          ),

                        p_quantite:
                          Math.trunc(
                            lpTransitQty
                          ),

                        p_stock_avant:
                          Math.trunc(
                            lpTransitStockBefore
                          ),

                        p_vente_ref:
                          String(
                            row.ref ||
                            row.id ||
                            lpTransitMovementId
                          )
                      };

                      fetch(
                        SUPABASE.url +
                          '/rest/v1/rpc/' +
                          'lp_apply_stock_sale',
                        {
                          method:
                            'POST',

                          headers:{
                            apikey:
                              SUPABASE.key,

                            Authorization:
                              'Bearer ' +
                              SUPABASE.key,

                            'Content-Type':
                              'application/json'
                          },

                          body:
                            JSON.stringify(
                              lpTransitBody
                            )
                        }
                      )
                      .then(
                        async function(r){

                          const txt =
                            await r.text();

                          if(!r.ok){
                            throw new Error(
                              'Stock central ' +
                              r.status +
                              ' ' +
                              txt.slice(
                                0,
                                180
                              )
                            );
                          }

                          let centralStock =
                            Number(txt);

                          try{
                            centralStock =
                              Number(
                                JSON.parse(
                                  txt
                                )
                              );
                          }catch(e){}

                          if(
                            Number.isFinite(
                              centralStock
                            )
                          ){
                            lpTransitProduct.stock =
                              centralStock;
                          }

                          row.transitCentralPending =
                            false;

                          row.transitCentralDone =
                            true;

                          if(
                            typeof save ===
                              'function'
                          ){
                            save();
                          }

                          if(
                            typeof lpV17Toast ===
                              'function'
                          ){
                            lpV17Toast(
                              'Stock source mis à jour : ' +
                              lpTransitProduct.stock
                            );
                          }
                        }
                      )
                      .catch(
                        function(e){

                          console.warn(
                            'TRANSFERT STOCK CENTRAL',
                            e
                          );

                          row.transitCentralPending =
                            true;

                          if(
                            typeof save ===
                              'function'
                          ){
                            save();
                          }
                        }
                      );
                    }
                    catch(e){
                      console.warn(
                        'TRANSFERT STOCK CENTRAL',
                        e
                      );
                    }
                  }


                            row.phase =
                    'En transit';

                  row.status =
                    'En attente';

                  row.transitAt =
                    lpV17Now();

                  row.transitBy =
                    lpV17User();

                  lpV17Event(
                    row,
                    'En transit',
                    'Colis déclaré en transit'
                  );

                  lpV17Audit(
                    'Transfert en transit',
                    row.ref || ''
                  );

                  lpV17Save();

                  lpV17Render();

                  lpV17Toast(
                    'Bon maintenant en transit'
                  );

                  return;
                }

                if(
                  action ===
                  'close'
                ){

                  if(
                    lpV17Phase(row) !==
                      'Reçu' ||
                    !lpV17CanReceive(
                      row
                    )
                  ){
                    return lpV17Toast(
                      'Clôture non autorisée'
                    );
                  }

                  row.phase =
                    'Clôturé';

                  row.status =
                    'Clôturé';

                  row.closedAt =
                    lpV17Now();

                  row.closedBy =
                    lpV17User();

                  lpV17Event(
                    row,
                    'Clôturé',
                    'Transfert reçu sans écart'
                  );

                  lpV17Audit(
                    'Transfert clôturé',
                    row.ref || ''
                  );

                  lpV17Save();

                  lpV17Render();

                  lpV17Toast(
                    'Transfert clôturé'
                  );

                  return;
                }

                if(
                  action ===
                  'close-diff'
                ){

                  if(
                    lpV17Phase(row) !==
                      'Écart constaté' ||
                    !lpV17IsDG()
                  ){
                    return lpV17Toast(
                      'Clôture de l’écart réservée au DG'
                    );
                  }

                  row.phase =
                    'Clôturé';

                  row.status =
                    'Clôturé';

                  row.closedWithDifference =
                    true;

                  row.closedAt =
                    lpV17Now();

                  row.closedBy =
                    lpV17User();

                  lpV17Event(
                    row,
                    'Clôturé',
                    'Écart clôturé par le DG : ' +
                    (
                      row.differenceReason ||
                      '—'
                    )
                  );

                  lpV17Audit(
                    'Écart transfert clôturé DG',
                    row.ref +
                    ' • écart ' +
                    Number(
                      row.difference ||
                      0
                    ) +
                    ' • ' +
                    (
                      row.differenceReason ||
                      '—'
                    )
                  );

                  lpV17Save();

                  lpV17Render();

                  lpV17Toast(
                    'Écart clôturé par le DG'
                  );

                  return;
                }

              }finally{
                lpV17Busy =
                  false;
              }
            };
        }
      );

    const receiveRow =
      lpV17Transfers()
        .find(
          function(x){
            return (
              String(x.id) ===
              String(
                lpV17ReceiveId ||
                ''
              )
            );
          }
        );

    const receivedInput =
      document.querySelector(
        '#lpV17ReceivedQty'
      );

    const preview =
      document.querySelector(
        '#lpV17DiffPreview'
      );

    function lpV17SyncDiff(){

      if(
        !receiveRow ||
        !receivedInput ||
        !preview
      ){
        return;
      }

      const sent =
        Number(
          receiveRow.sentQty ||
          receiveRow.qty ||
          0
        );

      const received =
        Number(
          receivedInput.value ||
          0
        );

      preview.textContent =
        String(
          Math.max(
            0,
            sent-received
          )
        );
    }

    if(receivedInput){
      receivedInput.oninput =
        lpV17SyncDiff;

      lpV17SyncDiff();
    }

    const cancelReceipt =
      document.querySelector(
        '#lpV17CancelReceipt'
      );

    if(cancelReceipt){
      cancelReceipt.onclick =
        function(){

          lpV17ReceiveId = '';

          lpV17Render();
        };
    }

    const confirmReceipt =
      document.querySelector(
        '#lpV17ConfirmReceipt'
      );

    if(
      confirmReceipt &&
      receiveRow
    ){
      confirmReceipt.onclick =
        function(){

          if(lpV17Busy){
            return;
          }

          if(
            lpV17Phase(
              receiveRow
            ) !== 'En transit'
          ){
            return lpV17Toast(
              'Le bon doit être en transit avant réception'
            );
          }

          if(
            !lpV17CanReceive(
              receiveRow
            )
          ){
            return lpV17Toast(
              'Réception réservée à l’agence destination ou au DG'
            );
          }

          if(
            receiveRow
              .destStockCredited ||
            receiveRow
              .receivedAt
          ){
            return lpV17Toast(
              'Ce bon a déjà été réceptionné'
            );
          }

          const sent =
            Number(
              receiveRow.sentQty ||
              receiveRow.qty ||
              0
            );

          const received =
            Number(
              document
                .querySelector(
                  '#lpV17ReceivedQty'
                )
                ?.value ||
              0
            );

          const reason =
            String(
              document
                .querySelector(
                  '#lpV17DiffReason'
                )
                ?.value ||
              ''
            ).trim();

          if(
            received < 0 ||
            received > sent
          ){
            return lpV17Toast(
              'Quantité reçue invalide : maximum ' +
              sent
            );
          }

          const diff =
            sent -
            received;

          if(
            diff > 0 &&
            !reason
          ){
            return lpV17Toast(
              'Motif obligatoire pour l’écart de ' +
              diff
            );
          }

          lpV17Busy = true;

          try{

            if(received > 0){

              const snap =
                receiveRow
                  .productSnapshot ||
                {};

              let dest =
                (
                  db.products ||
                  []
                ).find(
                  function(p){
                    return (
                      String(
                        p.agency ||
                        ''
                      ) ===
                      String(
                        receiveRow.to ||
                        ''
                      ) &&
                      lpV17Norm(
                        p.name
                      ) ===
                      lpV17Norm(
                        receiveRow
                          .productName
                      ) &&
                      lpV17Norm(
                        p.lot
                      ) ===
                      lpV17Norm(
                        receiveRow
                          .lot
                      )
                    );
                  }
                );

              if(dest){

                dest.stock =
                  Number(
                    dest.stock ||
                    0
                  ) +
                  received;

                if(
                  receiveRow
                    .expiry
                ){
                  dest.expiry =
                    receiveRow
                      .expiry;
                }

                if(
                  snap.cost !=
                  null
                ){
                  dest.cost =
                    snap.cost;
                }

              }else{

                dest = {
                  ...snap,

                  id:
                    lpV17Uid(),

                  agency:
                    receiveRow.to,

                  name:
                    receiveRow
                      .productName,

                  lot:
                    receiveRow
                      .lot ||
                    snap.lot ||
                    '',

                  expiry:
                    receiveRow
                      .expiry ||
                    snap.expiry ||
                    '',

                  stock:
                    received
                };

                db.products
                  .push(dest);
              }
            }

            receiveRow
              .receivedQty =
              received;

            receiveRow
              .difference =
              diff;

            receiveRow
              .differenceReason =
              diff > 0
                ? reason
                : '';

            receiveRow
              .destStockCredited =
              true;

            receiveRow
              .receivedAt =
              lpV17Now();

            receiveRow
              .receivedBy =
              lpV17User();

            receiveRow.phase =
              diff > 0
                ? 'Écart constaté'
                : 'Reçu';

            receiveRow.status =
              diff > 0
                ? 'Écart'
                : 'Reçu';

            lpV17Event(
              receiveRow,
              receiveRow.phase,
              'Envoyé ' +
              sent +
              ' • reçu ' +
              received +
              ' • écart ' +
              diff +
              (
                diff > 0
                  ? ' • ' +
                    reason
                  : ''
              )
            );

            lpV17Audit(
              diff > 0
                ? 'Réception transfert avec écart'
                : 'Réception transfert',

              receiveRow.ref +
              ' • ' +
              receiveRow
                .productName +
              ' • envoyé ' +
              sent +
              ' • reçu ' +
              received +
              ' • écart ' +
              diff +
              (
                diff > 0
                  ? ' • ' +
                    reason
                  : ''
              )
            );

            lpV17Save();

            lpV17ReceiveId =
              '';

            lpV17Render();

            lpV17Toast(
              diff > 0

                ? 'Réception enregistrée avec écart ' +
                  diff +
                  ' • contrôle DG requis'

                : 'Réception complète • stock destination mis à jour une seule fois'
            );

          }finally{
            lpV17Busy =
              false;
          }
        };
    }
  }

  try{
    transfers =
      lpV17Render;

  }catch(e){

    try{
      window.transfers =
        lpV17Render;
    }catch(x){}
  }

  window.lpV17TransfersPro =
    lpV17Render;

  console.log(
    'LEADER PHARMA V17 TRANSFERTS INTER AGENCES PRO LEGER ACTIF'
  );

})();

console.log(
  'LEADER PHARMA TRANSFERT FINAL RUN24 ACTIF'
);



console.log(
  'LEADER PHARMA TRANSFERT STOCK A LA MISE EN TRANSIT ACTIF'
);
