  async function lpRequestRecovery(
    email,
    msg
  ){

    const cleanEmail =
      String(email || "")
      .trim();

    if(
      !cleanEmail ||
      !cleanEmail.includes("@")
    ){

      msg.textContent =
        "Veuillez saisir une adresse email valide.";

      return;
    }

    if(
      typeof SUPABASE === "undefined" ||
      !SUPABASE ||
      !SUPABASE.url ||
      !SUPABASE.key
    ){

      msg.textContent =
        "Configuration Supabase introuvable.";

      return;
    }

    msg.textContent =
      "Envoi de la récupération...";

    try{

      const url =
        SUPABASE.url.replace(
          /\/$/,
          ""
        )
        +
        "/auth/v1/recover?redirect_to="
        +
        encodeURIComponent(
          LP_REDIRECT
        );

      const response =
        await fetch(
          url,
          {
            method:"POST",

            headers:{
              "Content-Type":
                "application/json",

              "apikey":
                SUPABASE.key,

              "Authorization":
                "Bearer " +
                SUPABASE.key
            },

            body:JSON.stringify({
              email:cleanEmail
            })
          }
        );

      if(!response.ok){

        let detail = "";

        try{
          detail =
            await response.text();
        }catch(e){}

        throw new Error(
          "Erreur " +
          response.status +
          (
            detail
              ? " - " + detail
              : ""
          )
        );
      }

      msg.textContent =
        "Email de récupération envoyé. Consultez votre boîte mail.";

    }catch(error){

      console.error(
        "LP DG RECOVERY:",
        error
      );

      msg.textContent =
        "Impossible d'envoyer la récupération : "
        +
        (
          error &&
          error.message
            ? error.message
            : "erreur inconnue"
        );

    }

  }

