  async function lpUpdatePassword(
    password,
    confirmPassword,
    msg,
    button
  ){

    const pass =
      String(password || "");

    const confirm =
      String(confirmPassword || "");

    if(pass.length < 6){

      msg.textContent =
        "Le nouveau mot de passe doit contenir au moins 6 caractères.";

      return;
    }

    if(pass !== confirm){

      msg.textContent =
        "Les deux mots de passe ne correspondent pas.";

      return;
    }

    if(!lpRecoveryAccessToken){

      msg.textContent =
        "Session de récupération absente ou expirée. Demandez un nouveau lien.";

      return;
    }

    if(
      typeof SUPABASE === "undefined" ||
      !SUPABASE ||
      !SUPABASE.url ||
      !SUPABASE.key
    ){

      msg.textContent =
        "Configuration Supabase introuvable.";

      return;
    }

    button.disabled = true;

    msg.textContent =
      "Modification du mot de passe...";

    try{

      const response =
        await fetch(
          SUPABASE.url.replace(
            /\/$/,
            ""
          )
          +
          "/auth/v1/user",

          {
            method:"PUT",

            headers:{
              "Content-Type":
                "application/json",

              "apikey":
                SUPABASE.key,

              "Authorization":
                "Bearer " +
                lpRecoveryAccessToken
            },

            body:JSON.stringify({
              password:pass
            })
          }
        );

      if(!response.ok){

        let detail = "";

        try{
          detail =
            await response.text();
        }catch(e){}

        throw new Error(
          "Erreur " +
          response.status +
          (
            detail
              ? " - " + detail
              : ""
          )
        );
      }

      lpRecoveryAccessToken = "";

      msg.textContent =
        "Mot de passe DG modifié avec succès. Fermez cette fenêtre puis connectez-vous avec le nouveau mot de passe.";

      button.disabled = true;

    }catch(error){

      console.error(
        "LP DG RESET PASSWORD:",
        error
      );

      msg.textContent =
        "Impossible de modifier le mot de passe : "
        +
        (
          error &&
          error.message
            ? error.message
            : "erreur inconnue"
        );

      button.disabled = false;
    }

  }

