  function lpExtractRecoveryData(
    rawUrl
  ){

    if(!rawUrl){
      return null;
    }

    try{

      const url =
        new URL(
          String(rawUrl)
        );

      if(
        url.protocol !==
          "leaderpharma:" ||
        url.hostname !==
          "reset-password"
      ){
        return null;
      }

      const params =
        new URLSearchParams(
          url.search
        );

      const hash =
        String(
          url.hash || ""
        ).replace(
          /^#/,
          ""
        );

      const hashParams =
        new URLSearchParams(
          hash
        );

      const accessToken =
        hashParams.get(
          "access_token"
        )
        ||
        params.get(
          "access_token"
        )
        ||
        "";

      const refreshToken =
        hashParams.get(
          "refresh_token"
        )
        ||
        params.get(
          "refresh_token"
        )
        ||
        "";

      const type =
        hashParams.get(
          "type"
        )
        ||
        params.get(
          "type"
        )
        ||
        "";

      const error =
        hashParams.get(
          "error_description"
        )
        ||
        params.get(
          "error_description"
        )
        ||
        hashParams.get(
          "error"
        )
        ||
        params.get(
          "error"
        )
        ||
        "";

      return {
        accessToken,
        refreshToken,
        type,
        error
      };

    }catch(error){

      console.error(
        "LP DEEP LINK PARSE:",
        error
      );

      return null;
    }

  }

  function lpHandleRecoveryUrl(
    rawUrl
  ){

    const cleanUrl =
      String(rawUrl || "");

    if(!cleanUrl){
      return false;
    }

    if(
      cleanUrl ===
      lpLastRecoveryUrl
    ){
      return false;
    }

    const data =
      lpExtractRecoveryData(
        cleanUrl
      );

    if(!data){
      return false;
    }

    lpLastRecoveryUrl =
      cleanUrl;

    console.log(
      "LP RECOVERY URL NATIVE RECEIVED"
    );

    if(data.error){

      lpRecoveryAccessToken = "";

      setTimeout(
        function(){

          alert(
            "Lien de récupération invalide ou expiré : "
            +
            data.error
          );

        },
        300
      );

      return true;
    }

    if(!data.accessToken){

      console.log(
        "LP RECOVERY LINK SANS ACCESS TOKEN"
      );

      return true;
    }

    lpRecoveryAccessToken =
      data.accessToken;

    setTimeout(
      lpResetPasswordUI,
      300
    );

    console.log(
      "LEADER PHARMA SESSION RECUPERATION DG NATIVE RECUE"
    );

    return true;
  }

  function lpReadNativeRecoveryUrl(){

    try{

      if(
        !window.LeaderRecovery ||
        typeof window.LeaderRecovery.lpGetRecoveryUrl !==
          "function"
      ){

        return false;
      }

      const raw =
        window.LeaderRecovery
          .lpGetRecoveryUrl();

      if(!raw){
        return false;
      }

      return lpHandleRecoveryUrl(
        String(raw)
      );

    }catch(error){

      console.log(
        "LP NATIVE RECOVERY BRIDGE:",
        error
      );

      return false;
    }

  }

