/* LP_RAPPORTS_RETOUR_MENU_DG_V3_START */

(function(){

  'use strict';

  const REPORT_ID =
    'lpR1RapportsDG';

  const BTN_ID =
    'lpRapportsRetourMenuDGV3';

  const STYLE_ID =
    'lpRapportsRetourMenuDGV3Style';

  let reportsOpen = false;

  let historyProtected = false;


  function norm(v){

    try{

      return String(
        v == null ? '' : v
      )
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(
        /[\u0300-\u036f]/g,
        ''
      );

    }catch(e){

      return String(
        v == null ? '' : v
      )
      .trim()
      .toLowerCase();
    }
  }


  function isDG(){

    try{

      if(
        typeof currentUser ===
          'undefined'
        ||
        !currentUser
      ){
        return false;
      }

      const role =
        norm(currentUser.role);

      const username =
        norm(currentUser.username);

      return (
        role === 'dg'
        ||
        role ===
          'direction'
        ||
        role ===
          'directeur general'
        ||
        username ===
          'leader.fr'
      );

    }catch(e){

      return false;
    }
  }


  function getReport(){

    return document.getElementById(
      REPORT_ID
    );
  }


  function reportVisible(){

    try{

      const root =
        getReport();

      if(!root){
        return false;
      }

      if(
        root.classList.contains(
          'lp-r3-rapport-final-actif'
        )
      ){
        return true;
      }

      const cs =
        window.getComputedStyle(
          root
        );

      if(
        cs.display === 'none'
        ||
        cs.visibility ===
          'hidden'
      ){
        return false;
      }

      const rect =
        root.getBoundingClientRect();

      return (
        rect.width > 0
        &&
        rect.height > 0
      );

    }catch(e){

      return false;
    }
  }


  function installStyle(){

    if(
      document.getElementById(
        STYLE_ID
      )
    ){
      return;
    }

    const style =
      document.createElement(
        'style'
      );

    style.id =
      STYLE_ID;

    style.textContent = `

      #${BTN_ID}{

        position:fixed !important;

        left:12px !important;

        top:
          calc(
            env(
              safe-area-inset-top,
              0px
            )
            + 10px
          ) !important;

        z-index:
          2147483646 !important;

        display:none;

        align-items:center;

        justify-content:center;

        min-height:44px;

        padding:
          10px 15px;

        border:none;

        border-radius:12px;

        background:#087f5b;

        color:white;

        font-size:14px;

        font-weight:700;

        box-shadow:
          0 3px 12px
          rgba(
            0,
            0,
            0,
            .28
          );

        cursor:pointer;

        -webkit-tap-highlight-color:
          transparent;
      }


      #${BTN_ID}.lp-visible{

        display:flex !important;
      }


      #${BTN_ID}:active{

        transform:
          scale(.97);
      }

    `;

    document.head.appendChild(
      style
    );
  }


  function installButton(){

    installStyle();

    let btn =
      document.getElementById(
        BTN_ID
      );

    if(btn){
      return btn;
    }

    btn =
      document.createElement(
        'button'
      );

    btn.id =
      BTN_ID;

    btn.type =
      'button';

    btn.textContent =
      '← Menu DG';

    btn.setAttribute(
      'aria-label',
      'Retour au menu DG'
    );


    btn.addEventListener(
      'click',
      function(e){

        e.preventDefault();

        e.stopPropagation();

        e.stopImmediatePropagation();

        returnMenu();

      },
      true
    );


    document.body.appendChild(
      btn
    );

    return btn;
  }


  function hideReport(){

    try{

      const root =
        getReport();

      if(root){

        root.classList.remove(
          'lp-r3-rapport-final-actif'
        );

        root.style.setProperty(
          'display',
          'none',
          'important'
        );

        root.setAttribute(
          'aria-hidden',
          'true'
        );
      }

    }catch(e){}
  }


  function showDashboard(){

    /*
     * 1. Fonction principale existante
     */

    try{

      if(
        typeof dashboard ===
          'function'
      ){

        dashboard();

        return true;
      }

    }catch(e){

      console.error(
        'LP V3 dashboard',
        e
      );
    }


    /*
     * 2. Stabilisateur menu existant
     */

    try{

      if(
        window
          .lpMenuStabiliteProV1
        &&
        typeof window
          .lpMenuStabiliteProV1
          .select
          === 'function'
      ){

        window
          .lpMenuStabiliteProV1
          .select(
            'tableau de bord'
          );

      }

    }catch(e){}


    /*
     * 3. Recherche du bouton
     * Tableau de bord existant
     */

    try{

      const list =
        document.querySelectorAll(
          'button,a,[role="button"]'
        );

      for(
        const el of list
      ){

        if(
          el.id === BTN_ID
        ){
          continue;
        }

        const label =
          norm(
            el.innerText
            ||
            el.textContent
            ||
            ''
          );

        if(
          label ===
            'tableau de bord'
          ||
          label.startsWith(
            'tableau de bord '
          )
        ){

          el.click();

          return true;
        }
      }

    }catch(e){}

    return false;
  }


  function returnMenu(){

    if(!isDG()){
      return false;
    }

    reportsOpen =
      false;

    hideReport();


    const btn =
      document.getElementById(
        BTN_ID
      );

    if(btn){

      btn.classList.remove(
        'lp-visible'
      );
    }


    try{

      if(
        window
          .lpMenuStabiliteProV1
        &&
        typeof window
          .lpMenuStabiliteProV1
          .select
          === 'function'
      ){

        window
          .lpMenuStabiliteProV1
          .select(
            'tableau de bord'
          );
      }

    }catch(e){}


    setTimeout(
      showDashboard,
      10
    );

    setTimeout(
      showDashboard,
      100
    );


    setTimeout(
      function(){

        try{

          window.scrollTo({
            top:0,
            left:0,
            behavior:'auto'
          });

        }catch(e){

          window.scrollTo(
            0,
            0
          );
        }

      },
      160
    );


    return true;
  }


  function protectAndroidBack(){

    if(
      historyProtected
      ||
      !reportsOpen
    ){
      return;
    }

    try{

      window.history.pushState(
        {
          lpRapportsDG:true,
          t:Date.now()
        },
        '',
        window.location.href
      );

      historyProtected =
        true;

    }catch(e){}
  }


  function sync(){

    const btn =
      installButton();

    const visible =
      isDG()
      &&
      reportVisible();

    reportsOpen =
      visible;


    if(visible){

      btn.classList.add(
        'lp-visible'
      );

      protectAndroidBack();

    }else{

      btn.classList.remove(
        'lp-visible'
      );
    }
  }


  /*
   * RETOUR ANDROID / HISTORIQUE WEBVIEW
   */

  window.addEventListener(
    'popstate',
    function(){

      if(reportsOpen){

        historyProtected =
          false;

        returnMenu();

        return;
      }

      historyProtected =
        false;

    }
  );


  /*
   * Capacitor / Cordova selon
   * disponibilite du moteur.
   */

  document.addEventListener(
    'backbutton',
    function(e){

      if(reportsOpen){

        try{
          e.preventDefault();
        }catch(x){}

        returnMenu();
      }

    },
    true
  );


  /*
   * Surveillance de l'ouverture
   * et fermeture des Rapports.
   */

  try{

    let timer = null;

    const observer =
      new MutationObserver(
        function(){

          clearTimeout(
            timer
          );

          timer =
            setTimeout(
              sync,
              30
            );
        }
      );

    observer.observe(
      document.documentElement,
      {
        subtree:true,
        childList:true,
        attributes:true,
        attributeFilter:[
          'class',
          'style',
          'hidden',
          'aria-hidden'
        ]
      }
    );

  }catch(e){}


  /*
   * Surveillance legere
   * supplementaire.
   */

  setInterval(
    sync,
    500
  );


  document.addEventListener(
    'click',
    function(){

      setTimeout(
        sync,
        20
      );

      setTimeout(
        sync,
        150
      );

      setTimeout(
        sync,
        500
      );

    },
    true
  );


  setTimeout(
    sync,
    0
  );

  setTimeout(
    sync,
    300
  );

  setTimeout(
    sync,
    1000
  );


  window
    .lpRapportsRetourMenuDGV3 =
    returnMenu;


  console.log(
    'LEADER PHARMA RAPPORTS RETOUR MENU DG V3 ACTIF'
  );

})();

/* LP_RAPPORTS_RETOUR_MENU_DG_V3_END */




/* LP_NAVIGATION_STABLE_V6_START */
(function () {
  'use strict';

  const BTN_ID = 'lpNavigationStableV6Button';
  const STYLE_ID = 'lpNavigationStableV6Style';
  const REPORT_ID = 'lpR1RapportsDG';

  const RUBRIQUES = [
    'controle dg',
    'ventes / factures',
    'ventes',
    'stock / lots',
    'stock',
    'achats',
    'fournisseurs',
    'inventaires',
    'transferts',
    'clients / ordonnances',
    'clients',
    'depenses',
    'tresorerie',
    'comptabilite',
    'creances / dettes',
    'creances',
    'rh / pointage',
    'analyses avancees',
    'analyses',
    'alertes',
    'multi-agences',
    'utilisateurs',
    'surveillance',
    'mises a jour',
    'sante du dg',
    "journal d'audit",
    'parametres'
  ];

  function norm(value) {
    return String(value || '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/\s+/g, ' ')
      .trim()
      .toLowerCase();
  }

  function currentUserSafe() {
    try {
      if (typeof currentUser !== 'undefined' && currentUser) {
        return currentUser;
      }
    } catch (e) {}

    try {
      if (window.currentUser) {
        return window.currentUser;
      }
    } catch (e) {}

    return null;
  }

  function isDG() {
    const u = currentUserSafe();

    if (!u) return false;

    const identity = norm([
      u.role,
      u.type,
      u.username,
      u.login,
      u.email,
      u.name,
      u.nom
    ].filter(Boolean).join(' '));

    return (
      identity.includes('leader.fr') ||
      identity === 'dg' ||
      identity.includes('direction generale') ||
      identity.includes('directeur general')
    );
  }

  function installStyle() {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement('style');
    style.id = STYLE_ID;

    style.textContent = `
      #${BTN_ID} {
        position: fixed !important;
        left: 12px !important;
        top: calc(env(safe-area-inset-top, 0px) + 10px) !important;
        z-index: 2147483645 !important;

        display: none;

        min-height: 42px;
        padding: 9px 15px;

        border: 0;
        border-radius: 12px;

        background: #168a45;
        color: #ffffff;

        font-size: 14px;
        font-weight: 800;
        line-height: 1;

        box-shadow: 0 4px 14px rgba(0,0,0,.22);

        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
        touch-action: manipulation;
      }

      #${BTN_ID}.lp-v6-visible {
        display: flex !important;
        align-items: center;
        justify-content: center;
      }

      /*
       * STABILISATION RAPPORTS
       *
       * Hors de la rubrique Rapports :
       * le panneau reste totalement masque.
       *
       * Au clic Rapports :
       * la classe est posee AVANT le gestionnaire original.
       * Cela evite le petit mouvement avant affichage.
       */
      html:not(.lp-v6-rapports-ouvert) #${REPORT_ID} {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
      }

      html.lp-v6-rapports-ouvert #${REPORT_ID} {
        visibility: visible !important;
        opacity: 1 !important;
        pointer-events: auto !important;
      }
    `;

    document.head.appendChild(style);
  }

  function button() {
    installStyle();

    let btn = document.getElementById(BTN_ID);

    if (!btn) {
      btn = document.createElement('button');
      btn.id = BTN_ID;
      btn.type = 'button';

      btn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();

        retourMenu();
      }, true);

      document.body.appendChild(btn);
    }

    btn.textContent = isDG() ? '← Menu DG' : '← Menu';

    return btn;
  }

  function showButton() {
    const btn = button();

    btn.textContent = isDG() ? '← Menu DG' : '← Menu';
    btn.classList.add('lp-v6-visible');
  }

  function hideButton() {
    const btn = document.getElementById(BTN_ID);

    if (btn) {
      btn.classList.remove('lp-v6-visible');
    }
  }

  function rapportsOpen() {
    document.documentElement.classList.add(
      'lp-v6-rapports-ouvert'
    );

    /*
     * Rapports garde SON bouton V3 deja valide.
     * Le bouton V6 n'est donc pas affiche dans Rapports.
     */
    hideButton();
  }

  function rapportsClose() {
    document.documentElement.classList.remove(
      'lp-v6-rapports-ouvert'
    );
  }

  function callDashboard() {
    try {
      if (
        window.lpMenuStabiliteProV1 &&
        typeof window.lpMenuStabiliteProV1.select === 'function'
      ) {
        window.lpMenuStabiliteProV1.select('tableau de bord');
      }
    } catch (e) {}

    try {
      if (typeof dashboard === 'function') {
        dashboard();
        return;
      }
    } catch (e) {}

    try {
      if (typeof window.dashboard === 'function') {
        window.dashboard();
      }
    } catch (e) {}
  }

  function retourMenu() {
    hideButton();
    rapportsClose();

    callDashboard();

    setTimeout(function () {
      try {
        window.scrollTo(0, 0);
      } catch (e) {}
    }, 80);
  }

  function rubriqueFromElement(el) {
    if (!el) return '';

    const label = norm(
      el.innerText ||
      el.textContent ||
      el.getAttribute('aria-label') ||
      ''
    );

    if (!label) return '';

    if (
      label === 'tableau de bord' ||
      label.startsWith('tableau de bord ')
    ) {
      return 'dashboard';
    }

    if (
      label === 'rapports' ||
      label.startsWith('rapports ')
    ) {
      return 'rapports';
    }

    for (const rubrique of RUBRIQUES) {
      if (
        label === rubrique ||
        label.startsWith(rubrique + ' ')
      ) {
        return rubrique;
      }
    }

    return '';
  }

  /*
   * IMPORTANT :
   * pointerdown / touchstart intervient avant le clic normal.
   * Rapports est donc stabilise avant son affichage original.
   */
  function prepareNavigation(e) {
    const el = e.target && e.target.closest
      ? e.target.closest(
          'button, a, [role="button"], [onclick]'
        )
      : null;

    if (!el) return;

    if (el.id === BTN_ID) return;

    const rubrique = rubriqueFromElement(el);

    if (!rubrique) return;

    if (rubrique === 'rapports') {
      rapportsOpen();
      return;
    }

    rapportsClose();

    if (rubrique === 'dashboard') {
      hideButton();
      return;
    }

    /*
     * Bouton visible immediatement,
     * avant meme la fin du rendu de la rubrique.
     */
    showButton();
  }

  document.addEventListener(
    'pointerdown',
    prepareNavigation,
    true
  );

  document.addEventListener(
    'touchstart',
    prepareNavigation,
    true
  );

  document.addEventListener(
    'click',
    function (e) {
      const el = e.target && e.target.closest
        ? e.target.closest(
            'button, a, [role="button"], [onclick]'
          )
        : null;

      if (!el) return;
      if (el.id === BTN_ID) return;

      const rubrique = rubriqueFromElement(el);

      if (!rubrique) return;

      if (rubrique === 'rapports') {
        rapportsOpen();
        return;
      }

      if (rubrique === 'dashboard') {
        rapportsClose();
        hideButton();
        return;
      }

      rapportsClose();
      showButton();
    },
    true
  );

  function install() {
    if (!document.body) {
      setTimeout(install, 100);
      return;
    }

    installStyle();
    button();

    /*
     * Au demarrage :
     * Rapports ferme et aucun bouton inutile sur accueil.
     */
    rapportsClose();
    hideButton();

    console.log(
      'LEADER PHARMA NAVIGATION STABLE V6 ACTIVE'
    );
  }

  if (document.readyState === 'loading') {
    document.addEventListener(
      'DOMContentLoaded',
      install,
      { once: true }
    );
  } else {
    install();
  }

  window.lpNavigationStableV6 = {
    retour: retourMenu,
    show: showButton,
    hide: hideButton,
    rapportsOpen: rapportsOpen,
    rapportsClose: rapportsClose
  };
})();
/* LP_NAVIGATION_STABLE_V6_END */


/* LP_BOUTON_MENU_GLOBAL_V7_START */
