/* LP_SECURITY_NO_LONGPRESS_COPY_SHARE_V1_START */
/*
 * LEADER PHARMA MANAGER PRO
 * SECURITE AFFICHAGE : APPUI LONG / COPIER / PARTAGER
 *
 * Objectif :
 * - bloquer la selection et le menu contextuel sur les donnees affichees ;
 * - conserver copier/coller et selection dans les zones de saisie ;
 * - ne modifier aucune fonction metier.
 */
(function(){
  'use strict';

  const STYLE_ID = 'lpSecurityNoLongPressCopyShareV1';
  const EDITABLE_SELECTOR = [
    'input',
    'textarea',
    'select',
    '[contenteditable="true"]',
    '[contenteditable=""]',
    '[contenteditable="plaintext-only"]'
  ].join(',');

  function isEditableTarget(target){
    if(!target || !target.closest){
      return false;
    }
    return !!target.closest(EDITABLE_SELECTOR);
  }

  function installStyle(){
    if(document.getElementById(STYLE_ID)){
      return;
    }

    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
      body * {
        -webkit-user-select: none !important;
        user-select: none !important;
        -webkit-touch-callout: none !important;
      }

      input,
      textarea,
      select,
      [contenteditable="true"],
      [contenteditable="true"] *,
      [contenteditable=""],
      [contenteditable=""] *,
      [contenteditable="plaintext-only"],
      [contenteditable="plaintext-only"] * {
        -webkit-user-select: text !important;
        user-select: text !important;
        -webkit-touch-callout: default !important;
      }
    `;

    (document.head || document.documentElement).appendChild(style);
  }

  function blockReadOnlyInteraction(event){
    if(isEditableTarget(event.target)){
      return;
    }
    event.preventDefault();
  }

  installStyle();

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', installStyle, { once:true });
  }

  document.addEventListener('selectstart', blockReadOnlyInteraction, true);
  document.addEventListener('contextmenu', blockReadOnlyInteraction, true);
  document.addEventListener('copy', blockReadOnlyInteraction, true);
  document.addEventListener('cut', blockReadOnlyInteraction, true);

  console.log('LEADER PHARMA SECURITE APPUI LONG COPIER PARTAGER V1 ACTIF');
})();
/* LP_SECURITY_NO_LONGPRESS_COPY_SHARE_V1_END */


/* LP_SECURITY_LONG_PRESS_V2_START */
(function () {
  'use strict';

  if (window.__LP_SECURITY_LONG_PRESS_V2__) return;
  window.__LP_SECURITY_LONG_PRESS_V2__ = true;

  function lpEditable(el) {
    if (!el || !el.closest) return false;

    return !!el.closest(
      'input, textarea, ' +
      '[contenteditable="true"], ' +
      '[contenteditable=""]'
    );
  }

  var style = document.createElement('style');
  style.id = 'lpSecurityLongPressV2Style';

  style.textContent = `
    html,
    body,
    body *:not(input):not(textarea):not([contenteditable="true"]):not([contenteditable=""]) {
      -webkit-user-select: none !important;
      user-select: none !important;
      -webkit-touch-callout: none !important;
    }

    input,
    textarea,
    [contenteditable="true"],
    [contenteditable=""] {
      -webkit-user-select: text !important;
      user-select: text !important;
    }
  `;

  function lpInstallStyle() {
    if (
      document.head &&
      !document.getElementById(
        'lpSecurityLongPressV2Style'
      )
    ) {
      document.head.appendChild(style);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener(
      'DOMContentLoaded',
      lpInstallStyle,
      { once: true }
    );
  } else {
    lpInstallStyle();
  }

  document.addEventListener(
    'contextmenu',
    function (e) {
      if (lpEditable(e.target)) return;
      e.preventDefault();
      e.stopPropagation();
    },
    true
  );

  document.addEventListener(
    'selectstart',
    function (e) {
      if (lpEditable(e.target)) return;
      e.preventDefault();
      e.stopPropagation();
    },
    true
  );

  document.addEventListener(
    'dragstart',
    function (e) {
      if (lpEditable(e.target)) return;
      e.preventDefault();
      e.stopPropagation();
    },
    true
  );

  document.addEventListener(
    'selectionchange',
    function () {
      var active = document.activeElement;

      if (lpEditable(active)) return;

      var sel = window.getSelection
        ? window.getSelection()
        : null;

      if (sel && sel.rangeCount) {
        sel.removeAllRanges();
      }
    },
    true
  );

  document.addEventListener(
    'touchend',
    function (e) {
      if (lpEditable(e.target)) return;

      var sel = window.getSelection
        ? window.getSelection()
        : null;

      if (sel && sel.rangeCount) {
        sel.removeAllRanges();
      }
    },
    {
      capture: true,
      passive: true
    }
  );

  console.log(
    'LEADER PHARMA SECURITE APPUI LONG V2 ACTIF'
  );
})();
/* LP_SECURITY_LONG_PRESS_V2_END */


/* LP_AUTH_USERS_SYNC_V5_START */
(function () {
  'use strict';

  if (window.__LP_AUTH_USERS_SYNC_V5__) {
    return;
  }

  window.__LP_AUTH_USERS_SYNC_V5__ = true;

  function lpV5IsDG(user) {
    return (
      String(
        user && user.role
          ? user.role
          : ''
      )
        .trim()
        .toLowerCase()
      === 'dg'
    );
  }

  function lpV5CloneUsers(users) {
    return (
      Array.isArray(users)
        ? users
        : []
    ).map(
      function (user) {
        return {
          ...user
        };
      }
    );
  }

  function lpV5NonDG(users) {
    return lpV5CloneUsers(users)
      .filter(
        function (user) {
          return !lpV5IsDG(user);
        }
      );
  }

  function lpV5DG(users) {
    return lpV5CloneUsers(users)
      .filter(lpV5IsDG);
  }

  function lpV5SaveLocal() {
    try {
      localStorage.setItem(
        'lpmp_v13',
        JSON.stringify(db)
      );
    } catch (e) {
      console.warn(
        'LP V5 LOCAL SAVE ERROR',
        e
      );
    }
  }

  function lpV5RefreshSellerCache() {
    try {
      const passwords =
        lpSellerPasswordsRead();

      lpV5NonDG(db.users)
        .forEach(
          function (user) {
            const username =
              String(
                user &&
                user.username
                  ? user.username
                  : ''
              )
                .trim()
                .toLowerCase();

            const password =
              String(
                user &&
                user.password
                  ? user.password
                  : ''
              );

            if (
              username &&
              password
            ) {
              passwords[username] =
                password;
            }
          }
        );

      localStorage.setItem(
        LP_SELLER_PASSWORD_KEY,
        JSON.stringify(passwords)
      );
    } catch (e) {}
  }

  window.lpV5ApplyRemoteUsers =
    function (
      remoteUsers,
      localUsers
    ) {
      if (
        !Array.isArray(remoteUsers)
      ) {
        return false;
      }

      const localDG =
        lpV5DG(localUsers);

      const remoteNonDG =
        lpV5NonDG(remoteUsers);

      db.users = [
        ...localDG,
        ...remoteNonDG
      ];

      lpV5RefreshSellerCache();
      lpV5SaveLocal();

      console.log(
        'LP V5 USERS PULL OK',
        remoteNonDG.length
      );

      return true;
    };

  window.lpV5PrepareRemoteUsers =
    function (
      remoteUsers,
      localUsers
    ) {
      const remoteDG =
        lpV5DG(remoteUsers);

      const localNonDG =
        lpV5NonDG(localUsers);

      return [
        ...remoteDG,
        ...localNonDG
      ];
    };

  console.log(
    'LEADER PHARMA AUTH USERS SYNC V5 ACTIF'
  );
})();
/* LP_AUTH_USERS_SYNC_V5_END */


/* LP_USERS_AUTO_SYNC_MENU_CLEAN_START */

(function () {

  'use strict';

  if (
    window.__LP_USERS_AUTO_SYNC_MENU_CLEAN__
  ) {
    return;
  }

  window.__LP_USERS_AUTO_SYNC_MENU_CLEAN__ =
    true;

  /*
   * =====================================
   * MENU PROPRE
   *
   * - masque les petites observations
   *   sous le titre des rubriques
   * - masque le texte ajouté au-dessus
   *   de la recherche rapide Vente
   * - conserve les champs et fonctions
   * =====================================
   */

  function lpMenuCleanInstallStyle() {

    if (
      document.getElementById(
        'lpMenuCleanFinalStyle'
      )
    ) {
      return;
    }

    var style =
      document.createElement(
        'style'
      );

    style.id =
      'lpMenuCleanFinalStyle';

    style.textContent = `
      #pageHint {
        display: none !important;
      }

      #lp153-fast-title {
        display: none !important;
      }
    `;

    if (document.head) {
      document.head.appendChild(
        style
      );
    }
  }

  function lpMenuCleanApply() {

    lpMenuCleanInstallStyle();

    var hint =
      document.getElementById(
        'pageHint'
      );

    if (hint) {
      hint.style.display =
        'none';
    }

    var salesHelp =
      document.getElementById(
        'lp153-fast-title'
      );

    if (salesHelp) {
      salesHelp.style.display =
        'none';
    }
  }

  /*
   * =====================================
   * AUTO SYNC UTILISATEURS
   *
   * save() de Leader Pharma effectue
   * déjà le PUSH automatique.
   *
   * Ici on ajoute le PULL automatique
   * sur les autres appareils.
   *
   * DG reste exclu grâce au moteur V5.
   * =====================================
   */

  var lpUsersAutoSyncBusy =
    false;

  var lpUsersLastPull =
    0;

  function lpUsersEditing() {

    var active =
      document.activeElement;

    if (!active) {
      return false;
    }

    if (
      active.isContentEditable
    ) {
      return true;
    }

    var tag =
      String(
        active.tagName || ''
      )
        .toLowerCase();

    return (
      tag === 'input' ||
      tag === 'textarea' ||
      tag === 'select'
    );
  }

  async function lpUsersAutoPull(
    force
  ) {

    if (
      lpUsersAutoSyncBusy
    ) {
      return;
    }

    if (
      document.hidden
    ) {
      return;
    }

    if (
      typeof currentUser !==
        'undefined' &&
      !currentUser
    ) {
      return;
    }

    if (
      !force &&
      lpUsersEditing()
    ) {
      return;
    }

    if (
      typeof syncPull !==
      'function'
    ) {
      return;
    }

    var now =
      Date.now();

    if (
      !force &&
      now - lpUsersLastPull <
        7000
    ) {
      return;
    }

    lpUsersAutoSyncBusy =
      true;

    try {

      await window.lpUsersOnlyRemotePull();

      lpUsersLastPull =
        Date.now();

      lpMenuCleanApply();

      /*
       * Si la page Utilisateurs
       * est déjà ouverte :
       * actualiser son affichage.
       */
      if (
        typeof page !==
          'undefined' &&
        String(page) ===
          'users' &&
        typeof render ===
          'function' &&
        !lpUsersEditing()
      ) {
        render();
        lpMenuCleanApply();
      }

      console.log(
        'LEADER PHARMA USERS AUTO PULL OK'
      );

    } catch (e) {

      console.warn(
        'LEADER PHARMA USERS AUTO PULL ERROR',
        e
      );

    } finally {

      lpUsersAutoSyncBusy =
        false;
    }
  }

  /*
   * À l'ouverture / retour application.
   */

  document.addEventListener(
    'visibilitychange',
    function () {

      lpMenuCleanApply();

      if (
        !document.hidden
      ) {
        setTimeout(
          function () {
            lpUsersAutoPull(
              true
            );
          },
          500
        );
      }
    }
  );

  window.addEventListener(
    'focus',
    function () {

      lpMenuCleanApply();

      setTimeout(
        function () {
          lpUsersAutoPull(
            true
          );
        },
        500
      );
    }
  );

  /*
   * Dès que Internet revient.
   */

  window.addEventListener(
    'online',
    function () {

      setTimeout(
        function () {
          lpUsersAutoPull(
            true
          );
        },
        500
      );
    }
  );

  /*
   * Vérification automatique régulière.
   * Aucun rafraîchissement pendant
   * la saisie dans un formulaire.
   */

  setInterval(
    function () {
      lpUsersAutoPull(
        false
      );
    },
    12000
  );

  /*
   * Le menu pouvant être reconstruit,
   * le nettoyage est réappliqué
   * automatiquement.
   */

  var observer =
    new MutationObserver(
      function () {
        lpMenuCleanApply();
      }
    );

  function lpStart() {

    lpMenuCleanApply();

    if (
      document.documentElement
    ) {
      observer.observe(
        document.documentElement,
        {
          childList: true,
          subtree: true
        }
      );
    }

    setTimeout(
      function () {
        lpUsersAutoPull(
          true
        );
      },
      1500
    );
  }

  if (
    document.readyState ===
    'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      lpStart,
      {
        once: true
      }
    );

  } else {

    lpStart();
  }

  console.log(
    'LEADER PHARMA USERS AUTO SYNC MENU CLEAN ACTIF'
  );

})();

