(function () {

  'use strict';

  if (
    window.__LP_AUTO_USERS_LOGIN_FINAL__
  ) {
    return;
  }

  window.__LP_AUTO_USERS_LOGIN_FINAL__ =
    true;

  /*
   * ==========================================
   * AUTO USERS - ECRAN DE CONNEXION
   *
   * Correction unique :
   *
   * récupérer les utilisateurs Supabase
   * même lorsqu'aucun utilisateur
   * n'est encore connecté.
   *
   * Ainsi le deuxième appareil reçoit
   * le nouveau mot de passe AVANT login.
   *
   * AUCUNE modification du menu.
   * AUCUNE synchronisation automatique
   * Stock/Ventes/Compta/RH/etc.
   * ==========================================
   */

  var lpLoginUsersBusy =
    false;

  var lpLoginUsersLast =
    0;

  async function lpLoginUsersPull(
    force
  ) {

    if (
      lpLoginUsersBusy
    ) {
      return false;
    }

    if (
      typeof window.lpUsersOnlyRemotePull !==
      'function'
    ) {
      return false;
    }

    if (
      document.hidden &&
      !force
    ) {
      return false;
    }

    var now =
      Date.now();

    if (
      !force &&
      now - lpLoginUsersLast <
        4000
    ) {
      return false;
    }

    lpLoginUsersBusy =
      true;

    try {

      var ok =
        await window.lpUsersOnlyRemotePull();

      lpLoginUsersLast =
        Date.now();

      if (ok) {

        console.log(
          'LEADER PHARMA AUTO USERS LOGIN PULL OK'
        );

      }

      return !!ok;

    } catch (e) {

      console.warn(
        'LEADER PHARMA AUTO USERS LOGIN PULL ERROR',
        e
      );

      return false;

    } finally {

      lpLoginUsersBusy =
        false;
    }
  }


  /*
   * Au démarrage de l'application.
   */

  function lpLoginUsersStart() {

    setTimeout(
      function () {
        lpLoginUsersPull(
          true
        );
      },
      800
    );

    setTimeout(
      function () {
        lpLoginUsersPull(
          true
        );
      },
      2500
    );

  }


  if (
    document.readyState ===
    'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      lpLoginUsersStart,
      {
        once: true
      }
    );

  } else {

    lpLoginUsersStart();
  }


  /*
   * Vérification régulière,
   * y compris sur l'écran Login.
   */

  setInterval(
    function () {

      lpLoginUsersPull(
        false
      );

    },
    6000
  );


  /*
   * Dès que l'application revient
   * au premier plan.
   */

  window.addEventListener(
    'focus',
    function () {

      setTimeout(
        function () {
          lpLoginUsersPull(
            true
          );
        },
        300
      );

    }
  );


  document.addEventListener(
    'visibilitychange',
    function () {

      if (
        !document.hidden
      ) {

        setTimeout(
          function () {
            lpLoginUsersPull(
              true
            );
          },
          300
        );

      }

    }
  );


  /*
   * Dès que Internet revient.
   */

  window.addEventListener(
    'online',
    function () {

      setTimeout(
        function () {
          lpLoginUsersPull(
            true
          );
        },
        300
      );

    }
  );


  /*
   * Très important :
   *
   * quand l'utilisateur touche
   * un champ mot de passe,
   * on récupère immédiatement
   * les utilisateurs distants.
   *
   * Cela laisse le temps au nouveau
   * mot de passe d'arriver avant
   * l'appui sur Connexion.
   */

  document.addEventListener(
    'focusin',
    function (event) {

      var el =
        event.target;

      if (!el) {
        return;
      }

      var type =
        String(
          el.type || ''
        )
          .toLowerCase();

      if (
        type === 'password'
      ) {

        lpLoginUsersPull(
          true
        );

      }

    },
    true
  );


  /*
   * On peut aussi déclencher
   * la récupération dès qu'un utilisateur
   * commence à écrire dans le login.
   *
   * Aucun blocage de saisie.
   */

  document.addEventListener(
    'input',
    function (event) {

      var el =
        event.target;

      if (!el) {
        return;
      }

      var type =
        String(
          el.type || ''
        )
          .toLowerCase();

      if (
        type === 'password'
      ) {

        lpLoginUsersPull(
          false
        );

      }

    },
    true
  );


  console.log(
    'LEADER PHARMA AUTO USERS LOGIN FINAL ACTIF'
  );

})();

/* LP_AUTO_USERS_LOGIN_FINAL_END */

/* LP_USERS_V6_ANTI_ECRASEMENT_START */

(function () {

  'use strict';

  if (
    window.__LP_USERS_V6_ANTI_ECRASEMENT__
  ) {
    return;
  }

  window.__LP_USERS_V6_ANTI_ECRASEMENT__ =
    true;


  /*
   * ==========================================
   * LEADER PHARMA USERS V6
   *
   * BUT :
   * - anti-écrasement
   * - multi-appareils
   * - fusion utilisateur par utilisateur
   * - le plus récent gagne
   * - un ancien appareil ne supprime pas
   *   les comptes absents de sa liste
   * ==========================================
   */


  function lpV6IsDG(
    user
  ) {

    return (
      String(
        user?.role || ''
      )
        .trim()
        .toLowerCase() ===
      'dg'
    );
  }


  function lpV6Key(
    user
  ) {

    var username =
      String(
        user?.username || ''
      )
        .trim()
        .toLowerCase();

    if (username) {
      return (
        'username:' +
        username
      );
    }

    if (
      user &&
      user.id !== undefined &&
      user.id !== null
    ) {
      return (
        'id:' +
        String(user.id)
      );
    }

    return '';
  }


  function lpV6Clone(
    value
  ) {

    try {

      return JSON.parse(
        JSON.stringify(value)
      );

    } catch (e) {

      return value;
    }
  }


  function lpV6UpdatedAt(
    user
  ) {

    var n =
      Number(
        user?._lpUserUpdatedAt ||
        0
      );

    return Number.isFinite(n)
      ? n
      : 0;
  }


  /*
   * Signature fonctionnelle.
   *
   * Le timestamp de synchronisation
   * lui-même est ignoré.
   */
  function lpV6NormaliseForSignature(
    value
  ) {

    if (
      value === null ||
      value === undefined
    ) {
      return value;
    }

    if (
      Array.isArray(value)
    ) {
      return value.map(
        lpV6NormaliseForSignature
      );
    }

    if (
      typeof value ===
      'object'
    ) {

      var out = {};

      Object.keys(value)
        .sort()
        .forEach(
          function (key) {

            if (
              key ===
              '_lpUserUpdatedAt'
            ) {
              return;
            }

            out[key] =
              lpV6NormaliseForSignature(
                value[key]
              );
          }
        );

      return out;
    }

    return value;
  }


  function lpV6Signature(
    user
  ) {

    try {

      return JSON.stringify(
        lpV6NormaliseForSignature(
          user
        )
      );

    } catch (e) {

      return '';
    }
  }


  function lpV6MakeBaseline(
    users
  ) {

    var baseline = {};

    (
      Array.isArray(users)
        ? users
        : []
    ).forEach(
      function (user) {

        if (
          !user ||
          lpV6IsDG(user)
        ) {
          return;
        }

        var key =
          lpV6Key(user);

        if (!key) {
          return;
        }

        baseline[key] =
          lpV6Signature(user);
      }
    );

    return baseline;
  }


  var lpV6Baseline =
    lpV6MakeBaseline(
      (
        typeof db !==
          'undefined' &&
        Array.isArray(
          db?.users
        )
      )
        ? db.users
        : []
    );


  function lpV6RefreshBaseline() {

    lpV6Baseline =
      lpV6MakeBaseline(
        (
          typeof db !==
            'undefined' &&
          Array.isArray(
            db?.users
          )
        )
          ? db.users
          : []
      );
  }


  /*
   * Avant chaque save(),
   * identifier uniquement les utilisateurs
   * réellement créés ou modifiés.
   *
   * Ils reçoivent un timestamp récent.
   */
  window.lpV6StampChangedUsers =
    function () {

      if (
        typeof db ===
          'undefined' ||
        !Array.isArray(
          db?.users
        )
      ) {
        return;
      }

      var now =
        Date.now();

      var changed =
        false;

      db.users.forEach(
        function (user) {

          if (
            !user ||
            lpV6IsDG(user)
          ) {
            return;
          }

          var key =
            lpV6Key(user);

          if (!key) {
            return;
          }

          var signature =
            lpV6Signature(user);

          if (
            !Object.prototype
              .hasOwnProperty
              .call(
                lpV6Baseline,
                key
              ) ||
            lpV6Baseline[key] !==
              signature
          ) {

            user._lpUserUpdatedAt =
              now;

            changed =
              true;
          }
        }
      );

      lpV6RefreshBaseline();

      if (changed) {

        console.log(
          'LEADER PHARMA USERS V6 MODIFICATION DATEE'
        );
      }
    };


  /*
   * Fusion centrale.
   *
   * IMPORTANT :
   * l'absence d'un compte dans une liste
   * ne signifie JAMAIS suppression.
   *
   * On garde donc l'union des comptes.
   */
  function lpV6MergeNonDG(
    remoteUsers,
    localUsers,
    mode
  ) {

    var map =
      new Map();

    function addRemote(
      user
    ) {

      if (
        !user ||
        lpV6IsDG(user)
      ) {
        return;
      }

      var key =
        lpV6Key(user);

      if (!key) {
        return;
      }

      map.set(
        key,
        lpV6Clone(user)
      );
    }


    function mergeLocal(
      local
    ) {

      if (
        !local ||
        lpV6IsDG(local)
      ) {
        return;
      }

      var key =
        lpV6Key(local);

      if (!key) {
        return;
      }

      var remote =
        map.get(key);

      if (!remote) {

        /*
         * Nouveau compte local :
         * on l'ajoute.
         */
        map.set(
          key,
          lpV6Clone(local)
        );

        return;
      }

      var remoteTime =
        lpV6UpdatedAt(
          remote
        );

      var localTime =
        lpV6UpdatedAt(
          local
        );

      /*
       * Celui qui possède le timestamp
       * le plus récent gagne.
       */
      if (
        localTime >
        remoteTime
      ) {

        map.set(
          key,
          lpV6Clone(local)
        );

        return;
      }

      if (
        remoteTime >
        localTime
      ) {

        return;
      }

      /*
       * Transition depuis anciennes APK :
       *
       * si aucun des deux n'a encore
       * de timestamp, le serveur reste
       * prioritaire pour éviter qu'un
       * ancien appareil réécrive
       * un compte central.
       *
       * Une vraie modification locale
       * reçoit automatiquement un
       * timestamp par save().
       */
      if (
        remoteTime === 0 &&
        localTime === 0
      ) {

        if (
          mode ===
          'push-new-local' &&
          lpV6Signature(remote) ===
          lpV6Signature(local)
        ) {

          map.set(
            key,
            lpV6Clone(local)
          );
        }

        return;
      }
    }


    (
      Array.isArray(
        remoteUsers
      )
        ? remoteUsers
        : []
    ).forEach(
      addRemote
    );


    (
      Array.isArray(
        localUsers
      )
        ? localUsers
        : []
    ).forEach(
      mergeLocal
    );


    return Array.from(
      map.values()
    );
  }


  /*
   * ==========================================
   * PULL
   *
   * DG local conservé.
   *
   * Pour les non-DG :
   * fusion remote + local.
   * Aucun compte local ou distant
   * n'est supprimé juste parce qu'il
   * manque dans l'autre appareil.
   * ==========================================
   */
  window.lpV5ApplyRemoteUsers =
    function (
      remoteUsers,
      localUsers
    ) {

      var local =
        Array.isArray(
          localUsers
        )
          ? localUsers
          : [];

      var remote =
        Array.isArray(
          remoteUsers
        )
          ? remoteUsers
          : [];

      var localDG =
        local
          .filter(
            lpV6IsDG
          )
          .map(
            lpV6Clone
          );

      var remoteNonDG =
        remote.filter(
          function (u) {
            return !lpV6IsDG(u);
          }
        );

      var localNonDG =
        local.filter(
          function (u) {
            return !lpV6IsDG(u);
          }
        );

      var merged =
        lpV6MergeNonDG(
          remoteNonDG,
          localNonDG,
          'pull'
        );

      db.users =
        localDG.concat(
          merged
        );

      try {

        if (
          typeof lpV5RefreshSellerCache ===
          'function'
        ) {

          lpV5RefreshSellerCache(
            db.users
          );
        }

      } catch (e) {

        console.warn(
          'LP V6 CACHE SELLER',
          e
        );
      }


      localStorage.setItem(
        'lpmp_v13',
        JSON.stringify(db)
      );


      lpV6RefreshBaseline();


      console.log(
        'LEADER PHARMA USERS V6 PULL FUSION OK'
      );


      return db.users;
    };


  /*
   * ==========================================
   * PUSH
   *
   * DG distant conservé.
   *
   * Pour les non-DG :
   * union remote + local.
   *
   * Un appareil ancien NE PEUT PLUS
   * supprimer les comptes récents.
   * ==========================================
   */
  window.lpV5PrepareRemoteUsers =
    function (
      remoteUsers,
      localUsers
    ) {

      var remote =
        Array.isArray(
          remoteUsers
        )
          ? remoteUsers
          : [];

      var local =
        Array.isArray(
          localUsers
        )
          ? localUsers
          : [];

      var remoteDG =
        remote
          .filter(
            lpV6IsDG
          )
          .map(
            lpV6Clone
          );

      var remoteNonDG =
        remote.filter(
          function (u) {
            return !lpV6IsDG(u);
          }
        );

      var localNonDG =
        local.filter(
          function (u) {
            return !lpV6IsDG(u);
          }
        );

      var merged =
        lpV6MergeNonDG(
          remoteNonDG,
          localNonDG,
          'push-new-local'
        );


      console.log(
        'LEADER PHARMA USERS V6 PUSH FUSION OK'
      );


      return remoteDG.concat(
        merged
      );
    };


  /*
   * Au chargement V6,
   * on garde simplement une photo
   * de référence locale.
   *
   * Aucun push automatique forcé ici,
   * pour éviter de pousser une ancienne
   * liste avant le premier échange.
   */
  lpV6RefreshBaseline();


  console.log(
    'LEADER PHARMA USERS V6 ANTI ECRASEMENT MULTI APPAREILS ACTIF'
  );

})();

