/* LP_V10_OBJECTIFS_PERFORMANCE_USERS_ISOLES_START */

(function(){

  function lpV10Norm(v){
    return String(v == null ? '' : v)
      .trim()
      .toLowerCase();
  }

  function lpV10Number(v){
    var n = Number(v || 0);
    return Number.isFinite(n) ? n : 0;
  }

  function lpV10Money(v){
    var n = lpV10Number(v);

    if(typeof lpU3Money === 'function'){
      return lpU3Money(n);
    }

    return n.toLocaleString('fr-FR') + ' FC';
  }

  function lpV10Escape(v){
    return String(v == null ? '' : v)
      .replace(/&/g,'&amp;')
      .replace(/</g,'&lt;')
      .replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;');
  }

  function lpV10Today(){
    if(typeof lpU3Today === 'function'){
      return lpU3Today();
    }

    return new Date().toISOString().slice(0,10);
  }

  function lpV10Agency(){
    if(typeof lpU3Agency === 'function'){
      return lpU3Agency();
    }

    return String(
      typeof currentAgency !== 'undefined'
        ? currentAgency
        : ''
    );
  }

  function lpV10CurrentUserRecord(){
    if(
      typeof db === 'undefined'
      ||
      !Array.isArray(db.users)
      ||
      typeof currentUser === 'undefined'
      ||
      !currentUser
    ){
      return null;
    }

    var myUsername = lpV10Norm(currentUser.username);
    var myId = lpV10Norm(currentUser.id);

    return db.users.find(function(u){

      if(!u){
        return false;
      }

      var username = lpV10Norm(u.username);
      var id = lpV10Norm(u.id);

      if(
        myUsername
        &&
        username
        &&
        myUsername === username
      ){
        return true;
      }

      if(
        myId
        &&
        id
        &&
        myId === id
      ){
        return true;
      }

      return false;
    }) || null;
  }

  function lpV10SaleOwnerKeys(sale){

    var keys = [];

    if(!sale){
      return keys;
    }

    [
      sale.sellerUsername,
      sale.sellerUserId,
      sale.sellerName,
      sale.seller,
      sale.username,
      sale.user
    ].forEach(function(v){

      var k = lpV10Norm(v);

      if(k && keys.indexOf(k) === -1){
        keys.push(k);
      }
    });

    return keys;
  }

  function lpV10MyKeys(){

    var keys = [];

    if(
      typeof currentUser === 'undefined'
      ||
      !currentUser
    ){
      return keys;
    }

    [
      currentUser.username,
      currentUser.id,
      currentUser.name
    ].forEach(function(v){

      var k = lpV10Norm(v);

      if(k && keys.indexOf(k) === -1){
        keys.push(k);
      }
    });

    return keys;
  }

  function lpV10SaleDate(sale){

    if(!sale){
      return '';
    }

    var value =
      sale.date ||
      sale.createdAt ||
      sale.created_at ||
      sale.datetime ||
      sale.time ||
      '';

    return String(value).slice(0,10);
  }

  function lpV10SaleAgency(sale){

    if(!sale){
      return '';
    }

    return String(
      sale.agency ||
      sale.agencyName ||
      sale.branch ||
      ''
    );
  }

  function lpV10AllSales(){

    if(
      typeof db === 'undefined'
      ||
      !Array.isArray(db.sales)
    ){
      return [];
    }

    var today = lpV10Today();
    var agency = lpV10Agency();

    return db.sales.filter(function(sale){

      if(!sale){
        return false;
      }

      var d = lpV10SaleDate(sale);

      if(d && d !== today){
        return false;
      }

      var a = lpV10SaleAgency(sale);

      if(
        agency
        &&
        a
        &&
        String(a) !== String(agency)
      ){
        return false;
      }

      return true;
    });
  }

  function lpV10MySalesToday(){

    var mine = lpV10MyKeys();

    if(!mine.length){
      return [];
    }

    return lpV10AllSales().filter(function(sale){

      var owners = lpV10SaleOwnerKeys(sale);

      if(!owners.length){
        return false;
      }

      return owners.some(function(owner){
        return mine.indexOf(owner) !== -1;
      });
    });
  }

  function lpV10SaleTotal(sale){

    if(!sale){
      return 0;
    }

    var direct = lpV10Number(
      sale.total ||
      sale.amount ||
      sale.grandTotal ||
      sale.totalAmount ||
      0
    );

    if(direct){
      return direct;
    }

    if(Array.isArray(sale.items)){

      return sale.items.reduce(function(sum,item){

        if(!item){
          return sum;
        }

        var qty = lpV10Number(
          item.qty ||
          item.quantity ||
          0
        );

        var price = lpV10Number(
          item.price ||
          item.unitPrice ||
          item.unit_price ||
          0
        );

        return sum + (qty * price);

      },0);
    }

    return 0;
  }

  function lpV10MySalesTotal(){

    return lpV10MySalesToday()
      .reduce(function(sum,sale){
        return sum + lpV10SaleTotal(sale);
      },0);
  }

  function lpV10Target(){

    var rec = lpV10CurrentUserRecord();

    if(!rec){
      return 0;
    }

    var value = lpV10Number(
      rec.salesDailyTarget
    );

    return value > 0 ? value : 0;
  }

  function lpV10Performance(rate,target){

    if(!target){
      return {
        icon:'⚪',
        label:'Objectif non défini'
      };
    }

    if(rate >= 100){
      return {
        icon:'🏆',
        label:'Excellente'
      };
    }

    if(rate >= 75){
      return {
        icon:'🟢',
        label:'Bonne'
      };
    }

    if(rate >= 50){
      return {
        icon:'🟠',
        label:'À améliorer'
      };
    }

    return {
      icon:'🔴',
      label:'Faible'
    };
  }

  function lpV10MountSellerPerformance(){

    if(
      typeof currentUser === 'undefined'
      ||
      !currentUser
      ||
      lpV10Norm(currentUser.role) !== 'vendeur'
    ){
      return;
    }

    var report =
      document.getElementById(
        'lpV9DailyReport'
      );

    if(!report){
      return;
    }

    var old =
      document.getElementById(
        'lpV10SellerPerformance'
      );

    if(old){
      old.remove();
    }

    var target = lpV10Target();
    var realised = lpV10MySalesTotal();

    var remaining =
      target > realised
        ? target - realised
        : 0;

    var rate =
      target > 0
        ? (realised / target) * 100
        : 0;

    var perf =
      lpV10Performance(
        rate,
        target
      );

    var card =
      document.createElement('div');

    card.id =
      'lpV10SellerPerformance';

    card.className = 'card';

    card.style.marginTop = '16px';

    card.innerHTML =
      '<h3>🎯 Objectif &amp; Performance</h3>' +

      '<div class="grid kpis">' +

        '<div class="card kpi">' +
          '<div class="label">Objectif du jour</div>' +
          '<div class="value">' +
            (
              target
                ? lpV10Money(target)
                : 'Non défini'
            ) +
          '</div>' +
        '</div>' +

        '<div class="card kpi">' +
          '<div class="label">Réalisé</div>' +
          '<div class="value">' +
            lpV10Money(realised) +
          '</div>' +
        '</div>' +

        '<div class="card kpi">' +
          '<div class="label">Reste à atteindre</div>' +
          '<div class="value">' +
            lpV10Money(remaining) +
          '</div>' +
        '</div>' +

        '<div class="card kpi">' +
          '<div class="label">Taux de réalisation</div>' +
          '<div class="value">' +
            (
              target
                ? Math.round(rate) + '%'
                : '—'
            ) +
          '</div>' +
        '</div>' +

      '</div>' +

      '<div style="margin-top:12px;font-weight:700">' +
        perf.icon +
        ' Performance : ' +
        perf.label +
      '</div>';

    report.parentNode.insertBefore(
      card,
      report
    );
  }

  function lpV10SellerUsers(){

    if(
      typeof db === 'undefined'
      ||
      !Array.isArray(db.users)
    ){
      return [];
    }

    return db.users.filter(function(u){

      return (
        u
        &&
        u.active !== false
        &&
        lpV10Norm(u.role) === 'vendeur'
      );
    });
  }

  function lpV10MountDGTargets(){

    if(
      typeof currentUser === 'undefined'
      ||
      !currentUser
      ||
      lpV10Norm(currentUser.role) !== 'dg'
    ){
      return;
    }

    var host =
      document.getElementById('content');

    if(!host){
      return;
    }

    var old =
      document.getElementById(
        'lpV10DGTargets'
      );

    if(old){
      old.remove();
    }

    var sellers =
      lpV10SellerUsers();

    var panel =
      document.createElement('div');

    panel.id =
      'lpV10DGTargets';

    panel.className = 'card';

    panel.style.marginTop = '16px';

    var html =
      '<h3>🎯 Objectifs des vendeurs</h3>' +
      '<div class="muted">' +
        'Définissez l’objectif quotidien de chaque vendeur.' +
      '</div>';

    if(!sellers.length){

      html +=
        '<div class="muted" style="margin-top:12px">' +
          'Aucun vendeur actif.' +
        '</div>';

    }else{

      sellers.forEach(function(u,i){

        var currentTarget =
          lpV10Number(
            u.salesDailyTarget
          );

        html +=
          '<div class="card" style="margin-top:12px">' +

            '<b>' +
              lpV10Escape(
                u.name ||
                u.username ||
                'Vendeur'
              ) +
            '</b>' +

            '<div class="muted">' +
              lpV10Escape(
                u.username || ''
              ) +
            '</div>' +

            '<label style="display:block;margin-top:10px">' +
              'Objectif du jour (FC)' +
            '</label>' +

            '<input ' +
              'type="number" ' +
              'min="0" ' +
              'inputmode="numeric" ' +
              'id="lpV10Target_' + i + '" ' +
              'value="' +
                (
                  currentTarget > 0
                    ? currentTarget
                    : ''
                ) +
              '" ' +
              'placeholder="Ex. 100000">' +

            '<button ' +
              'type="button" ' +
              'class="btn primary" ' +
              'style="margin-top:10px" ' +
              'data-lpv10-index="' + i + '">' +
              'Enregistrer objectif' +
            '</button>' +

          '</div>';
      });
    }

    panel.innerHTML = html;

    host.appendChild(panel);

    panel
      .querySelectorAll(
        '[data-lpv10-index]'
      )
      .forEach(function(btn){

        btn.onclick = function(){

          var i =
            Number(
              btn.getAttribute(
                'data-lpv10-index'
              )
            );

          var seller =
            sellers[i];

          var input =
            document.getElementById(
              'lpV10Target_' + i
            );

          if(!seller || !input){
            return;
          }

          var value =
            lpV10Number(
              input.value
            );

          seller.salesDailyTarget =
            value > 0 ? value : 0;

          seller._lpUserUpdatedAt =
            Date.now();

          if(typeof save === 'function'){
            save();
          }

          if(typeof toast === 'function'){
            toast(
              'Objectif vendeur enregistré'
            );
          }

          lpV10MountDGTargets();
        };
      });
  }

  if(typeof dashboard === 'function'){

    var lpV10OldDashboard =
      dashboard;

    dashboard = function(){

      var result =
        lpV10OldDashboard.apply(
          this,
          arguments
        );

      lpV10MountSellerPerformance();

      return result;
    };
  }

  if(typeof users === 'function'){

    var lpV10OldUsers =
      users;

    users = function(){

      var result =
        lpV10OldUsers.apply(
          this,
          arguments
        );

      lpV10MountDGTargets();

      return result;
    };
  }

  if(typeof lp16UsersPage === 'function'){

    var lpV10OldUsersPage =
      lp16UsersPage;

    lp16UsersPage = function(){

      var result =
        lpV10OldUsersPage.apply(
          this,
          arguments
        );

      lpV10MountDGTargets();

      return result;
    };
  }

  window.lpV10MountSellerPerformance =
    lpV10MountSellerPerformance;

  window.lpV10MountDGTargets =
    lpV10MountDGTargets;

  window.lpV10MySalesToday =
    lpV10MySalesToday;

  console.log(
    'LEADER PHARMA V10 OBJECTIFS PERFORMANCE USERS ISOLES ACTIF'
  );

})();

