/* LP_V15_ALERTES_UTILISATEURS_PRO_FINAL_START */
(function(){

  function lpAlertS(v){
    return String(
      v == null ? '' : v
    ).trim();
  }

  function lpAlertNorm(v){
    return lpAlertS(v)
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'');
  }

  function lpAlertUser(){
    try{
      return currentUser || {};
    }catch(e){
      return {};
    }
  }

  function lpAlertIsDG(){
    var u = lpAlertUser();

    var role = lpAlertNorm(
      u.role ||
      u.profil ||
      u.type ||
      ''
    );

    return (
      role === 'dg' ||
      role === 'direction' ||
      role === 'directeur general'
    );
  }

  function lpAlertEsc(v){
    return lpAlertS(v)
      .replace(/&/g,'&amp;')
      .replace(/</g,'&lt;')
      .replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;')
      .replace(/'/g,'&#39;');
  }

  function lpAlertToast(msg){
    try{
      if(typeof toast === 'function'){
        toast(msg);
        return;
      }
    }catch(e){}

    alert(msg);
  }

  function lpAlertIsPage(){

    var p = '';

    try{
      p = lpAlertNorm(page);
    }catch(e){}

    return (
      p === 'alerts' ||
      p === 'alertes'
    );
  }

  function lpAlertProducts(){

    try{

      if(typeof db === 'undefined'){
        return [];
      }

      var candidates = [
        db.products,
        db.produits,
        db.stock,
        db.items
      ];

      for(
        var i = 0;
        i < candidates.length;
        i++
      ){
        if(
          Array.isArray(candidates[i]) &&
          candidates[i].length
        ){
          return candidates[i];
        }
      }

    }catch(e){}

    return [];
  }

  function lpAlertName(p){

    return lpAlertS(
      p.name ||
      p.nom ||
      p.productName ||
      p.designation ||
      p.libelle ||
      'Produit'
    );
  }

  function lpAlertStock(p){

    var value =
      p.stock;

    if(value == null){
      value = p.quantity;
    }

    if(value == null){
      value = p.qty;
    }

    if(value == null){
      value = p.quantite;
    }

    value = Number(value);

    return isNaN(value)
      ? 0
      : value;
  }

  function lpAlertMin(p){

    var value =
      p.minStock;

    if(value == null){
      value = p.stockMin;
    }

    if(value == null){
      value = p.minimum;
    }

    if(value == null){
      value = p.seuil;
    }

    value = Number(value);

    if(
      isNaN(value) ||
      value <= 0
    ){
      value = 5;
    }

    return value;
  }

  function lpAlertExpiry(p){

    return lpAlertS(
      p.expiryDate ||
      p.expirationDate ||
      p.expiry ||
      p.expiration ||
      p.dateExpiration ||
      p.datePeremption ||
      p.peremption ||
      ''
    );
  }

  function lpAlertDays(dateValue){

    if(!dateValue){
      return null;
    }

    var d =
      new Date(dateValue);

    if(isNaN(d.getTime())){
      return null;
    }

    var now =
      new Date();

    now.setHours(
      0,0,0,0
    );

    d.setHours(
      0,0,0,0
    );

    return Math.ceil(
      (
        d.getTime() -
        now.getTime()
      ) /
      86400000
    );
  }

  function lpAlertAnalyse(p){

    var stock =
      lpAlertStock(p);

    var min =
      lpAlertMin(p);

    var expiry =
      lpAlertExpiry(p);

    var days =
      lpAlertDays(expiry);

    var expired =
      days !== null &&
      days < 0;

    var nearExpiry =
      days !== null &&
      days >= 0 &&
      days <= 30;

    if(
      expired ||
      (
        stock <= 0 &&
        expired
      )
    ){
      return {
        level:3,
        label:'🔴 Critique',
        action:
          'Retirer le lot périmé'
      };
    }

    if(stock <= 0){
      return {
        level:2,
        label:'🟠 Urgent',
        action:
          'Proposer un réapprovisionnement'
      };
    }

    if(
      stock <= min ||
      nearExpiry
    ){
      return {
        level:1,
        label:'🟡 À surveiller',
        action:
          nearExpiry
          ? 'Surveiller la péremption'
          : 'Anticiper la rupture'
      };
    }

    return {
      level:0,
      label:'🟢 Normal',
      action:'Aucune urgence'
    };
  }

  function lpAlertData(){

    return lpAlertProducts()
      .map(function(p){

        var analysis =
          lpAlertAnalyse(p);

        return {
          product:p,
          name:lpAlertName(p),
          stock:lpAlertStock(p),
          expiry:lpAlertExpiry(p),
          level:analysis.level,
          label:analysis.label,
          action:analysis.action
        };

      })
      .filter(function(x){
        return x.level > 0;
      })
      .sort(function(a,b){
        return b.level - a.level;
      });
  }

  function lpAlertFindHost(){

    var selectors = [
      '#alerts',
      '#alertsPage',
      '#alertsContent',
      '#alertes',
      '#alertesPage',
      '.alerts-page'
    ];

    for(
      var i = 0;
      i < selectors.length;
      i++
    ){
      var el =
        document.querySelector(
          selectors[i]
        );

      if(el){
        return el;
      }
    }

    return document.querySelector(
      '#content,main,.content,.page-content'
    );
  }

  function lpAlertRender(){

    /*
     * Innovation demandee uniquement
     * chez les utilisateurs.
     * Le DG reste totalement intact.
     */

    if(
      lpAlertIsDG() ||
      !lpAlertIsPage()
    ){
      return;
    }

    var host =
      lpAlertFindHost();

    if(!host){
      return;
    }

    var existing =
      document.getElementById(
        'lpUserAlertCenter'
      );

    if(existing){
      existing.remove();
    }

    var rows =
      lpAlertData();

    var critical =
      rows.filter(function(x){
        return x.level === 3;
      }).length;

    var urgent =
      rows.filter(function(x){
        return x.level === 2;
      }).length;

    var watch =
      rows.filter(function(x){
        return x.level === 1;
      }).length;

    var box =
      document.createElement(
        'section'
      );

    box.id =
      'lpUserAlertCenter';

    box.style.cssText =
      'margin:14px 0 18px;padding:16px;border:1px solid #dfe4ea;border-radius:16px;background:#fff;';

    var cards = '';

    if(!rows.length){

      cards =
        '<div style="padding:14px 0;color:#667085;">✅ Aucune alerte prioritaire actuellement.</div>';

    }else{

      cards =
        rows
        .slice(0,20)
        .map(function(x){

          var button = '';

          if(
            x.level === 2 ||
            (
              x.level === 1 &&
              lpAlertStock(
                x.product
              ) <=
              lpAlertMin(
                x.product
              )
            )
          ){

            button =
              '<button type="button" ' +
              'class="btn lpAlertPropose" ' +
              'data-product="' +
              lpAlertEsc(x.name) +
              '" ' +
              'style="margin-top:8px;">' +
              '🛒 Proposer commande' +
              '</button>';
          }

          return (
            '<div style="padding:12px 0;border-top:1px solid #eef1f4;">' +

            '<div style="font-weight:800;">' +
            lpAlertEsc(x.name) +
            '</div>' +

            '<div style="margin-top:4px;">' +
            x.label +
            '</div>' +

            '<div style="color:#667085;margin-top:4px;">' +
            'Stock : ' +
            lpAlertEsc(x.stock) +
            (
              x.expiry
              ?
              ' • Péremption : ' +
              lpAlertEsc(x.expiry)
              :
              ''
            ) +
            '</div>' +

            '<div style="margin-top:5px;"><b>Action recommandée :</b> ' +
            lpAlertEsc(x.action) +
            '</div>' +

            button +

            '</div>'
          );
        })
        .join('');
    }

    box.innerHTML =
      '<h3 style="margin:0 0 5px;">🚨 Centre d’alertes intelligent</h3>' +

      '<div style="color:#667085;margin-bottom:12px;">Priorités stock destinées à faciliter votre signalement à la Direction.</div>' +

      '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-bottom:12px;">' +

      '<div style="padding:9px;text-align:center;border:1px solid #f1d5d5;border-radius:10px;">' +
      '<b>🔴 ' + critical + '</b><br><small>Critiques</small>' +
      '</div>' +

      '<div style="padding:9px;text-align:center;border:1px solid #f0dfc8;border-radius:10px;">' +
      '<b>🟠 ' + urgent + '</b><br><small>Urgentes</small>' +
      '</div>' +

      '<div style="padding:9px;text-align:center;border:1px solid #eee6c8;border-radius:10px;">' +
      '<b>🟡 ' + watch + '</b><br><small>À surveiller</small>' +
      '</div>' +

      '</div>' +

      cards;

    /*
     * Le centre est ajoute au-dessus
     * de la liste actuelle.
     */

    if(host.firstChild){
      host.insertBefore(
        box,
        host.firstChild
      );
    }else{
      host.appendChild(box);
    }

    box
      .querySelectorAll(
        '.lpAlertPropose'
      )
      .forEach(function(btn){

        btn.onclick =
          function(){

            var product =
              btn.getAttribute(
                'data-product'
              ) || 'Produit';

            /*
             * On cherche le bouton
             * Proposer commande deja
             * existant dans l'application.
             */

            var all =
              Array.from(
                document.querySelectorAll(
                  'button,[role="button"]'
                )
              );

            var nativeButton =
              all.find(function(b){

                if(
                  b === btn ||
                  box.contains(b)
                ){
                  return false;
                }

                return lpAlertNorm(
                  b.textContent
                ).includes(
                  'proposer commande'
                );
              });

            if(nativeButton){

              nativeButton.click();

              setTimeout(
                function(){

                  var inputs =
                    Array.from(
                      document.querySelectorAll(
                        'input,textarea'
                      )
                    );

                  var productInput =
                    inputs.find(
                      function(input){

                        var info =
                          lpAlertNorm(
                            (
                              input.placeholder ||
                              ''
                            ) +
                            ' ' +
                            (
                              input.name ||
                              ''
                            )
                          );

                        return (
                          info.includes(
                            'produit'
                          ) ||
                          info.includes(
                            'designation'
                          )
                        );
                      }
                    );

                  if(productInput){

                    productInput.value =
                      product;

                    productInput.dispatchEvent(
                      new Event(
                        'input',
                        {
                          bubbles:true
                        }
                      )
                    );
                  }

                },
                100
              );

              return;
            }

            lpAlertToast(
              'Produit à proposer au DG : ' +
              product
            );
          };
      });
  }

  window.lpV15UserAlertCenter =
    lpAlertRender;

  var oldRender =
    window.render;

  if(
    typeof oldRender ===
    'function'
  ){

    window.render =
      function(){

        var result =
          oldRender.apply(
            this,
            arguments
          );

        setTimeout(
          lpAlertRender,
          80
        );

        return result;
      };
  }

  setTimeout(
    lpAlertRender,
    200
  );

  console.log(
    'LEADER PHARMA V15 ALERTES UTILISATEURS PRO FINAL ACTIF'
  );

})();
/* LP_V15_ALERTES_UTILISATEURS_PRO_FINAL_END */


/* LP_V15_COMMANDES_VALIDATION_DG_FINAL_START */
(function(){

  function lpCmdS(v){
    return String(
      v == null ? '' : v
    ).trim();
  }

  function lpCmdNorm(v){
    return lpCmdS(v)
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'');
  }

  function lpCmdEsc(v){
    return lpCmdS(v)
      .replace(/&/g,'&amp;')
      .replace(/</g,'&lt;')
      .replace(/>/g,'&gt;')
      .replace(/"/g,'&quot;')
      .replace(/'/g,'&#39;');
  }

  function lpCmdUser(){
    try{
      return currentUser || {};
    }catch(e){
      return {};
    }
  }

  function lpCmdRole(){
    var u = lpCmdUser();

    return lpCmdNorm(
      u.role ||
      u.profil ||
      u.type ||
      ''
    );
  }

  function lpCmdIsDG(){
    var r = lpCmdRole();

    return (
      r === 'dg' ||
      r === 'direction' ||
      r === 'directeur general'
    );
  }

  function lpCmdUserName(){
    var u = lpCmdUser();

    return lpCmdS(
      u.nom ||
      u.name ||
      u.username ||
      u.identifiant ||
      u.email ||
      'Utilisateur'
    );
  }

  function lpCmdUserId(){
    var u = lpCmdUser();

    return lpCmdS(
      u.id ||
      u.userId ||
      u.username ||
      u.identifiant ||
      u.email ||
      lpCmdUserName()
    );
  }

  function lpCmdToast(msg){
    try{
      if(typeof toast === 'function'){
        toast(msg);
        return;
      }
    }catch(e){}

    alert(msg);
  }

  function lpCmdSave(){
    try{
      if(typeof save === 'function'){
        save();
      }
    }catch(e){}
  }

  function lpCmdStore(){

    try{

      if(typeof db === 'undefined'){
        return [];
      }

      if(
        !Array.isArray(
          db.orderProposals
        )
      ){
        db.orderProposals = [];
      }

      return db.orderProposals;

    }catch(e){
      return [];
    }
  }

  function lpCmdDate(v){

    if(!v){
      return '';
    }

    try{
      return new Date(v)
        .toLocaleString('fr-FR');
    }catch(e){
      return lpCmdS(v);
    }
  }

  function lpCmdStatus(status){

    var s =
      lpCmdNorm(status);

    if(s === 'approved'){
      return '✅ Approuvée par le DG';
    }

    if(s === 'rejected'){
      return '❌ Refusée par le DG';
    }

    return '⏳ En attente de décision DG';
  }

  function lpCmdCreateProposal(
    product,
    quantity,
    reason
  ){

    product =
      lpCmdS(product);

    if(!product){
      lpCmdToast(
        'Produit obligatoire'
      );
      return false;
    }

    quantity =
      Number(quantity);

    if(
      !Number.isFinite(quantity) ||
      quantity <= 0
    ){
      quantity = 1;
    }

    var rows =
      lpCmdStore();

    /*
     * Eviter plusieurs propositions
     * en attente du meme utilisateur
     * pour le meme produit.
     */

    var exists =
      rows.some(function(r){

        return (
          lpCmdS(r.userId) ===
          lpCmdUserId() &&
          lpCmdNorm(r.product) ===
          lpCmdNorm(product) &&
          lpCmdNorm(r.status) ===
          'pending'
        );
      });

    if(exists){

      lpCmdToast(
        'Une proposition pour ce produit est déjà en attente du DG'
      );

      return false;
    }

    rows.push({

      id:
        'cmd_' +
        Date.now() +
        '_' +
        Math.random()
          .toString(36)
          .slice(2,8),

      product:
        product,

      quantity:
        quantity,

      reason:
        lpCmdS(reason) ||
        'Réapprovisionnement proposé depuis les alertes',

      userId:
        lpCmdUserId(),

      userName:
        lpCmdUserName(),

      status:
        'pending',

      dgComment:
        '',

      createdAt:
        new Date()
          .toISOString(),

      decidedAt:
        '',

      decidedBy:
        ''

    });

    /*
     * IMPORTANT :
     * aucune modification du stock ici.
     */

    lpCmdSave();

    lpCmdToast(
      'Proposition envoyée au DG'
    );

    return true;
  }

  /*
   * =================================================
   * CONNEXION AVEC LES BOUTONS ALERTES UTILISATEURS
   * =================================================
   */

  document.addEventListener(
    'click',
    function(e){

      if(lpCmdIsDG()){
        return;
      }

      var button =
        e.target &&
        e.target.closest
        ?
        e.target.closest(
          '.lpAlertPropose'
        )
        :
        null;

      if(!button){
        return;
      }

      /*
       * On prend la main uniquement
       * sur ce bouton Alertes.
       */

      e.preventDefault();
      e.stopImmediatePropagation();

      var product =
        lpCmdS(
          button.getAttribute(
            'data-product'
          )
        );

      if(!product){
        return;
      }

      var qtyText =
        window.prompt(
          'Quantité proposée pour ' +
          product +
          ' :',
          '1'
        );

      if(qtyText === null){
        return;
      }

      var quantity =
        Number(qtyText);

      if(
        !Number.isFinite(quantity) ||
        quantity <= 0
      ){
        lpCmdToast(
          'Quantité invalide'
        );
        return;
      }

      var reason =
        window.prompt(
          'Motif de la proposition :',
          'Réapprovisionnement recommandé par le centre d’alertes'
        );

      if(reason === null){
        return;
      }

      lpCmdCreateProposal(
        product,
        quantity,
        reason
      );

    },
    true
  );

  /*
   * =================================================
   * MES PROPOSITIONS - UTILISATEUR
   * =================================================
   */

  function lpCmdRenderUser(){

    if(lpCmdIsDG()){
      return;
    }

    var titles =
      Array.from(
        document.querySelectorAll(
          'h1,h2,h3,h4'
        )
      );

    var title =
      titles.find(function(el){

        return lpCmdNorm(
          el.textContent
        ).includes(
          'mes propositions de commande'
        );
      });

    if(!title){
      return;
    }

    var section =
      title.parentElement;

    if(!section){
      return;
    }

    var old =
      section.querySelector(
        '#lpCmdUserHistory'
      );

    if(old){
      old.remove();
    }

    var rows =
      lpCmdStore()
        .filter(function(r){

          return (
            lpCmdS(r.userId) ===
            lpCmdUserId()
          );
        })
        .slice()
        .reverse();

    var box =
      document.createElement(
        'div'
      );

    box.id =
      'lpCmdUserHistory';

    box.style.cssText =
      'margin-top:14px;';

    if(!rows.length){

      box.innerHTML =
        '<div style="color:#667085;padding:8px 0;">Aucune proposition de commande envoyée.</div>';

    }else{

      box.innerHTML =
        rows.map(function(r){

          return (
            '<div style="margin:10px 0;padding:13px;border:1px solid #e3e7ec;border-radius:12px;background:#fff;">' +

            '<div style="font-weight:800;">' +
            lpCmdEsc(r.product) +
            '</div>' +

            '<div>Quantité proposée : <b>' +
            lpCmdEsc(r.quantity) +
            '</b></div>' +

            '<div style="margin-top:5px;">' +
            lpCmdStatus(r.status) +
            '</div>' +

            (
              r.reason
              ?
              '<div style="margin-top:5px;color:#667085;"><b>Motif :</b> ' +
              lpCmdEsc(r.reason) +
              '</div>'
              :
              ''
            ) +

            (
              r.dgComment
              ?
              '<div style="margin-top:5px;"><b>Commentaire DG :</b> ' +
              lpCmdEsc(r.dgComment) +
              '</div>'
              :
              ''
            ) +

            '<small style="display:block;margin-top:6px;color:#667085;">Envoyée : ' +
            lpCmdEsc(
              lpCmdDate(
                r.createdAt
              )
            ) +
            '</small>' +

            '</div>'
          );
        }).join('');
    }

    section.appendChild(box);
  }

  /*
   * =================================================
   * PANNEAU DE DECISION - DG
   * =================================================
   */

  function lpCmdFindDGHost(){

    var main =
      document.querySelector(
        '#content,main,.content,.page-content'
      );

    return main || null;
  }

  function lpCmdDGPage(){

    if(!lpCmdIsDG()){
      return false;
    }

    var p = '';

    try{
      p = lpCmdNorm(page);
    }catch(e){}

    /*
     * Le panneau DG est rattache aux
     * Alertes pour ne pas creer
     * une nouvelle rubrique de menu.
     */

    return (
      p === 'alerts' ||
      p === 'alertes'
    );
  }

  function lpCmdRenderDG(){

    if(!lpCmdDGPage()){
      return;
    }

    var host =
      lpCmdFindDGHost();

    if(!host){
      return;
    }

    var old =
      document.getElementById(
        'lpCmdDGPanel'
      );

    if(old){
      old.remove();
    }

    var rows =
      lpCmdStore()
        .slice()
        .reverse();

    var pending =
      rows.filter(function(r){
        return (
          lpCmdNorm(r.status) ===
          'pending'
        );
      }).length;

    var box =
      document.createElement(
        'section'
      );

    box.id =
      'lpCmdDGPanel';

    box.style.cssText =
      'margin:14px 0 18px;padding:16px;border:1px solid #dfe4ea;border-radius:16px;background:#fff;';

    var html = '';

    if(!rows.length){

      html =
        '<div style="padding:10px 0;color:#667085;">Aucune proposition de commande reçue.</div>';

    }else{

      html =
        rows.map(function(r){

          var waiting =
            lpCmdNorm(
              r.status
            ) === 'pending';

          return (
            '<div style="padding:13px 0;border-top:1px solid #edf0f3;">' +

            '<div style="font-weight:800;font-size:17px;">' +
            lpCmdEsc(r.product) +
            '</div>' +

            '<div style="margin-top:4px;"><b>Proposé par :</b> ' +
            lpCmdEsc(
              r.userName ||
              'Utilisateur'
            ) +
            '</div>' +

            '<div><b>Quantité :</b> ' +
            lpCmdEsc(r.quantity) +
            '</div>' +

            '<div><b>Motif :</b> ' +
            lpCmdEsc(
              r.reason ||
              '—'
            ) +
            '</div>' +

            '<div style="margin-top:5px;">' +
            lpCmdStatus(r.status) +
            '</div>' +

            (
              waiting
              ?
              '<textarea id="lpCmdComment_' +
              lpCmdEsc(r.id) +
              '" rows="2" placeholder="Commentaire / décision du DG" style="width:100%;box-sizing:border-box;margin-top:10px;padding:9px;border:1px solid #ccd3dc;border-radius:8px;"></textarea>' +

              '<div style="display:flex;gap:8px;margin-top:9px;">' +

              '<button type="button" class="btn primary lpCmdApprove" data-id="' +
              lpCmdEsc(r.id) +
              '" style="flex:1;">✅ Approuver</button>' +

              '<button type="button" class="btn lpCmdReject" data-id="' +
              lpCmdEsc(r.id) +
              '" style="flex:1;">❌ Refuser</button>' +

              '</div>'
              :
              (
                r.dgComment
                ?
                '<div style="margin-top:6px;"><b>Commentaire DG :</b> ' +
                lpCmdEsc(
                  r.dgComment
                ) +
                '</div>'
                :
                ''
              )
            ) +

            '</div>'
          );
        }).join('');
    }

    box.innerHTML =
      '<h3 style="margin:0 0 5px;">🛒 Propositions de commande</h3>' +

      '<div style="color:#667085;margin-bottom:10px;">Décision DG — ' +
      pending +
      ' proposition(s) en attente.</div>' +

      html;

    /*
     * On ajoute le panneau dans
     * Alertes DG uniquement.
     */

    host.insertBefore(
      box,
      host.firstChild
    );

    box
      .querySelectorAll(
        '.lpCmdApprove,.lpCmdReject'
      )
      .forEach(function(button){

        button.onclick =
          function(){

            var id =
              lpCmdS(
                button.getAttribute(
                  'data-id'
                )
              );

            var row =
              lpCmdStore()
                .find(function(r){
                  return (
                    lpCmdS(r.id) === id
                  );
                });

            if(!row){
              return;
            }

            if(
              lpCmdNorm(
                row.status
              ) !== 'pending'
            ){
              lpCmdToast(
                'Cette proposition a déjà été traitée'
              );
              return;
            }

            var comment =
              document.getElementById(
                'lpCmdComment_' +
                id
              );

            row.dgComment =
              lpCmdS(
                comment
                ? comment.value
                : ''
              );

            row.status =
              button.classList
                .contains(
                  'lpCmdApprove'
                )
              ?
              'approved'
              :
              'rejected';

            row.decidedAt =
              new Date()
                .toISOString();

            row.decidedBy =
              lpCmdUserName();

            /*
             * REGLE DE GESTION :
             * aucune modification de stock.
             * La reception physique reste
             * la seule operation qui pourra
             * augmenter le stock.
             */

            lpCmdSave();

            lpCmdToast(
              row.status ===
              'approved'
              ?
              'Proposition approuvée'
              :
              'Proposition refusée'
            );

            lpCmdRenderDG();
          };
      });
  }

  function lpCmdRender(){

    if(lpCmdIsDG()){
      lpCmdRenderDG();
    }else{
      lpCmdRenderUser();
    }
  }

  window.lpV15CreateOrderProposal =
    lpCmdCreateProposal;

  window.lpV15RenderOrderProposals =
    lpCmdRender;

  var oldRender =
    window.render;

  if(
    typeof oldRender ===
    'function'
  ){

    window.render =
      function(){

        var result =
          oldRender.apply(
            this,
            arguments
          );

        setTimeout(
          lpCmdRender,
          100
        );

        return result;
      };
  }

  document.addEventListener(
    'click',
    function(){

      setTimeout(
        lpCmdRender,
        120
      );

    },
    false
  );

  setTimeout(
    lpCmdRender,
    250
  );

  console.log(
    'LEADER PHARMA V15 COMMANDES VALIDATION DG FINAL ACTIF'
  );

})();
/* LP_V15_COMMANDES_VALIDATION_DG_FINAL_END */


/* LP_V15_DG_COMMENTAIRE_CLAVIER_FINAL_START */
(function(){

  function lpDGCommentField(target){

    if(!target){
      return null;
    }

    var el = target;

    if(
      el.nodeType !== 1
    ){
      el = el.parentElement;
    }

    if(!el){
      return null;
    }

    if(
      el.matches &&
      el.matches(
        'textarea[id^="lpCmdComment_"]'
      )
    ){
      return el;
    }

    if(el.closest){
      return el.closest(
        'textarea[id^="lpCmdComment_"]'
      );
    }

    return null;
  }

  function lpDGUnlockComment(field){

    if(!field){
      return;
    }

    field.disabled = false;
    field.readOnly = false;

    field.removeAttribute(
      'disabled'
    );

    field.removeAttribute(
      'readonly'
    );

    field.removeAttribute(
      'aria-disabled'
    );

    field.removeAttribute(
      'data-lp171032-readonly'
    );

    field.removeAttribute(
      'data-lp1787-readonly'
    );

    field.removeAttribute(
      'data-lp1788-readonly'
    );

    field.style.setProperty(
      'pointer-events',
      'auto',
      'important'
    );

    field.style.setProperty(
      'user-select',
      'text',
      'important'
    );

    field.style.setProperty(
      '-webkit-user-select',
      'text',
      'important'
    );

    field.style.opacity = '1';

    field.setAttribute(
      'inputmode',
      'text'
    );

    field.setAttribute(
      'autocomplete',
      'off'
    );

    field.setAttribute(
      'enterkeyhint',
      'done'
    );
  }

  function lpDGUnlockAll(){

    document
      .querySelectorAll(
        'textarea[id^="lpCmdComment_"]'
      )
      .forEach(
        function(field){
          lpDGUnlockComment(
            field
          );
        }
      );
  }

  /*
   * On ne bloque PAS le clic.
   * On reactive simplement le champ
   * avant que le navigateur traite
   * normalement le toucher.
   */

  document.addEventListener(
    'touchstart',
    function(e){

      var field =
        lpDGCommentField(
          e.target
        );

      if(!field){
        return;
      }

      lpDGUnlockComment(
        field
      );

    },
    true
  );

  document.addEventListener(
    'pointerdown',
    function(e){

      var field =
        lpDGCommentField(
          e.target
        );

      if(!field){
        return;
      }

      lpDGUnlockComment(
        field
      );

    },
    true
  );

  document.addEventListener(
    'click',
    function(e){

      var field =
        lpDGCommentField(
          e.target
        );

      if(!field){
        return;
      }

      lpDGUnlockComment(
        field
      );

      /*
       * Le focus explicite permet
       * au WebView Android d'ouvrir
       * son clavier normalement.
       */

      try{
        field.focus({
          preventScroll:true
        });
      }catch(err){
        field.focus();
      }

    },
    true
  );

  document.addEventListener(
    'focusin',
    function(e){

      var field =
        lpDGCommentField(
          e.target
        );

      if(!field){
        return;
      }

      lpDGUnlockComment(
        field
      );

    },
    true
  );

  /*
   * Les champs sont recrees lorsque
   * le panneau DG est rerendu.
   * MutationObserver les reactive
   * sans modifier le panneau.
   */

  var observer =
    new MutationObserver(
      function(){
        lpDGUnlockAll();
      }
    );

  if(document.body){

    observer.observe(
      document.body,
      {
        childList:true,
        subtree:true
      }
    );
  }

  lpDGUnlockAll();

  window.lpV15UnlockDGComment =
    lpDGUnlockAll;

  console.log(
    'LEADER PHARMA V15 DG COMMENTAIRE CLAVIER FINAL ACTIF'
  );

})();
/* LP_V15_DG_COMMENTAIRE_CLAVIER_FINAL_END */


/* LP_V15_ALERTES_FIX_CIBLE_SANS_TOUCHER_RH_START */
(function(){

  function lpAFNorm(v){
    return String(v == null ? '' : v)
      .trim()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g,'');
  }

  function lpAFPage(){

    var p = '';

    try{
      if(typeof page !== 'undefined'){
        p = lpAFNorm(page);
      }
    }catch(e){}

    if(p){
      return p;
    }

    try{
      if(typeof currentPage !== 'undefined'){
        p = lpAFNorm(currentPage);
      }
    }catch(e){}

    return p;
  }

  function lpAFIsAlerts(){
    var p = lpAFPage();

    return (
      p === 'alerts' ||
      p === 'alertes'
    );
  }

  function lpAFRemoveParasites(){

    if(lpAFIsAlerts()){
      return;
    }

    var userCenter =
      document.getElementById(
        'lpUserAlertCenter'
      );

    if(userCenter){
      userCenter.remove();
    }

    var dgPanel =
      document.getElementById(
        'lpCmdDGPanel'
      );

    if(dgPanel){
      dgPanel.remove();
    }
  }

  /*
   * CORRECTIF CIBLE :
   * aucune modification de window.render.
   * aucune modification RH/Pointage.
   * aucune modification des boutons DG.
   *
   * Après une navigation, on vérifie
   * seulement si les éléments Alertes
   * doivent être retirés.
   */
  document.addEventListener(
    'click',
    function(){

      setTimeout(
        lpAFRemoveParasites,
        30
      );

      setTimeout(
        lpAFRemoveParasites,
        150
      );

      setTimeout(
        lpAFRemoveParasites,
        400
      );

    },
    false
  );

  /*
   * Si un ancien hook Alertes tente
   * de réinsérer son panneau ailleurs,
   * on retire uniquement ces deux IDs.
   */
  var observer =
    new MutationObserver(
      function(){

        if(!lpAFIsAlerts()){
          lpAFRemoveParasites();
        }
      }
    );

  if(document.body){

    observer.observe(
      document.body,
      {
        childList:true,
        subtree:true
      }
    );
  }

  setTimeout(
    lpAFRemoveParasites,
    300
  );

  console.log(
    'LEADER PHARMA ALERTES FIX CIBLE SANS TOUCHER RH ACTIF'
  );

})();
/* LP_V15_ALERTES_FIX_CIBLE_SANS_TOUCHER_RH_END */

